+static void *agent_loop_alloc_psram(size_t size)
+{
+    void *discarded[64];
+    int count = 0;
+    void *ptr;
+
+    while (count < (int)(sizeof(discarded) / sizeof(discarded[0]))) {
+        ptr = calloc(1, size);
+        if (!ptr || agent_loop_mem_kind(ptr)[0] == 'P') {
+            while (count > 0) {
+                free(discarded[--count]);
+            }
+            return ptr;
+        }
+
+        discarded[count++] = ptr;
+    }
+
+    while (count > 0) {
+        free(discarded[--count]);
+    }
+
+    return NULL;
+}
+
+static int agent_loop_pool_init_psram(agent_mem_pool_t *pool,
+    size_t buf_size, int count)
+{
+    if (count > AGENT_POOL_SLOTS) {
+        count = AGENT_POOL_SLOTS;
+    }
+
+    memset(pool, 0, sizeof(*pool));
+    pool->buf_size = buf_size;
+    pool->count = count;
+    pthread_mutex_init(&pool->lock, NULL);
+    for (int i = 0; i < count; i++) {
+        pool->buffers[i] = agent_loop_alloc_psram(buf_size);
+        if (!pool->buffers[i]) {
+            for (int j = 0; j < i; j++) {
+                free(pool->buffers[j]);
+            }
+            pthread_mutex_destroy(&pool->lock);
+            return ERROR;
+        }
+    }
+    return OK;
+}
+
+static void agent_loop_bisect_fill_canary(char* ptr)
+{
+    memset(ptr, 0xd3, AGENT_LOOP_DUMMY_REDZONE_BYTES);
+}
+
+static bool agent_loop_bisect_canary_ok(const char* ptr)
+{
+    for (size_t i = 0; i < AGENT_LOOP_DUMMY_REDZONE_BYTES; i++) {
+        if ((unsigned char)ptr[i] != 0xd3) {
+            return false;
+        }
+    }
+    return true;
+}
+
+void agent_loop_bisect_http_canary_check(const char* phase)
+{
