DEFAULT_OUTPUT = Path("robot_reply.wav")
DEFAULT_SYSTEM_PROMPT = (
    "你是机器狗小黑。请根据主人刚才说的话直接回复，语气友好、简短、自然。"
    "只输出准备朗读的中文回复，不要输出角色名、Markdown、JSON、工具调用或解释。"
    "如果内容不清楚，请礼貌地请主人再说一次。"
)
MAX_REPLY_CHARS = 512


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Run one MiMo ASR -> LLM -> TTS machine-dog reply."
    )
    parser.add_argument(
        "--wav",
        type=Path,
        default=DEFAULT_WAV,
        help="mono PCM16 input WAV; 16/24 kHz (default: contest test.wav)",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=DEFAULT_OUTPUT,
        help="output TTS WAV path (default: ./robot_reply.wav)",
    )
    parser.add_argument(
        "--base-url",
        default=os.environ.get("BASE_URL", DEFAULT_BASE_URL),
        help="MiMo OpenAI-compatible base URL (or BASE_URL)",
    )
    parser.add_argument(
        "--system-prompt",
        default=os.environ.get("MIMO_ROBOT_SYSTEM_PROMPT", DEFAULT_SYSTEM_PROMPT),
        help="robot-dog persona prompt (or MIMO_ROBOT_SYSTEM_PROMPT)",
    )
    parser.add_argument(
        "--play",
        action="store_true",
        help="play the generated WAV once with a locally available player",
    )
    return parser.parse_args()


def write_output(path: Path, audio_b64: str) -> int:
    try:
        import base64 as _base64

        audio = _base64.b64decode(audio_b64, validate=True)
    except (ValueError, _base64.binascii.Error):
        raise ProbeError("tts", "invalid_audio_base64")
    if not audio:
        raise ProbeError("tts", "empty_audio")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("wb") as output:
            output.write(audio)
    except OSError:
        raise ProbeError("output", "wav_write_failed")
    return len(audio)


def load_robot_input_wav(path: Path) -> bytes:
    """Load an ASR WAV, normalizing the board speaker-rate sample to 16 kHz."""
    try:
        raw = path.read_bytes()
    except OSError:
        raise ProbeError("input", "wav_read_failed")
    if len(raw) > MAX_WAV_BYTES:
        raise ProbeError("input", "wav_too_large")
    try:
        with wave.open(io.BytesIO(raw), "rb") as wav_file:
            channels = wav_file.getnchannels()
            width = wav_file.getsampwidth()
            rate = wav_file.getframerate()
            frames = wav_file.getnframes()
            pcm = wav_file.readframes(frames)
    except (EOFError, OSError, wave.Error):
        raise ProbeError("input", "invalid_wav")
    if channels != 1:
        raise ProbeError("input", "wav_not_mono")
    if width != 2:
        raise ProbeError("input", "wav_not_pcm16")
    if frames <= 0:
        raise ProbeError("input", "wav_has_no_frames")
    if rate == 16000:
        return raw
    if rate != 24000:
        raise ProbeError("input", "wav_rate_unsupported")

    source = array("h")
    source.frombytes(pcm)
    if sys.byteorder != "little":
        source.byteswap()
    target_count = (len(source) * 2) // 3
    target = array("h")
    for index in range(target_count):
        source_pos = index * 1.5
        left = int(source_pos)
        right = min(left + 1, len(source) - 1)
        fraction = source_pos - left
        sample = int(source[left] + (source[right] - source[left]) * fraction)
        target.append(max(-32768, min(32767, sample)))
    if sys.byteorder != "little":
        target.byteswap()
    normalized = io.BytesIO()
    with wave.open(normalized, "wb") as output:
        output.setnchannels(1)
        output.setsampwidth(2)
        output.setframerate(16000)
        output.writeframes(target.tobytes())
    return normalized.getvalue()


def play_once(path: Path) -> None:
    player = next(
        (name for name in ("aplay", "ffplay", "paplay") if shutil.which(name)),
        None,
    )
    if player is None:
        raise ProbeError("playback", "no_audio_player")
    if player == "ffplay":
        command = [player, "-nodisp", "-autoexit", str(path)]
    else:
        command = [player, str(path)]
    try:
        result = subprocess.run(command, check=False, timeout=120)
    except (OSError, subprocess.TimeoutExpired):
        raise ProbeError("playback", "player_failed")
    if result.returncode != 0:
        raise ProbeError("playback", "player_failed")


def run_once(args: argparse.Namespace) -> int:
    api_key = os.environ.get("MIMO_API_KEY")
    if not api_key:
        raise ProbeError("config", "missing_api_key")
    if not args.system_prompt.strip():
        raise ProbeError("config", "empty_system_prompt")

    endpoint = endpoint_from_base(args.base_url)
    wav_data = load_robot_input_wav(args.wav)
    asr_payload = {
        "model": "mimo-v2.5-asr",
        "messages": [{
            "role": "user",
            "content": [{
                "type": "input_audio",
                "input_audio": {
                    "data": "data:audio/wav;base64," +
                    base64.b64encode(wav_data).decode("ascii"),
                },
            }],
        }],
        "asr_options": {"language": "zh"},
    }
    _, asr_response, _ = post_json(endpoint, api_key, "ASR", asr_payload)
    asr_text = choices_message_content(asr_response, "asr").strip()
    if not asr_text:
        raise ProbeError("asr", "empty_text")

    llm_payload = {
        "model": LLM_MODEL,
        "messages": [
            {"role": "system", "content": args.system_prompt},
            {"role": "user", "content": asr_text},
        ],
        "thinking": {"type": "disabled"},
    }
    if len(bounded_json(llm_payload, "llm")) > MAX_REQUEST_BYTES:
        raise ProbeError("llm", "request_too_large")
    _, llm_response, _ = post_json(endpoint, api_key, "LLM", llm_payload)
    reply = choices_message_content(llm_response, "llm").strip()
    if not reply:
        raise ProbeError("llm", "empty_reply")
    if len(reply) > MAX_REPLY_CHARS:
        reply = reply[:MAX_REPLY_CHARS].rstrip() + "。"

    tts_payload = {
        "model": TTS_MODEL,
        "messages": [{"role": "assistant", "content": reply}],
        "audio": {"format": "wav", "voice": TTS_VOICE},
    }
    _, tts_response, _ = post_json(endpoint, api_key, "TTS", tts_payload)
    audio_b64 = choices_audio_data(tts_response, "tts")
    audio_bytes = decode_tts_wav(audio_b64)
    output_bytes = write_output(args.output, audio_b64)

    print(f"DOG ASR chars: {len(asr_text)}")
    print(f"DOG REPLY chars: {len(reply)}")
    print(f"DOG AUDIO: {args.output} ({output_bytes} bytes)")
    if audio_bytes != output_bytes:
        raise ProbeError("output", "audio_size_changed")
    if args.play:
        play_once(args.output)
        print("DOG PLAYBACK: complete")
    return 0


def main() -> int:
    try:
        return run_once(parse_args())
    except ProbeError as exc:
        sys.stderr.write(f"error stage={exc.stage} code={exc.code}\n")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

