   785	static int shell_quote(const char* src, char* buf, size_t buf_size)
   786	{
   787	    size_t out = 0;
   788	    if (buf_size < 3) return -1; /* need at least '' + NUL */
   789	    buf[out++] = '\'';
   790	    for (const char* p = src; *p; p++) {
   791	        if (*p == '\'') {
   792	            if (out + 4 >= buf_size) return -1;
   793	            buf[out++] = '\'';
   794	            buf[out++] = '\\';
   795	            buf[out++] = '\'';
