int voice_channel_init(void)
{
    syslog(LOG_INFO, "[%s] Voice channel initializing\n", TAG);

    /* Reset state on init — static vars may persist across process restarts
     * in NuttX depending on how the binary is loaded. */
    s_voice.state = VOICE_IDLE;
    s_voice.cap = NULL;
    s_voice.pcm_buf = NULL;
    s_voice.pcm_len = 0;
    s_voice.asr_stream = NULL;
    s_voice.tts_abort = 0;
    s_voice.tts_pb = NULL;
    sem_init(&s_voice.rec_ready, 0, 0);

    if (!s_backends_registered) {
        /* MiMo is the default backend for the contest voice path. */
        mimo_tts_register();
        mimo_asr_register();
        /* Keep Volcengine available for compatibility and fallback. */
        volc_tts_register();
        volc_asr_register();
        s_backends_registered = 1;
    }

    return 0;
}

int voice_channel_process_pcm(const unsigned char *pcm_data,
                              size_t pcm_len,
                              char *text_out,
                              size_t text_cap)
{
    int ret;

    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
        return -EINVAL;
    }

    text_out[0] = '\0';
    if (!voice_asr_get_backend()) {
        ret = voice_channel_init();
        if (ret < 0) {
            return ret;
        }
    }

    ret = voice_asr_recognize(pcm_data, pcm_len, text_out, text_cap);
    if (ret < 0) {
        return ret;
    }

    if (text_out[0] != '\0') {
        ret = dispatch_voice_text(text_out);
        if (ret < 0) {
            return ret;
        }
    }
    return 0;
}

