#define BOARD_I2S_CAPTURE_BLOCK_BYTES 1024
#define BOARD_I2S_CAPTURE_TIMEOUT_MS 1000
#define BOARD_I2S_CAPTURE_WARMUP_BYTES 2048

static void board_i2s_capture_done(struct i2s_dev_s* dev,
    struct ap_buffer_s* apb, void* arg, int result)
{
    audio_capture_t* cap = arg;

    (void)dev;
    cap->i2s_nbytes = apb ? apb->nbytes : 0;
    cap->i2s_result = result;
    cap->i2s_pending = 0;
    nxsem_post(&cap->i2s_done);
}

static int open_board_i2s_capture(audio_capture_t* cap,
    unsigned int sample_rate, unsigned int channels,
    unsigned int bits_per_sample)
{
    int actual;
    int ret;

    if (channels != 1 || bits_per_sample != 16) {
        return -ENOTSUP;
    }

    cap->i2s = board_voice_mic_i2s();
    if (!cap->i2s) {
        return -ENODEV;
    }

    ret = I2S_RXCHANNELS(cap->i2s, channels);
    if (ret < 0) {
        return ret;
    }

    actual = (int)I2S_RXSAMPLERATE(cap->i2s, sample_rate);
    if (actual != (int)sample_rate) {
        return actual < 0 ? actual : -ENOTSUP;
    }

    actual = (int)I2S_RXDATAWIDTH(cap->i2s, bits_per_sample);
    if (actual != (int)bits_per_sample) {
        return actual < 0 ? actual : -ENOTSUP;
    }

    nxsem_init(&cap->i2s_done, 0, 0);
    cap->backend = AUDIO_CAPTURE_BACKEND_BOARD_I2S;
    cap->bits_per_sample = bits_per_sample;
    cap->requested_channels = channels;
    cap->hw_channels = channels;
    cap->out_frame_bytes = (bits_per_sample / 8) * channels;
    cap->hw_frame_bytes = cap->out_frame_bytes;
    cap->warmup_bytes = BOARD_I2S_CAPTURE_WARMUP_BYTES;

    syslog(LOG_INFO, "[%s] opened contest I2S capture (%uHz %uch %ubit)\n",
        TAG, sample_rate, channels, bits_per_sample);
    return 0;
}

static int board_i2s_read_block(audio_capture_t* cap, void* buf,
    size_t cap_len, size_t* nbytes_out)
{
    struct audio_buf_desc_s desc;
    struct ap_buffer_s* apb = NULL;
    size_t request = cap_len;
    int ret;

    if (request > BOARD_I2S_CAPTURE_BLOCK_BYTES) {
        request = BOARD_I2S_CAPTURE_BLOCK_BYTES;
    }
    request -= request % cap->out_frame_bytes;
    if (request == 0) {
        return -EINVAL;
    }

    memset(&desc, 0, sizeof(desc));
    desc.numbytes = request;
    desc.u.pbuffer = &apb;
    ret = apb_alloc(&desc);
    if (ret < 0) {
        return ret;
    }

    while (nxsem_trywait(&cap->i2s_done) == 0)
        ;

    cap->i2s_apb = apb;
    cap->i2s_nbytes = 0;
    cap->i2s_result = -EINPROGRESS;
    cap->i2s_pending = 1;
    ret = I2S_RECEIVE(cap->i2s, apb, board_i2s_capture_done, cap,
        MSEC2TICK(BOARD_I2S_CAPTURE_TIMEOUT_MS));
    if (ret < 0) {
        cap->i2s_pending = 0;
        cap->i2s_apb = NULL;
        apb_free(apb);
        return ret;
    }

    ret = nxsem_tickwait(&cap->i2s_done,
        MSEC2TICK(BOARD_I2S_CAPTURE_TIMEOUT_MS));
    if (ret < 0) {
        I2S_IOCTL(cap->i2s, AUDIOIOC_STOP, 0);
        ret = nxsem_tickwait(&cap->i2s_done,
            MSEC2TICK(BOARD_I2S_CAPTURE_TIMEOUT_MS));
    }

    if (ret >= 0) {
        ret = cap->i2s_result;
    }

    if (ret >= 0 && cap->i2s_nbytes > 0) {
        size_t nbytes = cap->i2s_nbytes;

        if (nbytes > request) {
            ret = -EIO;
        } else {
            memcpy(buf, apb->samp, nbytes);
            *nbytes_out = nbytes;
        }
    }

    cap->i2s_pending = 0;
    cap->i2s_apb = NULL;
    apb_free(apb);
    return ret;
}

