static const char* resolve_alsa_name(const char* dev_path)
{
    if (!dev_path || dev_path[0] == '\0') {
        return CAP_ALSA_NAME_DEFAULT;
    }

    if (strncmp(dev_path, "/dev/audio/", strlen("/dev/audio/")) == 0) {
        return CAP_ALSA_NAME_DEFAULT;
