739	    /* Open capture device (but do NOT start yet — start after the
740	     * recording thread is spawned so the consumer is ready before
741	     * audio frames begin flowing, preventing media_recorder queue
742	     * overflow "data queue is more than max count(4)"). */
743	    s_voice.cap = audio_capture_open(
744	        AGENT_AUDIO_CAPTURE_DEV,
745	        AGENT_VOICE_SAMPLE_RATE,
746	        AGENT_VOICE_CHANNELS,
747	        AGENT_VOICE_BITS);
748	
749	    if (!s_voice.cap) {
750	        if (pre_stream) {
751	            voice_asr_stream_abort(pre_stream);
752	            s_voice.asr_stream = NULL;
753	        }
754	        pthread_mutex_unlock(&s_voice.lock);
755	        syslog(LOG_ERR, "[%s] capture open failed\n", TAG);
756	        return -EIO;
757	    }
758	
759	    s_voice.state = VOICE_RECORDING;
760	    pthread_mutex_unlock(&s_voice.lock);
761	
762	    /* Spawn recording thread BEFORE starting capture */
763	    pthread_attr_t attr;
764	
765	    pthread_attr_init(&attr);
766	    pthread_attr_setstacksize(&attr, AGENT_VOICE_STACK);
767	
768	    int ret = pthread_create(&s_voice.rec_thread, &attr,
769	        recording_thread, NULL);
770	
771	    pthread_attr_destroy(&attr);
772	
773	    if (ret != 0) {
774	        pthread_mutex_lock(&s_voice.lock);
775	        s_voice.state = VOICE_IDLE;
776	        audio_capture_close(s_voice.cap);
777	        s_voice.cap = NULL;
778	        if (s_voice.asr_stream) {
779	            voice_asr_stream_abort(s_voice.asr_stream);
780	            s_voice.asr_stream = NULL;
781	        }
782	        free(s_voice.pcm_buf);
783	        s_voice.pcm_buf = NULL;
784	        pthread_mutex_unlock(&s_voice.lock);
785	        return -ret;
786	    }
787	
788	    /* Now start capture — wait for recording thread to be ready first */
789	    sem_wait(&s_voice.rec_ready);
790	
791	    if (audio_capture_start(s_voice.cap) < 0) {
792	        pthread_mutex_lock(&s_voice.lock);
793	        s_voice.state = VOICE_IDLE;
794	        if (s_voice.asr_stream) {
795	            voice_asr_stream_abort(s_voice.asr_stream);
796	            s_voice.asr_stream = NULL;
797	        }
798	        pthread_mutex_unlock(&s_voice.lock);
799	        audio_capture_abort(s_voice.cap);
800	        pthread_join(s_voice.rec_thread, NULL);
801	        audio_capture_close(s_voice.cap);
802	        s_voice.cap = NULL;
803	        return -EIO;
804	    }
805	
806	    syslog(LOG_INFO, "[%s] PTT recording started\n", TAG);
807	    printf("Voice: recording... (use voice_stop to finish)\n");
808	    return 0;
809	}
