        return 0;
    }

    if (claw_config_get(AGENT_CFG_KEY_API_KEY, out, cap) == OK
        && out[0] != '\0') {
        return 0;
    }

    out[0] = '\0';
    return -ENOENT;
}

static void get_endpoint(char *host, size_t host_cap,
                         char *path, size_t path_cap)
{
    char configured[128] = { 0 };

    strncpy(host, AGENT_MIMO_VOICE_HOST, host_cap - 1);
    strncpy(path, AGENT_MIMO_VOICE_PATH, path_cap - 1);

    /* Reuse the already configured MiMo gateway when set_llm points at it. */
    if (claw_config_get(AGENT_CFG_KEY_LLM_HOST,
                        configured, sizeof(configured)) == OK
        && strstr(configured, "xiaomimimo.com") != NULL) {
        strncpy(host, configured, host_cap - 1);
    }

    configured[0] = '\0';
    if (claw_config_get(AGENT_CFG_KEY_LLM_PATH,
                        configured, sizeof(configured)) == OK
        && strstr(configured, "chat/completions") != NULL) {
        strncpy(path, configured, path_cap - 1);
    }

    host[host_cap - 1] = '\0';
    path[path_cap - 1] = '\0';
}

static int post_mimo(const char *body, char *response, size_t response_cap)
{
    char key[256] = { 0 };
    char host[128] = { 0 };
    char path[128] = { 0 };
    char auth[320];
    vela_header_t headers[2];
    int status;

    if (get_api_key(key, sizeof(key)) < 0) {
        syslog(LOG_ERR, "[%s] No API key; use set_llm or set_mimo_key\n", TAG);
        return -EACCES;
    }

    get_endpoint(host, sizeof(host), path, sizeof(path));
    snprintf(auth, sizeof(auth), "Bearer %s", key);
    headers[0].name = "Authorization";
    headers[0].value = auth;
    headers[1].name = NULL;
    headers[1].value = NULL;

    status = vela_https_post_json(host, AGENT_MIMO_VOICE_PORT, path,
        headers, body, response, response_cap);
    memset(key, 0, sizeof(key));

    if (status < 200 || status >= 300) {
        syslog(LOG_ERR, "[%s] HTTPS request status=%d\n", TAG, status);
        return status > 0 ? -EIO : status;
    }

    return 0;
}

static int make_wav(const unsigned char *pcm, size_t pcm_len,
                    unsigned char **wav_out, size_t *wav_len)
{
    unsigned char *wav;

    if (!pcm || !wav_out || !wav_len || pcm_len > UINT32_MAX - 44) {
        return -EINVAL;
    }

    wav = malloc(pcm_len + 44);
    if (!wav) {
        return -ENOMEM;
    }

    memset(wav, 0, pcm_len + 44);
    memcpy(wav, "RIFF", 4);
    write_le32(wav + 4, (uint32_t)(pcm_len + 36));
    memcpy(wav + 8, "WAVEfmt ", 8);
    write_le32(wav + 16, 16);
    write_le16(wav + 20, 1);
    write_le16(wav + 22, AGENT_VOICE_CHANNELS);
    write_le32(wav + 24, AGENT_VOICE_SAMPLE_RATE);
    write_le32(wav + 28, AGENT_VOICE_SAMPLE_RATE
        * AGENT_VOICE_CHANNELS * (AGENT_VOICE_BITS / 8));
    write_le16(wav + 32, AGENT_VOICE_CHANNELS * (AGENT_VOICE_BITS / 8));
    write_le16(wav + 34, AGENT_VOICE_BITS);
    memcpy(wav + 36, "data", 4);
    write_le32(wav + 40, (uint32_t)pcm_len);
    memcpy(wav + 44, pcm, pcm_len);

    *wav_out = wav;
    *wav_len = pcm_len + 44;
    return 0;
}

static int json_string(cJSON *root, const char *field,
                       char *out, size_t cap)
{
    cJSON *choices = cJSON_GetObjectItemCaseSensitive(root, "choices");
    cJSON *first;
    cJSON *message;
    cJSON *item;

    if (!cJSON_IsArray(choices) || cJSON_GetArraySize(choices) < 1) {
        return -EPROTO;
    }
    first = cJSON_GetArrayItem(choices, 0);
    message = cJSON_GetObjectItemCaseSensitive(first, "message");
    item = message ? cJSON_GetObjectItemCaseSensitive(message, field) : NULL;
    if (!cJSON_IsString(item) || !item->valuestring) {
        return -EPROTO;
    }

    strncpy(out, item->valuestring, cap - 1);
    out[cap - 1] = '\0';
    return 0;
}

static int json_audio_data(cJSON *root, const char **data_out)
{
    cJSON *choices = cJSON_GetObjectItemCaseSensitive(root, "choices");
    cJSON *first;
    cJSON *message;
    cJSON *audio;
    cJSON *data;

    if (!cJSON_IsArray(choices) || cJSON_GetArraySize(choices) < 1) {
        return -EPROTO;
    }
    first = cJSON_GetArrayItem(choices, 0);
    message = cJSON_GetObjectItemCaseSensitive(first, "message");
    audio = message ? cJSON_GetObjectItemCaseSensitive(message, "audio") : NULL;
    data = audio ? cJSON_GetObjectItemCaseSensitive(audio, "data") : NULL;
    if (!cJSON_IsString(data) || !data->valuestring
        || data->valuestring[0] == '\0') {
        return -EPROTO;
    }

    *data_out = data->valuestring;
    return 0;
}

static int make_asr_body(const unsigned char *pcm, size_t pcm_len,
                         char **body_out)
{
    unsigned char *wav = NULL;
    size_t wav_len = 0;
    size_t b64_cap;
    size_t b64_len = 0;
    char *b64 = NULL;
    char *data_uri = NULL;
    cJSON *root = NULL;
    cJSON *messages;
    cJSON *message;
    cJSON *content;
    cJSON *audio_item;
    cJSON *audio;
    char *body;
    int ret;

    ret = make_wav(pcm, pcm_len, &wav, &wav_len);
    if (ret < 0) {
        return ret;
    }

    b64_cap = ((wav_len + 2) / 3) * 4 + 1;
    b64 = malloc(b64_cap);
    if (!b64) {
        free(wav);
        return -ENOMEM;
    }

    ret = mbedtls_base64_encode((unsigned char *)b64, b64_cap - 1,
        &b64_len, wav, wav_len);
    free(wav);
    if (ret != 0) {
        free(b64);
        return -EIO;
    }
    b64[b64_len] = '\0';

    data_uri = malloc(b64_len + 24);
    if (!data_uri) {
        free(b64);
        return -ENOMEM;
    }
    snprintf(data_uri, b64_len + 24, "data:audio/wav;base64,%s", b64);
    free(b64);

    root = cJSON_CreateObject();
    messages = cJSON_CreateArray();
    message = cJSON_CreateObject();
    content = cJSON_CreateArray();
    audio_item = cJSON_CreateObject();
    audio = cJSON_CreateObject();
    if (!root || !messages || !message || !content || !audio_item || !audio) {
        cJSON_Delete(root);
        cJSON_Delete(messages);
        cJSON_Delete(message);
        cJSON_Delete(content);
        cJSON_Delete(audio_item);
        cJSON_Delete(audio);
        free(data_uri);
        return -ENOMEM;
    }

    cJSON_AddStringToObject(root, "model", AGENT_MIMO_ASR_MODEL);
    cJSON_AddStringToObject(message, "role", "user");
    cJSON_AddStringToObject(audio_item, "type", "input_audio");
    cJSON_AddStringToObject(audio, "data", data_uri);
    cJSON_AddItemToObject(audio_item, "input_audio", audio);
    cJSON_AddItemToArray(content, audio_item);
    cJSON_AddItemToObject(message, "content", content);
    cJSON_AddItemToArray(messages, message);
    cJSON_AddItemToObject(root, "messages", messages);
    cJSON_AddItemToObject(root, "asr_options", cJSON_CreateObject());
    cJSON_AddStringToObject(cJSON_GetObjectItem(root, "asr_options"),
        "language", "zh");

    body = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    free(data_uri);
    if (!body) {
        return -ENOMEM;
    }

    *body_out = body;
    return 0;
}

static int mimo_asr_init(void)
{
    char key[256] = { 0 };
    int ret = get_api_key(key, sizeof(key));
    memset(key, 0, sizeof(key));
    if (ret < 0) {
        syslog(LOG_WARNING, "[%s] ASR API key is not configured\n", TAG);
    }
    return 0;
}

static int mimo_asr_recognize(const unsigned char *pcm_data,
                              size_t pcm_len,
                              char *text_out,
                              size_t text_cap)
{
    char *body = NULL;
    char *response = NULL;
    cJSON *root = NULL;
    int ret;

    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
        return -EINVAL;
    }
    if (pcm_len > AGENT_MIMO_MAX_AUDIO_BYTES) {
        return -EFBIG;
    }

    ret = make_asr_body(pcm_data, pcm_len, &body);
    if (ret < 0) {
        return ret;
    }

    response = calloc(1, AGENT_MIMO_HTTP_RESP_BYTES);
    if (!response) {
        free(body);
        return -ENOMEM;
    }

    ret = post_mimo(body, response, AGENT_MIMO_HTTP_RESP_BYTES);
    free(body);
    if (ret < 0) {
        free(response);
        return ret;
    }

    root = cJSON_Parse(response);
    free(response);
    if (!root) {
        return -EPROTO;
    }

    ret = json_string(root, "content", text_out, text_cap);
    cJSON_Delete(root);
    if (ret == 0) {
        syslog(LOG_INFO, "[%s] ASR recognized %zu bytes\n", TAG, pcm_len);
    }
    return ret;
}

static int make_tts_body(const char *text, char **body_out)
{
    cJSON *root = cJSON_CreateObject();
    cJSON *messages = cJSON_CreateArray();
    cJSON *message = cJSON_CreateObject();
    cJSON *audio = cJSON_CreateObject();
    char *body;

    if (!root || !messages || !message || !audio) {
        cJSON_Delete(root);
        cJSON_Delete(messages);
        cJSON_Delete(message);
        cJSON_Delete(audio);
        return -ENOMEM;
    }

    cJSON_AddStringToObject(root, "model", AGENT_MIMO_TTS_MODEL);
    cJSON_AddStringToObject(message, "role", "assistant");
    cJSON_AddStringToObject(message, "content", text);
    cJSON_AddItemToArray(messages, message);
    cJSON_AddItemToObject(root, "messages", messages);
    cJSON_AddStringToObject(audio, "format", "wav");
    cJSON_AddStringToObject(audio, "voice", AGENT_MIMO_TTS_VOICE);
    cJSON_AddItemToObject(root, "audio", audio);

    body = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    if (!body) {
        return -ENOMEM;
    }
    *body_out = body;
    return 0;
}

static int extract_wav_pcm(const unsigned char *wav, size_t wav_len,
                           unsigned char *pcm_out, size_t pcm_cap,
                           size_t *pcm_len)
{
    size_t pos = 12;
    uint32_t sample_rate = 0;
    uint16_t channels = 0;
    uint16_t bits = 0;
    const unsigned char *data = NULL;
    size_t data_len = 0;

    if (wav_len < 44 || memcmp(wav, "RIFF", 4) != 0
        || memcmp(wav + 8, "WAVE", 4) != 0) {
        return -EPROTO;
    }

    while (pos + 8 <= wav_len) {
        const unsigned char *chunk = wav + pos;
        uint32_t chunk_len = read_le32(chunk + 4);
        size_t next = pos + 8 + chunk_len + (chunk_len & 1U);
        if (next > wav_len) {
            return -EPROTO;
        }
        if (memcmp(chunk, "fmt ", 4) == 0 && chunk_len >= 16) {
            const unsigned char *fmt = chunk + 8;
            if (read_le16(fmt) != 1) {
                return -ENOTSUP;
            }
            channels = read_le16(fmt + 2);
            sample_rate = read_le32(fmt + 4);
            bits = read_le16(fmt + 14);
        } else if (memcmp(chunk, "data", 4) == 0) {
            data = chunk + 8;
            data_len = chunk_len;
        }
        pos = next;
    }

    if (!data || channels != 1 || bits != 16 || sample_rate == 0) {
        return -EPROTO;
    }
    if (sample_rate != AGENT_MIMO_TTS_SAMPLE_RATE) {
        syslog(LOG_ERR, "[%s] TTS sample rate %lu unsupported\n",
            TAG, (unsigned long)sample_rate);
        return -ENOTSUP;
    }
    if (data_len > pcm_cap) {
        return -ENOSPC;
    }

    memcpy(pcm_out, data, data_len);
    *pcm_len = data_len;
    return 0;
}

static int mimo_tts_init(void)
{
    return mimo_asr_init();
}

static int mimo_tts_synthesize(const char *text,
                               unsigned char *pcm_out,
                               size_t pcm_cap,
                               size_t *pcm_len)
{
    char *body = NULL;
    char *response = NULL;
    const char *audio_b64 = NULL;
    unsigned char *wav = NULL;
    size_t wav_cap;
    size_t wav_len = 0;
    size_t decoded_len = 0;
    cJSON *root = NULL;
    int ret;

    if (!text || text[0] == '\0' || !pcm_out || !pcm_len) {
        return -EINVAL;
    }

    ret = make_tts_body(text, &body);
    if (ret < 0) {
        return ret;
    }
    response = calloc(1, AGENT_MIMO_HTTP_RESP_BYTES);
    if (!response) {
        free(body);
        return -ENOMEM;
    }

    ret = post_mimo(body, response, AGENT_MIMO_HTTP_RESP_BYTES);
    free(body);
    if (ret < 0) {
        free(response);
        return ret;
    }

    root = cJSON_Parse(response);
    free(response);
    if (!root) {
        return -EPROTO;
    }
    ret = json_audio_data(root, &audio_b64);
    if (ret < 0) {
        cJSON_Delete(root);
        return ret;
    }

    wav_cap = (strlen(audio_b64) * 3) / 4 + 4;
    wav = malloc(wav_cap);
    if (!wav) {
        cJSON_Delete(root);
        return -ENOMEM;
    }
    ret = mbedtls_base64_decode(wav, wav_cap, &wav_len,
        (const unsigned char *)audio_b64, strlen(audio_b64));
    cJSON_Delete(root);
    if (ret != 0) {
        free(wav);
        return -EPROTO;
    }

    ret = extract_wav_pcm(wav, wav_len, pcm_out, pcm_cap, &decoded_len);
    free(wav);
    if (ret == 0) {
        *pcm_len = decoded_len;
        syslog(LOG_INFO, "[%s] TTS PCM bytes=%zu\n", TAG, decoded_len);
    }
    return ret;
}

static const voice_asr_ops_t s_mimo_asr_ops = {
    .name = MIMO_ASR_BACKEND_NAME,
    .init = mimo_asr_init,
    .recognize = mimo_asr_recognize,
    .stream_open = NULL,
    .stream_send = NULL,
    .stream_finish = NULL,
    .stream_abort = NULL,
    .deinit = NULL,
};

