def endpoint_from_base(base_url: str) -> str:
    normalized = base_url.rstrip("/")
    if not normalized:
        fail("config", "empty_base_url")
    endpoint = f"{normalized}/chat/completions"
    if "/v1/v1/" in endpoint or endpoint.endswith("/v1/v1"):
        fail("config", "duplicate_v1_path")
    return endpoint


def run() -> int:
    api_key = os.environ.get("MIMO_API_KEY")
    wav_path = os.environ.get("MIMO_WAV_PATH")
    base_url = os.environ.get("BASE_URL", DEFAULT_BASE_URL)
    if not api_key:
        fail("config", "missing_api_key")
    if not wav_path:
        fail("config", "missing_wav_path")
    endpoint = endpoint_from_base(base_url)
    wav_data = load_wav(wav_path)

    asr_payload = {
        "model": ASR_MODEL,
        "messages": [{
            "role": "user",
            "content": [{
                "type": "input_audio",
                "input_audio": {
                    "data": "data:audio/wav;base64," +
                    base64.b64encode(wav_data).decode("ascii"),
                },
            }],
        }],
        "asr_options": {"language": "zh"},
    }
    _, asr_response, asr_bytes = post_json(
        endpoint, api_key, "ASR", asr_payload
    )
    print_top_level("ASR", asr_response)
    asr_text = choices_message_content(asr_response, "asr")
    print(f"ASR text length: {len(asr_text)}")

    llm_payload = {
        "model": LLM_MODEL,
        "messages": [{"role": "user", "content": asr_text}],
        "thinking": {"type": "disabled"},
    }
    _, llm_response, llm_bytes = post_json(
        endpoint, api_key, "LLM", llm_payload
    )
    print_top_level("LLM", llm_response)
    llm_text = choices_message_content(llm_response, "llm")
    print(f"LLM text length: {len(llm_text)}")

    tts_payload = {
        "model": TTS_MODEL,
        "messages": [{"role": "assistant", "content": llm_text}],
        "audio": {"format": "wav", "voice": TTS_VOICE},
    }
    _, tts_response, tts_bytes = post_json(
        endpoint, api_key, "TTS", tts_payload
    )
    print_top_level("TTS", tts_response)
    audio_b64 = choices_audio_data(tts_response, "tts")
    print(f"TTS Base64 length: {len(audio_b64)}")
    print(f"TTS WAV decoded bytes: {decode_tts_wav(audio_b64)}")
    _ = (asr_bytes, llm_bytes, tts_bytes)
    return 0


def main() -> int:
    try:
        return run()
    except ProbeError as exc:
        sys.stderr.write(f"error stage={exc.stage} code={exc.code}\n")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
}

