    char auth[160];

    snprintf(auth, sizeof(auth), "Bearer %s", api_key);
    hdrs[0].name = "Authorization";
    hdrs[0].value = auth;
    hdrs[1].name = "Accept";
    hdrs[1].value = "application/json";
    hdrs[2].name = NULL;
