int voice_channel_record_once(unsigned int duration_ms)
{
    int ret;

    if (duration_ms == 0 || duration_ms > 30000) {
        return -EINVAL;
    }

    ret = voice_channel_start();
    if (ret < 0) {
        return ret;
    }

    usleep((useconds_t)duration_ms * 1000U);
    return voice_channel_stop();
}

