   217	/****************************************************************************
   218	 * Name: syslog_write
   219	 *
   220	 * Description:
   221	 *   This is the low-level, multiple character, system logging interface.
   222	 *
   223	 * Input Parameters:
   224	 *   buffer - The buffer containing the data to be output
   225	 *   buflen - The number of bytes in the buffer
   226	 *
   227	 * Returned Value:
   228	 *   On success, the number of characters written is returned.  A negated
   229	 *   errno value is returned on any failure.
   230	 *
   231	 ****************************************************************************/
   232	
   233	ssize_t syslog_write(FAR const char *buffer, size_t buflen)
   234	{
   235	  bool force = !syslog_safe_to_block();
   236	
   237	#ifdef CONFIG_SYSLOG_INTBUFFER
   238	  if (force)
   239	    {
   240	      syslog_add_intbuffer(buffer, buflen);
   241	      return buflen;
   242	    }
   243	  else
   244	    {
   245	      /* Flush any characters that may have been added to the interrupt
   246	       * buffer.
   247	       */
   248	
   249	      syslog_flush_intbuffer(false);
   250	    }
   251	#endif
   252	
   253	  return syslog_write_foreach(buffer, buflen, force);
   254	}

