   418	static int board_i2s_read_block(audio_capture_t* cap, void* buf,
   419	    size_t cap_len, size_t* nbytes_out)
   420	{
   421	    struct audio_buf_desc_s desc;
   422	    struct ap_buffer_s* apb = NULL;
   423	    size_t request = cap_len;
   424	    int ret;
   425	
   426	    /* voice_channel_start() deliberately starts the reader thread before
   427	     * enabling the device.  Let that short hand-off window be retried by the
   428	     * reader instead of submitting to a stopped I2S stream (which returns
   429	     * -EBUSY from the contest lower half). */
   430	    if (!cap->started) {
   431	        return -EAGAIN;
   432	    }
   433	
   434	    if (request > BOARD_I2S_CAPTURE_BLOCK_BYTES) {
   435	        request = BOARD_I2S_CAPTURE_BLOCK_BYTES;
   436	    }
   437	    request -= request % cap->out_frame_bytes;
   438	    if (request == 0) {
   439	        return -EINVAL;
   440	    }
   441	
   442	    memset(&desc, 0, sizeof(desc));
   443	    desc.numbytes = request;
   444	    desc.u.pbuffer = &apb;
   445	    ret = apb_alloc(&desc);
   446	    if (ret < 0) {
   447	        return ret;
   448	    }
   449	
   450	    while (nxsem_trywait(&cap->i2s_done) == 0)
   451	        ;
   452	
   453	    cap->i2s_apb = apb;
   454	    cap->i2s_nbytes = 0;
   455	    cap->i2s_result = -EINPROGRESS;
   456	    cap->i2s_pending = 1;
   457	    ret = I2S_RECEIVE(cap->i2s, apb, board_i2s_capture_done, cap,
   458	        MSEC2TICK(BOARD_I2S_CAPTURE_TIMEOUT_MS));
   459	    if (ret < 0) {
   460	        cap->i2s_pending = 0;
   461	        cap->i2s_apb = NULL;
   462	        apb_free(apb);
   463	        return ret;
   464	    }
   465	
   466	    /* I2S completion owns the lower-half APB reference.  Do not release the
   467	     * application's reference on a timeout: a late callback would otherwise
   468	     * access a freed capture object.  audio_capture_abort() issues STOP,
   469	     * which completes this wait with the driver's cancellation result. */
   470	    ret = nxsem_wait_uninterruptible(&cap->i2s_done);
   471	
   472	    if (ret >= 0) {
   473	        ret = cap->i2s_result;
   474	    }
   475	
   476	    if (ret >= 0 && cap->i2s_nbytes > 0) {
   477	        size_t nbytes = cap->i2s_nbytes;
   478	
   479	        if (nbytes > request) {
   480	            ret = -EIO;
   481	        } else {
   482	            memcpy(buf, apb->samp, nbytes);
   483	            *nbytes_out = nbytes;
   484	        }
   485	    }
   486	
   487	    cap->i2s_pending = 0;
   488	    cap->i2s_apb = NULL;
   489	    apb_free(apb);
   490	    return ret;

