static void tls_diag_log_build_caps(const char* host)
{
    int tls12 = 0;
    int tls13 = 0;
    int sni = 0;
    int alpn = 0;
    int ecdh = 0;
    int rsa = 0;
    int pss = 0;
    int curve25519 = 0;
    int p256 = 0;

#if defined(MBEDTLS_SSL_PROTO_TLS1_2)
    tls12 = 1;
#endif
#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
    tls13 = 1;
#endif
#if defined(MBEDTLS_SSL_SERVER_NAME_INDICATION)
    sni = 1;
#endif
#if defined(MBEDTLS_SSL_ALPN)
    alpn = 1;
#endif
#if defined(MBEDTLS_ECDH_C)
    ecdh = 1;
#endif
#if defined(MBEDTLS_RSA_C)
    rsa = 1;
#endif
#if defined(MBEDTLS_PKCS1_V21)
    pss = 1;
#endif
#if defined(MBEDTLS_ECP_DP_CURVE25519_ENABLED)
    curve25519 = 1;
#endif
#if defined(MBEDTLS_ECP_DP_SECP256R1_ENABLED)
    p256 = 1;
#endif

    syslog(LOG_INFO,
        "[TLS-CAP] host=%s tls12=%d tls13=%d sni=%d alpn=%d "
        "ecdh=%d rsa=%d rsa_pss=%d x25519=%d p256=%d\n",
        host ? host : "(null)", tls12, tls13, sni, alpn,
        ecdh, rsa, pss, curve25519, p256);

    if (tls_is_mimo_host(host) && !sni) {
        syslog(LOG_ERR,
            "[TLS-CAP] MiMo control uses OpenSSL -servername, but this "
            "mbedTLS build has no MBEDTLS_SSL_SERVER_NAME_INDICATION\n");
    }
}

static const char* tls_record_type_name(unsigned char type)
{
    switch (type) {
    case 20:
        return "change_cipher_spec";
    case 21:
        return "alert";
    case 22:
        return "handshake";
    case 23:
        return "application_data";
    default:
        return "unknown";
    }
}

static const char* tls_handshake_type_name(unsigned char type)
{
    switch (type) {
    case 1:
        return "client_hello";
    case 2:
        return "server_hello";
    case 4:
        return "new_session_ticket";
    case 11:
        int res_ret = network_acquire_resource(acquire_ms);
        if (res_ret != 0) {
            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
            return VELA_TLS_ERR_CONNECT;
        }
        syslog(LOG_INFO, "[%s] Network resource acquire OK\n", TAG);
    }
#endif

    if (http_proxy_is_enabled()) {
        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
        if (tunnel_fd < 0) {
            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
                TAG, host, port);
            return VELA_TLS_ERR_CONNECT;
        }
        ctx->net.fd = tunnel_fd;
        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
            TAG, tunnel_fd, host, port);
    } else {
        ret = tls_tcp_connect_ipv4(&ctx->net, host, port);
        if (ret != 0) {
            syslog(LOG_ERR, "[%s] net_connect %s:%s ret=0x%x\n",
                TAG, host, port, -ret);
            return VELA_TLS_ERR_CONNECT;
        }
    }

    /* Force blocking BIO and keep both read/write operations bounded. */
    mbedtls_net_set_block(&ctx->net);
    tls_set_socket_timeouts(ctx->net.fd);

    /* SSL config: client, TLS, default ciphersuites */
    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
             MBEDTLS_SSL_IS_CLIENT,
             MBEDTLS_SSL_TRANSPORT_STREAM,
             MBEDTLS_SSL_PRESET_DEFAULT))
        != 0) {
        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    const int is_mimo = tls_is_mimo_host(host);

    /*
     * Reproduce the known-good MiMo control as closely as possible.
     *
     * Host-side OpenSSL result:
     *   Protocol : TLSv1.2
     *   Cipher   : ECDHE-RSA-AES128-GCM-SHA256
     *   SNI      : token-plan-cn.xiaomimimo.com (-servername)
     *   ALPN     : none negotiated
     *
     * Do not broaden the MiMo cipher list here: the purpose of this run is to
     * isolate ClientHello extension differences, not to guess another cipher.
     */
    if (is_mimo) {
        mbedtls_ssl_conf_ciphersuites(&ctx->cfg, s_mimo_ciphersuites);
    } else {
        mbedtls_ssl_conf_ciphersuites(&ctx->cfg, s_tls_ciphersuites);
    }

    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
    if (is_mimo) {
        mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
            MBEDTLS_SSL_VERSION_TLS1_2);
        syslog(LOG_INFO,
            "[%s] TLS policy: MiMo control = TLS1.2 + "
            "ECDHE-RSA-AES128-GCM-SHA256 + SNI, no forced ALPN\n", TAG);
    } else {
#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
        mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
            MBEDTLS_SSL_VERSION_TLS1_3);
#else
        mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
            MBEDTLS_SSL_VERSION_TLS1_2);
#endif
    }

    /*
     * The successful MiMo OpenSSL control explicitly reported:
     *   "No ALPN negotiated"
     * so do not add an ALPN extension only on the MiMo diagnostic path.
     * Keep the existing HTTP/1.1 ALPN behavior for other endpoints.
     */
#if defined(MBEDTLS_SSL_ALPN)
    if (!is_mimo) {
        static const char* alpn_protos[] = { "http/1.1", NULL };
        if ((ret = mbedtls_ssl_conf_alpn_protocols(&ctx->cfg,
                 alpn_protos)) != 0) {
            syslog(LOG_WARNING,
                "[%s] Failed to set ALPN protocols: -0x%04x "
                "(non-fatal)\n", TAG, -ret);
        }
    }
#endif

    tls_diag_log_build_caps(host);

    /* Skip full chain verification — keeps portability without CA bundle */
    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);

    /* Read timeout is handled at the socket level via SO_RCVTIMEO,
     * not via mbedtls_ssl_conf_read_timeout + mbedtls_net_recv_timeout,
     * because select()/poll() inside mbedtls_net_recv_timeout fails on
     * NuttX/QEMU with MBEDTLS_ERR_NET_POLL_FAILED (-0x0047). */

    if ((ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg)) != 0) {
        syslog(LOG_ERR, "[%s] ssl_setup ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    if ((ret = mbedtls_ssl_set_hostname(&ctx->ssl, host)) != 0) {
        syslog(LOG_ERR, "[%s] ssl_set_hostname ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    /*
     * Route the mbedTLS BIO through handshake-only diagnostic wrappers.
     * The wrappers call the same mbedtls_net_send()/mbedtls_net_recv()
     * underneath, so this does not intentionally change TLS framing or the
     * HTTP application-data path.  It only exposes the actual socket I/O that
     * occurs during negotiation.
     */
    ctx->diag_handshake = true;
    ctx->diag_tx_calls = 0;
    ctx->diag_rx_calls = 0;
    ctx->diag_tx_bytes = 0;
    ctx->diag_rx_bytes = 0;
    mbedtls_ssl_set_bio(&ctx->ssl, ctx,
        tls_diag_send, tls_diag_recv, NULL);

    /* Handshake.  Socket timeouts are already active at this point. */
    syslog(LOG_INFO, "[%s] TLS handshake start: %s:%s fd=%d\n",
        TAG, host, port, ctx->net.fd);
    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
#if defined(MBEDTLS_ERROR_C)
            char err_buf[128];
            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n", TAG, -ret, err_buf);
#else
            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", TAG, -ret);
#endif
            /* Log common peer-side negotiation failures explicitly. */
            if (ret == MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE) {
                syslog(LOG_ERR, "[%s] Server sent fatal TLS alert\n", TAG);
            }
#ifdef MBEDTLS_ERR_SSL_CONN_EOF
            if (ret == MBEDTLS_ERR_SSL_CONN_EOF) {
                syslog(LOG_ERR,
                    "[%s] Peer closed during TLS negotiation; "
                    "inspect [TLS-IO] TX/RX records above\n",
                    TAG);
            }

