   180	    int fsz = PREPROC_FRAME_SIZE;
   181	    int32_t in32[PREPROC_FRAME_SIZE];
   182	    int32_t ref32[PREPROC_FRAME_SIZE];
   183	    int32_t out32[PREPROC_FRAME_SIZE];
   184	
   185	    memset(ref32, 0, sizeof(ref32));
   186	
   187	    for (int off = 0; off < total; off += fsz) {
   188	        int n = (off + fsz <= total) ? fsz : (total - off);
   189	
   190	        for (int i = 0; i < n; i++) {
   191	            in32[i] = samples[off + i];
   192	        }
   193	
   194	        if (pp->ns) {
