   315	
   316	static void recording_cleanup_locked(voice_asr_stream_t* stream)
   317	{
   318	    /* Abort streaming ASR if active */
   319	    if (stream) {
   320	        voice_asr_stream_abort(stream);
   321	        s_voice.asr_stream = NULL;
   322	    }
   323	
   324	    /* Close capture device */
   325	    if (s_voice.cap) {
   326	        audio_capture_close(s_voice.cap);
   327	        s_voice.cap = NULL;
   328	    }
   329	
   330	    /* Free PCM buffer */
   331	    free(s_voice.pcm_buf);
   332	    s_voice.pcm_buf = NULL;
   333	    s_voice.pcm_len = 0;
   334	
   335	    /* Reset state to IDLE */
   336	    s_voice.state = VOICE_IDLE;
   337	}
   338	
   339	/* Allocate fallback PCM buffer (must hold lock) */
   340	static int alloc_fallback_buffer_locked(void)
   341	{
   342	    if (s_voice.pcm_buf) {
   343	        return 0;
   344	    }
   345	
   346	    s_voice.pcm_buf = malloc(s_voice.pcm_cap);
   347	    if (!s_voice.pcm_buf) {
   348	        syslog(LOG_ERR, "[%s] fallback buffer alloc failed\n", TAG);
   349	        return -ENOMEM;
   350	    }
   351	
   352	    s_voice.pcm_len = 0;
   353	    return 0;
   354	}
   355	
   356	/* Accumulate PCM chunk to fallback buffer (must hold lock) */
   357	static void accumulate_pcm_locked(const unsigned char* chunk, size_t len)
   358	{
   359	    if (s_voice.pcm_buf && s_voice.pcm_len + len <= s_voice.pcm_cap) {
   360	        memcpy(s_voice.pcm_buf + s_voice.pcm_len, chunk, len);
   361	        s_voice.pcm_len += len;
   362	    }
   363	}
   364	
   365	/* Process one audio chunk: send to ASR or accumulate for fallback */
   366	static int process_audio_chunk(voice_asr_stream_t** stream_ptr,
   367	    const unsigned char* chunk, size_t len, int* need_fallback,
   368	    size_t* bytes_sent)
   369	{
   370	    if (*need_fallback) {
   371	        pthread_mutex_lock(&s_voice.lock);
   372	        accumulate_pcm_locked(chunk, len);
   373	        pthread_mutex_unlock(&s_voice.lock);
   374	    }
   375	
   376	    if (*stream_ptr) {
   377	        int ret = voice_asr_stream_send(*stream_ptr, chunk, len);
   378	
   379	        if (ret != 0) {
   380	            syslog(LOG_ERR,
   381	                "[%s] stream send failed: %d, batch fallback\n", TAG, ret);
   382	            voice_asr_stream_abort(*stream_ptr);
   383	            *stream_ptr = NULL;
   384	            *need_fallback = 1;
   385	
   386	            pthread_mutex_lock(&s_voice.lock);
   387	            alloc_fallback_buffer_locked();
   388	            pthread_mutex_unlock(&s_voice.lock);
   389	        } else {
   390	            *bytes_sent += len;
   391	        }
   392	    }
   393	
   394	    return 0;
   395	}
