   411	
   412	    /* Use pre-connected ASR stream if available (opened in
   413	     * voice_channel_start to avoid TLS handshake delay during
   414	     * recording).  Fall back to opening a new session if not. */
   415	    pthread_mutex_lock(&s_voice.lock);
   416	    voice_asr_stream_t* stream = s_voice.asr_stream;
   417	    s_voice.asr_stream = NULL; /* thread now owns it */
   418	    pthread_mutex_unlock(&s_voice.lock);
   419	
   420	    if (!stream) {
   421	        /* …554 tokens truncated…g\n", TAG, n);
   473	            abnormal_exit = 1;
   474	            break;
   475	        }
   476	
   477	        total_bytes_read += (size_t)n;
   478	        chunk_count++;
   479	
   480	        /* Dump raw PCM to file */
   481	        // if (dump_fd >= 0) {
   482	        //     write(dump_fd, chunk, (size_t)n);
