   484	
   485	        /* Log audio level for first few chunks and periodically
   486	         * to diagnose silence vs actual speech from QEMU mic. */
   487	        if (chunk_count <= 3 || chunk_count % 50 == 0) {
   488	            int16_t* samples = (int16_t*)chunk;
   489	            int sample_count = n / 2;
   490	            int32_t peak = 0;
   491	
   492	            for (int i = 0; i < sample_count; i++) {
   493	                int32_t v = samples[i] < 0 ? -samples[i] : samples[i];
   494	                if (v > peak) {
   495	                    peak = v;
   496	                }
   497	            }
   498	            syslog(LOG_INFO,
   499	                "[%s] chunk#%d: %d bytes, peak=%ld\n",
   500	                TAG, chunk_count, n, (long)peak);
   501	        }
   502	
   503	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
   504	        preproc_chunk(pp, chunk, n);
   505	#endif
   506	
   507	        process_audio_chunk(&stream, chunk, (size_t)n,
   508	            &need_fallback, &total_bytes_sent);
   509	    }
   510	
   511	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
   512	    preproc_destroy(pp);
   513	#endif
   514	
   515	    /* Store stream handle for voice_channel_stop to finish */
   516	    // if (dump_fd >= 0) {
   517	    //     close(dump_fd);
   518	    //     syslog(LOG_INFO, "[%s] PCM dump saved to /data/cap_dump.pcm\n", TAG);
   519	    // }
   520	
   521	    pthread_mutex_lock(&s_voice.lock);
   522	    s_voice.asr_stream = stream;
   523	
   524	    if (abnormal_exit && s_voice.state == VOICE_RECORDING) {
   525	        syslog(LOG_WARNING, "[%s] abnormal exit, cleaning up\n", TAG);
   526	        recording_cleanup_locked(stream);
   527	    }
   528	    pthread_mutex_unlock(&s_voice.lock);
   529	
   530	    syslog(LOG_INFO,
   531	        "[%s] recording thread exit: %d chunks, %zu read, %zu sent%s\n",
   532	        TAG, chunk_count, total_bytes_read, total_bytes_sent,
   533	        abnormal_exit ? " (abnormal)" : "");
   534	    return NULL;
   535	}
