   279	static int make_wav(const unsigned char *pcm, size_t pcm_len,
   280	                    unsigned char **wav_out, size_t *wav_len)
   281	{
   282	    unsigned char *wav;
   283	
   284	    if (!pcm || !wav_out || !wav_len || pcm_len > UINT32_MAX - 44) {
   285	        return -EINVAL;
   286	    }
   287	
   288	    wav = malloc(pcm_len + 44);
   289	    if (!wav) {
   290	        return -ENOMEM;
   291	    }
   292	
   293	    memset(wav, 0, pcm_len + 44);
   294	    memcpy(wav, "RIFF", 4);
   295	    write_le32(wav + 4, (uint32_t)(pcm_len + 36));
   296	    memcpy(wav + 8, "WAVEfmt ", 8);
   297	    write_le32(wav + 16, 16);
   298	    write_le16(wav + 20, 1);
   299	    write_le16(wav + 22, AGENT_VOICE_CHANNELS);
   300	    write_le32(wav + 24, AGENT_VOICE_SAMPLE_RATE);
   301	    write_le32(wav + 28, AGENT_VOICE_SAMPLE_RATE
   302	        * AGENT_VOICE_CHANNELS * (AGENT_VOICE_BITS / 8));
   303	    write_le16(wav + 32, AGENT_VOICE_CHANNELS * (AGENT_VOICE_BITS / 8));
   304	    write_le16(wav + 34, AGENT_VOICE_BITS);
   305	    memcpy(wav + 36, "data", 4);
   306	    write_le32(wav + 40, (uint32_t)pcm_len);
   307	    memcpy(wav + 44, pcm, pcm_len);
   308	
   309	    *wav_out = wav;
   310	    *wav_len = pcm_len + 44;
   311	    return 0;
   312	}
