   314	static int json_string(cJSON *root, const char *field,
   315	                       char *out, size_t cap)
   316	{
   317	    cJSON *choices = cJSON_GetObjectItemCaseSensitive(root, "choices");
   318	    cJSON *first;
   319	    cJSON *message;
   320	    cJSON *item;
   321	
   322	    if (!cJSON_IsArray(choices) || cJSON_GetArraySize(choices) < 1) {
   323	        return -EPROTO;
   324	    }
   325	    first = cJSON_GetArrayItem(choices, 0);
   326	    message = cJSON_GetObjectItemCaseSensitive(first, "message");
   327	    item = message ? cJSON_GetObjectItemCaseSensitive(message, field) : NULL;
   328	    if (!cJSON_IsString(item) || !item->valuestring) {
   329	        return -EPROTO;
   330	    }
   331	
   332	    strncpy(out, item->valuestring, cap - 1);
   333	    out[cap - 1] = '\0';
   334	    return 0;
   335	}
