   337	static int make_asr_body(const unsigned char *pcm, size_t pcm_len,
   338	                         char **body_out, size_t *body_len_out)
   339	{
   340	    unsigned char *wav = NULL;
   341	    size_t wav_len = 0;
   342	    size_t b64_cap;
   343	    size_t b64_len = 0;
   344	    char *b64 = NULL;
   345	    char *data_uri = NULL;
   346	    cJSON *root = NULL;
   347	    cJSON *messages;
   348	    cJSON *message;
   349	    cJSON *content;
   350	    cJSON *audio_item;
   351	    cJSON *audio;
   352	    char *body;
   353	    int ret;
   354	
   355	    ret = make_wav(pcm, pcm_len, &wav, &wav_len);
   356	    if (ret < 0) {
   357	        return ret;
   358	    }
   359	
   360	    b64_cap = ((wav_len + 2) / 3) * 4 + 1;
   361	    b64 = malloc(b64_cap);
   362	    if (!b64) {
   363	        free(wav);
   364	        return -ENOMEM;
   365	    }
   366	
   367	    /* The ESP mbedTLS implementation requires destination capacity for the
   368	     * encoded data plus its terminating NUL. */
   369	    ret = mbedtls_base64_encode((unsigned char *)b64, b64_cap,
   370	        &b64_len, wav, wav_len);
   371	    free(wav);
   372	    if (ret != 0) {
   373	        syslog(LOG_ERR, "[%s] WAV base64 encode failed: %d\n", TAG, ret);
   374	        free(b64);
   375	        return -EIO;
   376	    }
   377	    b64[b64_len] = '\0';
   378	
   379	    data_uri = malloc(b64_len + 24);
   380	    if (!data_uri) {
   381	        free(b64);
   382	        return -ENOMEM;
   383	    }
   384	    snprintf(data_uri, b64_len + 24, "data:audio/wav;base64,%s", b64);
   385	    free(b64);
   386	
   387	    root = cJSON_CreateObject();
   388	    messages = cJSON_CreateArray();
   389	    message = cJSON_CreateObject();
   390	    content = cJSON_CreateArray();
   391	    audio_item = cJSON_CreateObject();
   392	    audio = cJSON_CreateObject();
   393	    if (!root || !messages || !message || !content || !audio_item || !audio) {
   394	        cJSON_Delete(root);
   395	        cJSON_Delete(messages);
   396	        cJSON_Delete(message);
   397	        cJSON_Delete(content);
   398	        cJSON_Delete(audio_item);
   399	        cJSON_Delete(audio);
   400	        free(data_uri);
   401	        return -ENOMEM;
   402	    }
   403	
   404	    cJSON_AddStringToObject(root, "model", AGENT_MIMO_ASR_MODEL);
   405	    cJSON_AddStringToObject(message, "role", "user");
   406	    cJSON_AddStringToObject(audio_item, "type", "input_audio");
   407	    cJSON_AddStringToObject(audio, "data", data_uri);
   408	    cJSON_AddItemToObject(audio_item, "input_audio", audio);
   409	    cJSON_AddItemToArray(content, audio_item);
   410	    cJSON_AddItemToObject(message, "content", content);
   411	    cJSON_AddItemToArray(messages, message);
   412	    cJSON_AddItemToObject(root, "messages", messages);
   413	    cJSON_AddItemToObject(root, "asr_options", cJSON_CreateObject());
   414	    cJSON_AddStringToObject(cJSON_GetObjectItem(root, "asr_options"),
   415	        "language", "zh");
   416	
   417	    body = cJSON_PrintUnformatted(root);
   418	    cJSON_Delete(root);
   419	    free(data_uri);
   420	    if (!body) {
   421	        return -ENOMEM;
   422	    }
   423	
   424	    *body_out = body;
   425	    *body_len_out = strlen(body);
   426	    return 0;
   427	}
