   440	static int mimo_asr_recognize(const unsigned char *pcm_data,
   441	                              size_t pcm_len,
   442	                              char *text_out,
   443	                              size_t text_cap)
   444	{
   445	    char *body = NULL;
   446	    struct mimo_guard_buf body_buf = { 0 };
   447	    size_t body_len = 0;
   448	    struct mimo_guard_buf response_buf = { 0 };
   449	    cJSON *root = NULL;
   450	    int ret;
   451	
   452	    syslog(LOG_INFO, "[VOICE-DIAG] asr_begin\n");
   453	    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
   454	        return mimo_asr_done(-EINVAL);
   455	    }
   456	    if (pcm_len > AGENT_MIMO_MAX_AUDIO_BYTES) {
   457	        return mimo_asr_done(-EFBIG);
   458	    }
   459	
   460	    ret = make_asr_body(pcm_data, pcm_len, &body, &body_len);
   461	    if (ret < 0) {
   462	        return mimo_asr_done(ret);
   463	    }
   464	    if (body_len == SIZE_MAX) {
   465	        free(body);
   466	        return mimo_asr_done(-EOVERFLOW);
   467	    }
   468	
   469	    ret = mimo_guard_alloc(&body_buf, body_len + 1);
   470	    if (ret < 0) {
   471	        free(body);
   472	        return mimo_asr_done(ret);
   473	    }
   474	    memcpy(body_buf.data, body, body_len + 1);
   475	    free(body);
   476	    body = (char *)body_buf.data;
   477	
   478	    ret = mimo_guard_alloc(&response_buf, AGENT_MIMO_HTTP_RESP_BYTES);
   479	    if (ret < 0) {
   480	        mimo_guard_free(&body_buf);
   481	        return mimo_asr_done(ret);
   482	    }
   483	
   484	    mimo_voice_guard_diag("body", mimo_guard_ok(&body_buf));
   485	    mimo_voice_guard_diag("response", mimo_guard_ok(&response_buf));
   486	    if (!mimo_guard_ok(&body_buf) || !mimo_guard_ok(&response_buf)) {
   487	        return mimo_asr_done(-EFAULT);
   488	    }
   489	    syslog(LOG_INFO, "[VOICE-DIAG] body_ready len=%zu cap=%zu\n",
   490	        body_len, body_buf.cap);
   491	    mimo_voice_diag("body_ready", NULL, body, body_len, body_buf.cap,
   492	        response_buf.data, 0, response_buf.cap);
   493	    mimo_voice_guard_diag("body", mimo_guard_ok(&body_buf));
   494	    mimo_voice_guard_diag("response", mimo_guard_ok(&response_buf));
   495	    if (!mimo_guard_ok(&body_buf) || !mimo_guard_ok(&response_buf)) {
   496	        return mimo_asr_done(-EFAULT);
   497	    }
   498	    mimo_voice_diag("before_transport", NULL, body, body_len,
   499	        body_buf.cap, response_buf.data, 0, response_buf.cap);
   500	    syslog(LOG_INFO, "[VOICE-DIAG] transport_enter body=%p body_len=%zu response=%p response_cap=%zu\n",
   501	        body, body_len, response_buf.data, response_buf.cap);
   502	
   503	    ret = post_mimo(body, (char *)response_buf.data, response_buf.cap);
   504	    size_t response_len = ret >= 0
   505	        ? strnlen((char *)response_buf.data, response_buf.cap) : 0;
