  1793	static int contest_i2s_send(FAR struct i2s_dev_s *dev,
  1794	                            FAR struct ap_buffer_s *apb,
  1795	                            i2s_callback_t callback, FAR void *arg,
  1796	                            uint32_t timeout)
  1797	{
  1798	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
  1799	  FAR struct contest_i2s_xfer_s *xfer = NULL;
  1800	  irqstate_t flags;
  1801	  uint32_t queued;
  1802	  size_t nbytes;
  1803	  unsigned int last;
  1804	  unsigned int i;
  1805	
  1806	  (void)timeout;
  1807	
  1808	  if (apb == NULL || callback == NULL || apb->samp == NULL)
  1809	    {
  1810	      return -EINVAL;
  1811	    }
  1812	
  1813	  nbytes = apb->nbytes - apb->curbyte;
  1814	  nbytes -= nbytes % (priv->data_width / 8);
  1815	  if (nbytes == 0)
  1816	    {
  1817	      return -EINVAL;
  1818	    }
  1819	
  1820	  apb_reference(apb);
  1821	  flags = spin_lock_irqsave(&priv->lock);
  1822	  if (!priv->streaming || priv->reserved || priv->pending != NULL)
  1823	    {
  1824	      spin_unlock_irqrestore(&priv->lock, flags);
  1825	      apb_free(apb);
  1826	      return -EBUSY;
  1827	    }
  1828	
  1829	  for (i = 0; i < sizeof(priv->xfer) / sizeof(priv->xfer[0]); i++)
  1830	    {
  1831	      if (!priv->xfer[i].in_use)
  1832	        {
  1833	          xfer = &priv->xfer[i];
  1834	          xfer->in_use = true;
  1835	          break;
  1836	        }
  1837	    }
  1838	
  1839	  if (xfer == NULL)
  1840	    {
  1841	      spin_unlock_irqrestore(&priv->lock, flags);
  1842	      apb_free(apb);
  1843	      return -EBUSY;
  1844	    }
  1845	
  1846	  priv->reserved = true;
  1847	  spin_unlock_irqrestore(&priv->lock, flags);
  1848	
  1849	  xfer->next = NULL;
  1850	  xfer->apb = apb;
  1851	  xfer->callback = callback;
  1852	  xfer->arg = arg;
