240	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
241	{
242	    if (!pb || !buf || len == 0) {
243	        return -EINVAL;
244	    }
245	
246	    if (pb->stopped) {
247	        return -ECANCELED;
248	    }
249	
250	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
251	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_BOARD_I2S) {
252	        const unsigned char* src = buf;
253	        size_t total = 0;
254	
255	        len -= len % (size_t)pb->bytes_per_frame;
256	        while (total < len) {
257	            size_t block = len - total;
258	            int ret;
259	
260	            if (block > BOARD_I2S_PLAYBACK_BLOCK_BYTES) {
261	                block = BOARD_I2S_PLAYBACK_BLOCK_BYTES;
262	            }
263	            block -= block % (size_t)pb->bytes_per_frame;
264	            ret = board_i2s_write_block(pb, src + total, block);
265	            if (ret < 0) {
266	                return total > 0 ? (int)total : ret;
267	            }
268	            total += block;
269	        }
270	
271	        pb->total_written += total;
272	        return (int)total;
273	    }
274	#endif
275	
276	    if (pb->backend != AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER || !pb->player) {
277	        return -EINVAL;
278	    }
279	
280	    ssize_t n = media_player_write_data(pb->player, buf, len);
281	    if (n > 0) {
282	        pb->total_written += (size_t)n;
283	    }
284	
285	    return (int)n;
286	}
