703	static int mimo_wav_feed(struct mimo_wav_stream *wav,
704	                         const unsigned char *data, size_t len)
705	{
706	    while (len > 0) {
707	        if (wav->state == MIMO_WAV_RIFF) {
708	            size_t need = 12 - wav->small_used;
709	            size_t take = len < need ? len : need;
710	            memcpy(wav->small + wav->small_used, data, take);
711	            wav->small_used += take;
712	            data += take;
713	            len -= take;
714	            if (wav->small_used == 12) {
715	                if (memcmp(wav->small, "RIFF", 4) != 0
716	                    || memcmp(wav->small + 8, "WAVE", 4) != 0) {
717	                    return -EPROTO;
718	                }
719	                wav->small_used = 0;
720	                wav->state = MIMO_WAV_CHUNK_HEADER;
721	            }
722	            continue;
723	        }
724	
725	        if (wav->state == MIMO_WAV_CHUNK_HEADER) {
726	            size_t need = 8 - wav->small_used;
727	            size_t take = len < need ? len : need;
728	            memcpy(wav->small + wav->small_used, data, take);
729	            wav->small_used += take;
730	            data += take;
731	            len -= take;
732	            if (wav->small_used == 8) {
733	                memcpy(wav->chunk_id, wav->small, 4);
734	                wav->chunk_len = read_le32(wav->small + 4);
735	                wav->chunk_remaining = wav->chunk_len;
736	                wav->small_used = 0;
737	
738	                if (memcmp(wav->chunk_id, "data", 4) == 0) {
739	                    int ret = mimo_wav_validate_fmt(wav);
740	                    if (ret < 0) {
741	                        return ret;
742	                    }
743	                    wav->data_seen = true;
744	                    syslog(LOG_INFO,
745	                        "[%s] TTS WAV data begin bytes=%lu rate=%lu\n",
746	                        TAG, (unsigned long)wav->chunk_len,
747	                        (unsigned long)wav->sample_rate);
748	                }
749	                wav->state = MIMO_WAV_CHUNK_DATA;
750	            }
751	            continue;
752	        }
753	
754	        if (wav->state == MIMO_WAV_CHUNK_DATA) {
755	            size_t take = len;
756	            if (take > wav->chunk_remaining) {
757	                take = wav->chunk_remaining;
758	            }
759	
760	            if (memcmp(wav->chunk_id, "fmt ", 4) == 0) {
761	                size_t need = sizeof(wav->small) - wav->small_used;
762	                size_t keep = take < need ? take : need;
763	                if (keep > 0) {
764	                    memcpy(wav->small + wav->small_used, data, keep);
765	                    wav->small_used += keep;
766	                }
767	            } else if (memcmp(wav->chunk_id, "data", 4) == 0) {
768	                int ret = mimo_wav_emit(wav, data, take);
769	                if (ret < 0) {
770	                    return ret;
771	                }
772	            }
773	
774	            data += take;
775	            len -= take;
776	            wav->chunk_remaining -= (uint32_t)take;
777	
778	            if (wav->chunk_remaining == 0) {
779	                if (memcmp(wav->chunk_id, "fmt ", 4) == 0) {
780	                    if (wav->chunk_len < 16 || wav->small_used < 16) {
781	                        return -EPROTO;
782	                    }
783	                    wav->audio_format = read_le16(wav->small);
784	                    wav->channels = read_le16(wav->small + 2);
785	                    wav->sample_rate = read_le32(wav->small + 4);
786	                    wav->bits = read_le16(wav->small + 14);
787	                    wav->fmt_seen = true;
788	                    wav->small_used = 0;
789	                }
790	
791	                if (wav->chunk_len & 1U) {
792	                    wav->state = MIMO_WAV_PAD;
793	                } else {
794	                    wav->state = MIMO_WAV_CHUNK_HEADER;
795	                }
796	            }
797	            continue;
798	        }
799	
800	        if (wav->state == MIMO_WAV_PAD) {
801	            data++;
802	            len--;
803	            wav->state = MIMO_WAV_CHUNK_HEADER;
804	            continue;
805	        }
806	
807	        if (wav->state == MIMO_WAV_DONE) {
808	            return 0;
809	        }
810	    }
811	
812	    return 0;
813	}
