  1933	static int contest_i2s_tx_ioctl(FAR struct i2s_dev_s *dev, int cmd,
  1934	                                unsigned long arg)
  1935	{
  1936	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
  1937	  FAR struct contest_i2s_xfer_s *xfer;
  1938	  bool schedule = false;
  1939	  irqstate_t flags;
  1940	
  1941	  (void)arg;
  1942	
  1943	  switch (cmd)
  1944	    {
  1945	      case AUDIOIOC_START:
  1946	        flags = spin_lock_irqsave(&priv->lock);
  1947	        priv->streaming = true;
  1948	        priv->eof_count = 0;
  1949	        priv->chained_count = 0;
  1950	        priv->underrun_count = 0;
  1951	        priv->pending_submit_count = 0;
  1952	        priv->started_once = false;
  1953	        priv->idle = false;
  1954	        spin_unlock_irqrestore(&priv->lock, flags);
  1955	        up_enable_irq(priv->tx_irq);
  1956	        return OK;
  1957	
  1958	      case AUDIOIOC_STOP:
  1959	        flags = spin_lock_irqsave(&priv->lock);
  1960	        priv->streaming = false;
  1961	        contest_i2s_tx_capture_state(priv, priv->active);
  1962	        contest_i2s_tx_stop_hw(priv);
  1963	        if (priv->active != NULL)
  1964	          {
  1965	            xfer = priv->active;
  1966	            xfer->result = -ECANCELED;
  1967	            contest_i2s_tx_done_push(priv, xfer);
  1968	            priv->active = NULL;
  1969	            schedule = true;
  1970	          }
  1971	
  1972	        if (priv->pending != NULL)
  1973	          {
  1974	            xfer = priv->pending;
  1975	            xfer->result = -ECANCELED;
  1976	            contest_i2s_tx_done_push(priv, xfer);
  1977	            priv->pending = NULL;
  1978	            schedule = true;
  1979	          }
  1980	
  1981	        priv->idle = false;
  1982	        spin_unlock_irqrestore(&priv->lock, flags);
  1983	        syslog(LOG_INFO,
  1984	               "[C-I2S] tx eof=%lu chained=%lu underrun=%lu pending=%lu\n",
  1985	               (unsigned long)priv->eof_count,
  1986	               (unsigned long)priv->chained_count,
  1987	               (unsigned long)priv->underrun_count,
  1988	               (unsigned long)priv->pending_submit_count);
  1989	        if (schedule)
  1990	          {
  1991	            contest_i2s_tx_dump_state(priv);
  1992	            if (work_available(&priv->tx_work))
  1993	              {
  1994	                work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker,
  1995	                           priv, 0);
  1996	              }
  1997	          }
  1998	
  1999	        return OK;
  2000	
  2001	      default:
  2002	        return -ENOTTY;
  2003	    }
  2004	}
