   158	static int open_board_i2s_playback(audio_playback_t* pb,
   159	    unsigned int sample_rate, unsigned int channels,
   160	    unsigned int bits_per_sample)
   161	{
   162	    int actual;
   163	    int ret;
   164	
   165	    if (channels != 1 || bits_per_sample != 16) {
   166	        return -ENOTSUP;
   167	    }
   168	
   169	    pb->i2s = board_voice_speaker_i2s();
   170	    if (!pb->i2s) {
   171	        return -ENODEV;
   172	    }
   173	
   174	    ret = I2S_TXCHANNELS(pb->i2s, channels);
   175	    if (ret < 0) {
   176	        return ret;
   177	    }
   178	
   179	    actual = (int)I2S_TXSAMPLERATE(pb->i2s, sample_rate);
   180	    if (actual != (int)sample_rate) {
   181	        return actual < 0 ? actual : -ENOTSUP;
   182	    }
   183	
   184	    actual = (int)I2S_TXDATAWIDTH(pb->i2s, bits_per_sample);
   185	    if (actual != (int)bits_per_sample) {
   186	        return actual < 0 ? actual : -ENOTSUP;
   187	    }
   188	
   189	    ret = I2S_IOCTL(pb->i2s, AUDIOIOC_START, 0);
   190	    if (ret < 0) {
   191	        return ret;
   192	    }
   193	
   194	    ret = nxsem_init(&pb->i2s_done, 0, 0);
   195	    if (ret < 0) {
   196	        I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
   197	        return ret;
   198	    }
   199	
   200	    ret = nxsem_init(&pb->i2s_lock, 0, 1);
   201	    if (ret < 0) {
   202	        nxsem_destroy(&pb->i2s_done);
   203	        I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
   204	        return ret;
   205	    }
   206	
   207	    pb->backend = AUDIO_PLAYBACK_BACKEND_BOARD_I2S;
   208	    pb->i2s_started = 1;
   209	    pb->i2s_result = OK;
   210	    pb->i2s_inflight = 0;
   211	    pb->i2s_primed = 0;
   212	    pb->i2s_stage_len = 0;
   213	    syslog(LOG_INFO, "[%s] opened contest I2S playback (%uHz %uch %ubit)\n",
   214	        TAG, sample_rate, channels, bits_per_sample);
   215	    return 0;
   216	}
