   218	static int board_i2s_wait_slot(audio_playback_t* pb)
   219	{
   220	    int ret;
   221	
   222	    for (;;) {
   223	        ret = board_i2s_get_result(pb);
   224	        if (ret < 0) {
   225	            return ret;
   226	        }
   227	
   228	        if (pb->stopped) {
   229	            return -ECANCELED;
   230	        }
   231	
   232	        if (board_i2s_get_inflight(pb) < BOARD_I2S_PLAYBACK_MAX_INFLIGHT) {
   233	            return OK;
   234	        }
   235	
   236	        ret = nxsem_wait_uninterruptible(&pb->i2s_done);
   237	        if (ret < 0) {
   238	            return ret;
   239	        }
   240	    }
   241	}
   242	
   243	static int board_i2s_queue_block(audio_playback_t* pb,
   244	    const void* buf, size_t len)
   245	{
   246	    struct audio_buf_desc_s desc;
   247	    struct ap_buffer_s* apb = NULL;
   248	    int ret;
   249	
   250	    if (len == 0 || len > BOARD_I2S_PLAYBACK_BLOCK_BYTES) {
   251	        return -EINVAL;
   252	    }
   253	
   254	    len -= len % (size_t)pb->bytes_per_frame;
   255	    if (len == 0) {
   256	        return -EINVAL;
   257	    }
   258	
   259	    ret = board_i2s_wait_slot(pb);
   260	    if (ret < 0) {
   261	        return ret;
   262	    }
   263	
   264	    memset(&desc, 0, sizeof(desc));
   265	    desc.numbytes = len;
   266	    desc.u.pbuffer = &apb;
   267	    ret = apb_alloc(&desc);
   268	    if (ret < 0) {
   269	        return ret;
   270	    }
   271	
   272	    memcpy(apb->samp, buf, len);
   273	    apb->nbytes = len;
   274	    apb->nsamples = len / (size_t)pb->bytes_per_frame;
   275	
   276	    /*
   277	     * Count before I2S_SEND(): a very fast completion callback must never
   278	     * observe an uncounted transfer.
   279	     */
   280	    ret = board_i2s_lock(pb);
   281	    if (ret < 0) {
   282	        apb_free(apb);
   283	        return ret;
   284	    }
   285	
   286	    pb->i2s_inflight++;
   287	    board_i2s_unlock(pb);
   288	
   289	    ret = I2S_SEND(pb->i2s, apb, board_i2s_playback_done, pb,
   290	        MSEC2TICK(BOARD_I2S_PLAYBACK_TIMEOUT_MS));
   291	    if (ret < 0) {
   292	        int lock_ret = board_i2s_lock(pb);
   293	
   294	        if (pb->i2s_inflight > 0) {
   295	            pb->i2s_inflight--;
   296	        }
   297	
   298	        if (ret != -EBUSY && pb->i2s_result >= 0) {
   299	            pb->i2s_result = ret;
   300	        }
   301	
   302	        if (lock_ret == 0) {
   303	            board_i2s_unlock(pb);
   304	        }
   305	
   306	        apb_free(apb);
   307	        return ret;
   308	    }
   309	
   310	    /*
   311	     * The contest lower half takes its own APB reference in I2S_SEND().
   312	     * Drop this producer reference now; the lower half owns playback lifetime.
   313	     */
   314	    apb_free(apb);
   315	    return OK;
   316	}
