   318	static int board_i2s_submit_full_blocks(audio_playback_t* pb)
   319	{
   320	    int ret;
   321	
   322	    /*
   323	     * Prime with two complete blocks.  The previous implementation waited for
   324	     * every block to finish before submitting the next one, so lower-half
   325	     * pending was always empty at EOF.  Two-block priming fills active+pending.
   326	     */
   327	    if (!pb->i2s_primed) {
   328	        if (pb->i2s_stage_len < BOARD_I2S_PLAYBACK_STAGE_BYTES) {
   329	            return OK;
   330	        }
   331	
   332	        ret = board_i2s_queue_block(pb, pb->i2s_stage,
   333	            BOARD_I2S_PLAYBACK_BLOCK_BYTES);
   334	        if (ret < 0) {
   335	            return ret;
   336	        }
   337	
   338	        ret = board_i2s_queue_block(pb,
   339	            pb->i2s_stage + BOARD_I2S_PLAYBACK_BLOCK_BYTES,
   340	            BOARD_I2S_PLAYBACK_BLOCK_BYTES);
   341	        if (ret < 0) {
   342	            return ret;
   343	        }
   344	
   345	        pb->i2s_stage_len = 0;
   346	        pb->i2s_primed = 1;
   347	        syslog(LOG_INFO,
   348	            "[%s] I2S playback primed with %u blocks (%u bytes)\n",
   349	            TAG, BOARD_I2S_PLAYBACK_PREBUFFER_BLOCKS,
   350	            BOARD_I2S_PLAYBACK_STAGE_BYTES);
   351	        return OK;
   352	    }
   353	
   354	    while (pb->i2s_stage_len >= BOARD_I2S_PLAYBACK_BLOCK_BYTES) {
   355	        ret = board_i2s_queue_block(pb, pb->i2s_stage,
   356	            BOARD_I2S_PLAYBACK_BLOCK_BYTES);
   357	        if (ret < 0) {
   358	            return ret;
   359	        }
   360	
   361	        pb->i2s_stage_len -= BOARD_I2S_PLAYBACK_BLOCK_BYTES;
   362	        if (pb->i2s_stage_len > 0) {
   363	            memmove(pb->i2s_stage,
   364	                pb->i2s_stage + BOARD_I2S_PLAYBACK_BLOCK_BYTES,
   365	                pb->i2s_stage_len);
   366	        }
   367	    }
   368	
   369	    return OK;
   370	}
