   531	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
   532	{
   533	    if (!pb || !buf || len == 0) {
   534	        return -EINVAL;
   535	    }
   536	
   537	    if (pb->stopped) {
   538	        return -ECANCELED;
   539	    }
   540	
   541	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
   542	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_BOARD_I2S) {
   543	        size_t aligned = len - len % (size_t)pb->bytes_per_frame;
   544	        int ret;
   545	
   546	        if (aligned == 0) {
   547	            return 0;
   548	        }
   549	
   550	        ret = board_i2s_feed(pb, buf, aligned);
   551	        if (ret < 0) {
   552	            return ret;
   553	        }
   554	
   555	        pb->total_written += aligned;
   556	        return (int)aligned;
   557	    }
   558	#endif
   559	
   560	    if (pb->backend != AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER || !pb->player) {
   561	        return -EINVAL;
   562	    }
   563	
   564	    ssize_t n = media_player_write_data(pb->player, buf, len);
   565	    if (n > 0) {
   566	        pb->total_written += (size_t)n;
   567	    }
   568	
   569	    return (int)n;
   570	}
