   572	void audio_playback_stop(audio_playback_t* pb)
   573	{
   574	    if (!pb) {
   575	        return;
   576	    }
   577	
   578	    pb->stopped = 1;
   579	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
   580	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_BOARD_I2S && pb->i2s
   581	        && pb->i2s_started) {
   582	        pb->i2s_started = 0;
   583	        I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
   584	
   585	        /*
   586	         * STOP completes active/pending APBs through the callback.  Wait for
   587	         * those callbacks before close can destroy the semaphore.
   588	         */
   589	        board_i2s_drain(pb);
   590	        return;
   591	    }
   592	#endif
   593	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER && pb->player) {
   594	        media_player_stop(pb->player);
   595	    }
   596	}
