   598	void audio_playback_close(audio_playback_t* pb)
   599	{
   600	    if (!pb) {
   601	        return;
   602	    }
   603	
   604	    syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
   605	        TAG, pb->total_written);
   606	
   607	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
   608	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_BOARD_I2S) {
   609	        if (pb->i2s) {
   610	            if (!pb->stopped) {
   611	                int ret = board_i2s_flush(pb);
   612	                if (ret < 0) {
   613	                    syslog(LOG_ERR, "[%s] I2S flush failed: %d\n", TAG, ret);
   614	                }
   615	            }
   616	
   617	            /*
   618	             * Normal close is end-of-stream, not an abort.  Let queued PCM
   619	             * drain before stopping I2S so the final two async blocks survive.
   620	             */

