  1005	static int mimo_tts_json_feed(const unsigned char *data, size_t len,
  1006	                              void *user_data)
  1007	{
  1008	    static const char audio_key[] = "\"audio\"";
  1009	    static const char data_key[] = "\"data\"";
  1010	    struct mimo_tts_stream *st = (struct mimo_tts_stream *)user_data;
  1011	    size_t i;
  1012	
  1013	    if (!st || (!data && len > 0)) {
  1014	        return -EINVAL;
  1015	    }
  1016	    if (st->error < 0) {
  1017	        return st->error;
  1018	    }
  1019	
  1020	    st->http_bytes += len;
  1021	
  1022	    for (i = 0; i < len; i++) {
  1023	        unsigned char c = data[i];
  1024	        int ret;
  1025	
  1026	        switch (st->json_state) {
  1027	        case MIMO_JSON_FIND_AUDIO:
  1028	            mimo_match_key(&st->audio_match, audio_key, c);
  1029	            if (st->audio_match == strlen(audio_key)) {
  1030	                st->audio_found = true;
  1031	                st->audio_match = 0;
  1032	                st->json_state = MIMO_JSON_AFTER_AUDIO;
  1033	            }
  1034	            break;
  1035	
  1036	        case MIMO_JSON_AFTER_AUDIO:
  1037	            if (c == ':' || c == '{' || c == ' ' || c == '\r'
  1038	                || c == '\n' || c == '\t') {
  1039	                if (c == '{') {
  1040	                    st->json_state = MIMO_JSON_FIND_DATA;
  1041	                }
  1042	            } else {
  1043	                st->json_state = MIMO_JSON_FIND_AUDIO;
  1044	            }
  1045	            break;
  1046	
  1047	        case MIMO_JSON_FIND_DATA:
  1048	            mimo_match_key(&st->data_match, data_key, c);
  1049	            if (st->data_match == strlen(data_key)) {
  1050	                st->data_match = 0;
  1051	                st->json_state = MIMO_JSON_AFTER_DATA;
  1052	            } else if (c == '}') {
  1053	                st->json_state = MIMO_JSON_FIND_AUDIO;
  1054	            }
  1055	            break;
  1056	
  1057	        case MIMO_JSON_AFTER_DATA:
  1058	            if (c == ':' || c == ' ' || c == '\r' || c == '\n' || c == '\t') {
  1059	                break;
  1060	            }
  1061	            if (c == '"') {
  1062	                st->data_found = true;
  1063	                st->json_state = MIMO_JSON_IN_B64;
  1064	                syslog(LOG_INFO, "[%s] TTS audio base64 stream begin\n", TAG);
  1065	                break;
  1066	            }
  1067	            st->json_state = MIMO_JSON_FIND_DATA;
  1068	            break;
  1069	
  1070	        case MIMO_JSON_IN_B64:
  1071	            if (c == '"') {
  1072	                ret = mimo_b64_finish(st);
  1073	                if (ret < 0) {
  1074	                    st->error = ret;
  1075	                    return ret;
  1076	                }
  1077	                st->json_state = MIMO_JSON_DONE;
  1078	                break;
  1079	            }
  1080	            ret = mimo_b64_feed_char(st, c);
  1081	            if (ret < 0) {
  1082	                st->error = ret;
  1083	                return ret;
  1084	            }
  1085	            break;
  1086	
  1087	        case MIMO_JSON_DONE:
  1088	            break;
  1089	        }
  1090	    }
  1091	
  1092	    return 0;
  1093	}
