1486	static int voice_play_stream(struct i2s_dev_s *speaker,
1487	                             enum voice_mode_e mode,
1488	                             FAR const int16_t *samples, size_t count)
1489	{
1490	  struct voice_tx_slot_s slots[VOICE_TX_SLOT_COUNT];
1491	  size_t output_count;
1492	  size_t output_index = 0;
1493	  unsigned int submit_chunk = 0;
1494	  unsigned int wait_slot = 0;
1495	  unsigned int submitted = 0;
1496	  unsigned int completed = 0;
1497	  unsigned int in_flight = 0;
1498	  int ret;
1499	
1500	  memset(slots, 0, sizeof(slots));
1501	  output_count = mode == VOICE_MODE_ECHO ?
1502	    (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) / VOICE_INPUT_RATE :
1503	    VOICE_DIAGNOSTIC_OUTPUT_SAMPLES;
1504	
1505	  ret = I2S_IOCTL(speaker, AUDIOIOC_START, 0);
1506	  printf("voice_echo: SPK start ret=%d\n", ret);
1507	  if (ret < 0)
1508	    {
1509	      return ret;
1510	    }
1511	
1512	  while (output_index < output_count && in_flight < VOICE_TX_SLOT_COUNT)
1513	    {
1514	      size_t chunk = MIN(VOICE_DMA_BYTES / sizeof(int16_t),
1515	                         output_count - output_index);
1516	
1517	      ret = voice_tx_slot_submit(speaker, &slots[in_flight], mode, samples,
1518	                                 output_index, chunk, submit_chunk++);
1519	      if (ret < 0)
1520	        {
1521	          goto errout;
1522	        }
1523	
1524	      output_index += chunk;
1525	      in_flight++;
1526	      submitted++;
1527	    }
1528	
1529	  while (in_flight != 0)
1530	    {
1531	      ret = voice_tx_slot_wait(&slots[wait_slot]);
1532	      if (ret < 0)
1533	        {
1534	          printf("voice_echo: TX wait slot=%u failed: %d\n", wait_slot,
1535	                 ret);
1536	          goto errout;
1537	        }
1538	
1539	      completed++;
1540	      in_flight--;
