   638	static int mimo_wav_emit(struct mimo_wav_stream *wav,
   639	                         const unsigned char *data, size_t len)
   640	{
   641	    unsigned char pair[2];
   642	    size_t even_len;
   643	
   644	    if (!wav || (!data && len > 0) || !wav->pcm_cb) {
   645	        return -EINVAL;
   646	    }
   647	
   648	    if (len == 0) {
   649	        return 0;
   650	    }
   651	
   652	    if (wav->pcm_pending_valid) {
   653	        pair[0] = wav->pcm_pending;
   654	        pair[1] = data[0];
   655	        wav->pcm_cb(pair, sizeof(pair), 0, wav->pcm_user);
   656	        wav->pcm_total += sizeof(pair);
   657	        wav->pcm_pending_valid = false;
   658	        data++;
   659	        len--;
   660	    }
   661	
   662	    even_len = len & ~(size_t)1;
   663	    if (even_len > 0) {
   664	        wav->pcm_cb(data, even_len, 0, wav->pcm_user);
   665	        wav->pcm_total += even_len;
   666	        data += even_len;
   667	        len -= even_len;
   668	    }
   669	
   670	    if (len == 1) {
   671	        wav->pcm_pending = data[0];
   672	        wav->pcm_pending_valid = true;
   673	    }
   674	
   675	    return 0;
   676	}
