static int post_mimo(const char *body, char *response, size_t response_cap)
{
    char key[256] = { 0 };
    char host[128] = { 0 };
    char path[128] = { 0 };
    char auth[320];
    vela_header_t headers[2];
    int status;

    if (get_api_key(key, sizeof(key)) < 0) {
        syslog(LOG_ERR, "[%s] No API key; use set_llm or set_mimo_key\n", TAG);
        return -EACCES;
    }

    get_endpoint(host, sizeof(host), path, sizeof(path));
    snprintf(auth, sizeof(auth), "Bearer %s", key);
    headers[0].name = "Authorization";
    headers[0].value = auth;
    headers[1].name = NULL;
    headers[1].value = NULL;

    status = vela_https_post_json(host, AGENT_MIMO_VOICE_PORT, path,
        headers, body, response, response_cap);
    memset(key, 0, sizeof(key));

    if (status < 200 || status >= 300) {
        syslog(LOG_ERR, "[%s] HTTPS request status=%d\n", TAG, status);
        return status > 0 ? -EIO : status;
    }

    return 0;
}


/*
 * Streaming HTTPS body callback exported by the companion vela_tls change.
 * It returns the HTTP status code (2xx on success) and never stores the full
 * response body.  Keeping the declaration here avoids a hard dependency on a
 * header update while this change is being backported.
 */
typedef int (*mimo_https_body_cb_t)(const unsigned char *data, size_t len,
                                    void *user_data);

extern int vela_https_post_json_stream(const char *host, const char *port,
    const char *path, const vela_header_t *extra_headers,
    const char *json_body, mimo_https_body_cb_t body_cb, void *user_data);

static int post_mimo_stream(const char *body, mimo_https_body_cb_t body_cb,
                            void *user_data)
{
    char key[256] = { 0 };
    char host[128] = { 0 };
    char path[128] = { 0 };
    char auth[320];
    vela_header_t headers[2];
    int status;

    if (!body || !body_cb) {
