+struct playback_ctx_s
+{
+  pthread_t thread;
+  pthread_mutex_t lock;
+  sem_t wake;
+  uint8_t *ring;
+  size_t head;
+  size_t tail;
+  size_t used;
+  bool opened;
+  bool finished;
+  int error;
+};
