/* This is the original package's stable public transport ABI. robot_voice
 * does not include any modified ai_agent headers or private voice symbols. */
typedef robot_mimo_header_t vela_header_t;
extern int vela_https_request(const char *, const char *, const char *,
                              const char *, const vela_header_t *,
                              const char *, size_t, char *, size_t, size_t *);

int robot_mimo_post(const char *api_key, const char *body, size_t body_len,
                    char *response, size_t response_cap, size_t *response_len)
{
  char auth[320];
  vela_header_t headers[2];
  int status;

  if (!api_key || !body || !response || response_cap < 2)
    {
      return -EINVAL;
    }
  snprintf(auth, sizeof(auth), "Bearer %s", api_key);
  headers[0].name = "Authorization";
  headers[0].value = auth;
  headers[1].name = NULL;
  headers[1].value = NULL;
  printf("[RV-NET] POST %s body=%zu\n", ROBOT_VOICE_PATH, body_len);
  status = vela_https_request(ROBOT_VOICE_HOST, ROBOT_VOICE_PORT, "POST",
                              ROBOT_VOICE_PATH, headers, body, body_len,
                              response, response_cap, response_len);
  printf("[RV-NET] response status=%d bytes=%zu\n", status,
         response_len ? *response_len : 0);
  if (status < 0)
    {
      return status;
    }
  return status >= 200 && status < 300 ? 0 : -EIO;
}
