  ret = mimo_tts_speak_stream(key, text, robot_voice_pcm_sink, NULL);
  if (ret == 0)
    {
      ret = robot_audio_playback_finish();
    }
  robot_audio_playback_close();
  g_voice_speaking = 0;
  printf("[contest_voice] voice_channel_test_tts text_len=%zu rc=%d\n",
         strlen(text), ret);
  return ret;
}

int voice_channel_test_asr(const char *pcm_path)
{
  char key[256];
  char text[512];
  uint8_t *pcm = NULL;
  size_t len;
  int fd;
  int ret;
  if (!pcm_path || voice_get_api_key(key, sizeof(key)) < 0)
    {
      return -EINVAL;
    }

  fd = open(pcm_path, O_RDONLY);
  if (fd < 0)
    {
      return -errno;
    }
  len = (size_t)lseek(fd, 0, SEEK_END);
  if (len == 0 || len > ROBOT_VOICE_MAX_BODY)
    {
      close(fd);
      return -EFBIG;
    }
  lseek(fd, 0, SEEK_SET);
  pcm = malloc(len);
  if (pcm == NULL)
    {
      close(fd);
      return -ENOMEM;
    }
  if (read(fd, pcm, len) != (ssize_t)len)
    {
      free(pcm);
      close(fd);
      return -EIO;
    }
  close(fd);
  ret = mimo_asr_recognize(key, pcm, len, text, sizeof(text));
  free(pcm);
  if (ret == 0)
    {
      printf("[contest_voice] ASR: %s\n", text);
    }
  return ret;
}

