static int robot_voice_once(void)
{
  size_t pcm_cap = ROBOT_VOICE_CAPTURE_RATE * 2 * ROBOT_VOICE_CAPTURE_SECONDS;
  uint8_t *pcm = malloc(pcm_cap);
  char asr[512]; char reply[2048];
  size_t pcm_len = 0; int ret;
  if (!pcm) return -ENOMEM;
  ret = robot_audio_capture_record(pcm, pcm_cap, &pcm_len,
                                   ROBOT_VOICE_CAPTURE_SECONDS * 1000);
  if (ret < 0) goto out;
  ret = mimo_asr_recognize(g_api_key, pcm, pcm_len, asr, sizeof(asr));
  if (ret < 0) goto out;
  printf("[RV] ASR: %s\n", asr);
  ret = mimo_llm_chat(g_api_key, asr, reply, sizeof(reply));
  if (ret < 0) goto out;
  printf("[RV] LLM: %s\n", reply);
  ret = robot_audio_playback_open();
  if (ret < 0) goto out;
  ret = mimo_tts_speak_stream(g_api_key, reply, robot_voice_pcm_sink, NULL);
  if (ret == 0) ret = robot_audio_playback_finish();
  robot_audio_playback_close();
out:
  free(pcm); return ret;
}

