static void put16(uint8_t *p, unsigned int v)
{
  p[0] = v;
  p[1] = v >> 8;
}

static void put32(uint8_t *p, uint32_t v)
{
  p[0] = v;
  p[1] = v >> 8;
  p[2] = v >> 16;
  p[3] = v >> 24;
}

int mimo_asr_recognize(const char *api_key, const uint8_t *pcm, size_t pcm_len,
                       char *text, size_t text_cap)
{
  uint8_t *wav;
  unsigned char *b64;
  size_t wav_len = pcm_len + 44;
  size_t b64_len = 0;
  size_t b64_cap = ((wav_len + 2) / 3) * 4 + 1;
  cJSON *root = NULL;
  cJSON *messages = NULL;
  cJSON *message = NULL;
  cJSON *content = NULL;
  cJSON *item = NULL;
  cJSON *audio = NULL;
  char *body = NULL;
  char *data_uri = NULL;
  char *response = NULL;
  size_t response_len = 0;
  cJSON *choices;
  cJSON *first;
  cJSON *msg;
  cJSON *answer;
  int ret;

  if (!api_key || !pcm || !text || text_cap == 0 || pcm_len == 0 ||
      wav_len > ROBOT_VOICE_MAX_BODY)
    {
      return -EINVAL;
    }
  wav = malloc(wav_len);
  b64 = malloc(b64_cap);
  response = malloc(ROBOT_VOICE_HTTP_RESPONSE);
  if (!wav || !b64 || !response)
    {
      free(wav); free(b64); free(response);
      return -ENOMEM;
    }
  memcpy(wav, "RIFF", 4); put32(wav + 4, pcm_len + 36);
  memcpy(wav + 8, "WAVEfmt ", 8); put32(wav + 16, 16);
  put16(wav + 20, 1); put16(wav + 22, 1); put32(wav + 24, 16000);
  put32(wav + 28, 32000); put16(wav + 32, 2); put16(wav + 34, 16);
  memcpy(wav + 36, "data", 4); put32(wav + 40, pcm_len);
  memcpy(wav + 44, pcm, pcm_len);
  ret = mbedtls_base64_encode(b64, b64_cap, &b64_len, wav, wav_len);
  free(wav);
  if (ret != 0) { free(b64); free(response); return -EIO; }
  b64[b64_len] = '\0';
  data_uri = malloc(b64_len + 24);
  if (!data_uri) { free(b64); free(response); return -ENOMEM; }
  snprintf(data_uri, b64_len + 24, "data:audio/wav;base64,%s", b64);

  root = cJSON_CreateObject(); messages = cJSON_CreateArray();
  message = cJSON_CreateObject(); content = cJSON_CreateArray();
  item = cJSON_CreateObject(); audio = cJSON_CreateObject();
  if (!root || !messages || !message || !content || !item || !audio)
    { ret = -ENOMEM; goto out; }
  cJSON_AddStringToObject(root, "model", ROBOT_VOICE_ASR_MODEL);
  cJSON_AddStringToObject(message, "role", "user");
  cJSON_AddStringToObject(item, "type", "input_audio");
  cJSON_AddStringToObject(audio, "data", data_uri);
  cJSON_AddStringToObject(audio, "format", "wav");
  cJSON_AddItemToObject(item, "input_audio", audio); audio = NULL;
  cJSON_AddItemToArray(content, item); item = NULL;
  cJSON_AddItemToObject(message, "content", content); content = NULL;
  cJSON_AddItemToArray(messages, message); message = NULL;
  cJSON_AddItemToObject(root, "messages", messages); messages = NULL;
  body = cJSON_PrintUnformatted(root);
  cJSON_Delete(root);
  root = NULL;
  free(data_uri);
  data_uri = NULL;
  if (!body) { ret = -ENOMEM; goto out; }
  ret = robot_mimo_post(api_key, body, strlen(body), response,
                        ROBOT_VOICE_HTTP_RESPONSE, &response_len);
  if (ret < 0) goto out;
  root = cJSON_Parse(response);
  if (!root) { ret = -EPROTO; goto out; }
  choices = cJSON_GetObjectItem(root, "choices");
  first = cJSON_GetArrayItem(choices, 0);
  msg = first ? cJSON_GetObjectItem(first, "message") : NULL;
  answer = msg ? cJSON_GetObjectItem(msg, "content") : NULL;
  if (!cJSON_IsString(answer) || !answer->valuestring)
    { ret = -EPROTO; goto out; }
  strncpy(text, answer->valuestring, text_cap - 1); text[text_cap - 1] = '\0';
  printf("[RV-ASR] pcm=%zu response=%zu result=%zu\n", pcm_len, response_len,
         strlen(text));
  ret = 0;
out:
  cJSON_Delete(root); cJSON_Delete(messages); cJSON_Delete(message);
  cJSON_Delete(content); cJSON_Delete(item); cJSON_Delete(audio);
  free(body); free(b64); free(data_uri); free(response);
  return ret;
}

