   175	static void voice_complete(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
   176	                           void *arg, int result)
   177	{
   178	  struct voice_transfer_s *transfer = arg;
   179	  size_t nbytes = apb == NULL ? 0 : apb->nbytes;
   180	  bool abandoned;
   181	
   182	  (void)dev;
   183	
   184	  if (transfer->log_rx)
   185	    {
   186	      if (transfer->chunk < 2 || result < 0)
   187	        {
   188	          printf("voice_echo: RX callback chunk=%u result=%d bytes=%zu\n",
   189	                 transfer->chunk, result, nbytes);
   190	        }
   191	    }
   192	
   193	  if (transfer->log_tx)
   194	    {
   195	      if (transfer->chunk < 2 || result < 0)
   196	        {
   197	          printf("voice_echo: TX callback chunk=%u result=%d bytes=%zu\n",
   198	                 transfer->chunk, result, nbytes);
   199	        }
   200	    }
   201	
   202	  nxmutex_lock(&transfer->lock);
   203	  abandoned = transfer->abandoned;
   204	
   205	  if (abandoned)
   206	    {
   207	      /* The lower-half still owns one reference and will release it after
   208	       * this callback.  Release the application's original reference here.
   209	       */
   210	
   211	      nxmutex_unlock(&transfer->lock);
   212	      if (apb != NULL)
   213	        {
   214	          apb_free(apb);
   215	        }
   216	      nxmutex_destroy(&transfer->lock);
   217	      nxsem_destroy(&transfer->done);
   218	      free(transfer);
   219	      return;
   220	    }
   221	
   222	  if (transfer->retain_apb && apb != NULL && result >= 0)
   223	    {
   224	      apb_reference(apb);
   225	      transfer->apb = apb;
   226	    }
   227	
   228	  transfer->result = result;
   229	  transfer->callback_done = true;
   230	  nxsem_post(&transfer->done);
   231	  nxmutex_unlock(&transfer->lock);
   232	}
