  1140	static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
  1141	                               FAR struct ap_buffer_s *apb,
  1142	                               i2s_callback_t callback, FAR void *arg,
  1143	                               uint32_t timeout)
  1144	{
  1145	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  1146	  FAR struct contest_i2s_rx_xfer_s *xfer = NULL;
  1147	  irqstate_t flags;
  1148	  size_t logical_bytes;
  1149	  size_t logical_samples;
  1150	  size_t raw_bytes;
  1151	  uint32_t queued;
  1152	  unsigned int i;
  1153	
  1154	  (void)timeout;
  1155	
  1156	  if (apb == NULL || callback == NULL || apb->samp == NULL)
  1157	    {
  1158	      return -EINVAL;
  1159	    }
  1160	
  1161	  logical_bytes = apb->nmaxbytes - apb->curbyte;
  1162	  logical_bytes -= logical_bytes % sizeof(int16_t);
  1163	  logical_samples = logical_bytes / sizeof(int16_t);
  1164	  raw_bytes = logical_samples * sizeof(uint32_t);
  1165	  if (logical_bytes == 0 || raw_bytes > CONTEST_I2S_RX_RAW_MAX_BYTES)
  1166	    {
  1167	      return -EINVAL;
  1168	    }
  1169	
  1170	  apb_reference(apb);
  1171	
  1172	  /* Reserve a free transaction while the descriptor is built outside the
  1173	   * spinlock.  active and pending each retain independent raw DMA storage.
  1174	   */
  1175	
  1176	  flags = spin_lock_irqsave(&priv->lock);
  1177	  if (!priv->streaming || priv->reserved || priv->pending != NULL)
  1178	    {
  1179	      spin_unlock_irqrestore(&priv->lock, flags);
  1180	      apb_free(apb);
  1180	      apb_free(apb);
  1181	      return -EBUSY;
  1182	    }
  1183	
  1184	  for (i = 0; i < CONTEST_I2S_RX_XFER_COUNT; i++)
  1185	    {
  1186	      if (!priv->xfer[i].in_use)
  1187	        {
  1188	          xfer = &priv->xfer[i];
  1189	          xfer->in_use = true;
  1190	          xfer->dma_diag = !priv->dma_diag_armed;
  1191	          priv->dma_diag_armed = true;
  1192	          break;
  1193	        }
  1194	    }
  1195	
  1196	  if (xfer == NULL)
  1197	    {
  1198	      spin_unlock_irqrestore(&priv->lock, flags);
  1199	      apb_free(apb);
  1200	      return -EBUSY;
  1201	    }
  1202	
  1203	  priv->reserved = true;
  1204	  spin_unlock_irqrestore(&priv->lock, flags);
  1205	
  1206	  xfer->next = NULL;
  1207	  xfer->apb = apb;
  1208	  xfer->callback = callback;
  1209	  xfer->arg = arg;
  1210	  xfer->logical_bytes = logical_bytes;
  1211	  xfer->raw_bytes = raw_bytes;
  1212	  xfer->queued_bytes = 0;
  1213	  xfer->result = -EINPROGRESS;
  1214	  if (xfer->dma_diag)
  1215	    {
  1216	      for (i = 0; i < logical_samples; i++)
  1217	        {
  1218	          xfer->raw[i] = CONTEST_I2S_RX_DMA_SENTINEL;
  1219	        }
  1220	
  1221	      up_clean_dcache((uintptr_t)xfer->raw,
  1222	                      (uintptr_t)xfer->raw + raw_bytes);
  1223	    }
  1224	
  1225	  queued = contest_i2s_dma_setup_rx(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
  1226	                                     (FAR uint8_t *)xfer->raw, raw_bytes);
  1227	  xfer->queued_bytes = queued;
  1228	  if (queued != raw_bytes)
  1229	    {
  1230	      flags = spin_lock_irqsave(&priv->lock);
  1231	      priv->reserved = false;
  1232	      xfer->in_use = false;
  1233	      spin_unlock_irqrestore(&priv->lock, flags);
  1234	      apb_free(apb);
  1235	      return -ENOMEM;
  1236	    }
  1237	
  1238	  /* Publish before hardware can complete.  The first transaction becomes
  1239	   * active; the second becomes pending and is started by the EOF ISR.
  1240	   */
  1241	
  1242	  flags = spin_lock_irqsave(&priv->lock);
  1243	  if (!priv->streaming)
  1244	    {
  1245	      priv->reserved = false;
  1246	      xfer->in_use = false;
  1247	      spin_unlock_irqrestore(&priv->lock, flags);
  1248	      apb_free(apb);
  1249	      return -ECANCELED;
  1250	    }
  1251	
  1252	  priv->reserved = false;
  1253	  if (priv->active == NULL)
  1254	    {
  1255	      if (priv->started_once && priv->idle)
  1256	        {
  1257	          priv->underrun_count++;
  1258	        }
  1259	
  1260	      priv->active = xfer;
  1261	      contest_i2s_rx_start_active(priv);
  1262	    }
  1263	  else
  1264	    {
  1265	      priv->pending = xfer;
  1266	    }
  1267	
  1268	  spin_unlock_irqrestore(&priv->lock, flags);
  1269	
  1270	  if (priv->eof_count < 2)
  1271	    {
  1272	      uint32_t eof_reg = getreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT));
  1273	
  1274	      syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
  1275	      syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n",
  1276	             raw_bytes, logical_bytes);
  1277	      syslog(LOG_INFO,
  1278	             "[C-I2S] rx dma start raw=%zu eof_arg=%lu eof_reg=%08lx\n",
  1279	             raw_bytes,
  1280	             (unsigned long)contest_i2s_rx_eof_value(raw_bytes),
  1281	             (unsigned long)eof_reg);
  1282	    }
  1283	
  1284	  return OK;
  1285	}
