+#include "robot_voice_capture.h"
+#include "robot_voice_config.h"
+
+#define ROBOT_VOICE_RX_DMA_BYTES       1024
+#define ROBOT_VOICE_RX_SLOT_COUNT      2
+#define ROBOT_VOICE_RX_WARMUP_CHUNKS   2
+#define ROBOT_VOICE_RX_TIMEOUT_MS      1000
+#define ROBOT_VOICE_RECORD_TIMEOUT_MS  7000
+
+struct robot_voice_rx_xfer_s
+{
+  sem_t done;
+  mutex_t lock;
+  int result;
+  FAR struct ap_buffer_s *completed_apb;
+  bool callback_done;
+  bool abandoned;
+  unsigned int chunk;
+};
+
+struct robot_voice_rx_slot_s
+{
+  FAR struct ap_buffer_s *apb;
+  FAR struct robot_voice_rx_xfer_s *xfer;
+  size_t request_bytes;
+  unsigned int chunk;
+  bool in_flight;
+};
+
+static void robot_voice_rx_xfer_destroy(
+  FAR struct robot_voice_rx_xfer_s *xfer)
+{
+  nxmutex_destroy(&xfer->lock);
+  nxsem_destroy(&xfer->done);
+}
+
+static void robot_voice_rx_callback(FAR struct i2s_dev_s *dev,
+                                    FAR struct ap_buffer_s *apb,
+                                    FAR void *arg, int result)
+{
+  FAR struct robot_voice_rx_xfer_s *xfer = arg;
+  bool abandoned;
+
+  (void)dev;
+
+  nxmutex_lock(&xfer->lock);
+  abandoned = xfer->abandoned;
+  if (abandoned)
+    {
+      nxmutex_unlock(&xfer->lock);
+      if (apb != NULL)
+        {
+          /* Release the application reference; the lower half releases its
+           * reference after this callback returns. */
+          apb_free(apb);
+        }
+
+      robot_voice_rx_xfer_destroy(xfer);
+      free(xfer);
+      return;
+    }
+
+  if (apb != NULL && result >= 0)
+    {
+      /* Retain the completed buffer until the capture task copies it. */
+      apb_reference(apb);
+      xfer->completed_apb = apb;
+    }
+
+  xfer->result = result;
+  xfer->callback_done = true;
+  printf("[RV-CAP] callback chunk=%u rc=%d nbytes=%zu nmax=%zu cur=%zu\n",
+         xfer->chunk, result, apb == NULL ? 0 : apb->nbytes,
+         apb == NULL ? 0 : apb->nmaxbytes,
+         apb == NULL ? 0 : apb->curbyte);
+  nxsem_post(&xfer->done);
+  nxmutex_unlock(&xfer->lock);
+}
+
+static int robot_voice_rx_slot_alloc(FAR struct robot_voice_rx_slot_s *slot,
+                                     size_t request_bytes,
+                                     unsigned int chunk)
+{
+  struct audio_buf_desc_s desc;
+  FAR struct robot_voice_rx_xfer_s *xfer;
+  int ret;
+
+  memset(&desc, 0, sizeof(desc));
+  desc.numbytes = request_bytes;
+  desc.u.pbuffer = &slot->apb;
+  ret = apb_alloc(&desc);
+  if (ret < 0 || slot->apb == NULL)
+    {
+      printf("[RV-CAP] alloc apb bytes=%zu rc=%d ptr=%p\n", request_bytes,
+             ret, slot->apb);
+      return ret < 0 ? ret : -ENOMEM;
+    }
+
+  xfer = calloc(1, sizeof(*xfer));
+  if (xfer == NULL)
+    {
+      apb_free(slot->apb);
+      slot->apb = NULL;
+      return -ENOMEM;
+    }
+
+  nxsem_init(&xfer->done, 0, 0);
+  nxmutex_init(&xfer->lock);
+  xfer->result = -EINPROGRESS;
+  xfer->chunk = chunk;
+  slot->xfer = xfer;
+  slot->request_bytes = request_bytes;
+  slot->chunk = chunk;
+  return OK;
+}
+
+static void robot_voice_rx_slot_release(
+  FAR struct robot_voice_rx_slot_s *slot)
+{
+  if (slot->xfer != NULL)
+    {
+      if (slot->xfer->completed_apb != NULL)
+        {
+          apb_free(slot->xfer->completed_apb);
+        }
+
+      robot_voice_rx_xfer_destroy(slot->xfer);
+      free(slot->xfer);
+    }
+
+  if (slot->apb != NULL)
+    {
+      apb_free(slot->apb);
+    }
+
+  memset(slot, 0, sizeof(*slot));
+}
+
+static int robot_voice_rx_slot_submit(FAR struct i2s_dev_s *mic,
+                                      FAR struct robot_voice_rx_slot_s *slot,
+                                      size_t request_bytes,
+                                      unsigned int chunk)
+{
+  int ret;
+
+  ret = robot_voice_rx_slot_alloc(slot, request_bytes, chunk);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  printf("[RV-CAP] receive submit chunk=%u apb=%p nmax=%zu nbytes=%zu "
+         "cur=%zu logical=%zu\n", chunk, slot->apb,
+         slot->apb->nmaxbytes, slot->apb->nbytes, slot->apb->curbyte,
+         request_bytes);
+  ret = I2S_RECEIVE(mic, slot->apb, robot_voice_rx_callback, slot->xfer,
+                    MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS));
+  printf("[RV-CAP] I2S_RECEIVE chunk=%u rc=%d\n", chunk, ret);
+  if (ret < 0)
+    {
+      robot_voice_rx_slot_release(slot);
+      return ret;
+    }
+
+  slot->in_flight = true;
+  return OK;
+}
+
+static int robot_voice_rx_slot_wait(FAR struct robot_voice_rx_slot_s *slot,
+                                    clock_t timeout)
+{
+  FAR struct robot_voice_rx_xfer_s *xfer = slot->xfer;
+  int ret;
+
+  printf("[RV-CAP] wait callback chunk=%u\n", slot->chunk);
+  do
+    {
+      ret = nxsem_tickwait(&xfer->done, timeout);
+    }
+  while (ret == -EINTR);
+
+  if (ret >= 0)
+    {
+      nxmutex_lock(&xfer->lock);
+      ret = xfer->result;
+      nxmutex_unlock(&xfer->lock);
+      return ret;
+    }
+
+  if (ret == -ETIMEDOUT)
+    {
+      nxmutex_lock(&xfer->lock);
+      if (xfer->callback_done)
+        {
+          ret = xfer->result;
+          nxmutex_unlock(&xfer->lock);
+          return ret;
+        }
+
+      xfer->abandoned = true;
+      nxmutex_unlock(&xfer->lock);
+      /* The later callback owns the context and both APB references. */
+      slot->xfer = NULL;
+      slot->apb = NULL;
+      slot->in_flight = false;
+    }
+
+  return ret;
+}
+
+static int robot_voice_rx_copy(FAR const struct robot_voice_rx_slot_s *slot,
+                               uint8_t *dst, size_t cap, size_t *used)
+{
+  FAR const struct robot_voice_rx_xfer_s *xfer = slot->xfer;
+  FAR const int16_t *src;
+  FAR int16_t *out;
+  size_t nbytes;
+  size_t samples;
+  size_t i;
+
+  if (xfer == NULL || xfer->completed_apb == NULL || dst == NULL ||
+      used == NULL)
+    {
+      return -EIO;
+    }
+
+  nbytes = xfer->completed_apb->nbytes;
+  nbytes -= nbytes % sizeof(int16_t);
+  if (nbytes != slot->request_bytes || nbytes > cap - *used)
+    {
+      return -EIO;
+    }
+
+  memcpy(dst + *used, xfer->completed_apb->samp, nbytes);
+  src = (FAR const int16_t *)(dst + *used);
+  out = (FAR int16_t *)(dst + *used);
+  samples = nbytes / sizeof(int16_t);
+  for (i = 0; i < samples; i++)
+    {
+      int32_t gained = (int32_t)src[i] * 2;
+
+      if (gained > INT16_MAX)
+        {
+          gained = INT16_MAX;
+        }
+      else if (gained < INT16_MIN)
+        {
+          gained = INT16_MIN;
+        }
+
+      out[i] = (int16_t)gained;
+    }
+
+  *used += nbytes;
+  return OK;
+}
+
+static void robot_voice_rx_abort(FAR struct i2s_dev_s *mic,
+                                 FAR struct robot_voice_rx_slot_s *slots)
+{
+  unsigned int i;
+
+  for (i = 0; i < ROBOT_VOICE_RX_SLOT_COUNT; i++)
+    {
+      FAR struct robot_voice_rx_slot_s *slot = &slots[i];
+
+      if (!slot->in_flight)
+        {
+          continue;
+        }
+
+      nxmutex_lock(&slot->xfer->lock);
+      if (!slot->xfer->callback_done)
+        {
+          slot->xfer->abandoned = true;
+          nxmutex_unlock(&slot->xfer->lock);
+          slot->xfer = NULL;
+          slot->apb = NULL;
+          slot->in_flight = false;
+        }
+      else
+        {
+          nxmutex_unlock(&slot->xfer->lock);
+          robot_voice_rx_slot_release(slot);
+        }
+    }
+
+  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
+}
+
+int robot_voice_capture_record(uint8_t *buf, size_t cap, size_t *out_len,
+                               unsigned int duration_ms)
+{
+  struct robot_voice_rx_slot_s slots[ROBOT_VOICE_RX_SLOT_COUNT];
+  FAR struct i2s_dev_s *mic;
+  size_t target;
+  size_t capture_target;
+  size_t submitted_bytes = 0;
+  size_t used = 0;
+  unsigned int submitted = 0;
+  unsigned int completed = 0;
+  unsigned int in_flight = 0;
+  unsigned int wait_slot = 0;
+  unsigned int warmup_chunks = 0;
+  clock_t deadline;
+  int ret;
+
+  if (buf == NULL || out_len == NULL || cap < sizeof(int16_t) ||
+      duration_ms == 0)
