+      return -EINVAL;
+    }
+
+  *out_len = 0;
+  target = ((size_t)ROBOT_VOICE_CAPTURE_RATE * sizeof(int16_t) *
+            duration_ms) / 1000;
+  target = target > cap ? cap : target;
+  target -= target % sizeof(int16_t);
+  if (target == 0)
+    {
+      return -EINVAL;
+    }
+
+  memset(slots, 0, sizeof(slots));
+  printf("[RV-CAP] open i2s...\n");
+  mic = board_voice_mic_i2s();
+  printf("[RV-CAP] i2s=%p\n", mic);
+  if (mic == NULL)
+    {
+      return -ENODEV;
+    }
+
+  ret = I2S_RXCHANNELS(mic, ROBOT_VOICE_CHANNELS);
+  printf("[RV-CAP] set channels %d rc=%d\n", ROBOT_VOICE_CHANNELS, ret);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  ret = I2S_RXSAMPLERATE(mic, ROBOT_VOICE_CAPTURE_RATE);
+  printf("[RV-CAP] set rate %d rc=%d\n", ROBOT_VOICE_CAPTURE_RATE, ret);
+  if (ret != ROBOT_VOICE_CAPTURE_RATE)
+    {
+      return ret < 0 ? ret : -ENOTSUP;
+    }
+
+  ret = I2S_RXDATAWIDTH(mic, ROBOT_VOICE_BITS);
+  printf("[RV-CAP] set width %d rc=%d\n", ROBOT_VOICE_BITS, ret);
+  if (ret != ROBOT_VOICE_BITS)
+    {
+      return ret < 0 ? ret : -ENOTSUP;
+    }
+
+  board_voice_mic_set_diagnostics(false);
+  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
+  printf("[RV-CAP] start rc=%d\n", ret);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  capture_target = target +
+                   ROBOT_VOICE_RX_WARMUP_CHUNKS * ROBOT_VOICE_RX_DMA_BYTES;
+  deadline = clock_systime_ticks() + MSEC2TICK(ROBOT_VOICE_RECORD_TIMEOUT_MS);
+  printf("[RV-CAP] recording %u ms target=%zu chunk=%d warmup=%d\n",
+         duration_ms, target, ROBOT_VOICE_RX_DMA_BYTES,
+         ROBOT_VOICE_RX_WARMUP_CHUNKS);
+
+  while (submitted_bytes < capture_target &&
+         in_flight < ROBOT_VOICE_RX_SLOT_COUNT)
+    {
+      size_t request = capture_target - submitted_bytes;
+
+      if (request > ROBOT_VOICE_RX_DMA_BYTES)
+        {
+          request = ROBOT_VOICE_RX_DMA_BYTES;
+        }
+
+      ret = robot_voice_rx_slot_submit(mic, &slots[in_flight], request,
+                                       submitted);
+      if (ret < 0)
+        {
+          goto errout;
+        }
+
+      submitted_bytes += request;
+      submitted++;
+      in_flight++;
+    }
+
+  while (in_flight != 0)
+    {
+      FAR struct robot_voice_rx_slot_s *slot = &slots[wait_slot];
+      clock_t remaining = deadline - clock_systime_ticks();
+      clock_t wait_ticks;
+
+      if ((int32_t)remaining <= 0)
+        {
+          ret = -ETIMEDOUT;
+          goto errout;
+        }
+
+      wait_ticks = remaining < MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS) ?
+                   remaining : MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS);
+      ret = robot_voice_rx_slot_wait(slot, wait_ticks);
+      if (ret < 0)
+        {
+          printf("[RV-CAP] wait chunk=%u rc=%d\n", slot->chunk, ret);
+          goto errout;
+        }
+
+      if (warmup_chunks < ROBOT_VOICE_RX_WARMUP_CHUNKS)
+        {
+          warmup_chunks++;
+          printf("[RV-CAP] warmup discard chunk=%u bytes=%zu\n",
+                 slot->chunk, slot->request_bytes);
+        }
+      else
+        {
+          ret = robot_voice_rx_copy(slot, buf, cap, &used);
+          if (ret < 0)
+            {
+              printf("[RV-CAP] copy chunk=%u rc=%d\n", slot->chunk, ret);
+              goto errout;
+            }
+        }
+
+      robot_voice_rx_slot_release(slot);
+      completed++;
+      in_flight--;
+      if (submitted_bytes < capture_target)
+        {
+          size_t request = capture_target - submitted_bytes;
+
+          if (request > ROBOT_VOICE_RX_DMA_BYTES)
+            {
+              request = ROBOT_VOICE_RX_DMA_BYTES;
+            }
+
+          ret = robot_voice_rx_slot_submit(mic, slot, request, submitted);
+          if (ret < 0)
+            {
+              goto errout;
+            }
+
+          submitted_bytes += request;
+          submitted++;
+          in_flight++;
+        }
+
+      wait_slot = (wait_slot + 1) % ROBOT_VOICE_RX_SLOT_COUNT;
+    }
+
+  ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
+  printf("[RV-CAP] stop rc=%d submitted=%u completed=%u\n", ret,
+         submitted, completed);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (used != target || submitted_bytes != capture_target)
+    {
+      return -EIO;
+    }
+
+  *out_len = used;
+  printf("[RV-CAP] captured %zu bytes\n", used);
+  return OK;
+
+errout:
+  robot_voice_rx_abort(mic, slots);
+  printf("[RV-CAP] failed stage=rx rc=%d submitted=%u completed=%u\n", ret,
+         submitted, completed);
+  return ret;
+}
