   187	static int robot_voice_rx_slot_wait(FAR struct robot_voice_rx_slot_s *slot,
   188	                                    clock_t timeout)
   189	{
   190	  FAR struct robot_voice_rx_xfer_s *xfer = slot->xfer;
   191	  int ret;
   192	
   193	  printf("[RV-CAP] wait callback chunk=%u\n", slot->chunk);
   194	  do
   195	    {
   196	      ret = nxsem_tickwait(&xfer->done, timeout);
   197	    }
   198	  while (ret == -EINTR);
   199	
   200	  if (ret >= 0)
   201	    {
   202	      nxmutex_lock(&xfer->lock);
   203	      ret = xfer->result;
   204	      nxmutex_unlock(&xfer->lock);
   205	      return ret;
   206	    }
   207	
   208	  if (ret == -ETIMEDOUT)
   209	    {
   210	      nxmutex_lock(&xfer->lock);
   211	      if (xfer->callback_done)
   212	        {
   213	          ret = xfer->result;
   214	          nxmutex_unlock(&xfer->lock);
   215	          return ret;
   216	        }
   217	
   218	      xfer->abandoned = true;
   219	      nxmutex_unlock(&xfer->lock);
   220	      /* The later callback owns the context and both APB references. */
   221	      slot->xfer = NULL;
   222	      slot->apb = NULL;
   223	      slot->in_flight = false;
   224	    }
   225	
   226	  return ret;
   227	}
