   229	static int robot_voice_rx_copy(FAR const struct robot_voice_rx_slot_s *slot,
   230	                               uint8_t *dst, size_t cap, size_t *used)
   231	{
   232	  FAR const struct robot_voice_rx_xfer_s *xfer = slot->xfer;
   233	  FAR const int16_t *src;
   234	  FAR int16_t *out;
   235	  size_t nbytes;
   236	  size_t samples;
   237	  size_t i;
   238	
   239	  if (xfer == NULL || xfer->completed_apb == NULL || dst == NULL ||
   240	      used == NULL)
   241	    {
   242	      return -EIO;
   243	    }
   244	
   245	  nbytes = xfer->completed_apb->nbytes;
   246	  nbytes -= nbytes % sizeof(int16_t);
   247	  if (nbytes != slot->request_bytes || nbytes > cap - *used)
   248	    {
   249	      return -EIO;
   250	    }
   251	
   252	  memcpy(dst + *used, xfer->completed_apb->samp, nbytes);
   253	  src = (FAR const int16_t *)(dst + *used);
   254	  out = (FAR int16_t *)(dst + *used);
   255	  samples = nbytes / sizeof(int16_t);
   256	  for (i = 0; i < samples; i++)
   257	    {
   258	      int32_t gained = (int32_t)src[i] * 2;
   259	
   260	      if (gained > INT16_MAX)
   261	        {
   262	          gained = INT16_MAX;
   263	        }
   264	      else if (gained < INT16_MIN)
   265	        {
   266	          gained = INT16_MIN;
   267	        }
   268	
   269	      out[i] = (int16_t)gained;
   270	    }
   271	
   272	  *used += nbytes;
   273	  return OK;
   274	}
