    56	static void robot_voice_rx_callback(FAR struct i2s_dev_s *dev,
    57	                                    FAR struct ap_buffer_s *apb,
    58	                                    FAR void *arg, int result)
    59	{
    60	  FAR struct robot_voice_rx_xfer_s *xfer = arg;
    61	  bool abandoned;
    62	
    63	  (void)dev;
    64	
    65	  nxmutex_lock(&xfer->lock);
    66	  abandoned = xfer->abandoned;
    67	  if (abandoned)
    68	    {
    69	      nxmutex_unlock(&xfer->lock);
