    68	static void *voice_record_worker(void *arg)
    69	{
    70	  size_t pcm_cap = (size_t)ROBOT_VOICE_CAPTURE_RATE * 2 *
    71	                   ROBOT_VOICE_CAPTURE_SECONDS;
    72	  uint8_t *pcm = malloc(pcm_cap);
    73	  char key[256];
    74	  char text[512];
    75	  (void)arg;
    76	
    77	  if (pcm == NULL)
    78	    {
    79	      g_voice_running = 0;
    80	      return NULL;
    81	    }
    82	
    83	  while (g_voice_running)
    84	    {
    85	      size_t pcm_len = 0;
    86	      int ret = robot_voice_capture_record(
    87	          pcm, pcm_cap, &pcm_len, ROBOT_VOICE_CAPTURE_SECONDS * 1000);
    88	      if (ret < 0 || !g_voice_running)
    89	        {
    90	          break;
    91	        }
    92	      if (g_voice_speaking)
    93	        {
    94	          continue;
    95	        }
    96	      if (voice_get_api_key(key, sizeof(key)) < 0)
    97	        {
    98	          printf("[contest_voice] ASR skipped: configure set_llm first\n");
    99	          break;
   100	        }
   101	      ret = mimo_asr_recognize(key, pcm, pcm_len, text, sizeof(text));
   102	      if (ret < 0 || text[0] == '\0')
   103	        {
   104	          printf("[contest_voice] ASR failed: %d\n", ret);
   105	          if (g_voice_oneshot)
   106	            {
   107	              break;
   108	            }
   109	          continue;
   110	        }
   111	
   112	      printf("[contest_voice] ASR: %s\n", text);
   113	      agent_msg_t msg;
   114	      memset(&msg, 0, sizeof(msg));
   115	      strncpy(msg.channel, AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
   116	      strncpy(msg.chat_id, "voice", sizeof(msg.chat_id) - 1);
   117	      msg.content = strdup(text);
   118	      if (msg.content == NULL || message_bus_push_inbound(&msg) != OK)
   119	        {
   120	          free(msg.content);
   121	          printf("[contest_voice] message bus submit failed\n");
   122	        }
   123	
   124	      if (g_voice_oneshot)
   125	        {
   126	          break;
   127	        }
   128	    }
   129	
   130	  free(pcm);
   131	  g_voice_running = 0;
   132	  return NULL;
   133	}
