   145	static int voice_channel_start_mode(int oneshot)
   146	{
   147	  pthread_mutex_lock(&g_voice_lock);
   148	  if (g_voice_thread_valid)
   149	    {
   150	      pthread_mutex_unlock(&g_voice_lock);
   151	      return -EBUSY;
   152	    }
   153	  g_voice_running = 1;
   154	  g_voice_oneshot = oneshot;
   155	  if (pthread_create(&g_voice_thread, NULL, voice_record_worker, NULL) != 0)
   156	    {
   157	      g_voice_running = 0;
   158	      g_voice_oneshot = 0;
   159	      pthread_mutex_unlock(&g_voice_lock);
   160	      return -EAGAIN;
   161	    }
   162	  g_voice_thread_valid = 1;
   163	  pthread_mutex_unlock(&g_voice_lock);
   164	  printf("[contest_voice] voice_channel_start mode=%s\n",
   165	         oneshot ? "once" : "continuous");
   166	  return 0;
   167	}
