   178	int voice_channel_stop(void)
   179	{
   180	  pthread_mutex_lock(&g_voice_lock);
   181	  if (!g_voice_thread_valid)
   182	    {
   183	      pthread_mutex_unlock(&g_voice_lock);
   184	      return 0;
   185	    }
   186	  g_voice_running = 0;
   187	  pthread_t tid = g_voice_thread;
   188	  pthread_mutex_unlock(&g_voice_lock);
   189	  pthread_join(tid, NULL);
   190	  pthread_mutex_lock(&g_voice_lock);
   191	  g_voice_thread_valid = 0;
   192	  g_voice_oneshot = 0;
   193	  pthread_mutex_unlock(&g_voice_lock);
   194	  printf("[contest_voice] voice_channel_stop\n");
   195	  return 0;
   196	}
