};

struct robot_voice_rx_slot_s
{
  FAR struct ap_buffer_s *apb;
  FAR struct robot_voice_rx_xfer_s *xfer;
  size_t request_bytes;
  unsigned int chunk;
  bool in_flight;
};

static void robot_voice_rx_xfer_destroy(
  FAR struct robot_voice_rx_xfer_s *xfer)
{
  /* Serialize with a callback that has posted the completion semaphore but
   * has not returned from its critical section yet. */

  nxmutex_lock(&xfer->lock);
  nxmutex_unlock(&xfer->lock);
  nxmutex_destroy(&xfer->lock);
  nxsem_destroy(&xfer->done);
}

static void robot_voice_rx_callback(FAR struct i2s_dev_s *dev,
                                    FAR struct ap_buffer_s *apb,
                                    FAR void *arg, int result)
{
  FAR struct robot_voice_rx_xfer_s *xfer = arg;

  (void)dev;

  nxmutex_lock(&xfer->lock);
  /* The I2S worker releases its reference only after this callback returns.
   * Take an application reference before waking the recording worker so the
   * APB remains valid while it copies the completed PCM. */

  if (apb != NULL)
    {
      apb_reference(apb);
      xfer->app_refs++;
    }

  xfer->result = result;
  xfer->callback_done = true;
  xfer->callback_pending = false;
  if (xfer->chunk < 2 || result < 0)
    {
      printf("[RV-CAP] callback chunk=%u rc=%d nbytes=%zu nmax=%zu "
             "cur=%zu\n", xfer->chunk, result,
             apb == NULL ? 0 : apb->nbytes,
             apb == NULL ? 0 : apb->nmaxbytes,
             apb == NULL ? 0 : apb->curbyte);
    }
  nxsem_post(&xfer->done);
  nxmutex_unlock(&xfer->lock);
}

static int robot_voice_rx_slot_alloc(FAR struct robot_voice_rx_slot_s *slot,
                                     size_t request_bytes,
                                     unsigned int chunk)
{
  struct audio_buf_desc_s desc;
  FAR struct robot_voice_rx_xfer_s *xfer;
  int ret;

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = request_bytes;
  desc.u.pbuffer = &slot->apb;
  ret = apb_alloc(&desc);
  if (ret < 0 || slot->apb == NULL)
    {
      printf("[RV-CAP] alloc apb bytes=%zu rc=%d ptr=%p\n", request_bytes,
             ret, slot->apb);
      return ret < 0 ? ret : -ENOMEM;
    }

  printf("[RV-CAP] alloc apb bytes=%zu ptr=%p\n", request_bytes,
         slot->apb);

  xfer = calloc(1, sizeof(*xfer));
  if (xfer == NULL)
    {
      apb_free(slot->apb);
      slot->apb = NULL;
      return -ENOMEM;
    }

  nxsem_init(&xfer->done, 0, 0);
  nxmutex_init(&xfer->lock);
  xfer->result = -EINPROGRESS;
  xfer->app_refs = 1;
  xfer->callback_pending = true;
  xfer->chunk = chunk;
  slot->xfer = xfer;
  slot->request_bytes = request_bytes;
  slot->chunk = chunk;
  return OK;
}

static void robot_voice_rx_slot_release(
  FAR struct robot_voice_rx_slot_s *slot)
{
  unsigned int app_refs = 0;

  if (slot->xfer != NULL)
    {
      nxmutex_lock(&slot->xfer->lock);
      app_refs = slot->xfer->app_refs;
      slot->xfer->app_refs = 0;
      nxmutex_unlock(&slot->xfer->lock);
      robot_voice_rx_xfer_destroy(slot->xfer);
      free(slot->xfer);
    }

  while (slot->apb != NULL && app_refs-- != 0)
    {
      apb_free(slot->apb);
    }

  memset(slot, 0, sizeof(*slot));
}

static int robot_voice_rx_slot_submit(FAR struct i2s_dev_s *mic,
                                      FAR struct robot_voice_rx_slot_s *slot,
                                      size_t request_bytes,
                                      unsigned int chunk)
{
  int ret;

  ret = robot_voice_rx_slot_alloc(slot, request_bytes, chunk);
  if (ret < 0)
    {
      return ret;
