   * protects PCM copying and final release. */


  nxmutex_lock(&slot->xfer->lock);
  apb_free(slot->apb);
  slot->xfer->app_refs--;
  nxmutex_unlock(&slot->xfer->lock);
  slot->in_flight = true;
  return OK;
}

static int robot_voice_rx_slot_wait(FAR struct robot_voice_rx_slot_s *slot,
                                    clock_t timeout)
{
  FAR struct robot_voice_rx_xfer_s *xfer = slot->xfer;
  int ret;

  printf("[RV-CAP] wait callback chunk=%u\n", slot->chunk);
  do
    {
      ret = nxsem_tickwait(&xfer->done, timeout);
    }
  while (ret == -EINTR);

  if (ret >= 0)
    {
      nxmutex_lock(&xfer->lock);
      ret = xfer->result;
      nxmutex_unlock(&xfer->lock);
      return ret;
    }

