int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
{
    if (!cap || !buf || len == 0) {
        return -EINVAL;
    }

    switch (cap->backend) {
    case AUDIO_CAPTURE_BACKEND_ALSA: {
#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
        snd_pcm_uframes_t frames;
        int nframes;
        size_t out_len;

        if (!cap->handle.pcm || cap->out_frame_bytes == 0) {
            return -EINVAL;
        }

        frames = len / cap->out_frame_bytes;
        if (frames == 0) {
            return -EINVAL;
        }

        if (cap->hw_channels == cap->requested_channels) {
            nframes = alsa_read_frames(cap, buf, frames);
            if (nframes <= 0) {
                return nframes;
            }

            out_len = (size_t)nframes * cap->out_frame_bytes;
            if (cap->bits_per_sample == 16) {
                apply_capture_gain(buf, out_len);
            }
            return (int)out_len;
        }

        if (cap->bits_per_sample != 16 || cap->requested_channels != 1) {
            return -ENOTSUP;
        }

        if (ensure_scratch_capacity(cap, frames * cap->hw_frame_bytes) < 0) {
            return -ENOMEM;
        }

        nframes = alsa_read_frames(cap, cap->scratch, frames);
        if (nframes <= 0) {
            return nframes;
        }

        downmix_interleaved_s16_to_mono(cap, buf, cap->scratch,
            (size_t)nframes);
        out_len = (size_t)nframes * cap->out_frame_bytes;
        apply_capture_gain(buf, out_len);
        return (int)out_len;
#else
        return -ENOTSUP;
#endif
    }

    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
        ssize_t n;

        if (!cap->handle.recorder) {
            return -EINVAL;
        }

        n = media_recorder_read_data(cap->handle.recorder, buf, len);
        if (n > 0 && cap->bits_per_sample == 16) {
            apply_capture_gain(buf, (size_t)n);
        }

        return (int)n;
    }

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
    case AUDIO_CAPTURE_BACKEND_BOARD_I2S: {
        unsigned char* dst = buf;
        size_t total = 0;

        while (total < len) {
            size_t nbytes = 0;
            int ret = board_i2s_read_block(cap, dst + total, len - total,
                &nbytes);

            if (ret < 0) {
                return total > 0 ? (int)total : ret;
            }

            if (nbytes == 0) {
                return total > 0 ? (int)total : -EIO;
            }

            if (cap->warmup_bytes >= nbytes) {
                cap->warmup_bytes -= nbytes;
                continue;
            }

            if (cap->warmup_bytes > 0) {
                size_t skip = cap->warmup_bytes;

                memmove(dst + total, dst + total + skip, nbytes - skip);
                nbytes -= skip;
                cap->warmup_bytes = 0;
            }

            total += nbytes;
        }

        apply_capture_gain(buf, total);
        return (int)total;
    }
#endif

    default:
        return -EINVAL;
    }
}

int audio_capture_abort(audio_capture_t* cap)
{
    if (!cap) {
        return -EINVAL;
    }

    switch (cap->backend) {
    case AUDIO_CAPTURE_BACKEND_ALSA:
#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
        if (cap->handle.pcm && cap->started) {
            int ret = snd_vela_pcm_drop(cap->handle.pcm);
            cap->started = 0;
            return ret;
        }
        return 0;
#else
        return -ENOTSUP;
#endif

    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
        if (cap->handle.recorder) {
#ifdef CONFIG_MEDIA_GRAPH
            media_recorder_close_socket(cap->handle.recorder);
#endif
            return media_recorder_stop(cap->handle.recorder);
        }
        return 0;

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
    case AUDIO_CAPTURE_BACKEND_BOARD_I2S:
        if (cap->i2s && cap->started) {
            cap->started = 0;
            return I2S_IOCTL(cap->i2s, AUDIOIOC_STOP, 0);
        }
        return 0;
#endif

    default:
        return -EINVAL;
    }
}

