#define ROBOT_VOICE_RX_DMA_BYTES       1024
#define ROBOT_VOICE_RX_SLOT_COUNT      2
#define ROBOT_VOICE_RX_WARMUP_CHUNKS   2
#define ROBOT_VOICE_RX_TIMEOUT_MS      1000
#define ROBOT_VOICE_RECORD_TIMEOUT_MS  7000

struct robot_voice_rx_xfer_s
{
  sem_t done;
  mutex_t lock;
  int result;
  bool callback_done;
  unsigned int app_refs;
  unsigned int chunk;
};

struct robot_voice_rx_slot_s
{
  FAR struct ap_buffer_s *apb;
  FAR struct robot_voice_rx_xfer_s *xfer;
  size_t request_bytes;
  unsigned int chunk;
  bool in_flight;
};

static void robot_voice_rx_xfer_destroy(
  FAR struct robot_voice_rx_xfer_s *xfer)
{
  /* Serialize with a callback that has posted the completion semaphore but
   * has not returned from its critical section yet. */

  nxmutex_lock(&xfer->lock);
  nxmutex_unlock(&xfer->lock);
  nxmutex_destroy(&xfer->lock);
  nxsem_destroy(&xfer->done);
}

static void robot_voice_rx_callback(FAR struct i2s_dev_s *dev,
                                    FAR struct ap_buffer_s *apb,
                                    FAR void *arg, int result)
{
  FAR struct robot_voice_rx_xfer_s *xfer = arg;

  (void)dev;

  nxmutex_lock(&xfer->lock);
  /* The I2S worker releases its reference only after this callback returns.
   * Take an application reference before waking the recording worker so the
   * APB remains valid while it copies the completed PCM. */

  if (apb != NULL)
    {
      apb_reference(apb);
      xfer->app_refs++;
    }

  xfer->result = result;
  xfer->callback_done = true;
  if (xfer->chunk < 2 || result < 0)
    {
      printf("[RV-CAP] callback chunk=%u rc=%d nbytes=%zu nmax=%zu "
             "cur=%zu\n", xfer->chunk, result,
             apb == NULL ? 0 : apb->nbytes,
             apb == NULL ? 0 : apb->nmaxbytes,
             apb == NULL ? 0 : apb->curbyte);
    }
  nxsem_post(&xfer->done);
  nxmutex_unlock(&xfer->lock);
}

static int robot_voice_rx_slot_alloc(FAR struct robot_voice_rx_slot_s *slot,
                                     size_t request_bytes,
                                     unsigned int chunk)
{
  struct audio_buf_desc_s desc;
  FAR struct robot_voice_rx_xfer_s *xfer;
  int ret;

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = request_bytes;
  desc.u.pbuffer = &slot->apb;
  ret = apb_alloc(&desc);
  if (ret < 0 || slot->apb == NULL)
    {
      printf("[RV-CAP] alloc apb bytes=%zu rc=%d ptr=%p\n", request_bytes,
             ret, slot->apb);
      return ret < 0 ? ret : -ENOMEM;
    }

  printf("[RV-CAP] alloc apb bytes=%zu ptr=%p\n", request_bytes,
         slot->apb);

  xfer = calloc(1, sizeof(*xfer));
  if (xfer == NULL)
    {
      apb_free(slot->apb);
      slot->apb = NULL;
      return -ENOMEM;
    }

  nxsem_init(&xfer->done, 0, 0);
  nxmutex_init(&xfer->lock);
  xfer->result = -EINPROGRESS;
  xfer->app_refs = 1;
  xfer->chunk = chunk;
  slot->xfer = xfer;
  slot->request_bytes = request_bytes;
  slot->chunk = chunk;
  return OK;
}

static void robot_voice_rx_slot_release(
  FAR struct robot_voice_rx_slot_s *slot)
{
  unsigned int app_refs = 0;

  if (slot->xfer != NULL)
    {
      nxmutex_lock(&slot->xfer->lock);
      app_refs = slot->xfer->app_refs;
      slot->xfer->app_refs = 0;
      nxmutex_unlock(&slot->xfer->lock);
      robot_voice_rx_xfer_destroy(slot->xfer);
      free(slot->xfer);
    }

  while (slot->apb != NULL && app_refs != 0)
    {
      apb_free(slot->apb);
      app_refs--;
    }

  memset(slot, 0, sizeof(*slot));
}

static int robot_voice_rx_slot_submit(FAR struct i2s_dev_s *mic,
                                      FAR struct robot_voice_rx_slot_s *slot,
                                      size_t request_bytes,
                                      unsigned int chunk)
{
  int ret;

  ret = robot_voice_rx_slot_alloc(slot, request_bytes, chunk);
  if (ret < 0)
    {
      return ret;
    }

  printf("[RV-CAP] receive submit chunk=%u apb=%p nmax=%zu nbytes=%zu "
         "cur=%zu logical=%zu\n", chunk, slot->apb,
         slot->apb->nmaxbytes, slot->apb->nbytes, slot->apb->curbyte,
         request_bytes);
  ret = I2S_RECEIVE(mic, slot->apb, robot_voice_rx_callback, slot->xfer,
                    MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS));
  printf("[RV-CAP] I2S_RECEIVE chunk=%u rc=%d\n", chunk, ret);
  if (ret < 0)
    {
      robot_voice_rx_slot_release(slot);
      return ret;
    }

  /* I2S_RECEIVE retained a driver reference.  Drop the allocation reference
   * now; the completion callback obtains the application reference that
   * protects PCM copying and final release. */

  nxmutex_lock(&slot->xfer->lock);
  apb_free(slot->apb);
  slot->xfer->app_refs--;
  nxmutex_unlock(&slot->xfer->lock);
  slot->in_flight = true;
  return OK;
}

static int robot_voice_rx_slot_wait(FAR struct robot_voice_rx_slot_s *slot,
                                    clock_t timeout)
{
  FAR struct robot_voice_rx_xfer_s *xfer = slot->xfer;
  int ret;

  printf("[RV-CAP] wait callback chunk=%u\n", slot->chunk);
  do
    {
      ret = nxsem_tickwait(&xfer->done, timeout);
    }
  while (ret == -EINTR);

  if (ret >= 0)
    {
      nxmutex_lock(&xfer->lock);
      ret = xfer->result;
      nxmutex_unlock(&xfer->lock);
      return ret;
    }

  return ret;
}

static int robot_voice_rx_slot_drain(FAR struct robot_voice_rx_slot_s *slot,
                                     int *callback_result)
{
  FAR struct robot_voice_rx_xfer_s *xfer = slot->xfer;
  int ret;

  if (callback_result == NULL)
    {
      return -EINVAL;
    }

  if (!slot->in_flight || xfer == NULL)
    {
      *callback_result = OK;
      return OK;
    }

  nxmutex_lock(&xfer->lock);
  if (xfer->callback_done)
    {
      *callback_result = xfer->result;
      nxmutex_unlock(&xfer->lock);
      return OK;
    }

  nxmutex_unlock(&xfer->lock);
  printf("[RV-CAP] waiting callback drain chunk=%u\n", slot->chunk);
  do
    {
      ret = nxsem_wait(&xfer->done);
    }
  while (ret == -EINTR);

  if (ret < 0)
    {
      return ret;
    }

  nxmutex_lock(&xfer->lock);
  *callback_result = xfer->result;
  nxmutex_unlock(&xfer->lock);
  return OK;
}

static int robot_voice_rx_copy(FAR const struct robot_voice_rx_slot_s *slot,
                               uint8_t *dst, size_t cap, size_t *used)
{
  FAR const int16_t *src;
  FAR int16_t *out;
  size_t nbytes;
  size_t samples;
  size_t i;

  if (slot->xfer == NULL || slot->apb == NULL || dst == NULL || used == NULL)
    {
      return -EIO;
    }

  nbytes = slot->apb->nbytes;
  nbytes -= nbytes % sizeof(int16_t);
  if (nbytes != slot->request_bytes || nbytes > cap - *used)
    {
      return -EIO;
    }

  memcpy(dst + *used, slot->apb->samp, nbytes);
  src = (FAR const int16_t *)(dst + *used);
  out = (FAR int16_t *)(dst + *used);
  samples = nbytes / sizeof(int16_t);
  for (i = 0; i < samples; i++)
    {
      int32_t gained = (int32_t)src[i] * 2;

      if (gained > INT16_MAX)
        {
          gained = INT16_MAX;
        }
      else if (gained < INT16_MIN)
        {
          gained = INT16_MIN;
        }

      out[i] = (int16_t)gained;
    }

  *used += nbytes;
  return OK;
}

static int robot_voice_rx_stop_and_drain(
  FAR struct i2s_dev_s *mic, FAR struct robot_voice_rx_slot_s *slots)
{
  unsigned int i;
  int ret;
  int drain_ret = OK;
  int callback_result;

  ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
  printf("[RV-CAP] stop requested rc=%d\n", ret);

  for (i = 0; i < ROBOT_VOICE_RX_SLOT_COUNT; i++)
    {
      FAR struct robot_voice_rx_slot_s *slot = &slots[i];

      if (!slot->in_flight)
        {
          continue;
        }

      drain_ret = robot_voice_rx_slot_drain(slot, &callback_result);
      if (drain_ret < 0)
        {
          printf("[RV-CAP] callback drain chunk=%u rc=%d\n", slot->chunk,
                 drain_ret);
          continue;
        }

      printf("[RV-CAP] callback drained chunk=%u result=%d\n", slot->chunk,
             callback_result);
      robot_voice_rx_slot_release(slot);
    }

  return ret < 0 ? ret : drain_ret;
}

static bool robot_voice_capture_stop_requested(
  FAR volatile bool *stop_requested)
{
  return stop_requested != NULL && *stop_requested;
}

int robot_voice_capture_record_interruptible(
  uint8_t *buf, size_t cap, size_t *out_len, unsigned int duration_ms,
  FAR volatile bool *stop_requested)
{
  struct robot_voice_rx_slot_s slots[ROBOT_VOICE_RX_SLOT_COUNT];
  FAR struct i2s_dev_s *mic;
  size_t target;
  size_t capture_target;
  size_t submitted_bytes = 0;
  size_t used = 0;
  unsigned int submitted = 0;
  unsigned int completed = 0;
  unsigned int in_flight = 0;
  unsigned int wait_slot = 0;
  unsigned int warmup_chunks = 0;
  clock_t deadline;
  int ret;

  if (buf == NULL || out_len == NULL || cap < sizeof(int16_t) ||
      duration_ms == 0)
    {
      return -EINVAL;
    }

  *out_len = 0;
  target = ((size_t)ROBOT_VOICE_CAPTURE_RATE * sizeof(int16_t) *
            duration_ms) / 1000;
  target = target > cap ? cap : target;
  target -= target % sizeof(int16_t);
  if (target == 0)
    {
      return -EINVAL;
    }

  memset(slots, 0, sizeof(slots));
  printf("[RV-CAP] open i2s...\n");
  mic = board_voice_mic_i2s();
  printf("[RV-CAP] i2s=%p\n", mic);
  if (mic == NULL)
    {
      return -ENODEV;
    }

  ret = I2S_RXCHANNELS(mic, ROBOT_VOICE_CHANNELS);
  printf("[RV-CAP] set channels %d rc=%d\n", ROBOT_VOICE_CHANNELS, ret);
  if (ret < 0)
    {
      return ret;
    }

  ret = I2S_RXSAMPLERATE(mic, ROBOT_VOICE_CAPTURE_RATE);
  printf("[RV-CAP] set rate %d rc=%d\n", ROBOT_VOICE_CAPTURE_RATE, ret);
  if (ret != ROBOT_VOICE_CAPTURE_RATE)
    {
      return ret < 0 ? ret : -ENOTSUP;
    }

  ret = I2S_RXDATAWIDTH(mic, ROBOT_VOICE_BITS);
  printf("[RV-CAP] set width %d rc=%d\n", ROBOT_VOICE_BITS, ret);
  if (ret != ROBOT_VOICE_BITS)
    {
      return ret < 0 ? ret : -ENOTSUP;
    }

  board_voice_mic_set_diagnostics(false);
  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
  printf("[RV-CAP] start rc=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  capture_target = target +
                   ROBOT_VOICE_RX_WARMUP_CHUNKS * ROBOT_VOICE_RX_DMA_BYTES;
  deadline = clock_systime_ticks() + MSEC2TICK(ROBOT_VOICE_RECORD_TIMEOUT_MS);
  printf("[RV-CAP] recording %u ms target=%zu chunk=%d warmup=%d\n",
         duration_ms, target, ROBOT_VOICE_RX_DMA_BYTES,
         ROBOT_VOICE_RX_WARMUP_CHUNKS);

  while (submitted_bytes < capture_target &&
         in_flight < ROBOT_VOICE_RX_SLOT_COUNT)
    {
      size_t request = capture_target - submitted_bytes;

      if (robot_voice_capture_stop_requested(stop_requested))
        {
          ret = -ECANCELED;
          goto errout;
        }

      if (request > ROBOT_VOICE_RX_DMA_BYTES)
        {
          request = ROBOT_VOICE_RX_DMA_BYTES;
        }

      ret = robot_voice_rx_slot_submit(mic, &slots[in_flight], request,
                                       submitted);
      if (ret < 0)
        {
          goto errout;
        }

      submitted_bytes += request;
      submitted++;
      in_flight++;
    }

  while (in_flight != 0)
    {
      FAR struct robot_voice_rx_slot_s *slot = &slots[wait_slot];
      clock_t remaining = deadline - clock_systime_ticks();
      clock_t wait_ticks;

      if (robot_voice_capture_stop_requested(stop_requested))
        {
          ret = -ECANCELED;
          goto errout;
        }

      if ((int32_t)remaining <= 0)
        {
          ret = -ETIMEDOUT;
          goto errout;
        }

      wait_ticks = remaining < MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS) ?
                   remaining : MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS);
      ret = robot_voice_rx_slot_wait(slot, wait_ticks);
      if (ret < 0)
        {
          printf("[RV-CAP] wait chunk=%u rc=%d\n", slot->chunk, ret);
          goto errout;
        }

      if (warmup_chunks < ROBOT_VOICE_RX_WARMUP_CHUNKS)
        {
          warmup_chunks++;
          printf("[RV-CAP] warmup discard chunk=%u bytes=%zu\n",
                 slot->chunk, slot->request_bytes);
        }
      else
        {
          ret = robot_voice_rx_copy(slot, buf, cap, &used);
          if (ret < 0)
            {
              printf("[RV-CAP] copy chunk=%u rc=%d\n", slot->chunk, ret);
              goto errout;
            }
        }

      robot_voice_rx_slot_release(slot);
      completed++;
      in_flight--;
      if (submitted_bytes < capture_target)
        {
          size_t request = capture_target - submitted_bytes;

          if (robot_voice_capture_stop_requested(stop_requested))
            {
              ret = -ECANCELED;
              goto errout;
            }

          if (request > ROBOT_VOICE_RX_DMA_BYTES)
            {
              request = ROBOT_VOICE_RX_DMA_BYTES;
            }

          ret = robot_voice_rx_slot_submit(mic, slot, request, submitted);
          if (ret < 0)
            {
              goto errout;
            }

          submitted_bytes += request;
          submitted++;
          in_flight++;
        }

      wait_slot = (wait_slot + 1) % ROBOT_VOICE_RX_SLOT_COUNT;
    }

  ret = robot_voice_rx_stop_and_drain(mic, slots);
  printf("[RV-CAP] stop complete rc=%d submitted=%u completed=%u\n", ret,
         submitted, completed);
  if (ret < 0)
    {
      return ret;
    }

  if (used != target || submitted_bytes != capture_target)
    {
      return -EIO;
    }

  *out_len = used;
  printf("[RV-CAP] captured %zu bytes\n", used);
  printf("[RV-CAP] capture complete\n");
  return OK;

errout:
  (void)robot_voice_rx_stop_and_drain(mic, slots);
  printf("[RV-CAP] failed stage=rx rc=%d submitted=%u completed=%u\n", ret,
         submitted, completed);
  return ret;
}

int robot_voice_capture_record(uint8_t *buf, size_t cap, size_t *out_len,
                               unsigned int duration_ms)
{
  return robot_voice_capture_record_interruptible(buf, cap, out_len,
                                                  duration_ms, NULL);
}
