   105	static int make_asr_body(const uint8_t *pcm, size_t pcm_len, char **body_out,
   106	                         size_t *body_len_out)
   107	{
   108	  uint8_t *wav = NULL;
   109	  unsigned char *b64 = NULL;
   110	  char *data_uri = NULL;
   111	  char *body = NULL;
   112	  cJSON *root = NULL;
   113	  cJSON *messages = NULL;
   114	  cJSON *message = NULL;
   115	  cJSON *content = NULL;
   116	  cJSON *item = NULL;
   117	  cJSON *audio = NULL;
   118	  size_t wav_len;
   119	  size_t b64_len = 0;
   120	  size_t b64_cap;
   121	  int ret;
   122	
   123	  if (pcm == NULL || body_out == NULL || body_len_out == NULL ||
   124	      pcm_len == 0 || pcm_len > ROBOT_VOICE_MAX_BODY - 44)
   125	    {
   126	      return -EINVAL;
   127	    }
   128	
   129	  wav_len = pcm_len + 44;
   130	  b64_cap = ((wav_len + 2) / 3) * 4 + 1;
   131	  wav = malloc(wav_len);
   132	  b64 = malloc(b64_cap);
   133	  if (wav == NULL || b64 == NULL)
   134	    {
   135	      ret = -ENOMEM;
   136	      goto out;
   137	    }
   138	
   139	  memcpy(wav, "RIFF", 4); put32(wav + 4, pcm_len + 36);
   140	  memcpy(wav + 8, "WAVEfmt ", 8); put32(wav + 16, 16);
   141	  put16(wav + 20, 1); put16(wav + 22, 1); put32(wav + 24, 16000);
   142	  put32(wav + 28, 32000); put16(wav + 32, 2); put16(wav + 34, 16);
   143	  memcpy(wav + 36, "data", 4); put32(wav + 40, pcm_len);
   144	  memcpy(wav + 44, pcm, pcm_len);
   145	  ret = mbedtls_base64_encode(b64, b64_cap, &b64_len, wav, wav_len);
   146	  free(wav);
   147	  wav = NULL;
   148	  if (ret != 0)
   149	    {
   150	      ret = -EIO;
   151	      goto out;
   152	    }
   153	
   154	  b64[b64_len] = '\0';
   155	  data_uri = malloc(b64_len + 24);
   156	  if (data_uri == NULL)
   157	    {
   158	      ret = -ENOMEM;
   159	      goto out;
   160	    }
   161	
   162	  snprintf(data_uri, b64_len + 24, "data:audio/wav;base64,%s", b64);
   163	  free(b64);
   164	  b64 = NULL;
   165	
   166	  root = cJSON_CreateObject();
   167	  messages = cJSON_CreateArray();
   168	  message = cJSON_CreateObject();
   169	  content = cJSON_CreateArray();
   170	  item = cJSON_CreateObject();
   171	  audio = cJSON_CreateObject();
   172	  if (!root || !messages || !message || !content || !item || !audio)
   173	    {
   174	      ret = -ENOMEM;
   175	      goto out;
   176	    }
   177	
   178	  cJSON_AddStringToObject(root, "model", ROBOT_VOICE_ASR_MODEL);
   179	  cJSON_AddStringToObject(message, "role", "user");
   180	  cJSON_AddStringToObject(item, "type", "input_audio");
   181	  cJSON_AddStringToObject(audio, "data", data_uri);
   182	  cJSON_AddItemToObject(item, "input_audio", audio); audio = NULL;
   183	  cJSON_AddItemToArray(content, item); item = NULL;
   184	  cJSON_AddItemToObject(message, "content", content); content = NULL;
   185	  cJSON_AddItemToArray(messages, message); message = NULL;
   186	  cJSON_AddItemToObject(root, "messages", messages); messages = NULL;
   187	  cJSON_AddItemToObject(root, "asr_options", cJSON_CreateObject());
   188	  cJSON_AddStringToObject(cJSON_GetObjectItem(root, "asr_options"),
   189	                          "language", "zh");
   190	
   191	  body = cJSON_PrintUnformatted(root);
   192	  if (body == NULL)
   193	    {
   194	      ret = -ENOMEM;
   195	      goto out;
   196	    }
   197	
   198	  *body_out = body;
   199	  *body_len_out = strlen(body);
   200	  body = NULL;
   201	  ret = 0;
   202	
   203	out:
   204	  cJSON_Delete(root);
   205	  cJSON_Delete(messages);
   206	  cJSON_Delete(message);
   207	  cJSON_Delete(content);
   208	  cJSON_Delete(item);
   209	  cJSON_Delete(audio);
   210	  free(wav);
   211	  free(b64);
   212	  free(data_uri);
   213	  free(body);
   214	  return ret;
   215	}
