   217	int mimo_asr_recognize(const char *api_key, const uint8_t *pcm, size_t pcm_len,
   218	                       char *text, size_t text_cap)
   219	{
   220	  char *body = NULL;
   221	  struct rv_guard_buf_s body_buf = { 0 };
   222	  struct rv_guard_buf_s response_buf = { 0 };
   223	  size_t response_len = 0;
   224	  size_t body_len = 0;
   225	  cJSON *root = NULL;
   226	  cJSON *choices = NULL;
   227	  cJSON *first = NULL;
   228	  cJSON *msg = NULL;
   229	  cJSON *answer = NULL;
   230	  int ret;
   231	
   232	  printf("[RV-ASR] request begin\n");
   233	  if (!api_key || !pcm || !text || text_cap == 0 || pcm_len == 0 ||
   234	      pcm_len > ROBOT_VOICE_MAX_BODY - 44)
   235	    {
   236	      return -EINVAL;
   237	    }
   238	
   239	  ret = make_asr_body(pcm, pcm_len, &body, &body_len);
   240	  if (ret < 0)
   241	    {
   242	      goto out;
   243	    }
   244	
   245	  ret = rv_guard_alloc(&body_buf, body_len + 1);
   246	  if (ret < 0)
   247	    {
   248	      goto out;
   249	    }
   250	  memcpy(body_buf.data, body, body_len + 1);
   251	  free(body);
   252	  body = NULL;
   253	
   254	  ret = rv_guard_alloc(&response_buf, ROBOT_VOICE_HTTP_RESPONSE);
   255	  if (ret < 0)
   256	    {
   257	      goto out;
   258	    }
   259	
   260	  printf("[RV-GUARD] body %s\n", rv_guard_ok(&body_buf) ? "PASS" : "FAIL");
   261	  printf("[RV-GUARD] response %s\n",
   262	         rv_guard_ok(&response_buf) ? "PASS" : "FAIL");
   263	  if (!rv_guard_ok(&body_buf) || !rv_guard_ok(&response_buf))
   264	    {
   265	      ret = -EFAULT;
   266	      goto out;
   267	    }
   268	
   269	  rv_asr_diag("before_transport", body_buf.data, body_len, body_buf.cap,
   270	              response_buf.data, 0, response_buf.cap);
   271	  ret = robot_mimo_post(api_key, (char *)body_buf.data, body_len,
   272	                        (char *)response_buf.data, response_buf.cap,
   273	                        &response_len);
   274	  rv_asr_diag("after_transport", body_buf.data, body_len, body_buf.cap,
   275	              response_buf.data, response_len, response_buf.cap);
   276	  printf("[RV-GUARD] body %s\n", rv_guard_ok(&body_buf) ? "PASS" : "FAIL");
   277	  printf("[RV-GUARD] response %s\n",
   278	         rv_guard_ok(&response_buf) ? "PASS" : "FAIL");
   279	  if (!rv_guard_ok(&body_buf) || !rv_guard_ok(&response_buf))
   280	    {
   281	      ret = -EFAULT;
   282	      goto out;
   283	    }
   284	  if (ret < 0)
   285	    {
   286	      goto out;
   287	    }
   288	  if (response_len == response_buf.cap)
   289	    {
   290	      ret = -EOVERFLOW;
   291	      goto out;
   292	    }
   293	
   294	  root = cJSON_Parse((char *)response_buf.data);
   295	  if (!root) { ret = -EPROTO; goto out; }
   296	  choices = cJSON_GetObjectItem(root, "choices");
   297	  first = cJSON_GetArrayItem(choices, 0);
   298	  msg = first ? cJSON_GetObjectItem(first, "message") : NULL;
   299	  answer = msg ? cJSON_GetObjectItem(msg, "content") : NULL;
   300	  if (!cJSON_IsString(answer) || !answer->valuestring)
   301	    { ret = -EPROTO; goto out; }
   302	  strncpy(text, answer->valuestring, text_cap - 1); text[text_cap - 1] = '\0';
   303	  printf("[RV-ASR] pcm=%zu response=%zu result=%zu\n", pcm_len, response_len,
   304	         strlen(text));
   305	  ret = 0;
   306	out:
   307	  cJSON_Delete(root);
   308	  free(body);
   309	  rv_guard_free(&body_buf);
   310	  rv_guard_free(&response_buf);
   311	  printf("[RV-ASR] request done rc=%d\n", ret);
   312	  return ret;
   313	}

