   117	static unsigned int agent_oled_make_lines(const char *text,
   118	                                           char lines[AGENT_OLED_MAX_LINES]
   119	                                                [AGENT_OLED_CHARS_PER_LINE + 1])
   120	{
   121	  unsigned int line = 0;
   122	  unsigned int column = 0;
   123	  size_t pos = 0;
   124	
   125	  while (text[pos] != '\0' && line < AGENT_OLED_MAX_LINES)
   126	    {
   127	      unsigned char ch = (unsigned char)text[pos++];
   128	
   129	      if (ch >= 0x80)
   130	        {
   131	          agent_oled_mark_non_ascii();
   132	          while ((unsigned char)text[pos] >= 0x80 &&
   133	                 ((unsigned char)text[pos] & 0xc0) != 0xc0)
   134	            {
   135	              pos++;
   136	            }
   137	          ch = ' ';
   138	        }
   139	
   140	      if (ch == '\r')
   141	        continue;
   142	
   143	      if (ch == '\n' || column == AGENT_OLED_CHARS_PER_LINE)
   144	        {
   145	          lines[line][column] = '\0';
   146	          line++;
   147	          column = 0;
   148	          if (line >= AGENT_OLED_MAX_LINES)
   149	            break;
   150	          if (ch == '\n')
   151	            continue;
   152	        }
   153	
   154	      if (ch < ' ' || !agent_oled_font_supported(ch))
   155	        ch = ' ';
   156	      lines[line][column++] = (char)ch;
   157	    }
   158	
   159	  if (line < AGENT_OLED_MAX_LINES)
   160	    {
   161	      lines[line][column] = '\0';
   162	      line++;
   163	    }
   164	
   165	  return line == 0 ? 1 : line;
   166	}
