   178	static bool agent_oled_render_window(
   179	    char lines[AGENT_OLED_MAX_LINES][AGENT_OLED_CHARS_PER_LINE + 1],
   180	    unsigned int line_count, unsigned int first)
   181	{
   182	  uint8_t frame[AGENT_OLED_HEIGHT][AGENT_OLED_WIDTH / 8];
   183	  unsigned int page;
   184	  unsigned int y;
   185	
   186	  memset(frame, 0, sizeof(frame));
   187	  for (page = 0; page < AGENT_OLED_PAGES; page++)
   188	    {
   189	      unsigned int line = first + page;
   190	      unsigned int column;
   191	      unsigned int glyph_row;
   192	
   193	      if (line >= line_count)
   194	        break;
   195	
   196	      for (column = 0; lines[line][column] != '\0'; column++)
   197	        {
   198	          unsigned char glyph = (unsigned char)lines[line][column];
   199	          unsigned int glyph_col;
   200	
   201	          for (glyph_col = 0; glyph_col < AGENT_OLED_FONT_WIDTH;
   202	               glyph_col++)
   203	            {
   204	              for (glyph_row = 0; glyph_row < 7; glyph_row++)
   205	                {
   206	                  if ((g_font[glyph][glyph_col] & (1u << glyph_row)) != 0)
   207	                    {
   208	                      agent_oled_set_pixel(frame[page * 8 + glyph_row],
   209	                                           column * AGENT_OLED_FONT_STEP +
   210	                                           glyph_col);
   211	                    }
   212	                }
   213	            }
   214	        }
   215	    }
   216	
   217	  for (page = 0; page < AGENT_OLED_PAGES; page++)
   218	    {
   219	      syslog(LOG_INFO, "[OLED-DIAG] render page=%u\n", page);
   220	      for (y = page * 8; y < (page + 1) * 8; y++)
   221	        {
   222	          if (g_oled_plane.putrun(g_oled_dev, y, 0, frame[y],
   223	                                  AGENT_OLED_WIDTH) < 0)
   224	            {
   225	              return false;
   226	            }
   227	        }
   228	    }
   229	
   230	  return true;
   231	}
