   233	static void *agent_oled_task(void *arg)
   234	{
   235	  (void)arg;
   236	
   237	  if (board_oled_initialize == NULL || board_oled_getdev == NULL ||
   238	      board_oled_initialize() < 0)
   239	    {
   240	      g_oled_disabled = true;
   241	      return NULL;
   242	    }
   243	
   244	  g_oled_dev = board_oled_getdev();
   245	  if (g_oled_dev == NULL || g_oled_dev->getplaneinfo(g_oled_dev, 0,
   246	                                                      &g_oled_plane) < 0)
   247	    {
   248	      g_oled_disabled = true;
   249	      return NULL;
   250	    }
   251	
   252	  while (!agent_shutdown_requested())
   253	    {
   254	      char text[AGENT_OLED_TEXT_CAPACITY];
   255	      char lines[AGENT_OLED_MAX_LINES][AGENT_OLED_CHARS_PER_LINE + 1];
   256	      unsigned int line_count;
   257	      unsigned int first;
   258	
   259	      pthread_mutex_lock(&g_oled_queue.lock);
   260	      while (g_oled_queue.count == 0 && !agent_shutdown_requested())
   261	        pthread_cond_wait(&g_oled_queue.available, &g_oled_queue.lock);
   262	      if (g_oled_queue.count == 0)
   263	        {
   264	          pthread_mutex_unlock(&g_oled_queue.lock);
   265	          continue;
   266	        }
   267	
   268	      memcpy(text, g_oled_queue.slots[g_oled_queue.head].text,
   269	             g_oled_queue.slots[g_oled_queue.head].len + 1);
   270	      g_oled_queue.head = (g_oled_queue.head + 1) % AGENT_OLED_QUEUE_DEPTH;
   271	      g_oled_queue.count--;
   272	      pthread_mutex_unlock(&g_oled_queue.lock);
   273	
   274	      line_count = agent_oled_make_lines(text, lines);
   275	      for (first = 0; first < line_count && !g_oled_disabled; first += 1)
   276	        {
   277	          if (!agent_oled_render_window(lines, line_count, first))
   278	            {
   279	              g_oled_disabled = true;
   280	              break;
   281	            }
   282	          if (first + AGENT_OLED_PAGES < line_count)
   283	            usleep(250000);
   284	        }
   285	    }
   286	
   287	  return NULL;
   288	}
