   220	static void contest_voice_wait_for_reply_cycle(void)
   221	{
   222	  /* Once ASR text has entered ai_agent, keep the microphone idle until the
   223	   * outbound voice reply has gone through TTS.  voice_channel_speak() changes
   224	   * WAIT_AGENT -> SPEAKING -> RECORDING, which releases this wait. */
   225	
   226	  while (!g_voice_stop_requested)
   227	    {
   228	      if (!g_voice_speaking && g_voice_state == CONTEST_VOICE_RECORDING)
   229	        {
   230	          return;
   231	        }
   232	
   233	      usleep(20 * 1000);
   234	    }
   235	}
