   249	    }
   250	
   251	  while (!g_voice_stop_requested)
   252	    {
   253	      size_t pcm_len = 0;
   254	      int ret;
   255	
   256	      contest_voice_set_state(CONTEST_VOICE_RECORDING);
   257	      ret = robot_voice_capture_record_interruptible(
   258	          pcm, pcm_cap, &pcm_len, ROBOT_VOICE_CAPTURE_SECONDS * 1000,
   259	          &g_voice_stop_requested);
