   261	      if (ret < 0 || g_voice_stop_requested)
   262	        {
   263	          break;
   264	        }
   265	      if (g_voice_speaking)
   266	        {
   267	          continue;
   268	        }
   269	      contest_voice_set_state(CONTEST_VOICE_ASR);
   270	      printf("[RV-VOICE] invoking ASR bytes=%zu on dedicated worker\n", pcm_len);
   271	      ret = contest_voice_run_asr(pcm, pcm_len, text, sizeof(text));
   272	      if (g_voice_stop_requested)
   273	        {
   274	          break;
   275	        }
   276	      if (ret < 0 || text[0] == '\0')
   277	        {
   278	          printf("[contest_voice] ASR failed: %d\n", ret);
   279	          if (g_voice_oneshot)
   280	            {
