   291	      msg.content = strdup(text);
   292	      contest_voice_set_state(CONTEST_VOICE_WAIT_AGENT);
   293	      printf("[RV-VOICE] push inbound voice:voice\n");
   294	      if (msg.content == NULL || message_bus_push_inbound(&msg) != OK)
   295	        {
   296	          free(msg.content);
   297	          printf("[contest_voice] message bus submit failed\n");
   298	          if (g_voice_oneshot)
   299	            {
   300	              break;
   301	            }
   302	          continue;
   303	        }
   304	
   305	      if (g_voice_oneshot)
   306	        {
   307	          break;
   308	        }
   309	
   310	      contest_voice_wait_for_reply_cycle();
   311	    }
