int node_manager_init(void)
{
    memset(s_nodes, 0, sizeof(s_nodes));
    memset(s_pending, 0, sizeof(s_pending));

    /* Register as tool provider to break circular dependency */
    tool_registry_register_provider("node",
                                    node_manager_get_tools_json,
                                    node_manager_execute);

    syslog(LOG_INFO, "[%s] Node manager initialized (max %d nodes)\n", TAG,
        NODE_MAX_NODES);
    return OK;
}

bool node_manager_handle_message(int ws_fd, const char* data, int len)
{
    cJSON* root = cJSON_ParseWithLength(data, len);
    if (!root) {
        syslog(LOG_DEBUG, "[%s] handle_message: JSON parse failed fd=%d len=%d\n",
            TAG, ws_fd, len);
        return false;
    }

    const char* type = cJSON_GetStringValue(cJSON_GetObjectItem(root, "type"));
    if (!type) {
        cJSON_Delete(root);
        return false;
    }

    /* ── Request from Node ─────────────────────────────────── */
    if (strcmp(type, "req") == 0) {
        const char* method = cJSON_GetStringValue(cJSON_GetObjectItem(root, "method"));
        const char* req_id = cJSON_GetStringValue(cJSON_GetObjectItem(root, "id"));
        cJSON* params = cJSON_GetObjectItem(root, "params");

        if (!method || !req_id) {
                 "Error: tool '%s' blocked — %s",
                 name ? name : "(null)", reason);
        return ERROR;
    }

    /* Try builtin tools first */
    for (int i = 0; i < s_tool_count; i++) {
        if (strcmp(s_tools[i].name, name) == 0) {
            syslog(LOG_INFO, "[%s] Executing tool: %s\n", TAG, name);
            int ret = s_tools[i].execute(input_json, output, output_size);
            if (ret == OK) {
                tool_guard_record_call(name);
            }
            return ret;
        }
    }

    /* Try MCP bridge */
#ifdef CONFIG_AI_AGENT_MCP
    if (mcp_bridge_execute(name, input_json, output, output_size) == OK) {
        syslog(LOG_INFO, "[%s] Executed MCP tool: %s\n", TAG, name);
        tool_guard_record_call(name);
        return OK;
    }
#endif

    /* Try registered providers */
    for (int p = 0; p < s_provider_count; p++) {
        if (!s_providers[p].execute) {
            continue;
        }
        int ret = s_providers[p].execute(name, input_json, output, output_size);
        if (ret == OK) {
            syslog(LOG_INFO, "[%s] Executed %s tool: %s\n",
                   TAG, s_providers[p].name, name);
            tool_guard_record_call(name);
            return OK;
        }
    }

    syslog(LOG_WARNING, "[%s] Unknown tool: %s\n", TAG, name);
    snprintf(output, output_size, "Error: unknown tool '%s'", name);
    return ERROR;
}

