    94	      pthread_cond_broadcast(&g_oled_queue.available);
    95	      pthread_mutex_unlock(&g_oled_queue.lock);
    96	      printf("[RV-OLED] board OLED plane unavailable\n");
    97	      return NULL;
    98	    }
