   100	  pthread_mutex_lock(&g_oled_queue.lock);
   101	  g_oled_ready = true;
   102	  pthread_cond_broadcast(&g_oled_queue.available);
   103	  pthread_mutex_unlock(&g_oled_queue.lock);
   104	  printf("[RV-OLED] worker ready %ux%u\n", ROBOT_OLED_WIDTH,
