   189	int robot_oled_stop(void)
   190	{
   191	  bool join_needed;
   192	
   193	  pthread_mutex_lock(&g_oled_queue.lock);
   194	  join_needed = g_oled_thread_valid;
   195	  g_oled_stop = true;
   196	  pthread_cond_broadcast(&g_oled_queue.available);
   197	  pthread_mutex_unlock(&g_oled_queue.lock);
   198	
   199	  if (join_needed)
   200	    {
   201	      pthread_join(g_oled_thread, NULL);
   202	    }
   203	
   204	  pthread_mutex_lock(&g_oled_queue.lock);
   205	  g_oled_thread_valid = false;
   206	  g_oled_initialized = false;
   207	  g_oled_ready = false;
   208	  pthread_mutex_unlock(&g_oled_queue.lock);
   209	  return 0;
   210	}
