   212	int robot_oled_submit(enum robot_expression_e expression)
   213	{
   214	  if (expression < 0 || expression >= ROBOT_EXPRESSION_COUNT)
   215	    {
   216	      return -EINVAL;
   217	    }
   218	
   219	  pthread_mutex_lock(&g_oled_queue.lock);
   220	  if (!g_oled_initialized || g_oled_stop)
   221	    {
   222	      pthread_mutex_unlock(&g_oled_queue.lock);
   223	      return -EAGAIN;
   224	    }
   225	  if (g_oled_failed)
   226	    {
   227	      pthread_mutex_unlock(&g_oled_queue.lock);
   228	      return -ENODEV;
   229	    }
   230	
   231	  if (g_oled_queue.count == ROBOT_OLED_QUEUE_DEPTH)
   232	    {
   233	      g_oled_queue.head = (g_oled_queue.head + 1) % ROBOT_OLED_QUEUE_DEPTH;
   234	      g_oled_queue.count--;
   235	    }
   236	
   237	  g_oled_queue.slots[g_oled_queue.tail] = expression;
   238	  g_oled_queue.tail = (g_oled_queue.tail + 1) % ROBOT_OLED_QUEUE_DEPTH;
   239	  g_oled_queue.count++;
   240	  pthread_cond_signal(&g_oled_queue.available);
   241	  pthread_mutex_unlock(&g_oled_queue.lock);
   242	  return 0;
   243	}
