    14	static void robot_oled_pixel(uint8_t frame[ROBOT_OLED_HEIGHT]
    15	                                             [ROBOT_OLED_ROW_BYTES],
    16	                             int x, int y)
    17	{
    18	  if (x < 0 || x >= ROBOT_OLED_WIDTH || y < 0 || y >= ROBOT_OLED_HEIGHT)
    19	    {
    20	      return;
    21	    }
    22	
    23	#ifdef CONFIG_LCD_PACKEDMSFIRST
    24	  frame[y][x >> 3] |= (uint8_t)(0x80u >> (x & 7));
    25	#else
    26	  frame[y][x >> 3] |= (uint8_t)(1u << (x & 7));
    27	#endif
    28	}
    29	
    30	static void robot_oled_line(uint8_t frame[ROBOT_OLED_HEIGHT]
    31	                                            [ROBOT_OLED_ROW_BYTES],
    32	                            int x0, int y0, int x1, int y1)
    33	{
    34	  int dx = x1 >= x0 ? x1 - x0 : x0 - x1;
    35	  int sx = x0 < x1 ? 1 : -1;
    36	  int dy = y1 >= y0 ? y0 - y1 : y1 - y0;
    37	  int sy = y0 < y1 ? 1 : -1;
    38	  int error = dx + dy;
    39	
    40	  for (;;)
    41	    {
    42	      robot_oled_pixel(frame, x0, y0);
    43	      if (x0 == x1 && y0 == y1)
    44	        {
    45	          break;
    46	        }
    47	
    48	      int twice = 2 * error;
    49	      if (twice >= dy)
    50	        {
    51	          error += dy;
