#define ROBOT_EXPRESSION_TOOL_NAME "robot_set_expression"


static bool g_robot_expression_tool_registered;

/*
 * Official AI Agent response cache is prompt-based.  That is safe for pure
 * text answers, but not for physical actions: reusing a cached sentence such
 * as "Expression set to thinking" does not replay robot_set_expression.
 *
 * We cannot modify packages/ai_agent from the contest tree, so after a real
 * physical expression action we temporarily invalidate the official response
 * cache.  The guard window covers the later ReAct/final-answer phase where
 * agent_loop may write the successful textual answer into the cache.
 *
 * The worker sleeps while inactive; it is not a permanent busy loop.
 */
#define ROBOT_EXPR_CACHE_GUARD_WINDOW_MS  (30ULL * 1000ULL)
#define ROBOT_EXPR_CACHE_GUARD_ACTIVE_US  (100 * 1000)
#define ROBOT_EXPR_CACHE_GUARD_IDLE_US    (500 * 1000)
#define ROBOT_EXPR_CACHE_GUARD_STACK      4096

/* Read-only official API: packages/ai_agent/src/llm/llm_cache.c */
extern void llm_cache_invalidate(void);

static pthread_mutex_t g_robot_expr_cache_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_t g_robot_expr_cache_thread;
static bool g_robot_expr_cache_thread_started;
static uint64_t g_robot_expr_cache_guard_until_ms;

static uint64_t robot_expr_cache_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000ULL +
         (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void *robot_expr_cache_guard_worker(void *arg)
{
  (void)arg;

  for (;;)
    {
      uint64_t now;
      uint64_t until;
      bool active;

      now = robot_expr_cache_now_ms();

      pthread_mutex_lock(&g_robot_expr_cache_lock);
      until = g_robot_expr_cache_guard_until_ms;
      pthread_mutex_unlock(&g_robot_expr_cache_lock);

      active = until != 0 && now < until;
      if (active)
        {
          /*
           * Repeated invalidation is intentional.  A single invalidate from
           * inside the Tool callback is too early: agent_loop may cache the
           * final natural-language answer after the Tool has already returned.
           */
          llm_cache_invalidate();
          usleep(ROBOT_EXPR_CACHE_GUARD_ACTIVE_US);
        }
      else
        {
          usleep(ROBOT_EXPR_CACHE_GUARD_IDLE_US);
        }
    }

  return NULL;
}

static void robot_expr_cache_guard_start(void)
{
  pthread_attr_t attr;
  int ret;

  pthread_mutex_lock(&g_robot_expr_cache_lock);
  if (g_robot_expr_cache_thread_started)
    {
      pthread_mutex_unlock(&g_robot_expr_cache_lock);
      return;
    }

  g_robot_expr_cache_thread_started = true;
  pthread_mutex_unlock(&g_robot_expr_cache_lock);

  pthread_attr_init(&attr);
  (void)pthread_attr_setstacksize(&attr, ROBOT_EXPR_CACHE_GUARD_STACK);
  ret = pthread_create(&g_robot_expr_cache_thread, &attr,
                       robot_expr_cache_guard_worker, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      pthread_mutex_lock(&g_robot_expr_cache_lock);
      g_robot_expr_cache_thread_started = false;
      pthread_mutex_unlock(&g_robot_expr_cache_lock);
      printf("[RV-EXPR-CACHE] guard worker create failed ret=%d\n", ret);
      return;
    }

  (void)pthread_detach(g_robot_expr_cache_thread);
  printf("[RV-EXPR-CACHE] guard worker started\n");
}

static void robot_expr_cache_guard_kick(void)
{
  uint64_t now;
  uint64_t until;

  robot_expr_cache_guard_start();

  now = robot_expr_cache_now_ms();
  until = now + ROBOT_EXPR_CACHE_GUARD_WINDOW_MS;

  pthread_mutex_lock(&g_robot_expr_cache_lock);
  if (until > g_robot_expr_cache_guard_until_ms)
    {
      g_robot_expr_cache_guard_until_ms = until;
    }
  pthread_mutex_unlock(&g_robot_expr_cache_lock);

  /*
   * Clear any old entry immediately, then the worker keeps clearing during
   * the final ReAct response/cache-write window.
   */
  llm_cache_invalidate();
  printf("[RV-EXPR-CACHE] cache guard active for %llu ms\n",
         (unsigned long long)ROBOT_EXPR_CACHE_GUARD_WINDOW_MS);
}

static enum robot_expression_e robot_expression_from_name(const char *name)
{
  enum robot_expression_e expression;

  if (name == NULL)
    {
      return ROBOT_EXPRESSION_COUNT;
    }
  for (expression = 0; expression < ROBOT_EXPRESSION_COUNT; expression++)
    {
      if (strcmp(name, robot_expression_name(expression)) == 0)
        {
          return expression;
        }
    }
  return ROBOT_EXPRESSION_COUNT;
}

static char *robot_expression_tool_get_tools(void)
{
  static const char tools_json[] =
    "[{\"name\":\"robot_set_expression\","
    "\"description\":\"ACTION TOOL for changing the robot dog's physical OLED facial expression. "
    "You MUST call this tool in the current turn whenever the user asks, commands, "
    "requests, or clearly intends to change/set/show/keep the robot's facial expression. "
    "A message consisting only of one supported expression word (idle, listening, thinking, "
    "happy, speaking, error), or its obvious Chinese meaning such as 待机、聆听、思考、开心、说话、错误, "
    "is a direct command to call this tool with that expression. "
    "Every new expression request requires a fresh tool call even if another expression was "
    "set earlier in the conversation. Never merely describe the expression change in text. "
    "Never say or imply that the robot's expression has changed unless this tool was actually "
    "called in the current turn and returned ok=true. "
    "The selected expression persists until this tool is called again with a different expression.\","
    "\"input_schema\":{\"type\":\"object\",\"properties\":{"
    "\"expression\":{\"type\":\"string\","
    "\"description\":\"The physical OLED expression to display now. Use the exact value requested by the user when it matches an enum value.\","
    "\"enum\":[\"idle\",\"listening\",\"thinking\",\"happy\","
    "\"speaking\",\"error\"]}},\"required\":[\"expression\"]}}]";

  printf("[RV-EXPR-TOOL] tools_json requested\n");
  return strdup(tools_json);
}

static int robot_expression_tool_execute(const char *name,
                                         const char *input_json,
                                         char *output,
                                         size_t output_size)
{
  cJSON *root;
  cJSON *expression_item;
  const char *expression_name;
  enum robot_expression_e expression;
  int ret;

  if (name == NULL || input_json == NULL || output == NULL ||
      output_size == 0 || strcmp(name, ROBOT_EXPRESSION_TOOL_NAME) != 0)
    {
      printf("[RV-EXPR-TOOL] execute rejected: invalid arguments/name\n");
      return ERROR;
    }

  printf("[RV-EXPR-TOOL] execute name=%s input=%s\n", name, input_json);

  root = cJSON_Parse(input_json);
  if (root == NULL)
    {
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"invalid json\"}");
      return ERROR;
    }

  expression_item = cJSON_GetObjectItem(root, "expression");
  expression_name = cJSON_GetStringValue(expression_item);
  expression = robot_expression_from_name(expression_name);
  if (expression == ROBOT_EXPRESSION_COUNT)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"unknown expression\"}");
      return ERROR;
    }

  /*
   * Agent-selected expressions are persistent.  duration_ms == 0 means this
   * source stays active until the next Agent expression replaces it.
   */
  printf("[RV-EXPR-TOOL] parsed expression=%s persistent=1\n",
         robot_expression_name(expression));

  ret = robot_expression_set(ROBOT_EXPRESSION_SOURCE_AGENT, expression, 0);
  cJSON_Delete(root);

  printf("[RV-EXPR-TOOL] expression_set rc=%d\n", ret);
  if (ret < 0)
    {
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"expression display unavailable\"}");
      return ERROR;
