+static int robot_motion_safe_interval(unsigned int period_ms)
+{
+  int interval_ms = (int)period_ms / 100;
+
+  if (interval_ms < 25)
+    {
+      interval_ms = 25;
+    }
+  else if (interval_ms > 30)
+    {
+      interval_ms = 30;
+    }
+
+  return interval_ms;
+}
+
+static int robot_motion_safe_settle(unsigned int period_ms)
+{
+  int settle_ms = (int)period_ms / 12;
+
+  if (settle_ms < 150)
+    {
+      settle_ms = 150;
+    }
+  else if (settle_ms > 250)
+    {
+      settle_ms = 250;
+    }
+
+  return settle_ms;
+}
