    ROBOTCTL_PHASE(45, 90, 45, 90, ROBOTCTL_LF, ROBOTCTL_RR),
    ROBOTCTL_PHASE(90, 90, 90, 90, ROBOTCTL_RF, ROBOTCTL_LR)
  }
};

