+      g_world.initialized = true;
+      g_world.proactive_enabled = true;
+      g_world.boot_ms = robot_world_monotonic_ms();
+      g_world.last_user_activity_ms = g_world.boot_ms;
+      printf("[ROBOT-WORLD] initialized boot_ms=%llu enabled=1\n",
