 17	/**
 18	 * skill_sync.c — Pull skills from Feishu Bitable to local filesystem
 19	 *
 20	 * Flow:
 21	 *   1. Refresh tenant_access_token (reuses feishu_http.c)
 22	 *   2. GET bitable records (enabled=true, paginated)
 23	 *   3. Filter by target_device
 24	 *   4. Compare version with local .versions.json
 25	 *   5. Write changed skills to /data/agent/skills/
 26	 *   6. Optionally clean orphaned local skills (full mode)
 27	 */
 28	
