 43	
 44	static const char *TAG = "skill_sync";
 45	
 46	/* ── Local version tracking ────────────────────────────────────── */
 47	
 48	/** Simple in-memory version map: skill_id → version string */
 49	typedef struct {
 50	    char skill_id[64];
 51	    char version[32];
 52	} version_entry_t;
 53	
 54	typedef struct {
 55	    version_entry_t entries[128];
 56	    int count;
 57	} version_map_t;
 58	
 59	static void version_map_load(version_map_t *map)
 60	{
 61	    map->count = 0;
 62	
 63	    FILE *f = fopen(AGENT_SKILL_SYNC_VERSION_FILE, "r");
 64	    if (!f) {
 65	        return;
 66	    }
 67	
 68	    /* Read entire file (small, ~2KB max) */
 69	    fseek(f, 0, SEEK_END);
 70	    long fsize = ftell(f);
 71	    fseek(f, 0, SEEK_SET);
 72	
 73	    if (fsize <= 0 || fsize > 8192) {
 74	        fclose(f);
 75	        return;
 76	    }
 77	
 78	    char *buf = malloc((size_t)fsize + 1);
 79	    if (!buf) {
 80	        fclose(f);
 81	        return;
 82	    }
 83	
 84	    fread(buf, 1, (size_t)fsize, f);
 85	    buf[fsize] = '\0';
 86	    fclose(f);
 87	
 88	    cJSON *root = cJSON_Parse(buf);
 89	    free(buf);
 90	    if (!root || !cJSON_IsObject(root)) {
 91	        cJSON_Delete(root);
 92	        return;
 93	    }
 94	
 95	    cJSON *item = NULL;
 96	    cJSON_ArrayForEach(item, root) {
 97	        if (map->count >= 128) {
 98	            break;
 99	        }
100	        if (cJSON_IsString(item) && item->string) {
101	            strncpy(map->entries[map->count].skill_id, item->string,
102	                    sizeof(map->entries[0].skill_id) - 1);
103	            strncpy(map->entries[map->count].version, item->valuestring,
104	                    sizeof(map->entries[0].version) - 1);
105	            map->count++;
106	        }
107	    }
108	
109	    cJSON_Delete(root);
110	    syslog(LOG_DEBUG, "[%s] Loaded %d version entries\n", TAG, map->count);
111	}
112	
113	static const char *version_map_get(const version_map_t *map,
114	                                   const char *skill_id)
115	{
116	    for (int i = 0; i < map->count; i++) {
117	        if (strcmp(map->entries[i].skill_id, skill_id) == 0) {
118	            return map->entries[i].version;
119	        }
120	    }
121	    return NULL;
122	}
123	
124	static void version_map_set(version_map_t *map, const char *skill_id,
125	                            const char *version)
126	{
127	    /* Update existing */
128	    for (int i = 0; i < map->count; i++) {
129	        if (strcmp(map->entries[i].skill_id, skill_id) == 0) {
130	            strncpy(map->entries[i].version, version,
131	                    sizeof(map->entries[0].version) - 1);
132	            return;
133	        }
134	    }
135	
136	    /* Add new */
137	    if (map->count < 128) {
138	        strncpy(map->entries[map->count].skill_id, skill_id,
139	                sizeof(map->entries[0].skill_id) - 1);
140	        strncpy(map->entries[map->count].version, version,
141	                sizeof(map->entries[0].version) - 1);
142	        map->count++;
143	    }
144	}
