146	static void version_map_save(const version_map_t *map)
147	{
148	    cJSON *root = cJSON_CreateObject();
149	    if (!root) {
150	        return;
151	    }
152	
153	    for (int i = 0; i < map->count; i++) {
154	        cJSON_AddStringToObject(root, map->entries[i].skill_id,
155	                                map->entries[i].version);
156	    }
157	
158	    char *json = cJSON_PrintUnformatted(root);
159	    cJSON_Delete(root);
160	
161	    if (!json) {
162	        return;
163	    }
164	
165	    FILE *f = fopen(AGENT_SKILL_SYNC_VERSION_FILE, "w");
166	    if (f) {
167	        fputs(json, f);
168	        fclose(f);
169	    }
170	
171	    free(json);
172	}
