229	/**
230	 * Fetch one page of bitable records.
231	 * Returns cJSON root (caller must free) or NULL on error.
232	 */
233	static cJSON *fetch_records_page(const char *page_token)
234	{
235	    /* Ensure token is valid */
236	    if (feishu_token_expired()) {
237	        if (feishu_get_app_token() != OK) {
238	            syslog(LOG_ERR, "[%s] Failed to refresh Feishu token\n", TAG);
239	            return NULL;
240	        }
241	    }
242	
243	    /* Build request path */
244	    char path[512];
245	    int off = snprintf(path, sizeof(path),
246	        "/open-apis/bitable/v1/apps/%s/tables/%s/records"
247	        "?page_size=500",
248	        AGENT_SKILL_SYNC_APP_TOKEN,
249	        AGENT_SKILL_SYNC_TABLE_ID);
250	
251	    if (page_token && page_token[0]) {
252	        snprintf(path + off, sizeof(path) - (size_t)off,
253	                 "&page_token=%s", page_token);
254	    }
255	
256	    /* Auth header */
257	    char auth_val[520];
258	    snprintf(auth_val, sizeof(auth_val), "Bearer %s", s_access_token);
259	    vela_header_t headers[] = {
260	        { "Authorization", auth_val },
261	        { NULL, NULL }
262	    };
263	
264	    /* Allocate response buffer */
265	    char *resp = malloc(AGENT_SKILL_SYNC_RESP_SIZE);
266	    if (!resp) {
267	        syslog(LOG_ERR, "[%s] OOM for response buffer\n", TAG);
268	        return NULL;
269	    }
270	
271	    size_t body_len = 0;
272	    int status = feishu_https_request("GET", path, headers, NULL, 0,
273	                                      resp, AGENT_SKILL_SYNC_RESP_SIZE,
274	                                      &body_len);
275	
276	    if (status != 200) {
277	        syslog(LOG_ERR, "[%s] Bitable API HTTP %d: %.200s\n",
278	               TAG, status, resp);
279	        free(resp);
280	        return NULL;
281	    }
282	
283	    cJSON *root = cJSON_Parse(resp);
284	    free(resp);
285	
286	    if (!root) {
287	        syslog(LOG_ERR, "[%s] Bitable API: invalid JSON response\n", TAG);
288	        return NULL;
289	    }
290	
291	    /* Check API-level error code */
292	    cJSON *code = cJSON_GetObjectItem(root, "code");
293	    if (cJSON_IsNumber(code) && (int)code->valuedouble != 0) {
294	        cJSON *msg = cJSON_GetObjectItem(root, "msg");
295	        syslog(LOG_ERR, "[%s] Bitable API error: code=%d msg=%s\n",
