 553	bool api_try_handle(int fd, const char* buf, int buf_len)
 554	{
 555	    /* Quick check: must start with a valid HTTP method targeting /api/ */
 556	    if (!buf || buf_len < 10) {
 557	        return false;
 558	    }
 559	
 560	    if (strncmp(buf, "GET /api/", 9) != 0 && strncmp(buf, "PUT /api/", 9) != 0 && strncmp(buf, "POST /api/", 10) != 0 && strncmp(buf, "DELETE /api/", 12) != 0) {
 561	        return false;
 562	    }
 563	
 564	    /* Parse method and path */
 565	    char method[8] = "";
 566	    char path[128] = "";
 567	    sscanf(buf, "%7s %127s", method, path);
 568	
 569	    syslog(LOG_INFO, "[%s] api_try_handle: %s %s\n", TAG, method, path);
 570	
 571	    /* Route: /api/config */
 572	    if (strcmp(path, "/api/config") == 0) {
 573	        if (strcmp(method, "GET") == 0) {
 574	            return handle_config_get(fd);
 575	        }
 576	        if (strcmp(method, "PUT") == 0) {
 577	            char* body = read_full_body(fd, buf, buf_len);
 578	            bool ret = handle_config_put(fd, body);
 579	            free(body);
 580	            return ret;
 581	        }
 582	    }
 583	
 584	    /* Route: /api/skills */
 585	    if (strcmp(path, "/api/skills") == 0) {
 586	        if (strcmp(method, "GET") == 0) {
 587	            return handle_skills_get(fd);
 588	        }
 589	        if (strcmp(method, "POST") == 0) {
 590	            char* body = read_full_body(fd, buf, buf_len);
 591	            bool ret = handle_skills_post(fd, body);
 592	            free(body);
 593	            return ret;
 594	        }
 595	    }
 596	
 597	    /* Route: /api/skills/{name} */
 598	    if (strncmp(path, "/api/skills/", 12) == 0 && strcmp(method, "DELETE") == 0) {
 599	        return handle_skills_delete(fd, path + 12);
 600	    }
 601	
 602	    /* Route: /api/logs */
 603	    if (strncmp(path, "/api/logs", 9) == 0 && strcmp(method, "GET") == 0) {
 604	        return handle_logs_get(fd);
