 25	#define ROBOT_SKILL_NAME "robot-proactive-idle.md"
 26	
 27	static const char g_robot_proactive_skill[] =
 28	  "# Robot Proactive Idle Companion\n"
 29	  "\n"
 30	  "Handle internal robot idle events and decide on a brief, natural companion\n"
 31	  "interaction.\n"
 32	  "\n"
 33	  "## When to use\n"
 34	  "\n"
 35	  "Use when the input contains `[ROBOT_INTERNAL_EVENT]` and `type=idle_long`.\n"
 36	  "This is an internal robot event, not something spoken by the user.\n"
 37	  "\n"
 38	  "## How to use\n"
 39	  "\n"
 40	  "1. Treat the event as a possible opportunity for a short companion interaction.\n"
 41	  "2. Do not pretend that the user said the internal event text.\n"
 42	  "3. Keep the interaction brief and natural.\n"
 43	  "4. Do not repeatedly ask generic questions such as \"Are you there?\".\n"
 44	  "5. When a visible emotional reaction helps, call `robot_set_expression`.\n"
 45	  "6. If a physical action is appropriate and safe, use the existing `robot_move` tool.\n"
 46	  "7. Never claim a physical action happened unless its tool was called in this turn and returned success.\n"
 47	  "8. Every new physical-action request requires a fresh tool call.\n"
 48	  "9. Never output servo angles, PWM values, or low-level motor instructions.\n"
 49	  "10. Prefer one small expression or action over many simultaneous actions.\n"
 50	  "11. Avoid unnecessary movement.\n"
 51	  "12. Spoken text should usually be one short sentence.\n"
 52	  "\n"
 53	  "## Example\n"
 54	  "\n"
 55	  "For an `idle_long` event, a suitable response may call\n"
 56	  "`robot_set_expression` with `happy` and then say one short sentence such as\n"
 57	  "\"忙完了吗？要不要陪你活动一下？\"\n";
 58	
 59	static pthread_mutex_t g_robot_skill_lock = PTHREAD_MUTEX_INITIALIZER;
 60	static bool g_robot_skill_exists;
 61	static bool g_robot_skill_matches;
 62	static int g_robot_skill_last_result = -EAGAIN;
 63	
 64	static int robot_skill_paths(char *path, size_t path_size,
 65	                             char *tmp, size_t tmp_size)
 66	{
 67	  int n;
 68	
 69	  n = snprintf(path, path_size, "%s%s", AGENT_SKILLS_DIR,
 70	               ROBOT_SKILL_NAME);
 71	  if (n < 0 || (size_t)n >= path_size)
 72	    {
 73	      return -ENAMETOOLONG;
 74	    }
 75	
 76	  n = snprintf(tmp, tmp_size, "%s%s.tmp", AGENT_SKILLS_DIR,
 77	               ROBOT_SKILL_NAME);
 78	  if (n < 0 || (size_t)n >= tmp_size)
 79	    {
 80	      return -ENAMETOOLONG;
 81	    }
 82	
 83	  return 0;
 84	}
 85	
 86	static bool robot_skill_file_matches(const char *path)
 87	{
 88	  FILE *file;
 89	  char buf[128];
 90	  size_t offset = 0;
 91	  size_t expected = sizeof(g_robot_proactive_skill) - 1;
 92	
 93	  file = fopen(path, "rb");
 94	  if (file == NULL)
 95	    {
 96	      return false;
 97	    }
 98	
 99	  while (offset < expected)
100	    {
101	      size_t want = expected - offset;
102	      size_t got;
103	
104	      if (want > sizeof(buf))
105	        {
106	          want = sizeof(buf);
107	        }
108	      got = fread(buf, 1, want, file);
109	      if (got != want || memcmp(buf, g_robot_proactive_skill + offset, got) != 0)
110	        {
111	          fclose(file);
112	          return false;
113	        }
114	      offset += got;
115	    }
116	
117	  if (fgetc(file) != EOF || ferror(file) != 0)
118	    {
119	      fclose(file);
120	      return false;
121	    }
122	
123	  fclose(file);
124	  return true;
125	}
126	
127	static int robot_skill_write_atomic(const char *path, const char *tmp)
128	{
129	  FILE *file;
130	  size_t length = sizeof(g_robot_proactive_skill) - 1;
131	  size_t written;
132	  int close_ret;
133	
134	  file = fopen(tmp, "wb");
135	  if (file == NULL)
136	    {
137	      return -errno;
138	    }
139	
140	  written = fwrite(g_robot_proactive_skill, 1, length, file);
141	  if (written != length || fflush(file) != 0)
142	    {
143	      int saved_errno = errno != 0 ? errno : EIO;
144	      fclose(file);
145	      unlink(tmp);
146	      return -saved_errno;
147	    }
148	
149	  close_ret = fclose(file);
150	  if (close_ret != 0)
151	    {
152	      int saved_errno = errno != 0 ? errno : EIO;
153	      unlink(tmp);
154	      return -saved_errno;
155	    }
156	
157	  if (rename(tmp, path) != 0)
158	    {
159	      int saved_errno = errno;
160	      unlink(tmp);
161	      return -saved_errno;
162	    }
163	
164	  return 0;
165	}
166	
167	int robot_skill_installer_ensure(void)
168	{
169	  char path[128];
170	  char tmp[160];
171	  struct stat st;
172	  int ret;
173	  bool existed;
174	
175	  pthread_mutex_lock(&g_robot_skill_lock);
176	  ret = robot_skill_paths(path, sizeof(path), tmp, sizeof(tmp));
177	  if (ret < 0)
178	    {
179	      g_robot_skill_last_result = ret;
180	      pthread_mutex_unlock(&g_robot_skill_lock);
181	      printf("[ROBOT-SKILL] path build failed rc=%d\n", ret);
182	      return ret;
183	    }
184	
185	  existed = stat(path, &st) == 0;
186	  g_robot_skill_exists = existed;
187	  g_robot_skill_matches = existed && robot_skill_file_matches(path);
188	  if (g_robot_skill_matches)
189	    {
190	      g_robot_skill_last_result = ROBOT_SKILL_INSTALL_ALREADY_CURRENT;
191	      pthread_mutex_unlock(&g_robot_skill_lock);
192	      printf("[ROBOT-SKILL] path=%s result=already-current\n", path);
193	      return 0;
194	    }
195	
196	  ret = robot_skill_write_atomic(path, tmp);
197	  if (ret < 0)
198	    {
199	      g_robot_skill_last_result = ret;
200	      g_robot_skill_exists = stat(path, &st) == 0;
201	      g_robot_skill_matches = false;
202	      pthread_mutex_unlock(&g_robot_skill_lock);
203	      printf("[ROBOT-SKILL] path=%s result=failed rc=%d errno=%d\n",
204	             path, ret, -ret);
205	      return ret;
206	    }
207	
208	  g_robot_skill_exists = true;
209	  g_robot_skill_matches = true;
210	  g_robot_skill_last_result = existed ? ROBOT_SKILL_INSTALL_UPDATED
211	                                      : ROBOT_SKILL_INSTALL_CREATED;
212	  printf("[ROBOT-SKILL] path=%s result=%s bytes=%zu\n", path,
213	         existed ? "updated" : "created",
214	         sizeof(g_robot_proactive_skill) - 1);
215	  pthread_mutex_unlock(&g_robot_skill_lock);
216	  return 0;
217	}
