219	const char *robot_skill_installer_path(void)
220	{
221	  return AGENT_SKILLS_DIR ROBOT_SKILL_NAME;
222	}
223	
224	bool robot_skill_installer_exists(void)
225	{
226	  bool value;
227	
228	  pthread_mutex_lock(&g_robot_skill_lock);
229	  value = g_robot_skill_exists;
230	  pthread_mutex_unlock(&g_robot_skill_lock);
231	  return value;
232	}
233	
234	bool robot_skill_installer_matches(void)
235	{
236	  bool value;
237	
238	  pthread_mutex_lock(&g_robot_skill_lock);
239	  value = g_robot_skill_matches;
240	  pthread_mutex_unlock(&g_robot_skill_lock);
241	  return value;
242	}
243	
244	int robot_skill_installer_last_result(void)
245	{
246	  int value;
247	
248	  pthread_mutex_lock(&g_robot_skill_lock);
249	  value = g_robot_skill_last_result;
250	  pthread_mutex_unlock(&g_robot_skill_lock);
251	  return value;
252	}
253	
254	const char *robot_skill_installer_result_name(int result)
255	{
256	  switch (result)
257	    {
258	      case ROBOT_SKILL_INSTALL_ALREADY_CURRENT:
259	        return "already-current";
260	      case ROBOT_SKILL_INSTALL_CREATED:
261	        return "created";
262	      case ROBOT_SKILL_INSTALL_UPDATED:
263	        return "updated";
264	      default:
265	        return "failed";
266	    }
267	}
