    64	static int robot_skill_paths(char *path, size_t path_size,
    65	                             char *tmp, size_t tmp_size)
    66	{
    67	  int n;
    68	
    69	  n = snprintf(path, path_size, "%s%s", AGENT_SKILLS_DIR,
    70	               ROBOT_SKILL_NAME);
    71	  if (n < 0 || (size_t)n >= path_size)
    72	    {
    73	      return -ENAMETOOLONG;
    74	    }
    75	
    76	  n = snprintf(tmp, tmp_size, "%s%s.tmp", AGENT_SKILLS_DIR,
    77	               ROBOT_SKILL_NAME);
    78	  if (n < 0 || (size_t)n >= tmp_size)
    79	    {
    80	      return -ENAMETOOLONG;
    81	    }
    82	
    83	  return 0;
    84	}
    85	
    86	static bool robot_skill_file_matches(const char *path)
    87	{
    88	  FILE *file;
    89	  char buf[128];
    90	  size_t offset = 0;
    91	  size_t expected = sizeof(g_robot_proactive_skill) - 1;
    92	
    93	  file = fopen(path, "rb");
    94	  if (file == NULL)
    95	    {
    96	      return false;
    97	    }
    98	
    99	  while (offset < expected)
   100	    {
   101	      size_t want = expected - offset;
   102	      size_t got;
   103	
   104	      if (want > sizeof(buf))
   105	        {
   106	          want = sizeof(buf);
   107	        }
   108	      got = fread(buf, 1, want, file);
   109	      if (got != want || memcmp(buf, g_robot_proactive_skill + offset, got) != 0)
   110	        {
   111	          fclose(file);
   112	          return false;
   113	        }
   114	      offset += got;
   115	    }
   116	
   117	  if (fgetc(file) != EOF || ferror(file) != 0)
   118	    {
   119	      fclose(file);
   120	      return false;
   121	    }
   122	
   123	  fclose(file);
   124	  return true;
   125	}
   126	
   127	static int robot_skill_write_atomic(const char *path, const char *tmp)
   128	{
   129	  FILE *file;
   130	  size_t length = sizeof(g_robot_proactive_skill) - 1;
   131	  size_t written;
   132	  int close_ret;
   133	
   134	  file = fopen(tmp, "wb");
   135	  if (file == NULL)
   136	    {
   137	      return -errno;
   138	    }
   139	
   140	  written = fwrite(g_robot_proactive_skill, 1, length, file);
   141	  if (written != length || fflush(file) != 0)
   142	    {
   143	      int saved_errno = errno != 0 ? errno : EIO;
   144	      fclose(file);
   145	      unlink(tmp);
   146	      return -saved_errno;
   147	    }
   148	
   149	  close_ret = fclose(file);
   150	  if (close_ret != 0)
   151	    {
   152	      int saved_errno = errno != 0 ? errno : EIO;
   153	      unlink(tmp);
   154	      return -saved_errno;
   155	    }
   156	
   157	  if (rename(tmp, path) != 0)
   158	    {
   159	      int saved_errno = errno;
   160	      unlink(tmp);
   161	      return -saved_errno;
   162	    }
   163	
   164	  return 0;
   165	}
