   167	int robot_skill_installer_ensure(void)
   168	{
   169	  char path[128];
   170	  char tmp[160];
   171	  struct stat st;
   172	  int ret;
   173	  bool existed;
   174	
   175	  pthread_mutex_lock(&g_robot_skill_lock);
   176	  ret = robot_skill_paths(path, sizeof(path), tmp, sizeof(tmp));
   177	  if (ret < 0)
   178	    {
   179	      g_robot_skill_last_result = ret;
   180	      pthread_mutex_unlock(&g_robot_skill_lock);
   181	      printf("[ROBOT-SKILL] path build failed rc=%d\n", ret);
   182	      return ret;
   183	    }
   184	
   185	  existed = stat(path, &st) == 0;
   186	  g_robot_skill_exists = existed;
   187	  g_robot_skill_matches = existed && robot_skill_file_matches(path);
   188	  if (g_robot_skill_matches)
   189	    {
   190	      g_robot_skill_last_result = ROBOT_SKILL_INSTALL_ALREADY_CURRENT;
   191	      pthread_mutex_unlock(&g_robot_skill_lock);
   192	      printf("[ROBOT-SKILL] path=%s result=already-current\n", path);
   193	      return 0;
   194	    }
   195	
   196	  ret = robot_skill_write_atomic(path, tmp);
   197	  if (ret < 0)
   198	    {
   199	      g_robot_skill_last_result = ret;
   200	      g_robot_skill_exists = stat(path, &st) == 0;
   201	      g_robot_skill_matches = false;
   202	      pthread_mutex_unlock(&g_robot_skill_lock);
   203	      printf("[ROBOT-SKILL] path=%s result=failed rc=%d errno=%d\n",
   204	             path, ret, -ret);
   205	      return ret;
   206	    }
   207	
   208	  g_robot_skill_exists = true;
   209	  g_robot_skill_matches = true;
   210	  g_robot_skill_last_result = existed ? ROBOT_SKILL_INSTALL_UPDATED
   211	                                      : ROBOT_SKILL_INSTALL_CREATED;
   212	  printf("[ROBOT-SKILL] path=%s result=%s bytes=%zu\n", path,
   213	         existed ? "updated" : "created",
   214	         sizeof(g_robot_proactive_skill) - 1);
   215	  pthread_mutex_unlock(&g_robot_skill_lock);
   216	  return 0;
   217	}
