 39	/* ── Schema builder macros (compile-time JSON Schema generation) ─── */
 40	
 41	#define TOOL_SCHEMA_BEGIN() "{\"type\":\"object\",\"properties\":{"
 42	
 43	#define TOOL_SCHEMA_END() "},\"required\":[]}"
 44	
 45	#define TOOL_SCHEMA_END_REQUIRED(required_list) \
 46	    "},\"required\":[" required_list "]}"
 47	
 48	#define TOOL_NO_PARAMS "{\"type\":\"object\",\"properties\":{},\"required\":[]}"
 49	
 50	#define TOOL_PARAM_STR(name, desc) \
 51	    "\"" name "\":{\"type\":\"string\",\"description\":\"" desc "\"}"
 52	
 53	#define TOOL_PARAM_NUM(name, desc) \
 54	    "\"" name "\":{\"type\":\"number\",\"description\":\"" desc "\"}"
 55	
 56	#define TOOL_PARAM_BOOL(name, desc) \
 57	    "\"" name "\":{\"type\":\"boolean\",\"description\":\"" desc "\"}"
 58	
 59	#define TOOL_PARAM_ENUM(name, desc, enum_values)                      \
 60	    "\"" name "\":{\"type\":\"string\",\"description\":\"" desc "\"," \
 61	    "\"enum\":[" enum_values "]}"
 62	
 63	/* ── Registration macros ───────────────────────────────────────────── */
 64	
 65	#define REGISTER_TOOL(tname, desc, schema, fn) \
 66	    do {                                       \
 67	        agent_tool_t _tool_##fn = {         \
 68	            .name = tname,                     \
 69	            .description = desc,               \
 70	            .input_schema_json = schema,       \
 71	            .execute = fn,                     \
 72	        };                                     \
 73	        register_tool(&_tool_##fn);            \
 74	    } while (0)
 75	
 76	#define REGISTER_TOOL_NO_PARAMS(tname, desc, fn) \
 77	    REGISTER_TOOL(tname, desc, TOOL_NO_PARAMS, fn)
 78	
 79	/* ── External tool provider callback (breaks circular dependency) ──── */
 80	
 81	/**
 82	 * Callback type for external tool providers.
 83	 * Returns a JSON array string of tools (caller must free), or NULL if none.
 84	 */
 85	typedef char* (*tool_provider_fn)(void);
 86	
 87	/**
 88	 * Callback type for external tool executors.
 89	 * Returns OK if tool was found and executed, ERROR otherwise.
 90	 */
 91	typedef int (*tool_executor_fn)(const char* name, const char* input_json,
 92	                                char* output, size_t output_size);
 93	
 94	/**
 95	 * Register an external tool provider (e.g., node_manager, mcp_client).
 96	 * The provider's get_tools_json callback will be called during tools JSON build.
 97	 * The executor callback will be called as fallback during tool execution.
 98	 * Max 4 providers supported.
 99	 */
100	void tool_registry_register_provider(const char* name,
101	                                     tool_provider_fn get_tools,
102	                                     tool_executor_fn execute);
103	
104	int   tool_registry_init(void);
105	char *tool_registry_get_tools_json(void);  /* caller must free() */
106	void  tool_registry_rebuild_json(void);    /* force rebuild tools JSON now */
107	void  tool_registry_invalidate(void);      /* mark tools dirty for rebuild */
108	void  tool_registry_cleanup(void);         /* free tools JSON cache */
109	int   tool_registry_execute(const char *name, const char *input_json,
110	                                   char *output, size_t output_size);
