 27	static void robot_agentctl_print_status(void)
 28	{
 29	  struct robot_world_state_s state;
 30	  uint64_t now_ms;
 31	  uint64_t idle_ms = 0;
 32	
 33	  if (robot_proactive_get_status(&state) < 0)
 34	    {
 35	      printf("robot_agentctl: state unavailable\n");
 36	      return;
 37	    }
 38	
 39	  now_ms = robot_agentctl_monotonic_ms();
 40	  if (state.user_has_interacted && now_ms >= state.last_user_activity_ms)
 41	    {
 42	      idle_ms = now_ms - state.last_user_activity_ms;
 43	    }
 44	
 45	  printf("proactive: initialized=%s enabled=%s\n",
 46	         state.initialized ? "yes" : "no",
 47	         state.proactive_enabled ? "yes" : "no");
 48	  printf("user_interacted: %s\n",
 49	         state.user_has_interacted ? "yes" : "no");
 50	  printf("last_user_activity_ms: %llu\n",
 51	         (unsigned long long)state.last_user_activity_ms);
 52	  printf("last_proactive_ms: %llu\n",
 53	         (unsigned long long)state.last_proactive_ms);
 54	  printf("idle_event_fired: %s pending=%s idle_ms=%llu\n",
 55	         state.idle_event_fired ? "yes" : "no",
 56	         state.idle_event_pending ? "yes" : "no",
 57	         (unsigned long long)idle_ms);
 58	  printf("last_event_id: %u\n", state.last_event_id);
 59	  printf("skill_path: %s\n", robot_skill_installer_path());
 60	  printf("skill_exists: %s matches: %s install_result: %s\n",
 61	         robot_skill_installer_exists() ? "yes" : "no",
 62	         robot_skill_installer_matches() ? "yes" : "no",
