+      return -ENAMETOOLONG;
+    }
+
+  strcpy(path, directory);
+  while (strlen(path) > 1 && path[strlen(path) - 1] == '/')
+    {
+      path[strlen(path) - 1] = '\0';
+    }
+
+  for (cursor = path + 1; *cursor != '\0'; cursor++)
+    {
+      if (*cursor != '/')
+        {
+          continue;
+        }
+      *cursor = '\0';
+      ret = mkdir(path, 0755);
+      *cursor = '/';
