+}
+
+static int robot_skill_make_paths(const struct contest_skill_resource_s *resource,
+                                  char *path, size_t path_size,
+                                  char *tmp, size_t tmp_size)
+{
+  int n;
+
+  if (resource == NULL || resource->filename == NULL ||
+      strchr(resource->filename, '/') != NULL)
+    {
+      return -EINVAL;
+    }
+
+  n = snprintf(path, path_size, "%s%s", AGENT_SKILLS_DIR,
+               resource->filename);
+  if (n < 0 || (size_t)n >= path_size)
+    {
+      return -ENAMETOOLONG;
+    }
+
+  n = snprintf(tmp, tmp_size, "%s%s.tmp", AGENT_SKILLS_DIR,
+               resource->filename);
+  if (n < 0 || (size_t)n >= tmp_size)
+    {
+      return -ENAMETOOLONG;
+    }
+  return 0;
+}
+
+static bool robot_skill_matches(const struct contest_skill_resource_s *resource,
+                                const char *path)
+{
+  FILE *file;
+  unsigned char buffer[128];
