+    }
+
+  if (fgetc(file) != EOF || ferror(file) != 0)
+    {
+      printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
+             resource->filename, errno != 0 ? errno : EIO);
+      fclose(file);
+      return false;
+    }
+
+  fclose(file);
+  return true;
+}
+
+static int robot_skill_write_atomic(const struct contest_skill_resource_s *resource,
+                                    const char *path, const char *tmp)
+{
+  FILE *file;
+  size_t written;
+  int saved_errno;
+
+  file = fopen(tmp, "wb");
+  if (file == NULL)
+    {
+      printf("[ROBOT-SKILL] name=%s stage=open-temp errno=%d\n",
