+  if (fclose(file) != 0)
+    {
+      saved_errno = errno != 0 ? errno : EIO;
+      printf("[ROBOT-SKILL] name=%s stage=close errno=%d\n",
+             resource->filename, saved_errno);
+      unlink(tmp);
+      return -saved_errno;
