+      return -saved_errno;
+    }
+  return 0;
+}
+
+static int robot_skill_sync_one(const struct contest_skill_resource_s *resource,
+                                size_t *current, size_t *created,
+                                size_t *updated)
+{
+  char path[ROBOT_SKILL_PATH_SIZE];
+  char tmp[ROBOT_SKILL_TMP_SIZE];
+  struct stat st;
+  bool existed;
+  int ret;
+
+  ret = robot_skill_make_paths(resource, path, sizeof(path), tmp, sizeof(tmp));
+  if (ret < 0)
+    {
+      printf("[ROBOT-SKILL] name=%s stage=check errno=%d\n",
+             resource->filename != NULL ? resource->filename : "(null)",
+             -ret);
+      return ret;
+    }
+
+  existed = stat(path, &st) == 0;
+  if (existed && robot_skill_matches(resource, path))
+    {
+      (*current)++;
+      return 0;
+    }
+
+  ret = robot_skill_write_atomic(resource, path, tmp);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (existed)
+    {
+      (*updated)++;
+    }
+  else
+    {
+      (*created)++;
+    }
+  return 0;
+}
