 35	static int robot_skill_mkdir_p(const char *directory)
 36	{
 37	  char path[ROBOT_SKILL_PATH_SIZE];
 38	  char *cursor;
 39	  int ret;
 40	
 41	  if (directory == NULL || strlen(directory) >= sizeof(path))
 42	    {
 43	      return -ENAMETOOLONG;
 44	    }
 45	
 46	  strcpy(path, directory);
 47	  while (strlen(path) > 1 && path[strlen(path) - 1] == '/')
 48	    {
 49	      path[strlen(path) - 1] = '\0';
 50	    }
 51	
 52	  for (cursor = path + 1; *cursor != '\0'; cursor++)
 53	    {
 54	      if (*cursor != '/')
 55	        {
 56	          continue;
 57	        }
 58	      *cursor = '\0';
 59	      ret = mkdir(path, 0755);
 60	      *cursor = '/';
 61	      if (ret != 0 && errno != EEXIST)
 62	        {
 63	          int saved_errno = errno;
 64	          printf("[ROBOT-SKILL] dir=%s stage=mkdir errno=%d\n", path,
 65	                 saved_errno);
 66	          return -saved_errno;
 67	        }
 68	    }
 69	
