171	      int saved_errno = errno;
172	      printf("[ROBOT-SKILL] name=%s stage=open-temp errno=%d\n",
173	             resource->filename, saved_errno);
174	      return -saved_errno;
175	    }
176	
177	  written = fwrite(resource->content, 1, resource->size, file);
178	  if (written != resource->size)
179	    {
180	      saved_errno = errno != 0 ? errno : EIO;
181	      printf("[ROBOT-SKILL] name=%s stage=write errno=%d\n",
182	             resource->filename, saved_errno);
