231	      printf("[ROBOT-SKILL] name=%s stage=check errno=%d\n",
232	             resource->filename != NULL ? resource->filename : "(null)",
233	             -ret);
234	      return ret;
235	    }
236	
237	  existed = stat(path, &st) == 0;
238	  if (existed && robot_skill_matches(resource, path))
239	    {
