   153	static int robot_motion_safe_interval(unsigned int period_ms)
   154	{
   155	  /* Keep the 3-degree POWER_SAFE increments, but reduce idle time between
   156	   * PWM frames so the requested period has a meaningful speed effect. */
   157	  int interval_ms = (int)period_ms / 125;
   158	
   159	  if (interval_ms < 12)
   160	    {
   161	      interval_ms = 12;
   162	    }
   163	  else if (interval_ms > 24)
   164	    {
   165	      interval_ms = 24;
   166	    }
   167	
   168	  return interval_ms;
   169	}
   170	
   171	static int robot_motion_safe_settle(unsigned int period_ms)
   172	{
   173	  int settle_ms = (int)period_ms / 20;
   174	
   175	  if (settle_ms < 80)
   176	    {
   177	      settle_ms = 80;
   178	    }
   179	  else if (settle_ms > 150)
   180	    {
   181	      settle_ms = 150;
   182	    }
   183	
   184	  return settle_ms;
   185	}
