   187	static int robot_motion_home_power_safe(struct robotctl_servo_ctx_s *ctx,
   188	                                        bool include_tail)
   189	{
   190	  int count = include_tail ? ROBOTCTL_SERVO_COUNT : ROBOTCTL_SERVO_COUNT - 1;
   191	  int i;
   192	
   193	  for (i = 0; i < count; i++)
   194	    {
   195	      enum robotctl_servo_e servo = g_home_order[i];
   196	      int ret;
   197	
   198	      printf("[ROBOT-MOTION] home move %s %d -> %d update=%s\n",
   199	             robotctl_servo_name(servo), ctx->angle[servo],
   200	             g_robotctl_home[servo],
   201	             ctx->angle_known[servo] &&
   202	             ctx->angle[servo] == g_robotctl_home[servo] ? "no" : "yes");
   203	      ret = robotctl_servo_move_one(ctx, servo, g_robotctl_home[servo],
   204	                                    ROBOT_MOTION_HOME_INTERVAL_MS,
   205	                                    ROBOT_MOTION_HOME_SETTLE_MS);
   206	      if (ret < 0)
   207	        {
   208	          return ret;
   209	        }
   210	    }
   211	
   212	  return 0;
   213	}
