   215	static enum robot_motion_phase_power_e robot_motion_phase_power(
   216	    const struct robotctl_servo_ctx_s *ctx,
   217	    const struct robot_motion_phase_s *phase, unsigned int *active)
   218	{
   219	  unsigned int count = 0;
   220	  unsigned int delta = 0;
   221	  unsigned int order;
   222	
   223	  for (order = 0; order < 2; order++)
   224	    {
   225	      enum robotctl_servo_e servo = phase->order[order];
   226	      int difference = phase->target[servo] - ctx->angle[servo];
   227	
   228	      if (difference != 0)
   229	        {
   230	          count++;
   231	          delta += (unsigned int)abs(difference);
   232	        }
   233	    }
   234	
   235	  if (active != NULL)
   236	    {
   237	      *active = count;
   238	    }
   239	
   240	  if (count >= 2 && delta >= 45)
   241	    {
   242	      return ROBOT_MOTION_PHASE_HEAVY;
   243	    }
   244	
   245	  return count == 0 ? ROBOT_MOTION_PHASE_LIGHT :
   246	                      ROBOT_MOTION_PHASE_MEDIUM;
   247	}
