   249	static const char *robot_motion_phase_power_name(
   250	    enum robot_motion_phase_power_e power)
   251	{
   252	  static const char *const names[] =
   253	  {
   254	    "light", "medium", "heavy"
   255	  };
   256	
   257	  return power >= ROBOT_MOTION_PHASE_LIGHT &&
   258	         power <= ROBOT_MOTION_PHASE_HEAVY ? names[power] : "unknown";
   259	}
