   573	static uint32_t robot_motion_elapsed_ms(const struct timespec *start)
   574	{
   575	  struct timespec now;
   576	  int64_t sec;
   577	  int64_t nsec;
   578	
   579	  if (start == NULL || clock_gettime(CLOCK_MONOTONIC, &now) != 0)
   580	    {
   581	      return 0;
   582	    }
   583	
   584	  sec = (int64_t)now.tv_sec - start->tv_sec;
   585	  nsec = (int64_t)now.tv_nsec - start->tv_nsec;
   586	  if (nsec < 0)
   587	    {
   588	      sec--;
   589	      nsec += 1000000000;
   590	    }
   591	
   592	  if (sec <= 0)
   593	    {
   594	      return nsec <= 0 ? 0 : (uint32_t)(nsec / 1000000);
   595	    }
   596	
   597	  if (sec > UINT32_MAX / 1000)
   598	    {
   599	      return UINT32_MAX;
   600	    }
   601	
   602	  return (uint32_t)(sec * 1000 + nsec / 1000000);
   603	}
   604	
   605	uint32_t robot_motion_default_timeout(unsigned int steps,
   606	                                      unsigned int period_ms)
   607	{
   608	  uint64_t timeout = (uint64_t)steps * period_ms +
   609	                     ROBOT_MOTION_WAIT_MARGIN_MS;
   610	
   611	  if (timeout > ROBOT_MOTION_MAX_TIMEOUT_MS)
   612	    {
   613	      timeout = ROBOT_MOTION_MAX_TIMEOUT_MS;
   614	    }
   615	
   616	  return (uint32_t)timeout;
   617	}
   618	
   619	int robot_motion_wait_timeout(uint32_t request_id, uint32_t timeout_ms,
   620	                              int *result)
   621	{
   622	  struct timespec start;
   623	  struct timespec deadline;
   624	  uint32_t elapsed;
   625	  uint32_t remaining;
   626	  uint32_t wait_ms;
   627	  int wait_ret;
   628	
   629	  if (request_id == 0 || timeout_ms == 0)
   630	    {
   631	      return -EINVAL;
   632	    }
   633	
   634	  if (clock_gettime(CLOCK_MONOTONIC, &start) != 0)
   635	    {
   636	      return -EIO;
   637	    }
   638	
   639	  pthread_mutex_lock(&g_motion.lock);
   640	  while (g_motion.completed_request_id < request_id)
   641	    {
   642	      elapsed = robot_motion_elapsed_ms(&start);
   643	      if (elapsed >= timeout_ms)
   644	        {
   645	          pthread_mutex_unlock(&g_motion.lock);
   646	          printf("[ROBOT-MOTION] wait timeout id=%lu elapsed_ms=%lu\n",
   647	                 (unsigned long)request_id, (unsigned long)elapsed);
   648	          return -ETIMEDOUT;
   649	        }
   650	
   651	      remaining = timeout_ms - elapsed;
   652	      wait_ms = remaining > 250 ? 250 : remaining;
   653	      if (clock_gettime(CLOCK_REALTIME, &deadline) != 0)
   654	        {
   655	          pthread_mutex_unlock(&g_motion.lock);
   656	          return -EIO;
   657	        }
   658	
   659	      deadline.tv_sec += wait_ms / 1000;
   660	      deadline.tv_nsec += (long)(wait_ms % 1000) * 1000000L;
   661	      if (deadline.tv_nsec >= 1000000000L)
   662	        {
   663	          deadline.tv_sec++;
   664	          deadline.tv_nsec -= 1000000000L;
   665	        }
   666	
   667	      wait_ret = pthread_cond_timedwait(&g_motion.cond, &g_motion.lock,
   668	                                        &deadline);
   669	      if (wait_ret != 0 && wait_ret != ETIMEDOUT)
   670	        {
   671	          pthread_mutex_unlock(&g_motion.lock);
   672	          return -wait_ret;
   673	        }
   674	    }
   675	
   676	  if (result != NULL)
   677	    {
   678	      *result = g_motion.last_result;
   679	    }
   680	  pthread_mutex_unlock(&g_motion.lock);
   681	  printf("[ROBOT-MOTION] wait complete id=%lu rc=%d\n",
   682	         (unsigned long)request_id, result != NULL ? *result : 0);
   683	  return 0;
   684	}
   685	
   686	int robot_motion_wait(uint32_t request_id, int *result)
   687	{
   688	  if (request_id == 0)
   689	    {
   690	      return -EINVAL;
   691	    }
   692	
   693	  pthread_mutex_lock(&g_motion.lock);
   694	  while (g_motion.completed_request_id < request_id)
   695	    {
   696	      pthread_cond_wait(&g_motion.cond, &g_motion.lock);
   697	    }
   698	
   699	  if (result != NULL)
   700	    {
   701	      *result = g_motion.last_result;
   702	    }
   703	  pthread_mutex_unlock(&g_motion.lock);
   704	  printf("[ROBOT-MOTION] wait complete id=%lu rc=%d\n",
   705	         (unsigned long)request_id, result != NULL ? *result : 0);
   706	  return 0;
   707	}
