   350	  if (total_steps < 1)
   351	    {
   352	      total_steps = 1;
   353	    }
   354	
   355	  do
   356	    {
   357	      if (current < target)
   358	        {
   359	          next = current + ROBOTCTL_SAFE_STEP_DEG;
   360	          if (next > target)
   361	            {
   362	              next = target;
   363	            }
   364	        }
   365	      else if (current > target)
   366	        {
   367	          next = current - ROBOTCTL_SAFE_STEP_DEG;
   368	          if (next < target)
   369	            {
   370	              next = target;
   371	            }
   372	        }
   373	      else
   374	        {
   375	          next = target;
   376	        }
