   378	      previous = current;
   379	      frame[servo] = next;
   380	      ret = robotctl_apply_frame(ctx, frame, 1u << servo);
   381	      if (ret < 0)
   382	        {
   383	          robotctl_servo_stop_and_close(ctx);
   384	          return ret;
