  char text[512];
  (void)arg;

  if (pcm == NULL)
    {
      printf("[contest_voice] worker cleanup: pcm allocation failed\n");
      goto cleanup;
    }

  while (!g_voice_stop_requested)
    {
      size_t pcm_len = 0;
      int ret;

      contest_voice_set_state(CONTEST_VOICE_RECORDING);
      (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_VOICE,
