  g_voice_running = 0;
  g_voice_worker_exited = true;
  contest_voice_set_state(CONTEST_VOICE_IDLE);
  pthread_mutex_unlock(&g_voice_lock);
  printf("[contest_voice] worker cleanup\n");
  return NULL;
}

