160	static const struct robot_motion_gait_s *
161	robot_motion_gait(enum robot_motion_direction_e direction)
162	{
163	  switch (direction)
164	    {
165	      case ROBOT_MOTION_FORWARD:
166	        return &g_forward;
167	      case ROBOT_MOTION_BACKWARD:
168	        return &g_backward;
169	      case ROBOT_MOTION_LEFT:
170	        return &g_left;
171	      case ROBOT_MOTION_RIGHT:
172	        return &g_right;
173	      default:
174	        return NULL;
175	    }
176	}
