178	static int robot_motion_safe_interval(unsigned int period_ms)
179	{
180	  /* Keep the 3-degree POWER_SAFE increments, but reduce idle time between
181	   * PWM frames so the requested period has a meaningful speed effect. */
182	  int interval_ms = (int)period_ms / 125;
183	
184	  if (interval_ms < 12)
185	    {
186	      interval_ms = 12;
187	    }
188	  else if (interval_ms > 24)
189	    {
190	      interval_ms = 24;
191	    }
192	
193	  return interval_ms;
194	}
195	
196	static int robot_motion_safe_settle(unsigned int period_ms)
197	{
198	  int settle_ms = (int)period_ms / 20;
199	
200	  if (settle_ms < 80)
201	    {
202	      settle_ms = 80;
203	    }
204	  else if (settle_ms > 150)
205	    {
206	      settle_ms = 150;
207	    }
208	
209	  return settle_ms;
210	}
