212	static int robot_motion_home_power_safe(struct robotctl_servo_ctx_s *ctx,
213	                                        bool include_tail)
214	{
215	  int count = include_tail ? ROBOTCTL_SERVO_COUNT : ROBOTCTL_SERVO_COUNT - 1;
216	  int i;
217	
218	  for (i = 0; i < count; i++)
219	    {
220	      enum robotctl_servo_e servo = g_home_order[i];
221	      int ret;
222	
223	      printf("[ROBOT-MOTION] home move %s %d -> %d update=%s\n",
224	             robotctl_servo_name(servo), ctx->angle[servo],
225	             g_robotctl_home[servo],
226	             ctx->angle_known[servo] &&
227	             ctx->angle[servo] == g_robotctl_home[servo] ? "no" : "yes");
228	      ret = robotctl_servo_move_one(ctx, servo, g_robotctl_home[servo],
229	                                    ROBOT_MOTION_HOME_INTERVAL_MS,
230	                                    ROBOT_MOTION_HOME_SETTLE_MS);
231	      if (ret < 0)
232	        {
233	          return ret;
234	        }
235	    }
236	
237	  return 0;
238	}
