240	static enum robot_motion_phase_power_e robot_motion_phase_power(
241	    const struct robotctl_servo_ctx_s *ctx,
242	    const struct robot_motion_phase_s *phase, unsigned int *active)
243	{
244	  unsigned int count = 0;
245	  unsigned int delta = 0;
246	  unsigned int order;
247	
248	  for (order = 0; order < 2; order++)
249	    {
250	      enum robotctl_servo_e servo = phase->order[order];
251	      int difference = phase->target[servo] - ctx->angle[servo];
252	
253	      if (difference != 0)
254	        {
255	          count++;
256	          delta += (unsigned int)abs(difference);
257	        }
258	    }
259	
260	  if (active != NULL)
261	    {
262	      *active = count;
263	    }
264	
265	  if (count >= 2 && delta >= 45)
266	    {
267	      return ROBOT_MOTION_PHASE_HEAVY;
268	    }
269	
270	  return count == 0 ? ROBOT_MOTION_PHASE_LIGHT :
271	                      ROBOT_MOTION_PHASE_MEDIUM;
272	}
273	
274	static const char *robot_motion_phase_power_name(
275	    enum robot_motion_phase_power_e power)
276	{
277	  static const char *const names[] =
278	  {
279	    "light", "medium", "heavy"
280	  };
281	
282	  return power >= ROBOT_MOTION_PHASE_LIGHT &&
283	         power <= ROBOT_MOTION_PHASE_HEAVY ? names[power] : "unknown";
284	}
285	
286	static int robot_motion_phase_settle(int settle_ms,
287	                                     enum robot_motion_phase_power_e power)
288	{
289	  if (power == ROBOT_MOTION_PHASE_LIGHT)
290	    {
291	      settle_ms = settle_ms * 3 / 4;
292	      return settle_ms < 60 ? 60 : settle_ms;
293	    }
294	
295	  if (power == ROBOT_MOTION_PHASE_HEAVY)
296	    {
297	      settle_ms = settle_ms * 5 / 4;
298	      return settle_ms > 200 ? 200 : settle_ms;
299	    }
300	
301	  return settle_ms;
302	}
