    61	static int robot_motion_tool_number(cJSON *item, unsigned int minimum,
    62	                                    unsigned int maximum,
    63	                                    unsigned int *value)
    64	{
    65	  double number;
    66	
    67	  if (item == NULL || !cJSON_IsNumber(item) || value == NULL)
    68	    {
    69	      return -EINVAL;
    70	    }
    71	
    72	  number = item->valuedouble;
    73	  if (number < minimum || number > maximum || number != (double)(int)number)
    74	    {
    75	      return -EINVAL;
    76	    }
    77	
    78	  *value = (unsigned int)number;
    79	  return 0;
    80	}
