    82	static int robot_motion_tool_execute(const char *name, const char *input_json,
    83	                                     char *output, size_t output_size)
    84	{
    85	  cJSON *root;
    86	  cJSON *direction_item;
    87	  cJSON *steps_item;
    88	  cJSON *period_item;
    89	  const char *direction_name;
    90	  enum robot_motion_direction_e direction;
    91	  unsigned int steps = ROBOT_MOTION_DEFAULT_STEPS;
    92	  unsigned int period_ms;
    93	  int ret;
    94	
    95	  if (name == NULL || input_json == NULL || output == NULL ||
    96	      output_size == 0 || strcmp(name, ROBOT_MOTION_TOOL_NAME) != 0)
    97	    {
    98	      return ERROR;
    99	    }
   100	
   101	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_ENTER\n",
   102	         robot_motion_tool_now_ms());
   103	  printf("[ROBOT-MOTION-TOOL] execute input=%s\n", input_json);
   104	  root = cJSON_Parse(input_json);
   105	  if (root == NULL)
   106	    {
   107	      snprintf(output, output_size,
   108	               "{\"ok\":false,\"error\":\"invalid json\"}");
   109	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   110	             robot_motion_tool_now_ms(), -EINVAL);
   111	      return ERROR;
   112	    }
   113	
   114	  direction_item = cJSON_GetObjectItem(root, "direction");
   115	  direction_name = cJSON_GetStringValue(direction_item);
   116	  ret = robot_motion_direction_from_name(direction_name, &direction);
   117	  if (ret < 0)
   118	    {
   119	      cJSON_Delete(root);
   120	      snprintf(output, output_size,
   121	               "{\"ok\":false,\"error\":\"invalid direction\"}");
   122	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   123	             robot_motion_tool_now_ms(), -EINVAL);
   124	      return ERROR;
   125	    }
   126	
   127	  period_ms = robot_motion_default_period(direction);
   128	  steps_item = cJSON_GetObjectItem(root, "steps");
   129	  if (steps_item != NULL &&
   130	      robot_motion_tool_number(steps_item, ROBOT_MOTION_MIN_STEPS, 1,
   131	                               &steps) < 0)
   132	    {
   133	      cJSON_Delete(root);
   134	      snprintf(output, output_size,
   135	               "{\"ok\":false,\"error\":\"steps must be 1\"}");
   136	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   137	             robot_motion_tool_now_ms(), -EINVAL);
   138	      return ERROR;
   139	    }
   140	
   141	  period_item = cJSON_GetObjectItem(root, "period_ms");
   142	  if (period_item != NULL &&
   143	      robot_motion_tool_number(period_item, ROBOT_MOTION_MIN_PERIOD,
   144	                               ROBOT_MOTION_MAX_PERIOD, &period_ms) < 0)
   145	    {
   146	      cJSON_Delete(root);
   147	      snprintf(output, output_size,
   148	               "{\"ok\":false,\"error\":\"period_ms must be 800..3000\"}");
   149	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   150	             robot_motion_tool_now_ms(), -EINVAL);
   151	      return ERROR;
   152	    }
   153	
   154	  printf("[ROBOT-MOTION-TOOL] power-safe synchronous execution\n");
   155	  printf("[ROBOT-MOTION-TOOL] direction=%s steps=%u period_ms=%u\n",
   156	         direction_name, steps, period_ms);
   157	  direction_name = robot_motion_direction_name(direction);
   158	  cJSON_Delete(root);
   159	  robot_action_guard_begin(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME);
   160	  ret = robot_motion_submit_and_wait(
   161	    ROBOT_MOTION_SOURCE_AGENT, direction, steps, period_ms,
   162	    robot_motion_default_timeout(steps, period_ms), NULL);
   163	  robot_action_guard_end(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME,
   164	                         ret);
   165	
   166	  if (ret < 0)
   167	    {
   168	      if (ret == -EBUSY)
   169	        {
   170	          snprintf(output, output_size,
   171	                   "{\"ok\":false,\"error\":\"motion_busy\"}");
   172	        }
   173	      else
   174	        {
   175	          snprintf(output, output_size,
   176	                   "{\"ok\":false,\"error\":\"motion unavailable\","
   177	                   "\"rc\":%d}", ret);
   178	        }
   179	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   180	             robot_motion_tool_now_ms(), ret);
   181	      return ERROR;
   182	    }
   183	
   184	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
   185	         robot_motion_tool_now_ms(), ret);
   186	  printf("[ROBOT-MOTION-TOOL] completed rc=%d\n", ret);
   187	  snprintf(output, output_size,
   188	           "{\"ok\":true,\"completed\":true,\"direction\":\"%s\","
   189	           "\"steps\":%u,\"period_ms\":%u}", direction_name, steps,
   190	           period_ms);
   191	  return OK;
   192	}
