   194	int robot_motion_register_tool(void)
   195	{
   196	  if (g_robot_motion_tool_registered)
   197	    {
   198	      return 0;
   199	    }
   200	
   201	  tool_registry_register_provider("robot_motion",
   202	                                  robot_motion_tool_get_tools,
   203	                                  robot_motion_tool_execute);
   204	  tool_registry_invalidate();
   205	  g_robot_motion_tool_registered = true;
   206	  printf("[ROBOT-MOTION-TOOL] provider registered\n");
   207	  return 0;
   208	}

