   616	static uint32_t robot_motion_elapsed_ms(const struct timespec *start)
   617	{
   618	  struct timespec now;
   619	  int64_t sec;
   620	  int64_t nsec;
   621	
   622	  if (start == NULL || clock_gettime(CLOCK_MONOTONIC, &now) != 0)
   623	    {
   624	      return 0;
   625	    }
   626	
   627	  sec = (int64_t)now.tv_sec - start->tv_sec;
   628	  nsec = (int64_t)now.tv_nsec - start->tv_nsec;
   629	  if (nsec < 0)
   630	    {
   631	      sec--;
   632	      nsec += 1000000000;
   633	    }
   634	
   635	  if (sec <= 0)
   636	    {
   637	      return nsec <= 0 ? 0 : (uint32_t)(nsec / 1000000);
   638	    }
   639	
   640	  if (sec > UINT32_MAX / 1000)
   641	    {
   642	      return UINT32_MAX;
   643	    }
   644	
   645	  return (uint32_t)(sec * 1000 + nsec / 1000000);
   646	}
