   827	int robot_motion_home_sync(void)
   828	{
   829	  struct robotctl_servo_ctx_s ctx;
   830	  int ret;
   831	
   832	  pthread_mutex_lock(&g_motion.lock);
   833	  if (g_motion.request_pending ||
   834	      g_motion.state == ROBOT_MOTION_STATE_RUNNING)
   835	    {
   836	      pthread_mutex_unlock(&g_motion.lock);
   837	      return -EBUSY;
   838	    }
   839	  g_motion.state = ROBOT_MOTION_STATE_RUNNING;
   840	  pthread_mutex_unlock(&g_motion.lock);
   841	
   842	  printf("[ROBOT-MOTION] backend init begin\n");
   843	  ret = robotctl_servo_open(&ctx);
   844	  printf("[ROBOT-MOTION] backend init done rc=%d\n", ret);
   845	  if (ret >= 0)
   846	    {
   847	      ret = robot_motion_home_power_safe(&ctx, true);
   848	      robotctl_servo_close(&ctx);
   849	    }
   850	
   851	  pthread_mutex_lock(&g_motion.lock);
   852	  g_motion.last_result = ret;
   853	  g_motion.state = ret < 0 ? ROBOT_MOTION_STATE_ERROR :
   854	                            ROBOT_MOTION_STATE_IDLE;
   855	  pthread_cond_broadcast(&g_motion.cond);
   856	  pthread_mutex_unlock(&g_motion.lock);
   857	  return ret;
   858	}
