   860	bool robot_motion_is_busy(void)
   861	{
   862	  bool busy;
   863	
   864	  pthread_mutex_lock(&g_motion.lock);
   865	  busy = g_motion.request_pending ||
   866	         g_motion.state == ROBOT_MOTION_STATE_RUNNING;
   867	  pthread_mutex_unlock(&g_motion.lock);
   868	  return busy;
   869	}
