   871	enum robot_motion_state_e robot_motion_get_state(void)
   872	{
   873	  enum robot_motion_state_e state;
   874	
   875	  pthread_mutex_lock(&g_motion.lock);
   876	  state = g_motion.state;
   877	  pthread_mutex_unlock(&g_motion.lock);
   878	  return state;
   879	}
   880	
   881	int robot_motion_get_active(struct robot_motion_request_s *request)
   882	{
   883	  if (request == NULL)
   884	    {
   885	      return -EINVAL;
   886	    }
   887	
   888	  pthread_mutex_lock(&g_motion.lock);
   889	  if (!g_motion.request_pending &&
   890	      g_motion.state != ROBOT_MOTION_STATE_RUNNING)
   891	    {
   892	      pthread_mutex_unlock(&g_motion.lock);
   893	      return -ENOENT;
   894	    }
   895	  *request = g_motion.request;
   896	  pthread_mutex_unlock(&g_motion.lock);
   897	  return 0;
   898	}

