    20	#define ROBOT_ACTION_CACHE_GUARD_WINDOW_MS (30ULL * 1000ULL)
    21	#define ROBOT_ACTION_CACHE_CLEAR_INTERVAL_US (100 * 1000)
    22	#define ROBOT_ACTION_CACHE_IDLE_INTERVAL_US (500 * 1000)
    23	#define ROBOT_ACTION_GUARD_STACK 4096
    24	
    25	struct robot_action_guard_state_s
    26	{
    27	  pthread_mutex_t lock;
    28	  pthread_t worker;
    29	  bool initialized;
    30	  bool worker_started;
    31	  bool worker_error_logged;
    32	  uint64_t guard_until_ms;
    33	  uint32_t generation;
    34	};
    35	
    36	static struct robot_action_guard_state_s g_guard =
    37	{
    38	  .lock = PTHREAD_MUTEX_INITIALIZER,
    39	};
    40	
    41	static uint64_t robot_action_guard_now_ms(void)
    42	{
    43	  struct timespec ts;
    44	
    45	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    46	    {
    47	      return 0;
    48	    }
    49	
    50	  return (uint64_t)ts.tv_sec * 1000ULL +
    51	         (uint64_t)ts.tv_nsec / 1000000ULL;
    52	}
    53	
    54	static const char *robot_action_type_name(enum robot_action_type_e type)
    55	{
    56	  switch (type)
    57	    {
    58	      case ROBOT_ACTION_EXPRESSION:
    59	        return "expression";
    60	      case ROBOT_ACTION_MOTION:
    61	        return "motion";
    62	      case ROBOT_ACTION_POSTURE:
    63	        return "posture";
    64	      case ROBOT_ACTION_BEHAVIOR:
    65	        return "behavior";
    66	      case ROBOT_ACTION_AUDIO:
    67	        return "audio";
    68	      case ROBOT_ACTION_SYSTEM:
    69	        return "system";
    70	      default:
    71	        return "unknown";
    72	    }
    73	}
    74	
    75	static void *robot_action_guard_worker(void *arg)
    76	{
    77	  bool was_active = false;
    78	
    79	  (void)arg;
    80	
    81	  printf("[ROBOT-ACTION] worker started\n");
    82	
    83	  for (;;)
    84	    {
    85	      uint64_t now = robot_action_guard_now_ms();
    86	      uint64_t until;
    87	      bool active;
    88	
    89	      pthread_mutex_lock(&g_guard.lock);
    90	      until = g_guard.guard_until_ms;
    91	      pthread_mutex_unlock(&g_guard.lock);
    92	
    93	      active = until != 0 && now != 0 && now < until;
    94	      if (active)
    95	        {
    96	          /*
    97	           * The Agent may put the final answer in the cache after the Tool
    98	           * callback returns, so one invalidate in begin/end is insufficient.
    99	           */
   100	          llm_cache_invalidate();
   101	          was_active = true;
   102	          usleep(ROBOT_ACTION_CACHE_CLEAR_INTERVAL_US);
   103	        }
   104	      else
   105	        {
   106	          if (was_active)
   107	            {
   108	              printf("[ROBOT-ACTION] guard window ended\n");
   109	              was_active = false;
   110	            }
   111	
   112	          usleep(ROBOT_ACTION_CACHE_IDLE_INTERVAL_US);
   113	        }
   114	    }
   115	
   116	  return NULL;
   117	}
   118	
   119	int robot_action_guard_init(void)
   120	{
   121	  pthread_attr_t attr;
   122	  int ret;
   123	
   124	  pthread_mutex_lock(&g_guard.lock);
   125	  if (g_guard.initialized)
   126	    {
   127	      pthread_mutex_unlock(&g_guard.lock);
   128	      return 0;
   129	    }
   130	
   131	  g_guard.initialized = true;
   132	  pthread_mutex_unlock(&g_guard.lock);
   133	
   134	  ret = pthread_attr_init(&attr);
   135	  if (ret == 0)
   136	    {
   137	      ret = pthread_attr_setstacksize(&attr, ROBOT_ACTION_GUARD_STACK);
   138	      if (ret == 0)
   139	        {
   140	          ret = pthread_create(&g_guard.worker, &attr,
   141	                               robot_action_guard_worker, NULL);
   142	        }
   143	      pthread_attr_destroy(&attr);
   144	    }
   145	
   146	  pthread_mutex_lock(&g_guard.lock);
   147	  if (ret == 0)
   148	    {
   149	      g_guard.worker_started = true;
   150	      pthread_detach(g_guard.worker);
   151	      pthread_mutex_unlock(&g_guard.lock);
   152	      printf("[ROBOT-ACTION] initialized\n");
   153	      return 0;
   154	    }
   155	
   156	  if (!g_guard.worker_error_logged)
   157	    {
   158	      printf("[ROBOT-ACTION] worker create failed rc=%d; fail-open\n", ret);
   159	      g_guard.worker_error_logged = true;
   160	    }
   161	  pthread_mutex_unlock(&g_guard.lock);
   162	  return -ret;
   163	}
   164	
   165	static uint32_t robot_action_guard_extend(enum robot_action_type_e type,
   166	                                          const char *tool_name,
   167	                                          bool begin)
   168	{
   169	  uint64_t now;
   170	  uint64_t requested_until;
   171	  uint32_t generation;
   172	  bool extended;
   173	
   174	  now = robot_action_guard_now_ms();
   175	  requested_until = now + ROBOT_ACTION_CACHE_GUARD_WINDOW_MS;
   176	
   177	  pthread_mutex_lock(&g_guard.lock);
   178	  extended = requested_until > g_guard.guard_until_ms;
   179	  if (extended)
   180	    {
   181	      g_guard.guard_until_ms = requested_until;
   182	    }
   183	  if (begin)
   184	    {
   185	      g_guard.generation++;
   186	    }
   187	  generation = g_guard.generation;
   188	  pthread_mutex_unlock(&g_guard.lock);
   189	
   190	  printf("[ROBOT-ACTION] %s type=%s tool=%s gen=%lu\n",
   191	         begin ? "begin" : "end", robot_action_type_name(type),
   192	         tool_name != NULL ? tool_name : "unknown",
   193	         (unsigned long)generation);
   194	  if (extended)
   195	    {
   196	      printf("[ROBOT-ACTION] guard window %s\n",
   197	             begin ? "started" : "extended");
   198	    }
   199	
   200	  return generation;
   201	}
   202	
   203	void robot_action_guard_begin(enum robot_action_type_e type,
   204	                              const char *tool_name)
   205	{
   206	  int ret;
   207	
   208	  ret = robot_action_guard_init();
   209	  if (ret < 0)
   210	    {
   211	      /* A cache guard failure must never block the physical action. */
   212	      printf("[ROBOT-ACTION] begin guard unavailable; fail-open\n");
   213	      return;
   214	    }
   215	
   216	  (void)robot_action_guard_extend(type, tool_name, true);
   217	  llm_cache_invalidate();
   218	}
   219	
   220	void robot_action_guard_end(enum robot_action_type_e type,
   221	                            const char *tool_name,
   222	                            int action_result)
   223	{
   224	  int ret;
   225	
   226	  ret = robot_action_guard_init();
   227	  if (ret < 0)
   228	    {
   229	      printf("[ROBOT-ACTION] end type=%s tool=%s rc=%d fail-open\n",
   230	             robot_action_type_name(type),
   231	             tool_name != NULL ? tool_name : "unknown", action_result);
   232	      return;
   233	    }
   234	
   235	  (void)robot_action_guard_extend(type, tool_name, false);
   236	  printf("[ROBOT-ACTION] action-result rc=%d\n", action_result);
   237	  llm_cache_invalidate();
   238	}

