253	int robot_oled_init(void)
254	{
255	  pthread_attr_t attr;
256	  int ret;
257	
258	  pthread_mutex_lock(&g_oled_queue.lock);
259	  if (g_oled_initialized)
260	    {
261	      ret = g_oled_failed ? -ENODEV : 0;
262	      pthread_mutex_unlock(&g_oled_queue.lock);
263	      return ret;
264	    }
265	
266	  g_oled_initialized = true;
267	  g_oled_stop = false;
268	  g_oled_ready = false;
269	  g_oled_failed = false;
270	  g_oled_queue.head = 0;
271	  g_oled_queue.tail = 0;
272	  g_oled_queue.count = 0;
273	  pthread_mutex_unlock(&g_oled_queue.lock);
274	
275	  ret = pthread_attr_init(&attr);
276	  if (ret == 0)
277	    {
278	      ret = pthread_attr_setstacksize(&attr, ROBOT_OLED_STACK);
279	      if (ret == 0)
280	        {
281	          ret = pthread_create(&g_oled_thread, &attr, robot_oled_worker,
282	                               NULL);
283	        }
284	
285	      pthread_attr_destroy(&attr);
286	    }
287	
288	  if (ret != 0)
289	    {
290	      pthread_mutex_lock(&g_oled_queue.lock);
291	      g_oled_failed = true;
292	      g_oled_initialized = false;
293	      pthread_mutex_unlock(&g_oled_queue.lock);
294	      printf("[RV-OLED] worker create failed rc=%d\n", ret);
295	      return -ret;
296	    }
297	
298	  pthread_mutex_lock(&g_oled_queue.lock);
299	  g_oled_thread_valid = true;
300	  pthread_mutex_unlock(&g_oled_queue.lock);
301	
302	  printf("[RV-OLED] worker created\n");
303	  return 0;
304	}
