306	int robot_oled_stop(void)
307	{
308	  bool join_needed;
309	
310	  pthread_mutex_lock(&g_oled_queue.lock);
311	  join_needed = g_oled_thread_valid;
312	  g_oled_stop = true;
313	  pthread_cond_broadcast(&g_oled_queue.available);
314	  pthread_mutex_unlock(&g_oled_queue.lock);
315	
316	  if (join_needed)
317	    {
318	      pthread_join(g_oled_thread, NULL);
319	    }
320	
321	  pthread_mutex_lock(&g_oled_queue.lock);
322	  g_oled_thread_valid = false;
323	  g_oled_initialized = false;
324	  g_oled_ready = false;
325	  g_oled_failed = false;
326	  g_oled_queue.head = 0;
327	  g_oled_queue.tail = 0;
328	  g_oled_queue.count = 0;
329	  pthread_mutex_unlock(&g_oled_queue.lock);
330	
331	  g_oled_dev = NULL;
332	  memset(&g_oled_plane, 0, sizeof(g_oled_plane));
333	  return 0;
334	}
335	
336	int robot_oled_submit(enum robot_expression_e expression)
337	{
338	  if (expression < 0 || expression >= ROBOT_EXPRESSION_COUNT)
339	    {
340	      return -EINVAL;
341	    }
342	
343	  pthread_mutex_lock(&g_oled_queue.lock);
344	
345	  if (!g_oled_initialized || g_oled_stop)
346	    {
347	      pthread_mutex_unlock(&g_oled_queue.lock);
348	      return -EAGAIN;
349	    }
350	
351	  if (g_oled_failed)
352	    {
353	      pthread_mutex_unlock(&g_oled_queue.lock);
354	      return -ENODEV;
355	    }
356	
357	  /*
358	   * Avoid piling up identical frames.  This also reduces I2C traffic when a
359	   * caller repeats the same state while the worker is still busy.
360	   */
361	
362	  if (g_oled_queue.count > 0)
363	    {
364	      unsigned int last =
365	          (g_oled_queue.tail + ROBOT_OLED_QUEUE_DEPTH - 1) %
366	          ROBOT_OLED_QUEUE_DEPTH;
367	
368	      if (g_oled_queue.slots[last] == expression)
369	        {
370	          pthread_mutex_unlock(&g_oled_queue.lock);
371	          return 0;
372	        }
373	    }
374	
375	  if (g_oled_queue.count == ROBOT_OLED_QUEUE_DEPTH)
376	    {
377	      printf("[RV-OLED] queue full: dropping oldest expression=%d\n",
378	             g_oled_queue.slots[g_oled_queue.head]);
379	      g_oled_queue.head =
380	          (g_oled_queue.head + 1) % ROBOT_OLED_QUEUE_DEPTH;
381	      g_oled_queue.count--;
382	    }
383	
384	  g_oled_queue.slots[g_oled_queue.tail] = expression;
385	  g_oled_queue.tail =
386	      (g_oled_queue.tail + 1) % ROBOT_OLED_QUEUE_DEPTH;
387	  g_oled_queue.count++;
388	
389	  printf("[RV-OLED] enqueue expression=%d pending=%u ready=%d\n",
390	         expression, g_oled_queue.count, g_oled_ready ? 1 : 0);
391	
392	  pthread_cond_signal(&g_oled_queue.available);
393	  pthread_mutex_unlock(&g_oled_queue.lock);
394	  return 0;
395	}
396	
397	bool robot_oled_is_available(void)
398	{
399	  bool available;
400	
401	  pthread_mutex_lock(&g_oled_queue.lock);
402	  available = g_oled_ready && !g_oled_failed;
403	  pthread_mutex_unlock(&g_oled_queue.lock);
404	  return available;
405	}

