   143	static void robot_expression_boot_latch_idle(void)
   144	{
   145	  int ret;
   146	  int i;
   147	  bool ready = false;
   148	
   149	  /*
   150	   * Startup display and runtime expression management are deliberately
   151	   * separated.
   152	   *
   153	   * We briefly start the OLED worker, draw IDLE, wait for the frame to reach
   154	   * the SSD1306, then stop the worker.  The panel keeps the last framebuffer,
   155	   * so ai_agent reaches its prompt with a naturally lit idle face but no OLED
   156	   * or expression background thread remains active while Wi-Fi is brought up.
   157	   *
   158	   * The first real Agent/voice expression later starts the normal persistent
   159	   * runtime workers through robot_expression_init().
   160	   */
   161	  printf("[RV-EXPR] boot idle display begin\n");
   162	
   163	  ret = robot_oled_init();
   164	  if (ret < 0)
   165	    {
   166	      printf("[RV-EXPR] boot idle display: oled init failed rc=%d\n", ret);
   167	      return;
   168	    }
   169	
   170	  ret = robot_oled_submit(ROBOT_EXPRESSION_IDLE);
   171	  if (ret < 0)
   172	    {
   173	      printf("[RV-EXPR] boot idle display: submit failed rc=%d\n", ret);
   174	      (void)robot_oled_stop();
   175	      return;
   176	    }
   177	
   178	  for (i = 0; i < ROBOT_BOOT_DISPLAY_READY_RETRIES; i++)
   179	    {
   180	      if (robot_oled_is_available())
   181	        {
   182	          ready = true;
   183	          break;
   184	        }
   185	
   186	      usleep(ROBOT_BOOT_DISPLAY_POLL_US);
   187	    }
   188	
   189	  if (ready)
   190	    {
   191	      /*
   192	       * Availability means board/plane setup has completed.  Give the worker
   193	       * enough time to drain the already queued 128x64 idle frame before
   194	       * asking it to exit.
   195	       */
   196	      usleep(ROBOT_BOOT_DISPLAY_SETTLE_US);
   197	      printf("[RV-EXPR] boot idle display latched\n");
   198	    }
   199	  else
   200	    {
   201	      printf("[RV-EXPR] boot idle display: worker not ready\n");
   202	    }
   203	
   204	  /*
   205	   * robot_oled_stop() does not power the SSD1306 off or clear it, so the last
   206	   * idle frame remains visible while the background worker is gone.
   207	   */
   208	  (void)robot_oled_stop();
   209	  printf("[RV-EXPR] boot OLED worker stopped; panel remains latched\n");
   210	}
