      if (ret < 0)
        {
          return ret;
        }
    }

  return 0;
}

static enum robot_motion_phase_power_e robot_motion_phase_power(
    const struct robotctl_servo_ctx_s *ctx,
    const struct robot_motion_phase_s *phase, unsigned int *active)
{
  unsigned int count = 0;
  unsigned int delta = 0;
