/**
 * message_bus.h — inter-task message bus
 *
 * with POSIX mutex + condition variable + ring buffer.
 */

#include "agent_compat.h"
#include <stdint.h>

/** A single message travelling on the bus. */
typedef struct {
    char  channel[16];   /**< "feishu", "websocket", "cli", "system" */
    char  chat_id[64];   /**< chat_id (Feishu IDs are ~36 chars) */
    char *content;       /**< Heap-allocated text; receiver must free. */
    char *image_b64;     /**< Optional base64-encoded image; receiver must free. NULL if none. */
} agent_msg_t;

/** Free heap members (content, image_b64) of a message.
 *  Safe to call on a zeroed or already-freed message. */
void message_bus_msg_free(agent_msg_t *msg);

/** Initialise inbound and outbound queues. */
int message_bus_init(void);

/** Destroy queues and release synchronisation resources. */
void message_bus_destroy(void);

/** Wake all threads blocked on pop (used during shutdown). */
void message_bus_wakeup(void);

/** Push a message to the inbound queue (towards the agent loop).
 *  On success the bus takes ownership of heap members.
 *  On failure (queue full / timeout) the caller still owns them. */
int message_bus_push_inbound(const agent_msg_t *msg);

/** Block until an inbound message is available (or timeout expires).
 *  Caller must free msg->content / msg->image_b64 when done. */
int message_bus_pop_inbound(agent_msg_t *msg, uint32_t timeout_ms);

/** Push a message to the outbound queue (towards channels).
 *  On success the bus takes ownership of heap members.
 *  On failure the caller still owns them. */
int message_bus_push_outbound(const agent_msg_t *msg);

/** Block until an outbound message is available (or timeout expires). */
int message_bus_pop_outbound(agent_msg_t *msg, uint32_t timeout_ms);
static void contest_voice_wait_for_reply_cycle(void)
{
  /* Once ASR text has entered ai_agent, keep the microphone idle until the
   * outbound voice reply has gone through TTS.  voice_channel_speak() changes
   * WAIT_AGENT -> SPEAKING -> RECORDING, which releases this wait. */

  while (!g_voice_stop_requested)
    {
      if (!g_voice_speaking && g_voice_state == CONTEST_VOICE_RECORDING)
        {
          return;
        }

      usleep(20 * 1000);
    }
}

static void *voice_record_worker(void *arg)
{
  size_t pcm_cap = (size_t)ROBOT_VOICE_CAPTURE_RATE * 2 *
                   ROBOT_VOICE_CAPTURE_SECONDS;
  uint8_t *pcm = malloc(pcm_cap);
  char text[512];
  (void)arg;

  if (pcm == NULL)
    {
      printf("[contest_voice] worker cleanup: pcm allocation failed\n");
      goto cleanup;
    }

  while (!g_voice_stop_requested)
    {
      size_t pcm_len = 0;
      int ret;

      contest_voice_set_state(CONTEST_VOICE_RECORDING);
      (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_VOICE,
                                  ROBOT_EXPRESSION_LISTENING, 0);
      ret = robot_voice_capture_record_interruptible(
          pcm, pcm_cap, &pcm_len, ROBOT_VOICE_CAPTURE_SECONDS * 1000,
          &g_voice_stop_requested);
      printf("[RV-VOICE] capture returned rc=%d bytes=%zu\n", ret, pcm_len);
      if (ret < 0 || g_voice_stop_requested)
        {
          break;
        }
      if (g_voice_speaking)
        {
          continue;
        }
      contest_voice_set_state(CONTEST_VOICE_ASR);
      printf("[RV-VOICE] invoking ASR bytes=%zu on dedicated worker\n", pcm_len);
      ret = contest_voice_run_asr(pcm, pcm_len, text, sizeof(text));
      if (g_voice_stop_requested)
        {
          break;
        }
      if (ret < 0 || text[0] == '\0')
        {
          (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_VOICE);
          (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_SYSTEM,
                                      ROBOT_EXPRESSION_ERROR, 1500);
          printf("[contest_voice] ASR failed: %d\n", ret);
          if (g_voice_oneshot)
            {
              break;
            }
          continue;
        }

      printf("[RV-ASR] text: %s\n", text);
      robot_world_state_note_user_activity();
      (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_VOICE,
                                  ROBOT_EXPRESSION_THINKING, 0);
      agent_msg_t msg;
      memset(&msg, 0, sizeof(msg));
      strncpy(msg.channel, AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
      strncpy(msg.chat_id, "voice", sizeof(msg.chat_id) - 1);
      msg.content = strdup(text);
      contest_voice_set_state(CONTEST_VOICE_WAIT_AGENT);
      printf("[RV-VOICE] push inbound voice:voice\n");
      if (msg.content == NULL || message_bus_push_inbound(&msg) != OK)
        {
          free(msg.content);
          (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_VOICE);
          (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_SYSTEM,
                                      ROBOT_EXPRESSION_ERROR, 1500);
          printf("[contest_voice] message bus submit failed\n");
          if (g_voice_oneshot)
            {
              break;
            }
          continue;
        }

      if (g_voice_oneshot)
        {
          break;
        }

      contest_voice_wait_for_reply_cycle();
    }

cleanup:
  free(pcm);
  (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_VOICE);
  pthread_mutex_lock(&g_voice_lock);
  g_voice_running = 0;
  g_voice_worker_exited = true;
  contest_voice_set_state(CONTEST_VOICE_IDLE);
  pthread_mutex_unlock(&g_voice_lock);
  printf("[contest_voice] worker cleanup\n");
  return NULL;
}

