  uint64_t idle_seconds = 0;

  if (event->type == ROBOT_EVENT_IDLE_LONG &&
      now_ms >= state->last_user_activity_ms)
    {
      idle_seconds = (now_ms - state->last_user_activity_ms) / 1000ULL;
