      return -ENOMEM;
    }

  ret = message_bus_push_inbound(&msg);
  if (ret != OK)
    {
      free(msg.content);
      return -EAGAIN;
    }

  printf("[ROBOT-PROACTIVE] inbound id=%u channel=%s chat_id=%s\n",
         event->id, msg.channel, msg.chat_id);
  return 0;
