  n = snprintf(tmp, tmp_size, "%s%s.tmp", AGENT_SKILLS_DIR,
               resource->filename);
  if (n < 0 || (size_t)n >= tmp_size)
    {
      return -ENAMETOOLONG;
    }
  return 0;
}

static bool robot_skill_matches(
  const struct contest_skill_resource_s *resource, const char *path)
