    media_ctx_init_once();

    pthread_mutex_lock(&g_media.lock);

    if (g_media.state == MEDIA_STATE_PAUSED) {
        int rc = respond_ok_state(output, output_size, "\"noop\":true");
        pthread_mutex_unlock(&g_media.lock);
        return rc;
    }

    if (g_media.state != MEDIA_STATE_PLAYING) {
        pthread_mutex_unlock(&g_media.lock);
