   132	/**
   133	 * Sanitize URL for logging — strip query string to avoid token leaks.
   134	 */
   135	
   136	static void log_url(const char* url, char* buf, size_t bufsz)
   137	{
   138	    const char* q = strchr(url, '?');
   139	    if (q) {
   140	        size_t len = (size_t)(q - url);
   141	        if (len >= bufsz) {
   142	            len = bufsz - 1;
   143	        }
   144	
   145	        memcpy(buf, url, len);
   146	        buf[len] = '\0';
   147	    } else {
   148	        snprintf(buf, bufsz, "%s", url);
   149	    }
   150	}
