   152	/**
   153	 * Force-close current session (stop + close). Caller must hold lock.
   154	 * Does NOT wait for events — used for error recovery and cleanup.
   155	 */
   156	
   157	static void force_close_locked(void)
   158	{
   159	    if (g_media.handle) {
   160	        syslog(LOG_INFO, "[%s] Force close session %" PRIu32 "\n",
   161	            TAG, g_media.session_id);
   162	        media_player_stop(g_media.handle);
   163	
   164	        /* Brief yield to let the player drain its internal queue
   165	         * before close — prevents "play/resume failed: End of file"
   166	         * log spam when the player tries to read after EOF. */
   167	
   168	        pthread_mutex_unlock(&g_media.lock);
   169	        usleep(50 * 1000); /* 50ms */
   170	        pthread_mutex_lock(&g_media.lock);
   171	
   172	        if (g_media.handle) {
   173	            media_player_close(g_media.handle, 0);
   174	            g_media.handle = NULL;
   175	        }
   176	    }
   177	
   178	    g_media.state = MEDIA_STATE_IDLE;
   179	    g_media.url[0] = '\0';
   180	}
