   182	/**
   183	 * Map user volume (0..100) to hardware index.
   184	 */
   185	
   186	static int volume_to_index(int vol)
   187	{
   188	    if (vol <= MEDIA_VOL_USER_MIN) {
   189	        return MEDIA_VOL_MIN_IDX;
   190	    }
   191	
   192	    if (vol >= MEDIA_VOL_USER_MAX) {
   193	        return MEDIA_VOL_MAX_IDX;
   194	    }
   195	
   196	    int idx = MEDIA_VOL_MIN_IDX + (int)round((double)vol * (MEDIA_VOL_MAX_IDX - MEDIA_VOL_MIN_IDX) / 100.0);
   197	
   198	    if (idx < MEDIA_VOL_MIN_IDX) {
   199	        idx = MEDIA_VOL_MIN_IDX;
   200	    }
   201	
   202	    if (idx > MEDIA_VOL_MAX_IDX) {
   203	        idx = MEDIA_VOL_MAX_IDX;
   204	    }
   205	
   206	    return idx;
   207	}
