   209	/**
   210	 * Push a notification to the agent loop so the LLM can inform the user
   211	 * about asynchronous playback events (EOF, errors).
   212	 * Must be called WITHOUT g_media.lock held (push may block briefly).
   213	 */
   214	
   215	static void notify_agent(const char* fmt, ...)
   216	{
   217	    char buf[256];
   218	    va_list ap;
   219	
   220	    va_start(ap, fmt);
   221	    vsnprintf(buf, sizeof(buf), fmt, ap);
   222	    va_end(ap);
