   224	    agent_msg_t msg;
   225	    memset(&msg, 0, sizeof(msg));
   226	    strncpy(msg.channel, "system", sizeof(msg.channel) - 1);
   227	    strncpy(msg.chat_id, "media", sizeof(msg.chat_id) - 1);
   228	    msg.content = strdup(buf);
   229	    if (msg.content) {
   230	        if (message_bus_push_inbound(&msg) != OK) {
   231	            syslog(LOG_WARNING, "[%s] Failed to push media notification\n", TAG);
   232	            free(msg.content);
   233	        }
   234	    }
