   237	/**
   238	 * Media event callback — called from media framework thread.
   239	 * Records event + result, then posts semaphore for waiting execute.
   240	 * Also handles autonomous events (COMPLETED / async errors).
   241	 */
   242	
   243	static void media_event_cb(void* cookie, int event, int result,
   244	    const char* extra)
   245	{
   246	    uint32_t cb_session = (uint32_t)(uintptr_t)cookie;
   247	
   248	    pthread_mutex_lock(&g_media.lock);
   249	
   250	    /* Discard stale session events */
   251	
   252	    if (cb_session != g_media.session_id) {
   253	        syslog(LOG_DEBUG,
   254	            "[%s] Stale event %d for session %" PRIu32
   255	            " (current %" PRIu32 "), discarded\n",
   256	            TAG, event, cb_session, g_media.session_id);
   257	        pthread_mutex_unlock(&g_media.lock);
   258	        return;
   259	    }
   260	
   261	    if (g_media.exiting) {
   262	        pthread_mutex_unlock(&g_media.lock);
   263	        return;
   264	    }
   265	
   266	    /* Discard events after force_close (e.g. STOPPED from cleanup) */
   267	
   268	    if (g_media.state == MEDIA_STATE_IDLE && g_media.handle == NULL) {
   269	        syslog(LOG_DEBUG,
   270	            "[%s] Event %d after cleanup, discarded\n",
   271	            TAG, event);
   272	        pthread_mutex_unlock(&g_media.lock);
   273	        return;
   274	    }
   275	
   276	    syslog(LOG_INFO, "[%s] Event %d result %d extra=%s\n",
   277	        TAG, event, result, extra ? extra : "");
   278	
   279	    /* Ignore NOP events — audio_output fires these continuously
   280	     * during playback.  If we let them through they poison
   281	     * last_event and wake sem, breaking wait_event() for real
   282	     * commands (stop / pause / seek / switch). */
   283	
   284	    if (event == MEDIA_EVENT_NOP) {
   285	        pthread_mutex_unlock(&g_media.lock);
   286	        return;
   287	    }
   288	
   289	    /* Handle autonomous COMPLETED (EOF or error-complete) */
   290	
   291	    if (event == MEDIA_EVENT_COMPLETED) {
   292	        char url_copy[MEDIA_URL_MAX];
   293	        snprintf(url_copy, sizeof(url_copy), "%s", g_media.url);
   294	        uint32_t sid = g_media.session_id;
   295	
   296	        if (result >= 0) {
   297	            /* Normal playback finished -> IDLE */
   298	
   299	            syslog(LOG_INFO, "[%s] EOF — auto stop session %" PRIu32 "\n",
   300	                TAG, sid);
   301	
   302	            /* Bump session_id so STOPPED from force_close is discarded */
   303	
   304	            g_media.session_id++;
   305	            force_close_locked();
   306	            pthread_mutex_unlock(&g_media.lock);
   307	
   308	            notify_agent("[music] Playback finished (session %" PRIu32 ")."
   309	                         " The track has ended normally.",
   310	                sid);
   311	        } else {
   312	            /* Error during playback -> close and go IDLE */
   313	
   314	            syslog(LOG_ERR,
   315	                "[%s] COMPLETED with error result=%d session %" PRIu32 "\n",
   316	                TAG, result, sid);
   317	
   318	            /* Bump session so any further stale events are discarded */
   319	
   320	            g_media.session_id++;
   321	            force_close_locked();
   322	            pthread_mutex_unlock(&g_media.lock);
   323	
   324	            notify_agent("[music] Playback failed (session %" PRIu32
   325	                         ", error=%d). Please inform the user that"
   326	                         " the music could not be played successfully.",
   327	                sid, result);
   328	        }
   329	
   330	        return;
   331	    }
   332	
   333	    /* Record event + result for the waiting execute function */
   334	
   335	    g_media.last_event = event;
   336	    g_media.last_result = result;
   337	
   338	    /* Update state based on confirmed events */
   339	
   340	    if (result >= 0) {
   341	        switch (event) {
   342	        case MEDIA_EVENT_PREPARED:
   343	            g_media.state = MEDIA_STATE_PREPARED;
   344	            break;
   345	
   346	        case MEDIA_EVENT_STARTED:
   347	            g_media.state = MEDIA_STATE_PLAYING;
   348	            break;
   349	
   350	        case MEDIA_EVENT_PAUSED:
   351	            g_media.state = MEDIA_STATE_PAUSED;
   352	            break;
   353	
   354	        case MEDIA_EVENT_STOPPED:
   355	            /* stop event — state will be set to IDLE by force_close */
   356	            break;
   357	
   358	        default:
   359	            break;
   360	        }
   361	    } else {
   362	        /* Async error */
   363	
   364	        syslog(LOG_ERR,
   365	            "[%s] Async error event=%d result=%d extra=%s\n",
   366	            TAG, event, result, extra ? extra : "");
   367	        g_media.state = MEDIA_STATE_ERROR;
   368	    }
   369	
   370	    pthread_mutex_unlock(&g_media.lock);
   371	
   372	    /* Wake up the waiting execute function */
   373	
   374	    sem_post(&g_media.sem);
   375	}
