148	
149	  if (!state.proactive_enabled)
150	    {
151	      robot_proactive_drop(event, "disabled");
152	      return;
153	    }
154	
155	  now_ms = robot_proactive_monotonic_ms();
156	  if (event->id <= state.last_processed_event_id)
157	    {
158	      robot_proactive_drop(event, "duplicate-event-id");
159	      return;
160	    }
161	
162	  if (state.last_proactive_ms != 0 &&
163	      now_ms - state.last_proactive_ms < ROBOT_PROACTIVE_COOLDOWN_MS)
164	    {
165	      robot_proactive_drop(event, "cooldown");
166	      return;
167	    }
168	
169	  if (event->type >= 0 && event->type < ROBOT_EVENT_TYPE_COUNT &&
170	      state.last_event_type_ms[event->type] != 0 &&
171	      now_ms - state.last_event_type_ms[event->type] <
172	        (event->type >= ROBOT_EVENT_MUSIC_STARTED &&
173	         event->type <= ROBOT_EVENT_MUSIC_STOPPED ?
174	         ROBOT_PROACTIVE_MUSIC_COOLDOWN_MS : ROBOT_PROACTIVE_COOLDOWN_MS))
175	    {
176	      robot_proactive_drop(event, "event-cooldown");
177	      return;
178	    }
179	
180	  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
181	      event->created_ms != 0 && now_ms >= event->created_ms &&
182	      now_ms - event->created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS)
183	    {
184	      robot_proactive_drop(event, "stale");
185	      return;
186	    }
187	
188	  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
189	      (state.conversation_active || state.motion_active || state.tts_active))
190	    {
191	      robot_proactive_drop(event, "robot-busy");
192	      return;
193	    }
194	
195	  if (event->type == ROBOT_EVENT_MANUAL_TEST)
196	    {
197	      /* Manual tests intentionally bypass scenario-specific predicates. */
198	    }
199	  else if (event->type == ROBOT_EVENT_IDLE_LONG)
200	    {
201	      if (!state.user_has_interacted)
202	        {
203	          robot_proactive_drop(event, "no-user-activity");
204	          return;
205	        }
206	      if (state.idle_event_fired)
207	        {
208	          robot_proactive_drop(event, "already-fired");
209	          return;
210	        }
211	      if (now_ms - state.last_user_activity_ms < ROBOT_PROACTIVE_IDLE_MS &&
212	          strcmp(event->detail, "manual diagnostic trigger") != 0)
213	        {
214	          robot_proactive_drop(event, "not-idle");
215	          return;
216	        }
217	    }
218	  else if (event->type == ROBOT_EVENT_USER_ACTIVITY)
219	    {
220	      robot_proactive_drop(event, "state-only-event");
221	      return;
222	    }
223	  else if (event->type < ROBOT_EVENT_MUSIC_STARTED ||
224	           event->type > ROBOT_EVENT_MEAL_WINDOW)
225	    {
226	      robot_proactive_drop(event, "unknown-type");
227	      return;
228	    }
229	
230	  printf("[ROBOT-PROACTIVE] accept id=%u type=%s\n",
231	         event->id, robot_event_type_name(event->type));
232	  ret = robot_proactive_send_to_agent(event, &state);
233	  if (ret < 0)
234	    {
235	      printf("[ROBOT-PROACTIVE] inbound failed id=%u rc=%d\n",
236	             event->id, ret);
237	    }
238	  else
239	    {
240	      robot_world_state_note_proactive(event->id, event->type);
241	    }
242	}
243	
244	static void *robot_proactive_worker(void *arg)
245	{
246	  (void)arg;
247	
248	  printf("[ROBOT-PROACTIVE] worker started stack=%u queue=%u\n",
249	         ROBOT_PROACTIVE_STACK_SIZE, ROBOT_PROACTIVE_QUEUE_DEPTH);
250	  while (true)
251	    {
252	      struct robot_event_s event;
253	      bool have_event = false;
254	      struct timespec deadline;
255	      struct robot_world_state_s state;
256	
257	      pthread_mutex_lock(&g_proactive.lock);
258	      if (g_proactive.stop_requested)
259	        {
260	          pthread_mutex_unlock(&g_proactive.lock);
261	          break;
262	        }
263	
264	      if (g_proactive.count > 0)
265	        {
266	          event = g_proactive.queue[g_proactive.head];
267	          g_proactive.head = (g_proactive.head + 1) %
268	                             ROBOT_PROACTIVE_QUEUE_DEPTH;
269	          g_proactive.count--;
270	          have_event = true;
271	        }
272	      else
273	        {
274	          robot_proactive_realtime_after_ms(&deadline, 1000);
275	          pthread_cond_timedwait(&g_proactive.cond, &g_proactive.lock,
276	                                 &deadline);
277	        }
278	      pthread_mutex_unlock(&g_proactive.lock);
279	
280	      if (have_event)
280	      if (have_event)
281	        {
282	          robot_proactive_process(&event);
283	          continue;
284	        }
285	
286	      if (robot_world_state_snapshot(&state) == 0 && state.initialized &&
287	          state.proactive_enabled && state.user_has_interacted &&
288	          robot_world_state_try_queue_idle(robot_proactive_monotonic_ms(),
289	                                           ROBOT_PROACTIVE_IDLE_MS,
290	                                           ROBOT_PROACTIVE_COOLDOWN_MS))
291	        {
292	          if (robot_proactive_post(ROBOT_EVENT_IDLE_LONG,
293	                                   "user inactive for the configured idle interval") < 0)
294	            {
295	              robot_world_state_cancel_idle_queue();
296	            }
297	        }
298	    }
299	
300	  pthread_mutex_lock(&g_proactive.lock);
301	  g_proactive.started = false;
302	  pthread_mutex_unlock(&g_proactive.lock);
303	  printf("[ROBOT-PROACTIVE] worker stopped\n");
304	  return NULL;
305	}
306	
307	int robot_proactive_init(void)
308	{
309	  pthread_mutex_lock(&g_proactive.lock);
310	  if (!g_proactive.initialized)
311	    {
312	      g_proactive.initialized = true;
313	      g_proactive.next_event_id = 1;
314	      g_proactive.stop_requested = false;
315	    }
316	  pthread_mutex_unlock(&g_proactive.lock);
317	  return robot_world_state_init();
318	}
319	
320	int robot_proactive_start(void)
321	{
322	  int ret;
323	  pthread_attr_t attr;
324	
325	  robot_proactive_init();
326	  pthread_mutex_lock(&g_proactive.lock);
327	  if (g_proactive.started)
328	    {
329	      pthread_mutex_unlock(&g_proactive.lock);
330	      return 0;
331	    }
332	  g_proactive.stop_requested = false;
333	  pthread_mutex_unlock(&g_proactive.lock);
334	
335	  ret = pthread_attr_init(&attr);
336	  if (ret != 0)
337	    {
338	      return -ret;
339	    }
340	  ret = pthread_attr_setstacksize(&attr, ROBOT_PROACTIVE_STACK_SIZE);
341	  if (ret == 0)
342	    {
343	      ret = pthread_create(&g_proactive.thread, &attr,
344	                           robot_proactive_worker, NULL);
345	    }
346	  pthread_attr_destroy(&attr);
347	  if (ret != 0)
348	    {
349	      printf("[ROBOT-PROACTIVE] start failed rc=%d\n", ret);
350	      return -ret;
351	    }
352	
353	  pthread_mutex_lock(&g_proactive.lock);
354	  g_proactive.started = true;
355	  pthread_mutex_unlock(&g_proactive.lock);
356	  return 0;
357	}
358	
359	int robot_proactive_stop(void)
360	{
361	  pthread_t thread;
362	  bool started;
363	
364	  pthread_mutex_lock(&g_proactive.lock);
365	  started = g_proactive.started;
366	  thread = g_proactive.thread;
367	  g_proactive.stop_requested = true;
368	  pthread_cond_broadcast(&g_proactive.cond);
369	  pthread_mutex_unlock(&g_proactive.lock);
370	  if (started)
371	    {
372	      return -pthread_join(thread, NULL);
373	    }
374	  return 0;
375	}
376	
377	int robot_proactive_post_ex(enum robot_event_type_e type, const char *source,
378	                            const char *detail,
379	                            const struct robot_event_payload_s *payload)
380	{
381	  struct robot_event_s *event;
382	  uint32_t event_id;
383	
384	  if (type < 0 || type >= ROBOT_EVENT_TYPE_COUNT)
385	    {
386	      return -EINVAL;
387	    }
388	
389	  pthread_mutex_lock(&g_proactive.lock);
390	  if (!g_proactive.initialized || g_proactive.count >= ROBOT_PROACTIVE_QUEUE_DEPTH)
391	    {
392	      pthread_mutex_unlock(&g_proactive.lock);
393	      printf("[ROBOT-EVENT] drop type=%s reason=queue-full-or-uninitialized\n",
394	             robot_event_type_name(type));
395	      return -EAGAIN;
396	    }
397	
398	  event = &g_proactive.queue[g_proactive.tail];
399	  memset(event, 0, sizeof(*event));
400	  event->id = g_proactive.next_event_id++;
401	  event->type = type;
402	  event->created_ms = robot_proactive_monotonic_ms();
403	  event->priority = type == ROBOT_EVENT_IDLE_LONG ? 1 : 0;
404	  strncpy(event->source, source != NULL ? source : "manual",
405	          sizeof(event->source) - 1);
406	  event->source[sizeof(event->source) - 1] = '\0';
407	  if (detail != NULL)
408	    {
409	      strncpy(event->detail, detail, sizeof(event->detail) - 1);
410	    }
411	  if (payload != NULL)
412	    {
413	      event->payload = *payload;
414	    }
415	  g_proactive.tail = (g_proactive.tail + 1) % ROBOT_PROACTIVE_QUEUE_DEPTH;
416	  g_proactive.count++;
417	  event_id = event->id;
418	  pthread_cond_signal(&g_proactive.cond);
419	  pthread_mutex_unlock(&g_proactive.lock);
420	
421	  printf("[ROBOT-EVENT] post id=%u type=%s\n",
422	         event_id, robot_event_type_name(type));
423	  return 0;
424	}
425	
426	int robot_proactive_post(enum robot_event_type_e type, const char *detail)
427	{
428	  return robot_proactive_post_ex(type, "manual", detail, NULL);
429	}
