431	int robot_proactive_music_update(enum robot_music_state_e music_state,
432	                                 const char *track, const char *category,
433	                                 const char *mood, uint16_t tempo_bpm)
434	{
435	  struct robot_world_state_s before;
436	  struct robot_event_payload_s payload;
437	  enum robot_event_type_e type;
438	  bool changed = false;
439	  int ret;
440	
441	  if (robot_world_state_snapshot(&before) < 0)
442	    {
443	      return -EAGAIN;
444	    }
445	  ret = robot_world_state_update_music(music_state, track, category, mood,
446	                                       tempo_bpm, &changed);
447	  if (ret < 0 || !changed)
448	    {
449	      return ret;
450	    }
451	
452	  if (music_state == ROBOT_MUSIC_PLAYING)
453	    {
454	      type = before.music_playing ? ROBOT_EVENT_MUSIC_CHANGED :
455	                                    ROBOT_EVENT_MUSIC_STARTED;
456	    }
457	  else
458	    {
459	      type = ROBOT_EVENT_MUSIC_STOPPED;
460	    }
461	
462	  memset(&payload, 0, sizeof(payload));
463	  payload.kind = ROBOT_EVENT_PAYLOAD_MUSIC;
464	  payload.data.music.state = music_state;
465	  payload.data.music.tempo_bpm = tempo_bpm;
466	  strncpy(payload.data.music.track, track != NULL ? track : "",
467	          sizeof(payload.data.music.track) - 1);
468	  strncpy(payload.data.music.category, category != NULL ? category : "",
469	          sizeof(payload.data.music.category) - 1);
470	  strncpy(payload.data.music.mood, mood != NULL ? mood : "",
471	          sizeof(payload.data.music.mood) - 1);
472	  return robot_proactive_post_ex(type, "music", "music state changed",
473	                                 &payload);
474	}
