 20	static uint64_t robot_world_monotonic_ms(void)
 21	{
 22	  struct timespec ts;
 23	
 24	  clock_gettime(CLOCK_MONOTONIC, &ts);
 25	  return (uint64_t)ts.tv_sec * 1000ULL +
 26	         (uint64_t)ts.tv_nsec / 1000000ULL;
 27	}
