 36	      g_world.proactive_enabled = true;
 37	      g_world.boot_ms = robot_world_monotonic_ms();
 38	      g_world.last_user_activity_ms = g_world.boot_ms;
 39	      printf("[ROBOT-WORLD] initialized boot_ms=%llu enabled=1\n",
 40	             (unsigned long long)g_world.boot_ms);
 41	    }
 42	  pthread_mutex_unlock(&g_world_lock);
 43	  return 0;
 44	}
