110	int robot_world_state_update_music(enum robot_music_state_e state,
111	                                   const char *track, const char *category,
112	                                   const char *mood, uint16_t tempo_bpm,
113	                                   bool *changed)
114	{
115	  uint64_t now_ms = robot_world_monotonic_ms();
116	  bool local_changed;
117	
118	  if (state < ROBOT_MUSIC_UNKNOWN || state > ROBOT_MUSIC_STOPPED)
119	    {
120	      return -EINVAL;
121	    }
122	
123	  pthread_mutex_lock(&g_world_lock);
124	  robot_world_state_ensure_locked(now_ms);
125	  local_changed = g_world.music_playing != (state == ROBOT_MUSIC_PLAYING) ||
126	                  g_world.music_tempo_bpm != tempo_bpm ||
127	                  strncmp(g_world.music_track, track != NULL ? track : "",
128	                          sizeof(g_world.music_track)) != 0 ||
129	                  strncmp(g_world.music_category,
130	                          category != NULL ? category : "",
131	                          sizeof(g_world.music_category)) != 0 ||
132	                  strncmp(g_world.music_mood, mood != NULL ? mood : "",
133	                          sizeof(g_world.music_mood)) != 0;
134	  if (local_changed)
135	    {
136	      g_world.music_playing = state == ROBOT_MUSIC_PLAYING;
137	      g_world.music_tempo_bpm = tempo_bpm;
138	      strncpy(g_world.music_track, track != NULL ? track : "",
139	              sizeof(g_world.music_track) - 1);
140	      strncpy(g_world.music_category, category != NULL ? category : "",
141	              sizeof(g_world.music_category) - 1);
142	      strncpy(g_world.music_mood, mood != NULL ? mood : "",
143	              sizeof(g_world.music_mood) - 1);
144	      g_world.music_track[sizeof(g_world.music_track) - 1] = '\0';
145	      g_world.music_category[sizeof(g_world.music_category) - 1] = '\0';
146	      g_world.music_mood[sizeof(g_world.music_mood) - 1] = '\0';
147	      g_world.last_music_update_ms = now_ms;
148	    }
149	  pthread_mutex_unlock(&g_world_lock);
150	  if (changed != NULL)
151	    {
152	      *changed = local_changed;
153	    }
154	  return 0;
155	}
