157	void robot_world_state_note_proactive(uint32_t event_id,
158	                                      enum robot_event_type_e type)
159	{
160	  pthread_mutex_lock(&g_world_lock);
161	  g_world.last_proactive_ms = robot_world_monotonic_ms();
162	  g_world.last_event_id = event_id;
163	  if (type >= 0 && type < ROBOT_EVENT_TYPE_COUNT)
164	    {
165	      g_world.last_event_type_ms[type] = g_world.last_proactive_ms;
166	    }
167	  g_world.last_processed_event_id = event_id;
168	  if (type == ROBOT_EVENT_IDLE_LONG)
169	    {
170	      g_world.idle_event_fired = true;
171	    }
172	  g_world.idle_event_pending = false;
173	  pthread_mutex_unlock(&g_world_lock);
174	}
175	
176	bool robot_world_state_try_queue_idle(uint64_t now_ms, uint64_t idle_ms,
177	                                      uint64_t cooldown_ms)
178	{
179	  bool accept = false;
180	
181	  pthread_mutex_lock(&g_world_lock);
182	  if (g_world.initialized && g_world.proactive_enabled &&
183	      g_world.user_has_interacted && !g_world.idle_event_fired &&
184	      !g_world.idle_event_pending &&
185	      now_ms - g_world.last_user_activity_ms >= idle_ms &&
186	      (g_world.last_proactive_ms == 0 ||
187	       now_ms - g_world.last_proactive_ms >= cooldown_ms))
188	    {
189	      g_world.idle_event_pending = true;
190	      accept = true;
191	    }
