+ */
+static const char *const g_cli_working_phrases[] =
+{
+  "\xE6\xAD\xA3\xE5\x9C\xA8\xE6\x80\x9D\xE8\x80\x83\xE4\xB8\xAD\x2E\x2E\x2E",
