 54	static int robot_music_observer_read_status(
 55	    enum robot_observed_music_state_e *state, char *track, size_t track_size)
 56	{
 57	  char output[ROBOT_MUSIC_STATUS_SIZE];
 58	  cJSON *root;
 59	  cJSON *state_json;
 60	  cJSON *url_json;
 61	  const char *state_text;
 62	  const char *url_text;
 63	
 64	  if (state == NULL || track == NULL || track_size == 0)
 65	    {
 66	      return -EINVAL;
 67	    }
 68	
 69	  memset(output, 0, sizeof(output));
 70	  if (tool_music_status_execute("{}", output, sizeof(output)) < 0)
 71	    {
 72	      return -EIO;
 73	    }
 74	
 75	  root = cJSON_Parse(output);
 76	  if (root == NULL)
 77	    {
 78	      return -EINVAL;
 79	    }
 80	
 81	  state_json = cJSON_GetObjectItem(root, "state");
 82	  state_text = cJSON_GetStringValue(state_json);
 83	  url_json = cJSON_GetObjectItem(root, "url");
 84	  url_text = cJSON_GetStringValue(url_json);
 85	  track[0] = '\0';
 86	
 87	  if (state_text != NULL && strcmp(state_text, "PLAYING") == 0)
 88	    {
 89	      *state = ROBOT_OBSERVED_MUSIC_PLAYING;
 90	    }
 91	  else if (state_text != NULL && strcmp(state_text, "PAUSED") == 0)
 92	    {
 93	      *state = ROBOT_OBSERVED_MUSIC_PAUSED;
 94	    }
 95	  else
 96	    {
 97	      *state = ROBOT_OBSERVED_MUSIC_STOPPED;
 98	    }
 99	
100	  if (url_text != NULL)
101	    {
102	      snprintf(track, track_size, "%s", url_text);
103	    }
104	
105	  cJSON_Delete(root);
106	  return 0;
107	}
