109	static void robot_music_observer_sample(void)
110	{
111	  enum robot_observed_music_state_e observed;
112	  enum robot_observed_music_state_e previous;
113	  char track[64];
114	  char previous_track[64];
115	  bool report_playing;
116	  bool report_stopped;
117	
118	  if (robot_music_observer_read_status(&observed, track, sizeof(track)) < 0)
119	    {
120	      return;
121	    }
122	
123	  pthread_mutex_lock(&g_music_observer.lock);
124	  previous = g_music_observer.last_state;
125	  snprintf(previous_track, sizeof(previous_track), "%s",
126	           g_music_observer.last_track);
127	  g_music_observer.last_state = observed;
128	  if (observed == ROBOT_OBSERVED_MUSIC_PLAYING)
129	    {
130	      snprintf(g_music_observer.last_track,
131	               sizeof(g_music_observer.last_track), "%s", track);
132	    }
133	  else if (observed == ROBOT_OBSERVED_MUSIC_STOPPED)
134	    {
135	      g_music_observer.last_track[0] = '\0';
136	    }
137	  pthread_mutex_unlock(&g_music_observer.lock);
138	
139	  report_playing = observed == ROBOT_OBSERVED_MUSIC_PLAYING;
140	  report_stopped = observed == ROBOT_OBSERVED_MUSIC_STOPPED &&
141	                   (previous == ROBOT_OBSERVED_MUSIC_PLAYING ||
142	                    previous == ROBOT_OBSERVED_MUSIC_PAUSED);
143	
144	  if (report_playing)
145	    {
146	      /* PAUSED is state-only: keep the last confirmed track without waking
147	       * the Agent, then let PLAYING resume be observed normally. */
148	      if (previous != ROBOT_OBSERVED_MUSIC_PLAYING ||
149	          strcmp(previous_track, track) != 0)
150	        {
151	          printf("[ROBOT-MUSIC] official status PLAYING track_changed=%d\n",
152	                 strcmp(previous_track, track) == 0 ? 0 : 1);
153	        }
154	      (void)robot_proactive_music_update(ROBOT_MUSIC_PLAYING, track,
155	                                         "", "", 0);
156	    }
157	  else if (report_stopped)
158	    {
159	      printf("[ROBOT-MUSIC] official status STOPPED\n");
160	      (void)robot_proactive_music_update(ROBOT_MUSIC_STOPPED, "", "", "", 0);
161	    }
162	}
