164	static void *robot_music_observer_worker(void *arg)
165	{
166	  (void)arg;
167	
168	  printf("[ROBOT-MUSIC] observer started interval_ms=%u\n",
169	         ROBOT_MUSIC_POLL_MS);
170	  while (true)
171	    {
172	      struct timespec ts;
173	
174	      robot_music_observer_sample();
175	      pthread_mutex_lock(&g_music_observer.lock);
176	      if (g_music_observer.stop_requested)
177	        {
178	          pthread_mutex_unlock(&g_music_observer.lock);
179	          break;
180	        }
181	      clock_gettime(CLOCK_REALTIME, &ts);
182	      ts.tv_sec += ROBOT_MUSIC_POLL_MS / 1000;
183	      ts.tv_nsec += (ROBOT_MUSIC_POLL_MS % 1000) * 1000000L;
184	      if (ts.tv_nsec >= 1000000000L)
185	        {
186	          ts.tv_sec++;
187	          ts.tv_nsec -= 1000000000L;
188	        }
189	      pthread_cond_timedwait(&g_music_observer.cond,
190	                             &g_music_observer.lock, &ts);
191	      if (g_music_observer.stop_requested)
192	        {
193	          pthread_mutex_unlock(&g_music_observer.lock);
194	          break;
195	        }
196	      pthread_mutex_unlock(&g_music_observer.lock);
197	    }
198	
199	  pthread_mutex_lock(&g_music_observer.lock);
200	  g_music_observer.started = false;
201	  pthread_mutex_unlock(&g_music_observer.lock);
202	  printf("[ROBOT-MUSIC] observer stopped\n");
203	  return NULL;
204	}
