206	int robot_music_observer_start(void)
207	{
208	  pthread_attr_t attr;
209	  int ret;
210	
211	  pthread_mutex_lock(&g_music_observer.lock);
212	  if (g_music_observer.started)
213	    {
214	      pthread_mutex_unlock(&g_music_observer.lock);
215	      return 0;
216	    }
217	  g_music_observer.stop_requested = false;
218	  g_music_observer.last_state = ROBOT_OBSERVED_MUSIC_UNKNOWN;
219	  g_music_observer.last_track[0] = '\0';
220	  pthread_mutex_unlock(&g_music_observer.lock);
221	
222	  ret = pthread_attr_init(&attr);
223	  if (ret == 0)
224	    {
225	      ret = pthread_attr_setstacksize(&attr, 8192);
226	      if (ret == 0)
227	        {
228	          ret = pthread_create(&g_music_observer.thread, &attr,
229	                               robot_music_observer_worker, NULL);
230	        }
231	      pthread_attr_destroy(&attr);
232	    }
233	  if (ret != 0)
234	    {
235	      printf("[ROBOT-MUSIC] observer start failed rc=%d\n", ret);
236	      return -ret;
237	    }
238	
239	  pthread_mutex_lock(&g_music_observer.lock);
240	  g_music_observer.started = true;
241	  pthread_mutex_unlock(&g_music_observer.lock);
242	  return 0;
243	}
244	
245	int robot_music_observer_stop(void)
246	{
247	  pthread_t thread;
248	  bool started;
249	
250	  pthread_mutex_lock(&g_music_observer.lock);
251	  started = g_music_observer.started;
252	  thread = g_music_observer.thread;
253	  g_music_observer.stop_requested = true;
254	  pthread_cond_broadcast(&g_music_observer.cond);
255	  pthread_mutex_unlock(&g_music_observer.lock);
256	  if (started && !pthread_equal(pthread_self(), thread))
257	    {
258	      return -pthread_join(thread, NULL);
259	    }
260	  return 0;
261	}
