int tool_music_seek_execute(const char* input_json,
    char* output, size_t output_size)
{
    media_ctx_init_once();

    cJSON* root = cJSON_Parse(input_json);
    if (!root) {
        return respond_error(output, output_size,
            "EINVAL_ARG", "Invalid JSON input");
