        {
          want = sizeof(buffer);
        }
      got = fread(buffer, 1, want, file);
      if (got != want)
        {
          printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
                 resource->filename, errno != 0 ? errno : EIO);
          fclose(file);
          return false;
        }
      if (memcmp(buffer, resource->content + offset, got) != 0)
        {
