 55	static int robot_music_observer_read_status(
 56	    enum robot_observed_music_state_e *state, char *track, size_t track_size)
 57	{
 58	  char output[ROBOT_MUSIC_STATUS_SIZE];
 59	  cJSON *root;
 60	  cJSON *state_json;
 61	  cJSON *url_json;
 62	  const char *state_text;
 63	  const char *url_text;
 64	
 65	  if (state == NULL || track == NULL || track_size == 0)
 66	    {
 67	      return -EINVAL;
 68	    }
 69	
 70	  memset(output, 0, sizeof(output));
 71	  if (tool_music_status_execute("{}", output, sizeof(output)) < 0)
 72	    {
 73	      return -EIO;
 74	    }
 75	
 76	  root = cJSON_Parse(output);
 77	  if (root == NULL)
 78	    {
 79	      return -EINVAL;
 80	    }
 81	
 82	  state_json = cJSON_GetObjectItem(root, "state");
 83	  state_text = cJSON_GetStringValue(state_json);
 84	  url_json = cJSON_GetObjectItem(root, "url");
 85	  url_text = cJSON_GetStringValue(url_json);
 86	  track[0] = '\0';
 87	
 88	  if (state_text != NULL && strcmp(state_text, "PLAYING") == 0)
 89	    {
 90	      *state = ROBOT_OBSERVED_MUSIC_PLAYING;
 91	    }
 92	  else if (state_text != NULL && strcmp(state_text, "PAUSED") == 0)
 93	    {
 94	      *state = ROBOT_OBSERVED_MUSIC_PAUSED;
 95	    }
 96	  else
 97	    {
 98	      *state = ROBOT_OBSERVED_MUSIC_STOPPED;
 99	    }
100	
101	  if (url_text != NULL)
102	    {
103	      snprintf(track, track_size, "%s", url_text);
104	    }
105	
106	  cJSON_Delete(root);
107	  return 0;
108	}
