110	static void robot_music_observer_sample(void)
111	{
112	  enum robot_observed_music_state_e observed;
113	  enum robot_observed_music_state_e previous;
114	  char track[64];
115	  char previous_track[64];
116	  bool report_playing;
117	  bool report_stopped;
118	
119	  if (robot_music_observer_read_status(&observed, track, sizeof(track)) < 0)
120	    {
121	      return;
122	    }
123	
124	  pthread_mutex_lock(&g_music_observer.lock);
125	  previous = g_music_observer.last_state;
126	  snprintf(previous_track, sizeof(previous_track), "%s",
127	           g_music_observer.last_track);
128	  g_music_observer.last_state = observed;
129	  if (observed == ROBOT_OBSERVED_MUSIC_PLAYING)
130	    {
131	      snprintf(g_music_observer.last_track,
132	               sizeof(g_music_observer.last_track), "%s", track);
133	    }
134	  else if (observed == ROBOT_OBSERVED_MUSIC_STOPPED)
135	    {
136	      g_music_observer.last_track[0] = '\0';
137	    }
138	  pthread_mutex_unlock(&g_music_observer.lock);
139	
140	  report_playing = observed == ROBOT_OBSERVED_MUSIC_PLAYING;
141	  report_stopped = observed == ROBOT_OBSERVED_MUSIC_STOPPED &&
142	                   (previous == ROBOT_OBSERVED_MUSIC_PLAYING ||
143	                    previous == ROBOT_OBSERVED_MUSIC_PAUSED);
144	
145	  if (report_playing)
146	    {
147	      /* PAUSED is state-only: keep the last confirmed track without waking
148	       * the Agent, then let PLAYING resume be observed normally. */
149	      if (previous != ROBOT_OBSERVED_MUSIC_PLAYING ||
150	          strcmp(previous_track, track) != 0)
151	        {
152	          printf("[ROBOT-MUSIC] official status PLAYING track_changed=%d\n",
153	                 strcmp(previous_track, track) == 0 ? 0 : 1);
154	        }
155	      (void)robot_proactive_music_update(ROBOT_MUSIC_PLAYING, track,
156	                                         "", "", 0);
157	    }
158	  else if (report_stopped)
159	    {
160	      printf("[ROBOT-MUSIC] official status STOPPED\n");
161	      (void)robot_proactive_music_update(ROBOT_MUSIC_STOPPED, "", "", "", 0);
162	    }
163	}
