   132	                 state->music_playing ? 1 : 0, state->music_track,
   133	                 state->music_category, state->music_mood,
   134	                 (unsigned int)state->music_tempo_bpm);
   135	  if (len < 0 || (size_t)len >= sizeof(content))
   136	    {
   137	      return -EOVERFLOW;
   138	    }
   139	
   140	  memset(&msg, 0, sizeof(msg));
   141	  strncpy(msg.channel, AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
   142	  strncpy(msg.chat_id, "robot_proactive", sizeof(msg.chat_id) - 1);
   143	  msg.content = strdup(content);
   144	  if (msg.content == NULL)
   145	    {
   146	      return -ENOMEM;
   147	    }
   148	
   149	  ret = message_bus_push_inbound(&msg);
   150	  if (ret != OK)
   151	    {
   152	      free(msg.content);
   153	      return -EAGAIN;
   154	    }
   155	
   156	  printf("[ROBOT-PROACTIVE] inbound id=%u channel=%s chat_id=%s\n",
   157	         event->id, msg.channel, msg.chat_id);
   158	  return 0;
   159	}
   160	
   161	static void robot_proactive_process(const struct robot_event_s *event)
   162	{
   163	  struct robot_world_state_s state;
   164	  uint64_t now_ms;
   165	  int ret;
   166	
   167	  if (robot_world_state_snapshot(&state) < 0 || !state.initialized)
   168	    {
   169	      robot_proactive_drop(event, "world-unavailable");
   170	      return;
   171	    }
   172	
   173	  if (!state.proactive_enabled)
   174	    {
   175	      robot_proactive_drop(event, "disabled");
   176	      return;
   177	    }
   178	
   179	  now_ms = robot_proactive_monotonic_ms();
   180	  if (event->id <= state.last_processed_event_id)
   181	    {
   182	      robot_proactive_drop(event, "duplicate-event-id");
   183	      return;
   184	    }
   185	
   186	  if (state.last_proactive_ms != 0 &&
   187	      now_ms - state.last_proactive_ms < ROBOT_PROACTIVE_COOLDOWN_MS)
   188	    {
   189	      if (robot_proactive_is_music_event(event->type))
   190	        {
   191	          robot_proactive_defer_music(event, "cooldown");
   192	        }
   193	      else
   194	        {
   195	          robot_proactive_drop(event, "cooldown");
   196	        }
   197	      return;
   198	    }
   199	
   200	  if (event->type >= 0 && event->type < ROBOT_EVENT_TYPE_COUNT &&
   201	      state.last_event_type_ms[event->type] != 0 &&
   202	      now_ms - state.last_event_type_ms[event->type] <
   203	        (event->type >= ROBOT_EVENT_MUSIC_STARTED &&
   204	         event->type <= ROBOT_EVENT_MUSIC_STOPPED ?
   205	         ROBOT_PROACTIVE_MUSIC_COOLDOWN_MS : ROBOT_PROACTIVE_COOLDOWN_MS))
   206	    {
   207	      if (robot_proactive_is_music_event(event->type))
   208	        {
   209	          robot_proactive_defer_music(event, "event-cooldown");
   210	        }
   211	      else
   212	        {
   213	          robot_proactive_drop(event, "event-cooldown");
   214	        }
   215	      return;
   216	    }
   217	
   218	  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
   219	      event->created_ms != 0 && now_ms >= event->created_ms &&
   220	      now_ms - event->created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS)
   221	    {
   222	      robot_proactive_drop(event, "stale");
   223	      return;
   224	    }
   225	
   226	  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
   227	      (state.conversation_active || state.motion_active || state.tts_active))
   228	    {
   229	      if (robot_proactive_is_music_event(event->type))
   230	        {
   231	          robot_proactive_defer_music(event, "robot-busy");
   232	        }
   233	      else
   234	        {
   235	          robot_proactive_drop(event, "robot-busy");
   236	        }
   237	      return;
   238	    }
   239	
   240	  if (event->type == ROBOT_EVENT_MANUAL_TEST)
   241	    {
   242	      /* Manual tests intentionally bypass scenario-specific predicates. */
   243	    }
   244	  else if (event->type == ROBOT_EVENT_IDLE_LONG)
   245	    {
   246	      if (!state.user_has_interacted)
   247	        {
   248	          robot_proactive_drop(event, "no-user-activity");
   249	          return;
   250	        }
   251	      if (state.idle_event_fired)
   252	        {
   253	          robot_proactive_drop(event, "already-fired");
   254	          return;
   255	        }
   256	      if (now_ms - state.last_user_activity_ms < ROBOT_PROACTIVE_IDLE_MS &&
   257	          strcmp(event->detail, "manual diagnostic trigger") != 0)
   258	        {
   259	          robot_proactive_drop(event, "not-idle");
   260	          return;
   261	        }
   262	    }
   263	  else if (event->type == ROBOT_EVENT_USER_ACTIVITY)
   264	    {
   265	      robot_proactive_drop(event, "state-only-event");
   266	      return;
   267	    }
   268	  else if (event->type < ROBOT_EVENT_MUSIC_STARTED ||
   269	           event->type > ROBOT_EVENT_MEAL_WINDOW)
   270	    {
   271	      robot_proactive_drop(event, "unknown-type");
   272	      return;
   273	    }
   274	
   275	  printf("[ROBOT-PROACTIVE] accept id=%u type=%s\n",
   276	         event->id, robot_event_type_name(event->type));
   277	  ret = robot_proactive_send_to_agent(event, &state);
   278	  if (ret < 0)
   279	    {
   280	      printf("[ROBOT-PROACTIVE] inbound failed id=%u rc=%d\n",
   281	             event->id, ret);
   282	    }
   283	  else
   284	    {
   285	      robot_world_state_note_proactive(event->id, event->type);
   286	    }
   287	}
