   289	static void robot_proactive_try_pending_music(void)
   290	{
   291	  struct robot_event_s event;
   292	  struct robot_world_state_s state;
   293	  uint64_t now_ms;
   294	  bool stale;
   295	  bool eligible;
   296	
   297	  pthread_mutex_lock(&g_proactive.lock);
   298	  if (g_proactive.pending_music_valid)
   299	    {
   300	      event = g_proactive.pending_music;
   301	    }
   302	  else
   303	    {
   304	      pthread_mutex_unlock(&g_proactive.lock);
   305	      return;
   306	    }
   307	  pthread_mutex_unlock(&g_proactive.lock);
   308	
   309	  if (robot_world_state_snapshot(&state) < 0 || !state.initialized ||
   310	      !state.proactive_enabled || state.conversation_active ||
   311	      state.motion_active || state.tts_active)
   312	    {
   313	      return;
   314	    }
   315	
   316	  now_ms = robot_proactive_monotonic_ms();
   317	  stale = event.created_ms != 0 && now_ms >= event.created_ms &&
   318	          now_ms - event.created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS;
   319	  eligible = !stale &&
   320	             (state.last_proactive_ms == 0 ||
   321	              now_ms - state.last_proactive_ms >= ROBOT_PROACTIVE_COOLDOWN_MS) &&
   322	             (state.last_event_type_ms[event.type] == 0 ||
   323	              now_ms - state.last_event_type_ms[event.type] >=
   324	                ROBOT_PROACTIVE_MUSIC_COOLDOWN_MS);
   325	  if (!eligible)
   326	    {
   327	      if (stale)
   328	        {
   329	          robot_proactive_drop(&event, "pending-stale");
   330	          pthread_mutex_lock(&g_proactive.lock);
   331	          if (g_proactive.pending_music_valid &&
   332	              g_proactive.pending_music.id == event.id)
   333	            {
   334	              g_proactive.pending_music_valid = false;
   335	            }
   336	          pthread_mutex_unlock(&g_proactive.lock);
   337	        }
   338	      return;
   339	    }
   340	
   341	  pthread_mutex_lock(&g_proactive.lock);
   342	  if (g_proactive.pending_music_valid &&
   343	      g_proactive.pending_music.id == event.id)
   344	    {
   345	      g_proactive.pending_music_valid = false;
   346	      eligible = true;
   347	    }
   348	  else
   349	    {
   350	      eligible = false;
   351	    }
   352	  pthread_mutex_unlock(&g_proactive.lock);
   353	
   354	  if (eligible)
   355	    {
   356	      printf("[ROBOT-PROACTIVE] dispatch deferred music id=%u\n", event.id);
   357	      robot_proactive_process(&event);
   358	    }
   359	}
