   361	static void *robot_proactive_worker(void *arg)
   362	{
   363	  (void)arg;
   364	
   365	  printf("[ROBOT-PROACTIVE] worker started stack=%u queue=%u\n",
   366	         ROBOT_PROACTIVE_STACK_SIZE, ROBOT_PROACTIVE_QUEUE_DEPTH);
   367	  while (true)
   368	    {
   369	      struct robot_event_s event;
   370	      bool have_event = false;
   371	      struct timespec deadline;
   372	      struct robot_world_state_s state;
   373	
   374	      pthread_mutex_lock(&g_proactive.lock);
   375	      if (g_proactive.stop_requested)
   376	        {
   377	          pthread_mutex_unlock(&g_proactive.lock);
   378	          break;
   379	        }
   380	
   381	      if (g_proactive.count > 0)
   382	        {
   383	          event = g_proactive.queue[g_proactive.head];
   384	          g_proactive.head = (g_proactive.head + 1) %
   385	                             ROBOT_PROACTIVE_QUEUE_DEPTH;
   386	          g_proactive.count--;
   387	          have_event = true;
   388	        }
   389	      else
   390	        {
   391	          robot_proactive_realtime_after_ms(&deadline, 1000);
   392	          pthread_cond_timedwait(&g_proactive.cond, &g_proactive.lock,
   393	                                 &deadline);
   394	        }
   395	      pthread_mutex_unlock(&g_proactive.lock);
   396	
   397	      if (have_event)
   398	        {
   399	          robot_proactive_process(&event);
   400	          continue;
   401	        }
   402	
   403	      robot_proactive_try_pending_music();
   404	
   405	      if (robot_world_state_snapshot(&state) == 0 && state.initialized &&
   406	          state.proactive_enabled && state.user_has_interacted &&
   407	          robot_world_state_try_queue_idle(robot_proactive_monotonic_ms(),
   408	                                           ROBOT_PROACTIVE_IDLE_MS,
   409	                                           ROBOT_PROACTIVE_COOLDOWN_MS))
   410	        {
   411	          if (robot_proactive_post(ROBOT_EVENT_IDLE_LONG,
   412	                                   "user inactive for the configured idle interval") < 0)
   413	            {
   414	              robot_world_state_cancel_idle_queue();
   415	            }
   416	        }
   417	    }
   418	
   419	  pthread_mutex_lock(&g_proactive.lock);
   420	  g_proactive.started = false;
   421	  pthread_mutex_unlock(&g_proactive.lock);
   422	  printf("[ROBOT-PROACTIVE] worker stopped\n");
   423	  return NULL;
   424	}
