125	static enum robot_expression_e
126	robot_expression_recompute_locked(uint64_t now_ms, bool *changed)
127	{
128	  unsigned int best_priority = 0;
129	  enum robot_expression_e next = ROBOT_EXPRESSION_IDLE;
130	  unsigned int source;
131	
132	  for (source = 0; source < ROBOT_EXPRESSION_SOURCE_COUNT; source++)
133	    {
134	      struct robot_expression_slot_s *slot = &g_slots[source];
135	
136	      if (!slot->active)
137	        {
138	          continue;
139	        }
140	
141	      if (slot->expires_ms != 0 && slot->expires_ms <= now_ms)
142	        {
143	          printf("[RV-EXPR] expire source=%s expression=%s generation=%u\n",
144	                 robot_expression_source_name(source),
145	                 robot_expression_name(slot->expression),
146	                 slot->generation);
147	          slot->active = false;
148	          slot->generation++;
149	          continue;
150	        }
151	
152	      if (g_source_priority[source] >= best_priority)
153	        {
154	          best_priority = g_source_priority[source];
155	          next = slot->expression;
156	        }
157	    }
158	
159	  *changed = next != g_effective;
160	  if (*changed)
161	    {
162	      g_effective = next;
163	    }
164	
165	  return next;
166	}
