168	static void *robot_expression_worker(void *arg)
169	{
170	  (void)arg;
171	
172	  for (;;)
173	    {
174	      bool changed = false;
175	      bool display_valid;
176	      bool need_submit;
177	      enum robot_expression_e expression;
178	
179	      /*
180	       * Expression expiry does not need a 50 ms scheduler tick.  A slower
181	       * poll substantially reduces SMP scheduling churn while Wi-Fi/audio
182	       * services are active, while still keeping short expressions visually
183	       * responsive (worst-case expiry delay is about 200 ms).
184	       */
185	      usleep(ROBOT_EXPRESSION_POLL_US);
186	
187	      pthread_mutex_lock(&g_expression_lock);
188	      if (g_expression_stop)
189	        {
190	          pthread_mutex_unlock(&g_expression_lock);
191	          break;
192	        }
193	
194	      expression =
195	          robot_expression_recompute_locked(robot_expression_now_ms(),
196	                                            &changed);
197	      display_valid = g_display_valid;
198	      pthread_mutex_unlock(&g_expression_lock);
199	
200	      /*
201	       * If a previous submission failed, retry only after the OLED worker
202	       * reports itself available.  This avoids a 50 ms error-log loop when
203	       * the panel is genuinely unavailable.
204	       */
205	
206	      need_submit =
207	          changed || (!display_valid && robot_oled_is_available());
208	
209	      if (need_submit)
210	        {
211	          (void)robot_expression_submit_display(expression);
212	
213	          if (changed)
214	            {
215	              printf("[RV-EXPR] effective=%s\n",
216	                     robot_expression_name(expression));
217	            }
218	        }
219	    }
220	
221	  return NULL;
222	}
