 28	static enum robot_expression_e robot_expression_from_name(const char *name)
 29	{
 30	  enum robot_expression_e expression;
 31	
 32	  if (name == NULL)
 33	    {
 34	      return ROBOT_EXPRESSION_COUNT;
 35	    }
 36	  for (expression = 0; expression < ROBOT_EXPRESSION_COUNT; expression++)
 37	    {
 38	      if (strcmp(name, robot_expression_name(expression)) == 0)
 39	        {
 40	          return expression;
 41	        }
 42	    }
 43	  return ROBOT_EXPRESSION_COUNT;
 44	}
