 46	static char *robot_expression_tool_get_tools(void)
 47	{
 48	  static const char tools_json[] =
 49	    "[{\"name\":\"robot_set_expression\"," 
 50	    "\"description\":\"" ROBOT_SIDE_EFFECT_TOOL_POLICY
 51	    "Set the robot dog's persistent OLED facial expression. Call it for an explicit "
 52	    "expression request in the current turn; do not claim success unless it returns ok=true.\","
 53	    "\"input_schema\":{\"type\":\"object\",\"properties\":{"
 54	    "\"expression\":{\"type\":\"string\","
 55	    "\"description\":\"The physical OLED expression to display now. Use the exact value requested by the user when it matches an enum value.\","
 56	    "\"enum\":[\"idle\",\"listening\",\"thinking\",\"happy\","
 57	    "\"speaking\",\"error\"]}},\"required\":[\"expression\"]}}]";
