 63	static int robot_expression_tool_execute(const char *name,
 64	                                         const char *input_json,
 65	                                         char *output,
 66	                                         size_t output_size)
 67	{
 68	  cJSON *root;
 69	  cJSON *expression_item;
 70	  const char *expression_name;
 71	  enum robot_expression_e expression;
 72	  int ret;
 73	
 74	  if (name == NULL || input_json == NULL || output == NULL ||
 75	      output_size == 0 || strcmp(name, ROBOT_EXPRESSION_TOOL_NAME) != 0)
 76	    {
 77	      printf("[RV-EXPR-TOOL] execute rejected: invalid arguments/name\n");
 78	      return ERROR;
 79	    }
 80	
 81	  printf("[RV-EXPR-TOOL] execute name=%s input=%s\n", name, input_json);
 82	
 83	  root = cJSON_Parse(input_json);
 84	  if (root == NULL)
 85	    {
 86	      snprintf(output, output_size,
 87	               "{\"ok\":false,\"error\":\"invalid json\"}");
 88	      return ERROR;
 89	    }
 90	
 91	  expression_item = cJSON_GetObjectItem(root, "expression");
 92	  expression_name = cJSON_GetStringValue(expression_item);
 93	  expression = robot_expression_from_name(expression_name);
 94	  if (expression == ROBOT_EXPRESSION_COUNT)
 95	    {
 96	      cJSON_Delete(root);
 97	      snprintf(output, output_size,
 98	               "{\"ok\":false,\"error\":\"unknown expression\"}");
 99	      return ERROR;
100	    }
101	
102	  /*
103	   * Agent-selected expressions are persistent.  duration_ms == 0 means this
104	   * source stays active until the next Agent expression replaces it.
105	   */
106	  printf("[RV-EXPR-TOOL] parsed expression=%s persistent=1\n",
107	         robot_expression_name(expression));
108	
109	  robot_action_guard_begin(ROBOT_ACTION_EXPRESSION,
110	                           ROBOT_EXPRESSION_TOOL_NAME);
111	  ret = robot_expression_set(ROBOT_EXPRESSION_SOURCE_AGENT, expression, 0);
112	  robot_action_guard_end(ROBOT_ACTION_EXPRESSION,
113	                         ROBOT_EXPRESSION_TOOL_NAME, ret);
114	  cJSON_Delete(root);
115	
116	  printf("[RV-EXPR-TOOL] expression_set rc=%d\n", ret);
117	  if (ret < 0)
118	    {
119	      snprintf(output, output_size,
120	               "{\"ok\":false,\"error\":\"expression display unavailable\"}");
121	      return ERROR;
122	    }
123	
124	  snprintf(output, output_size,
125	           "{\"ok\":true,\"expression\":\"%s\",\"persistent\":true}",
126	           robot_expression_name(expression));
127	  return OK;
128	}
