130	#define ROBOT_BOOT_DISPLAY_READY_RETRIES  100
131	#define ROBOT_BOOT_DISPLAY_POLL_US        (10 * 1000)
132	#define ROBOT_BOOT_DISPLAY_SETTLE_US      (250 * 1000)
133	
134	static void robot_expression_boot_latch_idle(void)
135	{
136	  int ret;
137	  int i;
138	  bool ready = false;
139	
140	  /*
141	   * Startup display and runtime expression management are deliberately
142	   * separated.
143	   *
144	   * We briefly start the OLED worker, draw IDLE, wait for the frame to reach
145	   * the SSD1306, then stop the worker.  The panel keeps the last framebuffer,
146	   * so ai_agent reaches its prompt with a naturally lit idle face but no OLED
147	   * or expression background thread remains active while Wi-Fi is brought up.
148	   *
149	   * The first real Agent/voice expression later starts the normal persistent
150	   * runtime workers through robot_expression_init().
151	   */
152	  printf("[RV-EXPR] boot idle display begin\n");
153	
154	  ret = robot_oled_init();
155	  if (ret < 0)
156	    {
157	      printf("[RV-EXPR] boot idle display: oled init failed rc=%d\n", ret);
158	      return;
159	    }
160	
161	  ret = robot_oled_submit(ROBOT_EXPRESSION_IDLE);
162	  if (ret < 0)
163	    {
164	      printf("[RV-EXPR] boot idle display: submit failed rc=%d\n", ret);
165	      (void)robot_oled_stop();
166	      return;
167	    }
168	
169	  for (i = 0; i < ROBOT_BOOT_DISPLAY_READY_RETRIES; i++)
170	    {
171	      if (robot_oled_is_available())
172	        {
173	          ready = true;
174	          break;
175	        }
176	
177	      usleep(ROBOT_BOOT_DISPLAY_POLL_US);
178	    }
179	
180	  if (ready)
181	    {
182	      /*
183	       * Availability means board/plane setup has completed.  Give the worker
184	       * enough time to drain the already queued 128x64 idle frame before
185	       * asking it to exit.
186	       */
187	      usleep(ROBOT_BOOT_DISPLAY_SETTLE_US);
188	      printf("[RV-EXPR] boot idle display latched\n");
189	    }
190	  else
191	    {
192	      printf("[RV-EXPR] boot idle display: worker not ready\n");
193	    }
194	
195	  /*
196	   * robot_oled_stop() does not power the SSD1306 off or clear it, so the last
197	   * idle frame remains visible while the background worker is gone.
198	   */
199	  (void)robot_oled_stop();
200	  printf("[RV-EXPR] boot OLED worker stopped; panel remains latched\n");
201	}
