203	int robot_expression_register_tool(void)
204	{
205	  if (g_robot_expression_tool_registered)
206	    {
207	      return 0;
208	    }
209	
210	  /*
211	   * Register the semantic Tool first.  Do NOT call robot_expression_init()
212	   * here: that would leave the long-lived expression/OLED workers running
213	   * during Wi-Fi bring-up, which previously correlated with the CPU1 panic.
214	   */
215	  tool_registry_register_provider("robot_expression",
216	                                  robot_expression_tool_get_tools,
217	                                  robot_expression_tool_execute);
218	  tool_registry_invalidate();
219	  g_robot_expression_tool_registered = true;
220	  printf("[RV-EXPR] tool provider registered (runtime lazy init)\n");
221	
222	  /*
223	   * Light a stable IDLE face for the completed ai_agent startup, but tear the
224	   * temporary OLED worker back down before returning to the rest of startup.
225	   */
226	  robot_expression_boot_latch_idle();
227	  return 0;
228	}
