 28	static unsigned long long robot_motion_tool_now_ms(void)
 29	{
 30	  struct timespec ts;
 31	
 32	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
 33	    {
 34	      return 0;
 35	    }
 36	
 37	  return (unsigned long long)ts.tv_sec * 1000ULL +
 38	         (unsigned long long)ts.tv_nsec / 1000000ULL;
 39	}
