 62	static int robot_motion_tool_number(cJSON *item, unsigned int minimum,
 63	                                    unsigned int maximum,
 64	                                    unsigned int *value)
 65	{
 66	  double number;
 67	
 68	  if (item == NULL || !cJSON_IsNumber(item) || value == NULL)
 69	    {
 70	      return -EINVAL;
 71	    }
 72	
 73	  number = item->valuedouble;
 74	  if (number < minimum || number > maximum || number != (double)(int)number)
 75	    {
 76	      return -EINVAL;
 77	    }
 78	
 79	  *value = (unsigned int)number;
 80	  return 0;
 81	}
 82	
 83	static int robot_motion_tool_execute(const char *name, const char *input_json,
 84	                                     char *output, size_t output_size)
 85	{
 86	  cJSON *root;
 87	  cJSON *direction_item;
 88	  cJSON *steps_item;
 89	  cJSON *period_item;
 90	  const char *direction_name;
 91	  enum robot_motion_direction_e direction;
 92	  unsigned int steps = ROBOT_MOTION_DEFAULT_STEPS;
 93	  unsigned int period_ms;
 94	  int ret;
 95	
 96	  if (name == NULL || input_json == NULL || output == NULL ||
 97	      output_size == 0 || strcmp(name, ROBOT_MOTION_TOOL_NAME) != 0)
 98	    {
 99	      return ERROR;
100	    }
101	
102	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_ENTER\n",
103	         robot_motion_tool_now_ms());
104	  printf("[ROBOT-MOTION-TOOL] execute input=%s\n", input_json);
105	  root = cJSON_Parse(input_json);
106	  if (root == NULL)
107	    {
108	      snprintf(output, output_size,
109	               "{\"ok\":false,\"error\":\"invalid json\"}");
110	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
111	             robot_motion_tool_now_ms(), -EINVAL);
112	      return ERROR;
113	    }
114	
115	  direction_item = cJSON_GetObjectItem(root, "direction");
116	  direction_name = cJSON_GetStringValue(direction_item);
117	  ret = robot_motion_direction_from_name(direction_name, &direction);
118	  if (ret < 0)
119	    {
120	      cJSON_Delete(root);
121	      snprintf(output, output_size,
122	               "{\"ok\":false,\"error\":\"invalid direction\"}");
123	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
124	             robot_motion_tool_now_ms(), -EINVAL);
125	      return ERROR;
126	    }
127	
128	  period_ms = robot_motion_default_period(direction);
129	  steps_item = cJSON_GetObjectItem(root, "steps");
130	  if (steps_item != NULL &&
131	      robot_motion_tool_number(steps_item, ROBOT_MOTION_MIN_STEPS, 1,
132	                               &steps) < 0)
133	    {
134	      cJSON_Delete(root);
135	      snprintf(output, output_size,
136	               "{\"ok\":false,\"error\":\"steps must be 1\"}");
137	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
138	             robot_motion_tool_now_ms(), -EINVAL);
139	      return ERROR;
140	    }
141	
142	  period_item = cJSON_GetObjectItem(root, "period_ms");
143	  if (period_item != NULL &&
144	      robot_motion_tool_number(period_item, ROBOT_MOTION_MIN_PERIOD,
145	                               ROBOT_MOTION_MAX_PERIOD, &period_ms) < 0)
146	    {
147	      cJSON_Delete(root);
148	      snprintf(output, output_size,
149	               "{\"ok\":false,\"error\":\"period_ms must be 800..3000\"}");
150	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
151	             robot_motion_tool_now_ms(), -EINVAL);
152	      return ERROR;
153	    }
154	
155	  printf("[ROBOT-MOTION-TOOL] power-safe synchronous execution\n");
156	  printf("[ROBOT-MOTION-TOOL] direction=%s steps=%u period_ms=%u\n",
157	         direction_name, steps, period_ms);
158	  direction_name = robot_motion_direction_name(direction);
159	  cJSON_Delete(root);
160	  robot_action_guard_begin(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME);
161	  robot_world_state_set_motion_active(true);
162	  ret = robot_motion_submit_and_wait(
163	    ROBOT_MOTION_SOURCE_AGENT, direction, steps, period_ms,
164	    robot_motion_default_timeout(steps, period_ms), NULL);
165	  robot_world_state_set_motion_active(false);
166	  robot_action_guard_end(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME,
167	                         ret);
168	
169	  if (ret < 0)
170	    {
171	      if (ret == -EBUSY)
172	        {
173	          snprintf(output, output_size,
174	                   "{\"ok\":false,\"error\":\"motion_busy\"}");
175	        }
176	      else
177	        {
178	          snprintf(output, output_size,
179	                   "{\"ok\":false,\"error\":\"motion unavailable\","
180	                   "\"rc\":%d}", ret);
181	        }
182	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
183	             robot_motion_tool_now_ms(), ret);
184	      return ERROR;
185	    }
186	
187	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
188	         robot_motion_tool_now_ms(), ret);
189	  printf("[ROBOT-MOTION-TOOL] completed rc=%d\n", ret);
190	  snprintf(output, output_size,
191	           "{\"ok\":true,\"completed\":true,\"direction\":\"%s\","
192	           "\"steps\":%u,\"period_ms\":%u}", direction_name, steps,
193	           period_ms);
194	  return OK;
195	}
