static pthread_t g_robot_runtime_bootstrap_thread;
static bool g_robot_runtime_bootstrap_valid;

static void *robot_runtime_bootstrap_worker(void *arg)
{
  (void)arg;

  /*
   * voice_channel_init() is called before the official Agent loop starts.
   * Keep contest background workers out of the Agent's first heap/pool
   * initialization window.  The semantic Tool providers remain registered
   * synchronously, while their active workers start after boot settles.
   */
  sleep(ROBOT_RUNTIME_BOOTSTRAP_DELAY_S);

  if (robot_proactive_init() < 0 || robot_proactive_start() < 0)
    {
      printf("[contest_voice] proactive runtime unavailable\n");
    }

  if (robot_music_observer_start() < 0)
    {
      printf("[contest_voice] official music observer unavailable\n");
    }

  printf("[contest_voice] deferred proactive runtime started\n");
  g_robot_runtime_bootstrap_valid = false;
  return NULL;
}

static int robot_runtime_bootstrap_start(void)
{
  pthread_attr_t attr;
  int ret;

  if (g_robot_runtime_bootstrap_valid)
    {
      return 0;
    }

  ret = pthread_attr_init(&attr);
  if (ret == 0)
    {
      ret = pthread_attr_setstacksize(&attr, ROBOT_RUNTIME_BOOTSTRAP_STACK);
      if (ret == 0)
        {
          ret = pthread_create(&g_robot_runtime_bootstrap_thread, &attr,
                               robot_runtime_bootstrap_worker, NULL);
        }
      pthread_attr_destroy(&attr);
    }

  if (ret != 0)
    {
      printf("[contest_voice] deferred proactive start failed rc=%d\n", ret);
      return -ret;
    }

  g_robot_runtime_bootstrap_valid = true;
  printf("[contest_voice] deferred proactive runtime scheduled delay_s=%u\n",
