/**
 * JSON ok response with state.
 */

static int respond_ok_state(char* output, size_t output_size,
    const char* extra)
{
    if (extra) {
        snprintf(output, output_size,
            "{\"ok\":true,\"state\":\"%s\",%s}",
            state_str(g_media.state), extra);
    } else {
        snprintf(output, output_size,
            "{\"ok\":true,\"state\":\"%s\"}",
            state_str(g_media.state));
    }

    return OK;
}

