#define RV_EVENT_COMPLETED           6

typedef void (*rv_media_event_callback)(void *cookie, int event, int result,
                                        const char *extra);

struct rv_media_player;

struct rv_media_event
{
  rv_media_event_callback callback;
  void *cookie;
  int event;
  int result;
};

struct rv_media_player
{
