}

static int rv_mp3_sink(char **buffer, int offset, int datend, int *buflen,
                       void *arg)
{
  struct rv_mp3_decoder *decoder = arg;

  (void)buffer;
  (void)buflen;
  if (!decoder || offset < 0 || datend < offset)
    {
      return -EINVAL;
    }

  return rv_mp3_decode(decoder, (const unsigned char *)*buffer + offset,
