#include <nuttx/config.h>
#include <unistd.h>
#include <uv.h>

#include <lvgl/lvgl.h>

static void lv_nuttx_uv_loop(uv_loop_t* loop, lv_nuttx_result_t* result) {
    lv_nuttx_uv_t uv_info;
    void* data;

    uv_loop_init(loop);

    lv_memset(&uv_info, 0, sizeof(uv_info));
    uv_info.loop = loop;
    uv_info.disp = result->disp;
    uv_info.indev = result->indev;
#ifdef CONFIG_UINPUT_TOUCH
    uv_info.uindev = result->utouch_indev;
#endif

    data = lv_nuttx_uv_init(&uv_info);
    uv_run(loop, UV_RUN_DEFAULT);
    lv_nuttx_uv_deinit(&data);
}

#include "music_player2.h"

int main(int argc, FAR char* argv[]) {
    // Initialize LVGL
    lv_nuttx_dsc_t info;
    lv_nuttx_result_t result;
    uv_loop_t ui_loop;
    lv_memset(&ui_loop, 0, sizeof(uv_loop_t));

    if (lv_is_initialized()) {
        LV_LOG_ERROR("LVGL already initialized! aborting.");
        return -1;
    }

    lv_init();

    lv_nuttx_dsc_init(&info);
    lv_nuttx_init(&info, &result);

    if (result.disp == NULL) {
        LV_LOG_ERROR("lv_demos initialization failure!");
        return 1;
    }

    splash_screen_create();

    lv_nuttx_uv_loop(&ui_loop, &result);

    lv_nuttx_deinit(&result);
    lv_deinit();

    return 0;
}

--- README ---
# music_player2

music_player2是一个嵌入式音乐播放器，基于 openvela 系统设计。提供 UI 界面，支持音频播放、播放列表管理、启动页面、音量控制等功能。采用模块化架构设计，易于扩展和维护。

## 目录

- [功能特性](#功能特性)
- [系统要求](#系统要求)
- [项目结构](#项目结构)
- [启动指南](#启动指南)
- [使用指南](#使用指南)
- [自定义指南](#自定义指南)
- [贡献指南](#贡献指南)

## 详细文档

- [故障排除指南](docs/ch/TROUBLESHOOTING.md)
- [技术文档](docs/ch/TECHNICAL.md)
- [更新日志](docs/ch/CHANGELOG.md)

## 功能特性

### 核心功能
- 音频播放控制
- 上一首/下一首切换
- 音量调节控制
- 播放列表管理
- 实时播放进度显示
- 顶部状态栏（时间、日期、Wi-Fi、电池）

### 界面功能
- 启动页面：Logo 动画和加载效果
- 长方形适配：为模拟器长方形屏幕优化
- 音量条：可视化音量控制
- 滚动歌曲信息：长标题自动滚动显示

### 系统功能
- Wi-Fi 网络连接管理
- 完整文件系统集成
- JSON 配置文件管理
- 系统资源实时监控
- 模块化架构设计

## 系统要求

### 硬件要求
支持 ARM 架构的嵌入式设备，具备音频输出和显示功能。

### 软件要求
- **操作系统**：openvela
- **图形库**：LVGL
- **音频库**：NuttX Audio 框架 / 模拟器音频控制器
- **网络**：Wi-Fi 驱动支持

### 开发环境
- **编译器**：arm-none-eabi-gcc
- **构建系统**：Make / NuttX 构建系统
- **调试工具**：ADB
- **主机系统**：Linux
- **模拟器**：QEMU

