   278	static int media_player_on_event_cb(void* udata, int evt, int64_t args)
   279	{
   280	    MediaPlayerContext* ctx = (MediaPlayerContext*)udata;
   281	    AVFrame* out_frame = (AVFrame*)(uintptr_t)args;
   282	    AVFrame* frame;
   283	    uint64_t cnt = 1;
   284	
   285	    MEDIA_DEBUG("audio audio_output event: %d", evt);
   286	
   287	    if (evt < 0) {
   288	        MEDIA_INFO("ctx %p received unlink event form audio_output.", ctx);
   289	        pthread_mutex_lock(&ctx->mutex);
   290	        ctx->audio_output_state = 0;
   291	        write(ctx->event_fd, &cnt, sizeof(cnt));
   292	        pthread_mutex_unlock(&ctx->mutex);
   293	        return 0;
   294	    }
   295	
   296	    frame = media_player_queue_pop(ctx, AVMEDIA_TYPE_AUDIO);
   297	    if (!frame) {
   298	        pthread_mutex_lock(&ctx->mutex);
   299	        if (ctx->audio_output_state & MEDIA_AUDIO_OUTPUT_XRUN) {
   300	            pthread_mutex_unlock(&ctx->mutex);
   301	            return AVERROR(EAGAIN);
   302	        }
   303	
   304	        ctx->audio_output_state |= MEDIA_AUDIO_OUTPUT_XRUN;
   305	
   306	        if (ctx->audio_output) {
   307	            MEDIA_INFO("player %s xrun, pause audio output.", ctx->name);
   308	            audio_graph_pause(ctx->audio_output);
   309	        }
   310	
   311	        pthread_mutex_unlock(&ctx->mutex);
   312	
   313	        return AVERROR(EAGAIN);
   314	    }
   315	
   316	    av_frame_move_ref(out_frame, frame);
   317	    av_frame_free(&frame);
   318	
   319	    write(ctx->event_fd, &cnt, sizeof(cnt));
   320	
   321	    return 0;
   322	}
