   346	static int media_player_queue_cnt(MediaPlayerContext* ctx, int type)
   347	{
   348	    OutputStream* stream = NULL;
   349	    int count = 0;
   350	
   351	    stream = type == AVMEDIA_TYPE_AUDIO ? ctx->audio_stream : ctx->video_stream;
   352	
   353	    if (!stream)
