   382	
   383	    if (!stream)
   384	        return NULL;
   385	
   386	    pthread_mutex_lock(&ctx->mutex);
   387	    if (ff_framequeue_queued_frames(&stream->queue)) {
   388	        frame = ff_framequeue_take(&stream->queue);
