   377	/**
   378	 * Wait for a specific media event with timeout.
   379	 * Caller must hold g_media.lock. Lock is released during wait
   380	 * to allow the callback to run, then re-acquired.
   381	 *
   382	 * Returns 0 on success (expected event with result >= 0).
   383	 * Returns -1 on timeout, wrong event, or error result.
   384	 */
   385	
   386	static int wait_event(int expected_event, int timeout_ms)
   387	{
   388	    struct timespec ts;
   389	
   390	    clock_gettime(CLOCK_REALTIME, &ts);
   391	    ts.tv_sec += timeout_ms / 1000;
