   187	/* When graph init is executed, this function needs
   188	 * to be called to set link status to eof and to 0
   189	 * when linking.
   190	 */
   191	static void audio_graph_set_links_status(AVFilterGraph* graph, int status)
   192	{
   193	    AVFilterContext* filt;
   194	    int i, j;
   195	
   196	    for (i = 0; i < graph->nb_filters; i++) {
   197	        filt = graph->filters[i];
   198	
   199	        for (j = 0; j < filt->nb_outputs; j++) {
   200	            if (filt->outputs[j]) {
   201	                FilterLinkInternal* li = (FilterLinkInternal*)filt->outputs[j];
   202	                li->status_in = status;
   203	                li->status_out = status;
   204	            }
   205	        }
   206	
   207	        for (j = 0; j < filt->nb_inputs; j++) {
   208	            if (filt->inputs[j]) {
   209	                FilterLinkInternal* li = (FilterLinkInternal*)filt->inputs[j];
   210	                li->status_in = status;
   211	                li->status_out = status;
   212	            }
   213	        }
   214	    }
   215	}
