   396	static inline bool audio_graph_immediate_cmd(const char* cmd)
   397	{
   398	    return strcmp(cmd, "link")
   399	        && strcmp(cmd, "unlink")
   400	        && strcmp(cmd, "map")
   401	        && strcmp(cmd, "pause")
   402	        && strcmp(cmd, "resume");
   403	}
