   405	static MediaCommand* audio_graph_create_command(const char* cmd, const char* arg, char* res, AVFilterContext* filter)
   406	{
   407	    MediaCommand* newcmd = NULL;
   408	    char* cmd_dup = NULL;
   409	    char* arg_dup = NULL;
   410	
   411	    cmd_dup = strdup(cmd);
   412	    if (!cmd_dup)
   413	        return NULL;
   414	
   415	    if (arg) {
   416	        arg_dup = strdup(arg);
   417	        if (!arg_dup) {
   418	            free(cmd_dup);
   419	            return NULL;
   420	        }
   421	    }
   422	
   423	    newcmd = malloc(sizeof(MediaCommand));
   424	    if (!newcmd) {
   425	        free(cmd_dup);
   426	        free(arg_dup);
   427	        return NULL;
   428	    }
   429	
   430	    newcmd->cmd = cmd_dup;
   431	    newcmd->arg = arg_dup;
   432	    newcmd->res = res;
   433	    newcmd->filter = filter;
   434	
   435	    return newcmd;
   436	}
