   438	static void audio_graph_try_touch(MediaGraphPriv* priv)
   439	{
   440	    eventfd_t val = 1;
   441	    write(priv->fd, &val, sizeof(val));
   442	}
   443	
   444	static int audio_graph_queue_command(MediaGraphPriv* priv, AVFilterContext* filter,
   445	    const char* cmd, const char* arg, char* res, int res_len, int flags)
   446	{
   447	    MediaCommand* newcmd = NULL;
   448	    char msg[128];
   449	    int ret = 0;
   450	
   451	    if (audio_graph_immediate_cmd(cmd)) {
   452	        if (!strcmp(cmd, "volume")) {
   453	            snprintf(msg, sizeof(msg), "volume=%.*s", (int)(sizeof(msg) - 8), arg ? arg : "");
   454	            return avfilter_process_command(filter, "set_parameter", msg, res, res_len, 0);
   455	        }
   456	
   457	        return avfilter_process_command(filter, cmd, arg, res, res_len, flags);
   458	    }
   459	
   460	    newcmd = audio_graph_create_command(cmd, arg, res, filter);
   461	    if (!newcmd)
   462	        return -ENOMEM;
   463	
   464	    pthread_mutex_lock(&priv->qlock);
   465	    TAILQ_INSERT_TAIL(&priv->cmdq, newcmd, entries);
   466	    pthread_mutex_unlock(&priv->qlock);
   467	
   468	    audio_graph_try_touch(priv);
   469	
   470	    av_log(NULL, AV_LOG_INFO, "Pending command: %s %s\n", cmd, arg ? arg : "_");
   471	    return ret;
   472	}
   473	
   474	static int audio_graph_dequeue_command(MediaGraphPriv* priv, bool process)
   475	{
   476	    MediaCommand* cmd = NULL;
   477	    int i, j, ret = 0;
   478	
   479	    pthread_mutex_lock(&priv->qlock);
   480	    cmd = TAILQ_FIRST(&priv->cmdq);
   481	    if (!cmd) {
   482	        pthread_mutex_unlock(&priv->qlock);
   483	        return -EAGAIN;
   484	    }
   485	
   486	    if (!process) {
   487	        TAILQ_REMOVE(&priv->cmdq, cmd, entries);
   488	        pthread_mutex_unlock(&priv->qlock);
   489	        goto exit;
   490	    }
   491	    pthread_mutex_unlock(&priv->qlock);
   492	
   493	    av_log(NULL, AV_LOG_INFO, "process %s %s %s\n",
   494	        cmd->filter->name, cmd->cmd, cmd->arg ? cmd->arg : "_");
   495	
   496	    if (!strcmp(cmd->cmd, "link") || !strcmp(cmd->cmd, "map")) {
   497	        for (i = 0; i < cmd->filter->nb_outputs; i++) {
   498	            AVFilterLink* outlink = cmd->filter->outputs[i];
   499	            FilterLinkInternal* li = (FilterLinkInternal*)outlink;
   500	
   501	            if (li->status_in != li->status_out) {
   502	                MEDIA_WARN("%s outlink %d is not EOF synchronized, cmd '%s' pending\n",
   503	                    cmd->filter->name, i, cmd->cmd);
   504	                return -EAGAIN;
   505	            }
   506	
   507	            if (outlink->dst && outlink->dst->nb_outputs > 0) {
   508	                for (j = 0; j < outlink->dst->nb_outputs; j++) {
   509	                    AVFilterLink* dst_outlink = outlink->dst->outputs[j];
   510	                    FilterLinkInternal* dst_li = (FilterLinkInternal*)dst_outlink;
   511	
   512	                    if (dst_li->status_in != dst_li->status_out) {
   513	                        MEDIA_WARN("%s (downstream of %s) outlink %d not EOF synchronized, cmd '%s' pending\n",
   514	                            outlink->dst->name, cmd->filter->name, j, cmd->cmd);
   515	                        return -EAGAIN;
   516	                    }
   517	                }
   518	            }
   519	        }
   520	
   521	        ret = avfilter_process_command(cmd->filter, cmd->cmd, cmd->arg, cmd->res, 0, 0);
   522	        if (ret >= 0) {
   523	            ret = audio_negotiation_trigger(cmd->filter);
   524	            if (ret < 0)
   525	                MEDIA_ERR("Media graph link error after command '%s': %d:%s\n",
   526	                    cmd->cmd, ret, av_err2str(ret));
   527	        }
   528	    } else
   529	        ret = avfilter_process_command(cmd->filter, cmd->cmd, cmd->arg,
   530	            cmd->res, 0, 0);
   531	
   532	    if (ret >= 0)
   533	        audio_graph_try_touch(priv);
   534	
   535	    pthread_mutex_lock(&priv->qlock);
   536	    TAILQ_REMOVE(&priv->cmdq, cmd, entries);
   537	    pthread_mutex_unlock(&priv->qlock);
   538	
   539	exit:
   540	    free(cmd->cmd);
   541	    free(cmd->arg);
   542	    free(cmd);
   543	    return ret;
   544	}
   545	
   546	static int audio_graph_uninit(MediadPlugin* ctx)
   547	{
   548	    MediaGraphPriv* priv = ctx->priv;
   549	    int ret;
   550	
   551	    do {
   552	        ret = audio_graph_dequeue_command(priv, false);
   553	    } while (ret >= 0);
   554	
   555	    avfilter_graph_free(&priv->graph);
   556	    av_freep(&priv->occupied);
   557	
   558	    return 0;
   559	}
