    63	
    64	static void get_blocksize(int fd, FAR struct media_info_s *info)
    65	{
    66	  struct mtd_geometry_s mtdgeo;
    67	  int ret;
    68	
    69	  /* If the underlying driver is an MTD driver, then we should able to get
    70	   * the erase block size from an MTD ioctl call.
    71	   */
    72	
    73	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&mtdgeo));
    74	  if (ret >= 0)
    75	    {
    76	      /* Its an MTD device.  Use its geometry */
    77	
    78	      printf("MTD Geometry:\n");
    79	      printf("  blocksize:    %u\n", (unsigned int)mtdgeo.blocksize);
    80	      printf("  erasesize:    %lu\n", (unsigned long)mtdgeo.erasesize);
    81	      printf("  neraseblocks: %lu\n", (unsigned long)mtdgeo.neraseblocks);
    82	
    83	      info->blocksize = mtdgeo.erasesize;
    84	      info->nblocks   = mtdgeo.neraseblocks;
    85	
    86	      /* Attempt to erase the entire MTD device */
    87	
    88	      ret = ioctl(fd, MTDIOC_BULKERASE, 0);
    89	      if (ret < 0)
    90	        {
    91	          fprintf(stderr, "ERROR: Failed erase the MTD device\n");
    92	        }
    93	    }
    94	
    95	  /* Otherwise, use the configured default.  We have no idea of the size
    96	   * of the media in this case.
    97	   */
    98	
    99	  else
   100	    {
   101	      info->blocksize = CONFIG_EXAMPLES_MEDIA_BLOCKSIZE;
   102	      info->nblocks   = 0;
   103	    }
   104	}
