  1202	static int media_player_start(MediaPlayerContext* ctx)
  1203	{
  1204	    char volume_str[16] = { 0 };
  1205	    int ret = 0;
  1206	
  1207	    if (!ctx->audio_output) {
  1208	        ret = AVERROR(EINVAL);
  1209	        goto err;
  1210	    }
  1211	
  1212	    if (ctx->state != MEDIA_PLAYER_STATE_PREPARED
  1213	        && ctx->state != MEDIA_PLAYER_STATE_PAUSED
  1214	        && ctx->state != MEDIA_PLAYER_STATE_COMPLETED) {
  1215	        ret = AVERROR(EPERM);
  1216	        goto err;
  1217	    }
  1218	
  1219	    media_player_set_avsync_mode(ctx);
  1220	
  1221	    pthread_mutex_lock(&ctx->mutex);
  1222	    if (ctx->audio_stream
  1223	        && ff_framequeue_queued_frames(&ctx->audio_stream->queue)
  1224	            >= ctx->audio_stream->nb_queue_max) {
  1225	        if (ctx->state == MEDIA_PLAYER_STATE_PAUSED)
  1226	            ret = media_player_resume_audio(ctx, false);
  1227	        else
  1228	            ret = media_player_start_audio(ctx);
  1229	
  1230	        if (ret >= 0)
  1231	            ctx->audio_output_state |= MEDIA_AUDIO_OUTPUT_STARTED;
  1232	    } else
  1233	        ctx->audio_output_state |= MEDIA_AUDIO_OUTPUT_STARTING;
  1234	
  1235	    pthread_mutex_unlock(&ctx->mutex);
  1236	
  1237	    if (ret < 0) {
  1238	        MEDIA_ERR("audio play/resume failed: %s\n", av_err2str(ret));
  1239	        goto err;
  1240	    }
  1241	
  1242	    snprintf(volume_str, sizeof(volume_str), "%f", ctx->volume);
  1243	    ret = audio_graph_set_parameter(ctx->audio_output, "player_volume", volume_str);
  1244	    if (ret < 0)
  1245	        MEDIA_ERR("audio_graph_set_parameter failed.\n");
  1246	
  1247	    ctx->state = MEDIA_PLAYER_STATE_STARTED;
  1248	    ctx->ts_base = AV_NOPTS_VALUE;
  1249	err:
  1250	    media_player_event_cb(ctx, MEDIA_EVENT_STARTED, ret, NULL);
  1251	    return ret;
  1252	}
