  1906	    }
  1907	
  1908	    pthread_attr_init(&attr);
  1909	    pthread_attr_setstacksize(&attr, CONFIG_MEDIA_PLAYER_STACKSIZE);
  1910	    param.sched_priority = CONFIG_MEDIA_PLAYER_PRIORITY;
  1911	    pthread_attr_setschedparam(&attr, &param);
  1912	    ret = pthread_create(&thread, &attr, media_player_thread, ctx);
  1913	    pthread_attr_destroy(&attr);
