580	int media_player_stop(void *handle)
581	{
582	  struct rv_media_player *player = handle;
583	  pthread_t worker;
584	  bool join_worker;
585	  bool playback_open;
586	
587	  if (!player)
588	    {
589	      return -EINVAL;
590	    }
591	
592	  pthread_mutex_lock(&player->lock);
593	  player->stop_requested = true;
594	  worker = player->worker;
595	  join_worker = player->worker_started;
596	  player->worker_started = false;
597	  pthread_mutex_unlock(&player->lock);
598	
599	  if (join_worker && !pthread_equal(pthread_self(), worker))
600	    {
601	      (void)pthread_join(worker, NULL);
602	    }
603	
604	  pthread_mutex_lock(&player->lock);
605	  playback_open = player->playback_open;
606	  player->playback_open = false;
607	  pthread_mutex_unlock(&player->lock);
608	  if (playback_open)
609	    {
610	      robot_audio_playback_finish();
611	      robot_audio_playback_close();
612	    }
613	
614	  rv_emit_event(player, RV_EVENT_STOPPED, 0);
615	  return 0;
