MediadPlugin* g_media[] = {
#ifdef CONFIG_MEDIA_FOCUS
    &media_focus_plugin,
#endif
#ifdef CONFIG_LIB_FFMPEG
    &audio_graph_plugin,
    &media_session_plugin,
    &media_player_plugin,
