int voice_asr_set_backend(const char *name)
{
  if (!name || strcmp(name, "mimo-v2.5-asr") != 0)
    {
      return -ENOENT;
    }

  strncpy(g_voice_asr_backend, name, sizeof(g_voice_asr_backend) - 1);
  g_voice_asr_backend[sizeof(g_voice_asr_backend) - 1] = '\0';
  return 0;
