#include <nuttx/config.h>

#include <errno.h>
#include <syslog.h>

#include <nuttx/audio/audio.h>

#if defined(CONFIG_AUDIO_I2S) && defined(CONFIG_AUDIO_FORMAT_PCM)
#  include <nuttx/audio/audio_i2s.h>
#  include <nuttx/audio/pcm.h>
#endif

#include <arch/board/board.h>

int board_voice_audio_initialize(void)
{
#if defined(CONFIG_DRIVERS_AUDIO) && defined(CONFIG_AUDIO_I2S) && \
    defined(CONFIG_AUDIO_FORMAT_PCM) && defined(CONFIG_CONTEST_BOARD_I2S1_TX)
  struct i2s_dev_s *i2s;
  struct audio_lowerhalf_s *audio_i2s;
  struct audio_lowerhalf_s *pcm;
  int ret;

  i2s = board_voice_speaker_i2s();
  if (i2s == NULL)
    {
      syslog(LOG_ERR, "[BOARD-AUDIO] speaker I2S unavailable\n");
      return -ENODEV;
    }

  audio_i2s = audio_i2s_initialize(i2s, true);
  if (audio_i2s == NULL)
    {
      syslog(LOG_ERR, "[BOARD-AUDIO] audio_i2s_initialize failed\n");
      return -ENODEV;
    }

#ifdef CONFIG_SYSTEM_NXLOOPER
  pcm = audio_i2s;
#else
  pcm = pcm_decode_initialize(audio_i2s);
  if (pcm == NULL)
    {
      syslog(LOG_ERR, "[BOARD-AUDIO] pcm_decode_initialize failed\n");
      return -ENODEV;
    }
#endif

  ret = audio_register("pcm0p", pcm);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[BOARD-AUDIO] register pcm0p failed: %d\n", ret);
      return ret;
    }

  syslog(LOG_INFO, "[BOARD-AUDIO] registered /dev/audio/pcm0p\n");
  return 0;
#else
  return -ENOSYS;
#endif
}

