 ****************************************************************************/

#define MAX_POLLFDS CONFIG_MEDIA_SERVER_MAX_POLLFDS
#define ARRAY_SIZE(x) (sizeof(x) / sizeof((x)[0]))

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct MediaPriv {
    int idx[MAX_POLLFDS];
    struct pollfd fds[MAX_POLLFDS];
    void* ctx[MAX_POLLFDS];
} MediaPriv;

/****************************************************************************
 * Private Data
 ****************************************************************************/
#ifdef CONFIG_MEDIA_FOCUS
