#ifdef CONFIG_MEDIA_TRIGGER
    &media_trigger_plugin,
#endif
    &media_server_plugin,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

MediadPlugin* media_plugin_get(const char* name)
{
    int i;

    for (i = 0; i < ARRAY_SIZE(g_media); i++) {
        if (!strcmp(name, g_media[i]->name))
            return g_media[i];
    }

    return NULL;
}

