132	static int audio_i2s_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
133	                             FAR struct audio_caps_s *caps)
134	{
135	  FAR struct audio_i2s_s *audio_i2s = (FAR struct audio_i2s_s *)dev;
136	  FAR struct i2s_dev_s *i2s = audio_i2s->i2s;
137	
138	  /* Validate the structure */
139	
140	  DEBUGASSERT(caps && caps->ac_len >= sizeof(struct audio_caps_s));
141	  audinfo("type=%d ac_type=%d\n", type, caps->ac_type);
142	
143	  caps->ac_format.hw  = 0;
144	  caps->ac_controls.w = 0;
145	
146	  switch (caps->ac_type)
147	    {
148	      /* Caller is querying for the types of units we support */
149	
150	      case AUDIO_TYPE_QUERY:
151	
152	        /* Provide our overall capabilities.  The interfacing software
153	         * must then call us back for specific info for each capability.
154	         */
155	
156	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
157	          {
158	              /* We don't decode any formats!  Only something above us in
159	               * the audio stream can perform decoding on our behalf.
160	               */
161	
162	              /* The types of audio units we implement */
163	
164	              if (audio_i2s->playback)
165	                {
166	                  caps->ac_controls.b[0] = AUDIO_TYPE_OUTPUT;
167	                }
168	              else
169	                {
170	                  caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
171	                }
172	
173	              caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
174	              break;
175	          }
176	
177	         caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
178	         break;
179	
180	        /* Provide capabilities of our OUTPUT unit */
181	
182	      case AUDIO_TYPE_OUTPUT:
183	      case AUDIO_TYPE_INPUT:
184	
185	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
186	          {
187	            /* Report the Sample rates we support */
188	
189	              caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_DEF_ALL;
190	
191	              caps->ac_channels = 2;
192	
193	              break;
194	          }
195	
196	      default:
197	        I2S_IOCTL(i2s, AUDIOIOC_GETCAPS, (unsigned long)caps);
198	        break;
199	    }
200	
201	  return caps->ac_len;
202	}
