246	            I2S_RXCHANNELS(i2s, nchannels);
247	            I2S_RXDATAWIDTH(i2s, bpsamp);
248	            I2S_RXSAMPLERATE(i2s, samprate);
249	          }
250	        break;
251	
252	      default:
253	        ret = I2S_IOCTL(i2s, AUDIOIOC_CONFIGURE, (unsigned long)caps);
