 21	/**
 22	 * @file
 23	 * NUTTX input and output: output
 24	 *
 25	 * This avdevice encoder can play audio to an NUTTX device.
 26	 *
 27	 * The playback period is set to the lower value available for the device,
 28	 * which gives a low latency suitable for real-time playback.
 29	 */
 30	
 31	#include <poll.h>
 32	
 33	#include "libavformat/internal.h"
 34	#include "libavformat/mux.h"
 35	#include "libavcodec/bsf.h"
