 41	#include "nuttx.h"
 42	
 43	static int nuttx_capbility_query_ranges(struct AVOptionRanges **ranges, void *obj,
 44	                                        const char *key, int flags)
 45	{
 46	    struct AVFormatContext *s1 = obj;
 47	
 48	    return ff_nuttx_capbility_query_ranges(ranges, s1->url, key, flags, true);
 49	}
 50	
 51	static int nuttx_init(struct AVFormatContext *s1)
 52	{
 53	    NuttxPriv *priv = s1->priv_data;
 54	    int ret;
 55	
 56	    ret = ff_nuttx_init(priv, s1->url, true);
 57	    return ret < 0 ? ret : 1;
 58	}
 59	
 60	static void nuttx_deinit(struct AVFormatContext *s1)
 61	{
 62	    NuttxPriv *priv = s1->priv_data;
 63	
 64	    if (priv->lastpkt)
 65	        av_packet_free(&priv->lastpkt);
 66	
 67	    ff_nuttx_deinit(s1->priv_data);
 68	}
 69	
 70	static int nuttx_write_header(AVFormatContext *s1)
 71	{
 72	    NuttxPriv *priv = s1->priv_data;
 73	    AVStream *st = s1->streams[0];
 74	    int ret;
 75	
 76	    if (s1->nb_streams != 1 || s1->streams[0]->codecpar->codec_type != AVMEDIA_TYPE_AUDIO)
 77	        return AVERROR(EINVAL);
 78	
 79	    if (s1->flags & AVFMT_FLAG_NONBLOCK)
 80	        priv->nonblock = true;
 81	
 82	    priv->codec       = st->codecpar->codec_id;
 83	    priv->sample_rate = st->codecpar->sample_rate;
 84	    priv->format      = st->codecpar->format;
 85	    priv->timestamp   = 0;
 86	    av_channel_layout_copy(&priv->ch_layout, &st->codecpar->ch_layout);
 87	
 88	    ret = ff_nuttx_open(s1->priv_data);
 89	    if (ret >= 0)
 90	        avpriv_set_pts_info(st, 64, 1, priv->sample_rate);
 91	
 92	    return ret;
 93	}
 94	
 95	static int nuttx_write_trailer(struct AVFormatContext *s1)
 96	{
 97	    FFStream *const sti = ffstream(s1->streams[0]);
 98	    NuttxPriv *priv = s1->priv_data;
 99	
100	    ff_nuttx_close(priv);
101	    priv->timestamp = 0;
102	    if (sti->bsfc) {
103	        av_bsf_flush(sti->bsfc);
104	        av_bsf_free(&sti->bsfc);
105	        sti->bitstream_checked = 0;
106	    }
107	    return 0;
108	}
109	
110	static int nuttx_write_lastpacket(AVFormatContext *s1)
111	{
112	    NuttxPriv *priv = s1->priv_data;
113	    int ret;
114	
115	    ret = ff_nuttx_write_data(priv, priv->lastpkt->data, priv->lastpkt->size);
116	    if (ret < 0)
117	        return ret;
118	
119	    priv->timestamp += ret / priv->sample_bytes;
120	
121	    priv->lastpkt->data += ret;
122	    priv->lastpkt->size -= ret;
123	    if (priv->lastpkt->size)
124	        return AVERROR(EAGAIN);
125	
126	    av_packet_free(&priv->lastpkt);
127	    return 0;
128	}
129	
130	static int nuttx_write_packet(AVFormatContext *s1, AVPacket *pkt)
131	{
132	    NuttxPriv *priv = s1->priv_data;
133	    int ret;
134	
135	    if (priv->stopped) {
136	        if (priv->lastpkt)
137	            av_packet_free(&priv->lastpkt);
138	        return AVERROR_EOF;
139	    }
140	
141	    if (priv->lastpkt)
142	        return nuttx_write_lastpacket(s1);
143	
144	    if (!pkt)
145	        return 0;
146	
147	    ret = ff_nuttx_write_data(priv, pkt->data, pkt->size);
148	    if (ret < 0)
149	        return ret;
150	
151	    priv->timestamp += ret / priv->sample_bytes;
152	
153	    if (ret != pkt->size) {
154	        priv->lastpkt = av_packet_clone(pkt);
