 700	static uint32_t contest_i2s_dma_setup_rx(
 701	  FAR struct esp32s3_dmadesc_s *desc, uint32_t count,
 702	  FAR uint8_t *buffer, uint32_t bytes)
 703	{
 704	  uint32_t offset = 0;
 705	  uint32_t i;
 706	
 707	  memset(desc, 0, count * sizeof(*desc));
 708	
 709	  for (i = 0; i < count && offset < bytes; i++)
 710	    {
 711	      uint32_t length = bytes - offset;
 712	
 713	      if (length > CONTEST_I2S_RX_DESC_BYTES)
 714	        {
 715	          length = CONTEST_I2S_RX_DESC_BYTES;
 716	        }
 717	
 718	      desc[i].ctrl = ESP32S3_DMA_CTRL_OWN |
 719	                     (length << ESP32S3_DMA_CTRL_BUFLEN_S);
 720	      desc[i].pbuf = buffer + offset;
 721	      offset += length;
 722	      desc[i].next = offset < bytes ? &desc[i + 1] : NULL;
 723	    }
 724	
 725	  return offset;
 726	}
