2074	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
2075	{
2076	  FAR struct contest_i2s_tx_s *priv = arg;
2077	  FAR struct contest_i2s_xfer_s *xfer;
2078	  uint32_t status;
2079	  unsigned int slot;
2080	  unsigned int i;
2081	  bool schedule = false;
2082	  bool fatal = false;
2083	  irqstate_t flags;
2084	
2085	  (void)irq;
2086	  (void)context;
2087	
2088	  /* OUT_DONE is sufficient for the fixed sequential ring. */
2089	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
2090	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
2091	
2092	  if ((status & (DMA_OUT_DONE_CH0_INT_ST |
2093	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
2094	    {
2095	      return OK;
2096	    }
2097	
2098	  flags = spin_lock_irqsave(&priv->lock);
2099	  priv->irq_status = status;
2100	
2101	  if (!priv->streaming || !priv->hw_running)
2102	    {
2103	      spin_unlock_irqrestore(&priv->lock, flags);
2104	      return OK;
2105	    }
2106	
2107	  if ((status & DMA_OUT_DSCR_ERR_CH0_INT_ST) != 0)
2108	    {
2109	      fatal = true;
2110	    }
2111	  else
2112	    {
2113	      /* The descriptor ring is immutable and advances in slot order.  Its
2114	       * payload remains stable until the deferred callback below runs; do not
2115	       * wait one extra ring block and replay stale PCM. */
2116	      if ((status & DMA_OUT_DONE_CH0_INT_ST) != 0)
2117	        {
2118	          priv->done_irq_count++;
2119	
2120	          slot = priv->done_index;
2121	          if (contest_i2s_tx_complete_slot(priv, slot))
2122	            {
2123	              schedule = true;
2124	            }
2125	
2126	          priv->done_index = (slot + 1) % CONTEST_I2S_TX_RING_SLOTS;
2127	          if (slot == CONTEST_I2S_TX_RING_SLOTS - 1)
2128	            {
2129	              priv->ring_wrap_count++;
2130	            }
2131	
2132	          if (priv->done_irq_count <= 8)
2133	            {
2134	              syslog(LOG_INFO,
2135	                     "[C-I2S] tx DONE irq=%lu release=%u next=%u "
2136	                     "queued=%u st=%08lx\n",
2137	                     (unsigned long)priv->done_irq_count, slot,
2138	                     priv->done_index, priv->queued_slots,
2139	                     (unsigned long)status);
2140	            }
2141	        }
2142	
2143	    }
2144	
2145	  if (fatal)
2146	    {
2147	      for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
2148	        {
2149	          xfer = &priv->xfer[i];
2150	          if (xfer->in_use && !xfer->done_queued)
2151	            {
2152	              xfer->result = -EIO;
2153	              xfer->done_queued = true;
2154	              contest_i2s_tx_done_push(priv, xfer);
2155	              schedule = true;
2156	            }
2157	        }
2158	
2159	      priv->queued_slots = 0;
2160	      priv->streaming = false;
2161	      contest_i2s_tx_stop_hw(priv);
2162	    }
2163	
2164	  if (schedule && work_available(&priv->tx_work))
2165	    {
2166	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv,
2167	                 MSEC2TICK(CONTEST_I2S_TX_FIFO_DRAIN_MS));
2168	    }
2169	
2170	  spin_unlock_irqrestore(&priv->lock, flags);
2171	  return OK;
2172	}
