 50	/**
 51	 * @brief Convert ammends to string.
 52	 */
 53	static void pfw_apply_ammends(pfw_vector_t* ammends, char* res, int len)
 54	{
 55	    pfw_criterion_t* criterion;
 56	    pfw_ammend_t* ammend;
 57	    int pos = 0, ret, i;
 58	
 59	    for (i = 0; (ammend = pfw_vector_get(ammends, i)); i++) {
 60	        criterion = ammend->u.criterion;
 61	
 62	        if (ammend->type == PFW_AMMEND_RAW) {
 63	            ret = snprintf(res + pos, len - pos, "%s", ammend->u.raw);
 64	        } else if (ammend->u.criterion->type == PFW_CRITERION_NUMERICAL) {
 65	            ret = snprintf(res + pos, len - pos, "%" PRId32, criterion->state);
 66	        } else {
 67	            ret = pfw_criterion_itoa(criterion, criterion->state,
 68	                res + pos, len - pos);
 69	        }
 70	
 71	        if (ret < 0)
 72	            return;
 73	
 74	        pos += ret;
 75	
 76	        if (pos >= len)
 77	            return;
 78	    }
 79	}
