 47	static void pfw_context_skip_indent(pfw_context_t* ctx)
 48	{
 49	    int space = 0, tab = 0;
 50	
 51	    for (; *(ctx->ptr) != '\0'; ctx->ptr++) {
 52	        if (*(ctx->ptr) == '\t')
 53	            tab++;
 54	        else if (*(ctx->ptr) == ' ')
 55	            space++;
 56	        else
 57	            break;
 58	    }
 59	
 60	    if (space > 0) {
 61	        if (space % 4 != 0 || tab > 0 || ctx->indent == '\t')
 62	            goto err;
 63	
 64	        ctx->indent = ' ';
 65	        ctx->depth = space / 4;
 66	    } else if (tab > 0) {
 67	        if (space > 0 || ctx->indent == ' ')
 68	            goto err;
 69	
 70	        ctx->indent = '\t';
 71	        ctx->depth = tab;
 72	    } else {
 73	        ctx->depth = 0;
 74	    }
 75	
 76	    return;
 77	
 78	err:
 79	    PFW_DEBUG("indent error: %d tab and %d space\n", tab, space);
 80	    ctx->depth = -EINVAL;
 81	}
