 86	
 87	char* pfw_context_take_word(pfw_context_t* ctx)
 88	{
 89	    if (!ctx || !ctx->ptr || *(ctx->ptr) == '\0' || ctx->depth < 0)
 90	        return NULL;
 91	
 92	    return strtok_r(NULL, " \t", &ctx->ptr);
 93	}
 94	
 95	char* pfw_context_take_line(pfw_context_t* ctx)
 96	{
 97	    char* line;
 98	
 99	    if (!ctx || ctx->depth < 0)
100	        return NULL;
101	
102	    line = ctx->ptr;
103	
104	    /* Take indents and skip empty line. */
105	
106	    while (1) {
107	        ctx->ptr = strtok_r(NULL, "\n", &ctx->rest);
108	        if (!ctx->ptr) {
109	            ctx->depth = EOF;
110	            break;
111	        }
112	
113	        pfw_context_skip_indent(ctx);
114	        if (ctx->depth >= 0 && *(ctx->ptr) != '\0')
115	            break;
116	    }
117	
118	    return line;
119	}
