129	pfw_context_t* pfw_context_create(const char* filename)
130	{
131	    pfw_context_t* ctx;
132	    size_t length;
133	    FILE* file;
134	
135	    // read file
136	    file = fopen(filename, "re");
137	    if (!file)
138	        return NULL;
139	
140	    fseek(file, 0, SEEK_END);
141	    length = ftell(file);
142	    if (length < 0)
143	        goto err1;
144	
145	    rewind(file);
146	    ctx = malloc(sizeof(pfw_context_t));
147	    if (!ctx)
148	        goto err1;
149	
150	    memset(ctx, 0, sizeof(pfw_context_t));
151	    ctx->buf = malloc(length + 1);
152	    if (!ctx->buf)
153	        goto err2;
154	
155	    if (fread(ctx->buf, length, 1, file) < 0)
156	        goto err3;
157	
158	    ctx->buf[length] = '\0';
159	    ctx->ptr = strtok_r(ctx->buf, "\n", &ctx->rest);
160	    pfw_context_skip_indent(ctx);
161	    if (ctx->depth >= 0) {
162	        fclose(file);
163	        return ctx;
164	    }
165	
166	err3:
167	    free(ctx->buf);
168	err2:
169	    free(ctx);
170	err1:
171	    fclose(file);
172	    return NULL;
173	}
