 43	/**
 44	 * @brief Check wether leaf node rule matches.
 45	 */
 46	static inline bool pfw_rule_match_atomic(pfw_rule_t* rule)
 47	{
 48	    pfw_interval_t* itv = rule->state.itv;
 49	    int32_t s1 = rule->criterion.p->state;
 50	    int32_t s2 = rule->state.v;
 51	
 52	    switch (rule->predicate) {
 53	    case PFW_PREDICATE_IS:
 54	        return s1 == s2;
 55	
 56	    case PFW_PREDICATE_ISNOT:
 57	        return s1 != s2;
 58	
 59	    case PFW_PREDICATE_INCLUDES:
 60	        return s1 & s2;
 61	
 62	    case PFW_PREDICATE_EXCLUDES:
 63	        return !(s1 & s2);
 64	
 65	    case PFW_PREDICATE_IN:
 66	        return s1 >= itv->left && s1 <= itv->right;
 67	
 68	    case PFW_PREDICATE_NOTIN:
 69	        return s1 < itv->left || s1 > itv->right;
 70	    }
 71	
 72	    return false;
 73	}
