 75	/**
 76	 * @brief Convert literal state to int/bit.
 77	 * @note For ExclusiveCriterion and InclusiveCriterion only.
 78	 */
 79	static int pfw_criterion_atoi_atomic(pfw_criterion_t* criterion,
 80	    const char* value, int32_t* state)
 81	{
 82	    const char* str;
 83	    int i;
 84	
 85	    for (i = 0; (str = pfw_vector_get(criterion->ranges, i)); i++) {
 86	        if (!strcmp(str, value)) {
 87	            if (criterion->type == PFW_CRITERION_EXCLUSIVE)
 88	                *state = i;
 89	            else
 90	                *state |= (1 << i);
 91	            return 0;
 92	        }
 93	    }
 94	
 95	    return -EINVAL;
 96	}
