100	 * @note For ExclusiveCriterion and InclusiveCriterion only.
101	 */
102	static int pfw_criterion_itoa_atomic(pfw_criterion_t* criterion,
103	    int32_t state, char* res, int len, bool first)
104	{
105	    const char* str;
106	
107	    str = pfw_vector_get(criterion->ranges, state);
108	    if (str) {
109	        if (first)
110	            return snprintf(res, len, "%s", str);
111	        else
112	            return snprintf(res, len, "%s%s", PFW_CRITERION_DELIM, str);
113	    }
114	
115	    return -EINVAL;
116	}
