118	static bool pfw_criterion_check_integer(pfw_criterion_t* criterion,
119	    int32_t state)
120	{
121	    char tmp[PFW_CRITERION_MAX_LITERAL];
122	    pfw_interval_t* interval;
123	    int i;
124	
125	    switch (criterion->type) {
126	    case PFW_CRITERION_NUMERICAL:
127	        for (i = 0; (interval = pfw_vector_get(criterion->ranges, i)); i++) {
128	            if (interval->left <= state && state <= interval->right)
129	                return true;
130	        }
131	        return false;
132	
133	    case PFW_CRITERION_EXCLUSIVE:
134	    case PFW_CRITERION_INCLUSIVE:
135	        return pfw_criterion_itoa(criterion, state, tmp, sizeof(tmp))
136	            >= 0;
137	    }
138	
139	    return false;
140	}
