142	/**
143	 * @brief Modify criterion state and auto-save.
144	 */
145	static inline void
146	pfw_criterion_set(void* handle, pfw_criterion_t* criterion, int32_t state)
147	{
148	    char literal[PFW_CRITERION_MAX_LITERAL];
149	    pfw_system_t* system = handle;
150	    pfw_listener_t* listener;
151	    int ret;
152	
153	    if (criterion->state != state) {
154	        criterion->state = state;
155	        ret = pfw_criterion_itoa(criterion, state, literal, PFW_CRITERION_MAX_LITERAL);
156	        LIST_FOREACH(listener, &criterion->listeners, entry)
157	        {
158	            listener->on_change(listener->cookie, criterion->state, ret < 0 ? NULL : literal);
159	        }
160	        if (system->on_save)
161	            system->on_save(system->cookie, pfw_vector_get(criterion->names, 0), state);
162	    }
163	}
