165	/**
166	 * @brief Modify InclusiveCriterion.
167	 */
168	static int pfw_adjust_inclusive(void* handle, const char* name,
169	    const char* value, bool include)
170	{
171	    pfw_system_t* system = handle;
172	    pfw_criterion_t* criterion;
173	    int32_t state;
174	    int ret;
175	
176	    if (!system || !value)
177	        return -EINVAL;
178	
179	    criterion = pfw_criteria_find(system->criteria, name);
180	    if (!criterion)
181	        return -EINVAL;
182	
183	    if (criterion->type != PFW_CRITERION_INCLUSIVE)
184	        return -EPERM;
185	
186	    ret = pfw_criterion_atoi(criterion, value, &state);
187	    if (ret < 0)
188	        return -EINVAL;
189	
190	    if (include)
191	        state = criterion->state | state;
192	    else
193	        state = criterion->state & ~state;
194	
195	    pfw_criterion_set(handle, criterion, state);
196	    return 0;
197	}
