def byte_array(name: str, data: bytes) -> str:
    if not data:
        return f"static const unsigned char {name}[1] = {{ 0 }};\n"

    lines = []
    for offset in range(0, len(data), 12):
        values = ", ".join(f"0x{byte:02x}" for byte in data[offset:offset + 12])
        lines.append(f"  {values},")
    lines[-1] = lines[-1][:-1]
