static void *robot_music_worker(void *arg)
{
  struct robot_music_job_s *job = arg;
  int ret;

  if (job == NULL)
    {
      return NULL;
    }

  printf("[ROBOT-MUSIC] worker start path=%s\n", job->path);
  ret = robot_music_play_file(job->path);

  pthread_mutex_lock(&g_robot_music_lock);
  g_robot_music_last_result = ret;
  g_robot_music_active = false;
  g_robot_music_path[0] = '\0';
  pthread_mutex_unlock(&g_robot_music_lock);

  printf("[ROBOT-MUSIC] worker done rc=%d\n", ret);
  free(job);
  return NULL;
}

static char *robot_music_tool_get_tools(void)
{
  cJSON *tools = NULL;
  cJSON *tool = NULL;
  cJSON *schema = NULL;
  cJSON *properties = NULL;
  cJSON *path = NULL;
  char *json = NULL;

  tools = cJSON_CreateArray();
  tool = cJSON_CreateObject();
  schema = cJSON_CreateObject();
  properties = cJSON_CreateObject();
  path = cJSON_CreateObject();

  if (tools == NULL || tool == NULL || schema == NULL ||
      properties == NULL || path == NULL)
    {
      cJSON_Delete(tools);
      cJSON_Delete(tool);
      cJSON_Delete(schema);
      cJSON_Delete(properties);
      cJSON_Delete(path);
      return NULL;
    }

  cJSON_AddStringToObject(tool, "name", ROBOT_MUSIC_TOOL_NAME);
  cJSON_AddStringToObject(
      tool, "description",
      "Play this robot's local or bundled WAV music through the proven "
      "robot voice speaker path. Use this instead of the official music_play "
      "tool for local playback on this board. Currently supports PCM16LE, "
      "24000 Hz, mono WAV. If path is omitted, plays /etc/media/test.wav.");

  cJSON_AddStringToObject(schema, "type", "object");
  cJSON_AddStringToObject(path, "type", "string");
  cJSON_AddStringToObject(
      path, "description",
      "Absolute local WAV path. Current format must be PCM16LE/24000Hz/mono. "
      "Default: /etc/media/test.wav.");
  cJSON_AddStringToObject(path, "default", ROBOT_MUSIC_DEFAULT_PATH);
  cJSON_AddItemToObject(properties, "path", path);
  path = NULL;
  cJSON_AddItemToObject(schema, "properties", properties);
  properties = NULL;
  cJSON_AddItemToObject(schema, "required", cJSON_CreateArray());
  cJSON_AddItemToObject(tool, "input_schema", schema);
  schema = NULL;
  cJSON_AddItemToArray(tools, tool);
  tool = NULL;

  json = cJSON_PrintUnformatted(tools);
  cJSON_Delete(tools);
  return json;
}

static int robot_music_tool_execute(const char *name,
                                    const char *input_json,
                                    char *output,
                                    size_t output_size)
{
  struct robot_music_job_s *job = NULL;
  cJSON *root = NULL;
  cJSON *path_json;
  const char *path = ROBOT_MUSIC_DEFAULT_PATH;
  pthread_attr_t attr;
  pthread_t thread;
  int fd;
  int ret;

  if (name == NULL || strcmp(name, ROBOT_MUSIC_TOOL_NAME) != 0)
    {
      return ERROR;
    }

  if (output == NULL || output_size == 0)
    {
      return ERROR;
    }

  if (input_json != NULL && input_json[0] != '\0')
    {
      root = cJSON_Parse(input_json);
      if (root == NULL)
        {
          snprintf(output, output_size,
                   "{\"ok\":false,\"error\":\"invalid JSON\"}");
          return ERROR;
        }

      path_json = cJSON_GetObjectItemCaseSensitive(root, "path");
      if (path_json != NULL)
        {
          const char *value = cJSON_GetStringValue(path_json);

          if (value == NULL || value[0] == '\0')
            {
              cJSON_Delete(root);
              snprintf(output, output_size,
                       "{\"ok\":false,\"error\":\"path must be a string\"}");
              return ERROR;
            }

          path = value;
        }
    }

  if (path[0] != '/' || strstr(path, "://") != NULL)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"only absolute local WAV paths are supported\"}");
      return ERROR;
    }

  if (strlen(path) >= ROBOT_MUSIC_PATH_MAX)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"path too long\"}");
      return ERROR;
    }

  /* Fail fast before starting a detached worker.  The WAV format itself is
   * validated by robot_music_play_file() in the worker. */
  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      ret = -errno;
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"open failed\",\"rc\":%d}", ret);
      return ERROR;
    }
  close(fd);

  pthread_mutex_lock(&g_robot_music_lock);
  if (g_robot_music_active)
    {
      char current[ROBOT_MUSIC_PATH_MAX];

      snprintf(current, sizeof(current), "%s", g_robot_music_path);
      pthread_mutex_unlock(&g_robot_music_lock);
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"music already playing\","
               "\"path\":\"%s\"}", current);
      return ERROR;
    }

  job = calloc(1, sizeof(*job));
  if (job == NULL)
    {
      pthread_mutex_unlock(&g_robot_music_lock);
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"out of memory\"}");
      return ERROR;
    }

  snprintf(job->path, sizeof(job->path), "%s", path);
  snprintf(g_robot_music_path, sizeof(g_robot_music_path), "%s", path);
  g_robot_music_active = true;
  g_robot_music_last_result = 0;
  pthread_mutex_unlock(&g_robot_music_lock);
  cJSON_Delete(root);

  ret = pthread_attr_init(&attr);
  if (ret == 0)
    {
      ret = pthread_attr_setstacksize(&attr, ROBOT_MUSIC_WORKER_STACK);
    }
  if (ret == 0)
    {
      ret = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    }
  if (ret == 0)
    {
      ret = pthread_create(&thread, &attr, robot_music_worker, job);
    }
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      pthread_mutex_lock(&g_robot_music_lock);
      g_robot_music_active = false;
      g_robot_music_path[0] = '\0';
      g_robot_music_last_result = -ret;
      pthread_mutex_unlock(&g_robot_music_lock);
      free(job);

      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"worker start failed\",\"rc\":%d}",
               -ret);
      return ERROR;
    }

  snprintf(output, output_size,
           "{\"ok\":true,\"state\":\"PLAYING\",\"path\":\"%s\","
           "\"backend\":\"robot_audio_playback\"}", path);
  printf("[ROBOT-MUSIC] Tool started path=%s\n", path);
  return OK;
}

int robot_music_register_tool(void)
{
  if (g_robot_music_tool_registered)
    {
      return 0;
    }

  tool_registry_register_provider("contest_robot_music",
                                  robot_music_tool_get_tools,
                                  robot_music_tool_execute);

  /* Safe both before and after tool_registry_init(): mark the cached tools
   * JSON dirty, and let the normal registry path rebuild it on demand. */
  tool_registry_invalidate();
  g_robot_music_tool_registered = true;

  printf("[ROBOT-MUSIC] Tool registered name=%s default=%s\n",
         ROBOT_MUSIC_TOOL_NAME, ROBOT_MUSIC_DEFAULT_PATH);
  return 0;
}

static size_t rv_ring_read(struct rv_playback_s *pb,
                           uint8_t *dst, size_t wanted)
{
  size_t n;
  size_t first;

  if (rv_lock(pb) < 0)
    {
      return 0;
    }

  n = pb->ring.count;
  if (n > wanted)
    {
      n = wanted;
    }

  first = RV_RING_BYTES - pb->ring.tail;
  if (first > n)
    {
      first = n;
    }

  if (first > 0)
    {
      memcpy(dst, pb->ring.data + pb->ring.tail, first);
      pb->ring.tail = (pb->ring.tail + first) % RV_RING_BYTES;
      pb->ring.count -= first;
    }

  if (first < n)
    {
      size_t second = n - first;

      memcpy(dst + first, pb->ring.data + pb->ring.tail, second);
      pb->ring.tail = (pb->ring.tail + second) % RV_RING_BYTES;
      pb->ring.count -= second;
    }

  if ((pb->state == RV_STATE_PLAYING || pb->state == RV_STATE_DRAINING) &&
      pb->ring.count < pb->ring_min_play)
    {
      pb->ring_min_play = pb->ring.count;
    }

  rv_unlock(pb);

  if (n > 0)
    {
      nxsem_post(&pb->ring_space);
    }

  return n;
}

static void rv_i2s_done(struct i2s_dev_s *dev,
                        struct ap_buffer_s *apb,
                        void *arg, int result)
{
  struct rv_slot_s *slot = arg;
  struct rv_playback_s *pb;

  (void)dev;
  (void)apb;

  if (slot == NULL || slot->pb == NULL)
    {
      return;
    }

  pb = slot->pb;

  if (rv_lock(pb) == 0)
    {
      slot->result = result;
      slot->inflight = 0;
      slot->done_count++;

      if (result < 0 && result != -ECANCELED && pb->i2s_result >= 0)
        {
          pb->i2s_result = result;
        }

      if (pb->i2s_inflight > 0)
        {
          pb->i2s_inflight--;
        }

      rv_unlock(pb);
    }
  else
    {
      slot->result = result;
      slot->inflight = 0;
      slot->done_count++;

      if (result < 0 && result != -ECANCELED && pb->i2s_result >= 0)
        {
          pb->i2s_result = result;
        }

      if (pb->i2s_inflight > 0)
        {
          pb->i2s_inflight--;
        }
    }

  nxsem_post(&slot->done);
  nxsem_post(&pb->i2s_done);
}

static int rv_wait_slot(struct rv_playback_s *pb,
                        struct rv_slot_s *slot)
{
  int ret;

  if (pb == NULL || slot == NULL)
    {
      return -EINVAL;
    }

  for (;;)
    {
      int inflight;
      int result;

      ret = rv_lock(pb);
      if (ret < 0)
        {
          return ret;
        }

      inflight = slot->inflight;
      result = slot->result;
      rv_unlock(pb);

      if (!inflight)
        {
          if (result < 0 && result != -ECANCELED)
            {
              return result;
            }
          return 0;
        }

      if (pb->stopped)
        {
          return -ECANCELED;
        }

      ret = nxsem_wait_uninterruptible(&slot->done);
      if (ret < 0)
        {
          return ret;
        }
    }
}

static int rv_queue_slot(struct rv_playback_s *pb,
                         struct rv_slot_s *slot,
                         const uint8_t *src, size_t len)
{
  struct audio_buf_desc_s desc;
  struct ap_buffer_s *apb;
  uint8_t *dst;
  size_t frames;
  size_t tx_len;
  size_t i;
  int ret;

  if (pb == NULL || slot == NULL || src == NULL || len == 0 ||
      len > RV_SOURCE_BLOCK_BYTES)
    {
      return -EINVAL;
    }

  len &= ~(size_t)1;
  if (len == 0)
    {
      return -EINVAL;
    }

  frames = len / sizeof(int16_t);
  tx_len = frames * RV_WIRE_BYTES_PER_SAMPLE;
  if (tx_len == 0 || tx_len > RV_WIRE_BLOCK_BYTES)
    {
      return -EINVAL;
    }

  /*
   * Normal blocks keep the proven 2048-byte wire contract.
   *
   * F7P exception: Media may submit one terminal short tail.  Its APB nbytes
   * is the exact converted wire length (for example 512 source bytes become
   * 1024 wire bytes).  contest_i2s shortens that descriptor and terminates
   * the cyclic ring after the real final samples.
   */
  if (RV_WIRE_BLOCK_BYTES != RV_LOWER_DMA_SLOT_BYTES)
    {
      return -EINVAL;
    }

  ret = rv_wait_slot(pb, slot);
  if (ret < 0)
    {
      return ret;
    }

