  ret = nxsem_init(&pb->ring_data, 0, 0);
  if (ret < 0)
    {
      nxsem_destroy(&pb->ring_lock);
      nxsem_destroy(&pb->i2s_done);
      free(pb->ring.data);
      memset(pb, 0, sizeof(*pb));
      return ret;
    }

  ret = nxsem_init(&pb->ring_space, 0, 0);
  if (ret < 0)
    {
      nxsem_destroy(&pb->ring_data);
      nxsem_destroy(&pb->ring_lock);
      nxsem_destroy(&pb->i2s_done);
      free(pb->ring.data);
      memset(pb, 0, sizeof(*pb));
      return ret;
    }

