+          usleep(ROBOT_DANCE_POLL_US);
+        }
+    }
+
+  if (ret >= 0)
+    {
+      (void)robot_dance_return_home(&ctx);
+    }
+  robotctl_servo_close(&ctx);
+
+  pthread_mutex_lock(&g_dance.lock);
+  g_dance.worker_started = false;
+  pthread_mutex_unlock(&g_dance.lock);
+  printf("[DANCE] worker stopped\n");
+  return NULL;
+}
+
+bool robot_music_dance_is_enabled(void)
+{
+  return robot_dance_atomic_enabled();
+}
+
+int robot_music_dance_start(const char *style_name, unsigned int intensity)
+{
+  enum robot_music_dance_style_e style;
+  pthread_attr_t attr;
+  int ret;
+
+  if (intensity < 1 || intensity > 3)
+    {
+      return -EINVAL;
+    }
+
+  if (style_name == NULL || style_name[0] == '\0')
+    {
+      style = ROBOT_DANCE_STYLE_HAPPY;
+    }
+  else
+    {
+      ret = robot_dance_style_from_name(style_name, &style);
+      if (ret < 0)
+        {
+          return ret;
+        }
+    }
+
+  if (!robot_dance_atomic_music_active() && !robot_music_is_playing())
+    {
+      return -EAGAIN;
+    }
+
+  if (robot_motion_is_busy())
+    {
+      return -EBUSY;
+    }
+
+  pthread_mutex_lock(&g_dance.lock);
+  g_dance.style = style;
+  g_dance.intensity = intensity;
+  g_dance.stop_requested = 0;
+  g_dance.enabled = 1;
+  robot_dance_detector_reset();
+
+  if (g_dance.worker_started)
+    {
+      pthread_mutex_unlock(&g_dance.lock);
+      printf("[DANCE] start style=%s intensity=%u\n",
+             robot_dance_style_name(style), intensity);
+      return 0;
+    }
+
+  g_dance.worker_started = true;
+  ret = pthread_attr_init(&attr);
+  if (ret == 0)
+    {
+      ret = pthread_attr_setstacksize(&attr, ROBOT_DANCE_WORKER_STACK);
+    }
+  if (ret == 0)
+    {
+      ret = pthread_create(&g_dance.worker, &attr, robot_dance_worker, NULL);
+    }
+  if (ret == 0)
+    {
+      ret = pthread_detach(g_dance.worker);
+    }
+  pthread_attr_destroy(&attr);
+
+  if (ret != 0)
+    {
+      g_dance.worker_started = false;
+      g_dance.enabled = 0;
+      pthread_mutex_unlock(&g_dance.lock);
+      return ret > 0 ? -ret : ret;
+    }
+
+  pthread_mutex_unlock(&g_dance.lock);
+  printf("[DANCE] start style=%s intensity=%u\n",
+         robot_dance_style_name(style), intensity);
+  return 0;
+}
+
+int robot_music_dance_stop(const char *reason)
+{
+  pthread_t worker;
+  bool started;
+
+  pthread_mutex_lock(&g_dance.lock);
+  started = g_dance.worker_started;
+  worker = g_dance.worker;
+  g_dance.enabled = 0;
+  g_dance.stop_requested = 1;
+  g_dance.music_active = 0;
+  __atomic_store_n(&g_dance.queue_head, 0, __ATOMIC_RELEASE);
+  __atomic_store_n(&g_dance.queue_tail, 0, __ATOMIC_RELEASE);
+  pthread_mutex_unlock(&g_dance.lock);
+
+  if (started && !pthread_equal(pthread_self(), worker))
+    {
+      /* Worker is detached, so wait for its state flag instead of joining. */
+      unsigned int waited = 0;
+      while (__atomic_load_n(&g_dance.worker_started, __ATOMIC_ACQUIRE) &&
+             waited < 3000)
+        {
+          usleep(10000);
+          waited += 10;
+        }
+    }
+
+  if (started)
+    {
+      printf("[DANCE] stop reason=%s\n",
+             reason != NULL ? reason : "requested");
+    }
+  return 0;
+}
+
+void robot_music_dance_music_started(void)
+{
+  pthread_mutex_lock(&g_dance.lock);
+  g_dance.music_active = 1;
+  g_dance.stop_requested = 0;
+  robot_dance_detector_reset();
+  pthread_mutex_unlock(&g_dance.lock);
+  printf("[DANCE] music active\n");
+}
+
+void robot_music_dance_music_stopped(const char *reason)
+{
+  if (robot_dance_atomic_music_active() || robot_dance_atomic_enabled())
+    {
+      (void)robot_music_dance_stop(reason != NULL ? reason : "music_end");
+    }
+  else
+    {
+      __atomic_store_n(&g_dance.music_active, 0, __ATOMIC_RELEASE);
+    }
+}
+
+int robot_music_dance_status(char *output, size_t output_size)
+{
+  enum robot_music_dance_style_e style;
+  unsigned int intensity;
+  bool active;
+  bool enabled;
+  uint32_t beats;
+  uint32_t dropped;
+
+  if (output == NULL || output_size == 0)
+    {
+      return -EINVAL;
+    }
+
+  pthread_mutex_lock(&g_dance.lock);
+  style = g_dance.style;
+  intensity = g_dance.intensity;
+  active = robot_dance_atomic_music_active();
+  enabled = robot_dance_atomic_enabled();
+  beats = g_dance.detected_beats;
+  dropped = g_dance.dropped_beats;
+  pthread_mutex_unlock(&g_dance.lock);
+
+  snprintf(output, output_size,
+           "{\"ok\":true,\"music_active\":%s,\"enabled\":%s,"
+           "\"style\":\"%s\",\"intensity\":%u,\"beats\":%lu,"
+           "\"dropped\":%lu}", active ? "true" : "false",
+           enabled ? "true" : "false", robot_dance_style_name(style),
+           intensity, (unsigned long)beats, (unsigned long)dropped);
+  return 0;
+}
