/*
 * Contest-local music-synchronized dance service.
 *
 * The audio callback performs only bounded energy analysis and a lock-free
 * single-producer/single-consumer queue push.  Servo work always runs on the
 * dedicated dance worker.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "robot_music_dance.h"
#include "robot_action_guard.h"
#include "robot_motion.h"
#include "robotctl_servo.h"
#include "robot_music_player.h"

#define ROBOT_DANCE_QUEUE_CAP          16
#define ROBOT_DANCE_WORKER_STACK       (12 * 1024)
#define ROBOT_DANCE_POLL_US            10000
#define ROBOT_DANCE_MIN_BEAT_MS        190
#define ROBOT_DANCE_MIN_FLOOR          800
#define ROBOT_DANCE_WARMUP_BLOCKS      8

enum robot_music_dance_style_e
{
  ROBOT_DANCE_STYLE_SWAY = 0,
  ROBOT_DANCE_STYLE_BOUNCE,
  ROBOT_DANCE_STYLE_HAPPY,
  ROBOT_DANCE_STYLE_COUNT,
};

struct robot_dance_event_s
{
  uint32_t sequence;
  uint16_t strength;
};

struct robot_music_dance_runtime_s
{
  pthread_mutex_t lock;
  pthread_t worker;
  bool worker_started;
  volatile int music_active;
  volatile int enabled;
  volatile int stop_requested;
  enum robot_music_dance_style_e style;
  unsigned int intensity;

  /* Single-producer (audio callback) / single-consumer (dance worker). */
  volatile uint32_t queue_head;
  volatile uint32_t queue_tail;
  struct robot_dance_event_s queue[ROBOT_DANCE_QUEUE_CAP];

  /* Detector state is owned by the audio callback. */
  uint32_t fast_energy;
  uint32_t slow_energy;
  uint32_t block_count;
  uint64_t last_beat_ms;
  uint32_t detected_beats;
  uint32_t dropped_beats;
};

static struct robot_music_dance_runtime_s g_dance =
{
  .lock = PTHREAD_MUTEX_INITIALIZER,
  .style = ROBOT_DANCE_STYLE_HAPPY,
  .intensity = 1,
};

static uint64_t robot_dance_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000ULL +
         (uint64_t)ts.tv_nsec / 1000000ULL;
}

static const char *robot_dance_style_name(
    enum robot_music_dance_style_e style)
{
  static const char *const names[] =
  {
    "sway", "bounce", "happy"
  };

  return style >= ROBOT_DANCE_STYLE_SWAY &&
         style < ROBOT_DANCE_STYLE_COUNT ? names[style] : "happy";
}

static int robot_dance_style_from_name(const char *name,
                                       enum robot_music_dance_style_e *style)
{
  enum robot_music_dance_style_e candidate;

  if (name == NULL || style == NULL)
    {
      return -EINVAL;
    }

  for (candidate = ROBOT_DANCE_STYLE_SWAY;
       candidate < ROBOT_DANCE_STYLE_COUNT; candidate++)
    {
      if (strcmp(name, robot_dance_style_name(candidate)) == 0)
        {
          *style = candidate;
          return 0;
        }
    }

  return -EINVAL;
}

static void robot_dance_detector_reset(void)
{
  g_dance.fast_energy = 0;
  g_dance.slow_energy = 0;
  g_dance.block_count = 0;
  g_dance.last_beat_ms = 0;
  g_dance.detected_beats = 0;
  g_dance.dropped_beats = 0;
  __atomic_store_n(&g_dance.queue_head, 0, __ATOMIC_RELEASE);
  __atomic_store_n(&g_dance.queue_tail, 0, __ATOMIC_RELEASE);
}

static bool robot_dance_atomic_enabled(void)
{
  return __atomic_load_n(&g_dance.enabled, __ATOMIC_ACQUIRE) != 0;
}

static bool robot_dance_atomic_music_active(void)
{
  return __atomic_load_n(&g_dance.music_active, __ATOMIC_ACQUIRE) != 0;
}

static bool robot_dance_atomic_stop_requested(void)
{
  return __atomic_load_n(&g_dance.stop_requested, __ATOMIC_ACQUIRE) != 0;
}

static bool robot_dance_cancel_check(void *arg)
{
  (void)arg;
  return robot_dance_atomic_stop_requested() ||
         !robot_dance_atomic_music_active() ||
         !robot_dance_atomic_enabled();
}

static void robot_dance_enqueue(uint16_t strength)
{
  uint32_t head;
  uint32_t tail;
  uint32_t next;
  struct robot_dance_event_s *event;

  head = __atomic_load_n(&g_dance.queue_head, __ATOMIC_RELAXED);
  tail = __atomic_load_n(&g_dance.queue_tail, __ATOMIC_ACQUIRE);
  next = (head + 1) % ROBOT_DANCE_QUEUE_CAP;
  if (next == tail)
    {
      g_dance.dropped_beats++;
      return;
    }

  event = &g_dance.queue[head];
  event->sequence = ++g_dance.detected_beats;
  event->strength = strength;
  __atomic_store_n(&g_dance.queue_head, next, __ATOMIC_RELEASE);
}

static bool robot_dance_dequeue(struct robot_dance_event_s *event)
{
  uint32_t head;
  uint32_t tail;
  uint32_t next;

  if (event == NULL)
    {
      return false;
    }

  tail = __atomic_load_n(&g_dance.queue_tail, __ATOMIC_RELAXED);
  head = __atomic_load_n(&g_dance.queue_head, __ATOMIC_ACQUIRE);
  if (tail == head)
    {
      return false;
    }

  *event = g_dance.queue[tail];
  next = (tail + 1) % ROBOT_DANCE_QUEUE_CAP;
  __atomic_store_n(&g_dance.queue_tail, next, __ATOMIC_RELEASE);
  return true;
}

static void robot_dance_analyze_block(const uint8_t *pcm, size_t len,
                                      uint32_t sample_rate)
{
  uint64_t sum = 0;
  size_t samples;
  size_t i;
  uint32_t energy;
  uint32_t novelty;
  uint32_t threshold;
  uint64_t now;
  uint32_t strength;

  if (pcm == NULL || len < sizeof(int32_t) || sample_rate != 24000)
    {
      return;
    }

  len &= ~(sizeof(int32_t) - 1);
  samples = len / sizeof(int32_t);
  if (samples == 0)
    {
      return;
    }

  for (i = 0; i < samples; i++)
    {
      const uint8_t *p = pcm + i * sizeof(int32_t);
      int32_t wire = (int32_t)((uint32_t)p[0] |
                               ((uint32_t)p[1] << 8) |
                               ((uint32_t)p[2] << 16) |
                               ((uint32_t)p[3] << 24));
      int32_t sample = wire >> 16;
      int32_t magnitude = sample < 0 ? -sample : sample;

      sum += (uint32_t)magnitude;
    }

  energy = (uint32_t)(sum / samples);
  g_dance.fast_energy = (g_dance.fast_energy * 3 + energy) / 4;
  g_dance.slow_energy = (g_dance.slow_energy * 31 + energy) / 32;
  g_dance.block_count++;

  if (g_dance.block_count < ROBOT_DANCE_WARMUP_BLOCKS)
    {
      return;
    }

  novelty = g_dance.fast_energy > g_dance.slow_energy ?
            g_dance.fast_energy - g_dance.slow_energy : 0;
  threshold = g_dance.slow_energy / 6;
  if (threshold < 500)
    {
      threshold = 500;
    }

  now = robot_dance_now_ms();
  if (energy < ROBOT_DANCE_MIN_FLOOR || novelty <= threshold ||
      (g_dance.last_beat_ms != 0 &&
       now - g_dance.last_beat_ms < ROBOT_DANCE_MIN_BEAT_MS))
    {
      return;
    }

  g_dance.last_beat_ms = now;
  strength = novelty * 100U / (g_dance.slow_energy + 1U);
  if (strength > 100)
    {
      strength = 100;
    }
  robot_dance_enqueue((uint16_t)strength);
}

void robot_music_dance_on_audio_played(const uint8_t *pcm, size_t len,
                                       uint32_t sample_rate)
{
  if (!robot_dance_atomic_music_active() || !robot_dance_atomic_enabled() ||
      robot_dance_atomic_stop_requested())
    {
      return;
    }

  /* No locks, allocation, waits, or servo calls in the playback callback. */
  robot_dance_analyze_block(pcm, len, sample_rate);
}

static int robot_dance_leg_amplitude(unsigned int intensity)
{
  static const int values[] = { 4, 7, 10 };
  return values[intensity - 1];
}

static int robot_dance_tail_amplitude(unsigned int intensity)
{
  static const int values[] = { 8, 12, 16 };
  return values[intensity - 1];
}

static int robot_dance_target(const struct robot_dance_event_s *event,
                              enum robot_music_dance_style_e style,
                              unsigned int intensity,
                              enum robotctl_servo_e *servo,
                              int *target)
{
  unsigned int phase;
  int leg_amp;
  int tail_amp;
  int offset;
  int base;

  if (event == NULL || servo == NULL || target || intensity < 1 ||
      intensity > 3)
    {
      return -EINVAL;
    }

  phase = (event->sequence - 1) % 8;
  leg_amp = robot_dance_leg_amplitude(intensity);
  tail_amp = robot_dance_tail_amplitude(intensity);

  if (style == ROBOT_DANCE_STYLE_SWAY && (phase & 1) != 0)
    {
      return -EAGAIN;
    }

  if (style == ROBOT_DANCE_STYLE_BOUNCE && (phase & 1) == 0)
    {
      return -EAGAIN;
    }

  switch (phase)
    {
      case 0:
        *servo = ROBOTCTL_TAIL;
        offset = tail_amp;
        break;
      case 1:
        *servo = ROBOTCTL_RF;
        offset = leg_amp;
        break;
      case 2:
        *servo = ROBOTCTL_TAIL;
        offset = -tail_amp;
        break;
      case 3:
        *servo = ROBOTCTL_LR;
        offset = -leg_amp;
        break;
      case 4:
        *servo = ROBOTCTL_LF;
        offset = leg_amp;
        break;
      case 5:
        *servo = ROBOTCTL_RR;
        offset = -leg_amp;
        break;
      case 6:
        *servo = ROBOTCTL_TAIL;
        offset = tail_amp;
        break;
      default:
        *servo = ROBOTCTL_TAIL;
        offset = -tail_amp;
        break;
    }

  base = g_robotctl_home[*servo];
  *target = base + offset;
  return 0;
}

static int robot_dance_apply_event(struct robotctl_servo_ctx_s *ctx,
                                   const struct robot_dance_event_s *event,
                                   enum robot_music_dance_style_e style,
                                   unsigned int intensity)
{
  enum robotctl_servo_e servo;
  int target;
  int ret;

  if (robot_motion_is_busy())
    {
      printf("[DANCE] beat skipped: manual motion active\n");
      return 0;
    }

  ret = robot_dance_target(event, style, intensity, &servo, &target);
  if (ret == -EAGAIN)
    {
      return 0;
    }
  if (ret < 0)
    {
      return ret;
    }

  if (event->sequence <= 3 || event->sequence % 32 == 0)
    {
      printf("[DANCE] beat #%lu strength=%u servo=%s target=%d\n",
             (unsigned long)event->sequence, event->strength,
             robotctl_servo_name(servo), target);
    }

  ret = robotctl_servo_move_one(ctx, servo, target, 12, 35);
  if (ret < 0)
    {
      printf("[DANCE] servo move failed rc=%d\n", ret);
    }
  return ret;
}

static int robot_dance_return_home(struct robotctl_servo_ctx_s *ctx)
{
  enum robotctl_servo_e servo;
  int ret = 0;

  if (ctx == NULL)
    {
      return -EINVAL;
    }

  /* Neutralization is intentional after stop, so disable cancellation. */
  ctx->cancel_check = NULL;
  ctx->cancel_arg = NULL;
  for (servo = ROBOTCTL_RF; servo < ROBOTCTL_SERVO_COUNT; servo++)
    {
      int one = robotctl_servo_move_one(ctx, servo, g_robotctl_home[servo],
                                        18, 40);
      if (one < 0 && ret >= 0)
        {
          ret = one;
        }
    }

  return ret;
}

static void *robot_dance_worker(void *arg)
{
  struct robotctl_servo_ctx_s ctx;
  enum robot_music_dance_style_e style;
  unsigned int intensity;
  int ret;

  (void)arg;
  memset(&ctx, 0, sizeof(ctx));
  ctx.fd = -1;

  ret = robotctl_servo_open(&ctx);
  if (ret < 0)
    {
      printf("[DANCE] servo open failed rc=%d\n", ret);
    }
  else
    {
      ctx.cancel_check = robot_dance_cancel_check;
      ctx.cancel_arg = NULL;
      printf("[DANCE] worker ready\n");
    }

  while (!robot_dance_atomic_stop_requested() &&
         robot_dance_atomic_enabled() && robot_dance_atomic_music_active())
    {
      struct robot_dance_event_s event;

      if (robot_dance_dequeue(&event))
        {
          pthread_mutex_lock(&g_dance.lock);
          style = g_dance.style;
          intensity = g_dance.intensity;
          pthread_mutex_unlock(&g_dance.lock);

          if (ret >= 0)
            {
              ret = robot_dance_apply_event(&ctx, &event, style, intensity);
              if (ret == -ECANCELED)
                {
                  break;
                }
              if (ret < 0)
                {
                  ret = robotctl_servo_open(&ctx);
                  if (ret >= 0)
                    {
                      ctx.cancel_check = robot_dance_cancel_check;
                      ctx.cancel_arg = NULL;
                    }
                }
            }
        }
      else
        {
          usleep(ROBOT_DANCE_POLL_US);
        }
    }

  if (ret >= 0)
    {
      (void)robot_dance_return_home(&ctx);
    }
  robotctl_servo_close(&ctx);

  pthread_mutex_lock(&g_dance.lock);
  g_dance.worker_started = false;
  pthread_mutex_unlock(&g_dance.lock);
  printf("[DANCE] worker stopped\n");
  return NULL;
}

