+static char *robot_music_dance_tool_get_tools(void)
+{
+  static const char tools_json[] =
+    "[{\"name\":\"robot_music_dance\","
+    "\"description\":\"" ROBOT_SIDE_EFFECT_TOOL_POLICY
+    "Start, stop, or query local beat-synchronized dancing while contest "
+    "music playback is active. The service detects beats locally; do not "
+    "call this once per beat. Start music first, then call start.\","
+    "\"input_schema\":{\"type\":\"object\",\"properties\":{"
+    "\"action\":{\"type\":\"string\",\"enum\":[\"start\","
+    "\"stop\",\"status\"]},"
+    "\"style\":{\"type\":\"string\",\"enum\":[\"sway\","
+    "\"bounce\",\"happy\"]},"
+    "\"intensity\":{\"type\":\"integer\",\"minimum\":1,"
+    "\"maximum\":3}},\"required\":[\"action\"]}}]";
+
+  return strdup(tools_json);
+}
+
+static int robot_music_dance_parse_intensity(cJSON *item,
+                                             unsigned int *intensity)
+{
+  double value;
+
+  if (item == NULL || intensity == NULL || !cJSON_IsNumber(item))
+    {
+      return -EINVAL;
+    }
+
+  value = item->valuedouble;
+  if (value < 1 || value > 3 || value != (double)(int)value)
+    {
+      return -EINVAL;
+    }
+
+  *intensity = (unsigned int)value;
+  return 0;
+}
+
+static int robot_music_dance_tool_execute(const char *name,
+                                          const char *input_json,
+                                          char *output,
+                                          size_t output_size)
+{
+  cJSON *root;
+  cJSON *action_json;
+  cJSON *style_json;
+  cJSON *intensity_json;
+  const char *action;
+  const char *style = "happy";
+  unsigned int intensity = 1;
+  int ret;
+
+  if (name == NULL || input_json == NULL || output == NULL ||
+      output_size == 0 || strcmp(name, ROBOT_MUSIC_DANCE_TOOL_NAME) != 0)
+    {
+      return ERROR;
+    }
+
+  root = cJSON_Parse(input_json);
+  if (root == NULL)
+    {
+      snprintf(output, output_size,
+               "{\"ok\":false,\"error\":\"invalid JSON\"}");
+      return ERROR;
+    }
+
+  action_json = cJSON_GetObjectItemCaseSensitive(root, "action");
+  action = cJSON_GetStringValue(action_json);
+  style_json = cJSON_GetObjectItemCaseSensitive(root, "style");
+  if (style_json != NULL)
+    {
+      style = cJSON_GetStringValue(style_json);
+      if (style == NULL)
+        {
+          cJSON_Delete(root);
+          snprintf(output, output_size,
+                   "{\"ok\":false,\"error\":\"style must be a string\"}");
+          return ERROR;
+        }
+    }
+
+  intensity_json = cJSON_GetObjectItemCaseSensitive(root, "intensity");
+  if (intensity_json != NULL &&
+      robot_music_dance_parse_intensity(intensity_json, &intensity) < 0)
+    {
+      cJSON_Delete(root);
+      snprintf(output, output_size,
+               "{\"ok\":false,\"error\":\"intensity must be 1..3\"}");
+      return ERROR;
+    }
+
+  if (action == NULL)
+    {
+      cJSON_Delete(root);
+      snprintf(output, output_size,
+               "{\"ok\":false,\"error\":\"action is required\"}");
+      return ERROR;
+    }
+
+  if (strcmp(action, "status") == 0)
+    {
+      ret = robot_music_dance_status(output, output_size);
+      cJSON_Delete(root);
+      return ret < 0 ? ERROR : OK;
+    }
+
+  robot_action_guard_begin(ROBOT_ACTION_BEHAVIOR,
+                           ROBOT_MUSIC_DANCE_TOOL_NAME);
+  if (strcmp(action, "start") == 0)
+    {
+      ret = robot_music_dance_start(style, intensity);
+    }
+  else if (strcmp(action, "stop") == 0)
+    {
+      ret = robot_music_dance_stop("tool_request");
+    }
+  else
+    {
+      ret = -EINVAL;
+    }
+  robot_action_guard_end(ROBOT_ACTION_BEHAVIOR,
+                         ROBOT_MUSIC_DANCE_TOOL_NAME, ret);
+  cJSON_Delete(root);
+
+  if (ret < 0)
+    {
+      snprintf(output, output_size,
+               "{\"ok\":false,\"error\":\"dance request failed\","
+               "\"rc\":%d}", ret);
+      return ERROR;
+    }
+
+  snprintf(output, output_size,
+           "{\"ok\":true,\"action\":\"%s\"}", action);
+  return OK;
+}
+
+int robot_music_dance_register_tool(void)
+{
+  if (g_robot_music_dance_tool_registered)
+    {
+      return 0;
+    }
+
+  tool_registry_register_provider("robot_music_dance",
+                                  robot_music_dance_tool_get_tools,
+                                  robot_music_dance_tool_execute);
+  tool_registry_invalidate();
+  g_robot_music_dance_tool_registered = true;
+  printf("[DANCE] Tool registered name=%s\n", ROBOT_MUSIC_DANCE_TOOL_NAME);
+  return 0;
+}

