165	static void robot_dance_enqueue(uint16_t strength)
166	{
167	  uint32_t head;
168	  uint32_t tail;
169	  uint32_t next;
170	  struct robot_dance_event_s *event;
171	
172	  head = __atomic_load_n(&g_dance.queue_head, __ATOMIC_RELAXED);
173	  tail = __atomic_load_n(&g_dance.queue_tail, __ATOMIC_ACQUIRE);
174	  next = (head + 1) % ROBOT_DANCE_QUEUE_CAP;
175	  if (next == tail)
176	    {
177	      g_dance.dropped_beats++;
178	      return;
179	    }
180	
181	  event = &g_dance.queue[head];
182	  event->sequence = ++g_dance.detected_beats;
183	  event->strength = strength;
184	  __atomic_store_n(&g_dance.queue_head, next, __ATOMIC_RELEASE);
185	}
