187	static bool robot_dance_dequeue(struct robot_dance_event_s *event)
188	{
189	  uint32_t head;
190	  uint32_t tail;
191	  uint32_t next;
192	
193	  if (event == NULL)
194	    {
195	      return false;
196	    }
197	
198	  tail = __atomic_load_n(&g_dance.queue_tail, __ATOMIC_RELAXED);
199	  head = __atomic_load_n(&g_dance.queue_head, __ATOMIC_ACQUIRE);
200	  if (tail == head)
201	    {
202	      return false;
203	    }
204	
205	  *event = g_dance.queue[tail];
206	  next = (tail + 1) % ROBOT_DANCE_QUEUE_CAP;
207	  __atomic_store_n(&g_dance.queue_tail, next, __ATOMIC_RELEASE);
208	  return true;
209	}
