211	static void robot_dance_analyze_block(const uint8_t *pcm, size_t len,
212	                                      uint32_t sample_rate)
213	{
214	  uint64_t sum = 0;
215	  size_t samples;
216	  size_t i;
217	  uint32_t energy;
218	  uint32_t novelty;
219	  uint32_t threshold;
220	  uint64_t now;
221	  uint32_t strength;
222	
223	  if (pcm == NULL || len < sizeof(int32_t) || sample_rate != 24000)
224	    {
225	      return;
226	    }
227	
228	  len &= ~(sizeof(int32_t) - 1);
229	  samples = len / sizeof(int32_t);
230	  if (samples == 0)
231	    {
232	      return;
233	    }
234	
235	  for (i = 0; i < samples; i++)
236	    {
237	      const uint8_t *p = pcm + i * sizeof(int32_t);
238	      int32_t wire = (int32_t)((uint32_t)p[0] |
239	                               ((uint32_t)p[1] << 8) |
240	                               ((uint32_t)p[2] << 16) |
241	                               ((uint32_t)p[3] << 24));
242	      int32_t sample = wire >> 16;
243	      int32_t magnitude = sample < 0 ? -sample : sample;
244	
245	      sum += (uint32_t)magnitude;
246	    }
247	
248	  energy = (uint32_t)(sum / samples);
249	  g_dance.fast_energy = (g_dance.fast_energy * 3 + energy) / 4;
250	  g_dance.slow_energy = (g_dance.slow_energy * 31 + energy) / 32;
251	  g_dance.block_count++;
252	
253	  if (g_dance.block_count < ROBOT_DANCE_WARMUP_BLOCKS)
254	    {
255	      return;
256	    }
257	
258	  novelty = g_dance.fast_energy > g_dance.slow_energy ?
259	            g_dance.fast_energy - g_dance.slow_energy : 0;
260	  threshold = g_dance.slow_energy / 6;
261	  if (threshold < 500)
262	    {
263	      threshold = 500;
264	    }
265	
266	  now = robot_dance_now_ms();
267	  if (energy < ROBOT_DANCE_MIN_FLOOR || novelty <= threshold ||
268	      (g_dance.last_beat_ms != 0 &&
269	       now - g_dance.last_beat_ms < ROBOT_DANCE_MIN_BEAT_MS))
270	    {

  1	  robot_dance_enqueue((uint16_t)strength);
  2	}
