 31	                              unsigned int intensity,
 32	                              enum robotctl_servo_e *servo,
 33	                              int *target)
 34	{
 35	  unsigned int phase;
 36	  int leg_amp;
 37	  int tail_amp;
 38	  int offset;
 39	  int base;
 40	
 41	  if (event == NULL || servo == NULL || target == NULL || intensity < 1 ||
