 62	    {
 63	      case 0:
 64	        *servo = ROBOTCTL_TAIL;
 65	        offset = tail_amp;
 66	        break;
 67	      case 1:
 68	        *servo = ROBOTCTL_RF;
 69	        offset = leg_amp;
 70	        break;
 71	      case 2:
 72	        *servo = ROBOTCTL_TAIL;
 73	        offset = -tail_amp;
