+/****************************************************************************
+ * Explicit set_wifi/reconnect linker wrappers
+ ****************************************************************************/
+
+/*
+ * These symbols are active only when app/robot_voice/CMakeLists.txt links:
+ *
+ *   -Wl,--wrap=network_wifi_connect
+ *   -Wl,--wrap=network_wifi_reconnect
+ *
+ * The official CLI remains unchanged:
+ *
+ *   set_wifi <ssid> <password>
+ *
+ * but the real-hardware wlan0 sequence is supplied by this contest-local
+ * file.  No packages/ai_agent source is modified.
+ */
+
+int __wrap_network_wifi_connect(const char *iface, const char *ssid,
+                                const char *pass)
+{
+  const char *dev = (iface != NULL && iface[0] != '\0') ? iface : RV_NET_IFACE;
+  int ret;
+
+  if (ssid == NULL || ssid[0] == '\0')
+    {
+      printf("[RV-NET] set_wifi rejected: empty SSID\n");
+      return ERROR;
+    }
+
+  /*
+   * This board-specific fix is only for wlan0.  set_wifi currently passes
+   * iface=NULL, which resolves here to wlan0.
+   */
+  if (strcmp(dev, RV_NET_IFACE) != 0)
+    {
+      printf("[RV-NET] unsupported Wi-Fi iface=%s\n", dev);
+      return ERROR;
+    }
+
+  printf("[RV-NET] explicit connect ssid=%s sequence=mode->essid->psk\n",
+         ssid);
+
+  ret = rv_net_run_connect(ssid, pass);
+  if (ret < 0)
+    {
+      printf("[RV-NET] explicit connect failed rc=%d\n", ret);
+      return ERROR;
+    }
+
+  /*
+   * Preserve the official network_wifi_connect() contract: successful
+   * set_wifi stores credentials for wifi_reconnect / reboot.
+   */
+  (void)agent_config_set(AGENT_CFG_KEY_WIFI_SSID, ssid);
+  (void)agent_config_set(AGENT_CFG_KEY_WIFI_PASS,
+                         (pass != NULL && pass[0] != '\0') ? pass : "");
+
+  printf("[RV-NET] explicit connect complete\n");
+  return OK;
+}
+
+int __wrap_network_wifi_reconnect(void)
+{
+  char ssid[64];
+  char pass[128];
+  int ret;
+
+  ret = rv_net_load_credentials(ssid, sizeof(ssid), pass, sizeof(pass));
+  if (ret < 0)
+    {
+      printf("[RV-NET] reconnect: no saved credentials rc=%d\n", ret);
+      return ERROR;
+    }
+
+  return __wrap_network_wifi_connect(NULL, ssid, pass);
+}
