   101	{
   102	  struct robotctl_servo_ctx_s ctx;
   103	  int ret;
   104	
   105	  if (robot_motion_is_busy())
   106	    {
   107	      fprintf(stderr, "robotctl: motion busy\n");
   108	      return -EBUSY;
   109	    }
   110	
   111	  ret = robotctl_servo_open(&ctx);
   112	  if (ret < 0)
   113	    {
   114	      return ret;
