   122	static int robotctl_single_servo(int argc, char *argv[])
   123	{
   124	  struct robotctl_servo_ctx_s ctx;
   125	  int servo;
   126	  int angle;
   127	  int ret;
   128	
   129	  if (argc != 4)
   130	    {
   131	      fprintf(stderr,
   132	              "robotctl: servo requires <lf|lr|rf|rr|tail> <angle>\n");
   133	      return -EINVAL;
   134	    }
   135	
   136	  servo = robotctl_servo_from_name(argv[2]);
   137	  if (servo < 0 || robotctl_parse_number(argv[3], 0, 180, &angle) < 0)
   138	    {
   139	      fprintf(stderr, "robotctl: invalid servo name or angle 0..180\n");
   140	      return -EINVAL;
   141	    }
   142	
   143	  if (robot_motion_is_busy())
   144	    {
   145	      fprintf(stderr, "robotctl: motion busy\n");
   146	      return -EBUSY;
   147	    }
   148	
   149	  ret = robotctl_servo_open(&ctx);
   150	  if (ret < 0)
   151	    {
   152	      return ret;
   153	    }
   154	
   155	  printf("robotctl: move %s %d -> %d\n", robotctl_servo_name(servo),
   156	         ctx.angle[servo], angle);
   157	  ret = robotctl_servo_move_one(&ctx, servo, angle, 30, 200);
   158	  robotctl_servo_close(&ctx);
   159	  return ret;
