    81	static int robotctl_clamp_angle(int angle)
    82	{
    83	  if (angle < 0)
    84	    {
    85	      return 0;
    86	    }
    87	
    88	  if (angle > 180)
    89	    {
    90	      return 180;
    91	    }
    92	
    93	  return angle;
    94	}
    95	
    96	static ub16_t robotctl_angle_to_duty(int angle)
    97	{
    98	  uint32_t pulse_us;
    99	
   100	  angle = robotctl_clamp_angle(angle);
   101	  pulse_us = ROBOTCTL_SERVO_MIN_US +
   102	             ((ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US) * angle) / 180;
   103	
   104	  return (ub16_t)(((uint64_t)pulse_us << 16) / ROBOTCTL_SERVO_PERIOD_US);
   105	}
   106	
   107	static int robotctl_duty_to_angle(ub16_t duty)
   108	{
   109	  uint32_t pulse_us;
   110	
   111	  pulse_us = ((uint64_t)duty * ROBOTCTL_SERVO_PERIOD_US) >> 16;
   112	  if (pulse_us < ROBOTCTL_SERVO_MIN_US ||
   113	      pulse_us > ROBOTCTL_SERVO_MAX_US)
   114	    {
   115	      return -1;
   116	    }
   117	
   118	  return (int)(((pulse_us - ROBOTCTL_SERVO_MIN_US) * 180) /
   119	               (ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US));
   120	}
   121	
   122	static int robotctl_apply_frame(struct robotctl_servo_ctx_s *ctx,
   123	                                const int angle[ROBOTCTL_SERVO_COUNT],
   124	                                unsigned int active_mask)
   125	{
   126	  struct pwm_info_s info;
   127	  int saved_errno;
   128	  int ret;
   129	  int i;
   130	
   131	  memset(&info, 0, sizeof(info));
   132	  info.frequency = ROBOTCTL_PWM_FREQUENCY;
   133	
   134	  for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
   135	    {
   136	      info.channels[i].channel = i + 1;
   137	      if ((active_mask & (1u << i)) != 0)
   138	        {
   139	          info.channels[i].duty =
   140	            robotctl_angle_to_duty(angle[i] + g_trim[i]);
   141	        }
   142	
   143	      info.channels[i].cpol = PWM_CPOL_NDEF;
   144	      info.channels[i].dcpol = PWM_DCPOL_LOW;
   145	    }
   146	
   147	  ret = ioctl(ctx->fd, PWMIOC_SETCHARACTERISTICS,
   148	              (unsigned long)((uintptr_t)&info));
   149	  if (ret < 0)
   150	    {
   151	      saved_errno = errno;
   152	      fprintf(stderr,
   153	              "robotctl: PWMIOC_SETCHARACTERISTICS failed errno=%d\n",
   154	              saved_errno);
   155	      return -saved_errno;
   156	    }
   157	
   158	  ret = ioctl(ctx->fd, PWMIOC_START, 0);
   159	  if (ret < 0)
   160	    {
   161	      saved_errno = errno;
   162	      fprintf(stderr, "robotctl: PWMIOC_START failed errno=%d\n",
   163	              saved_errno);
   164	      return -saved_errno;
   165	    }
   166	
   167	  ctx->pwm_enabled = true;
   168	  return 0;
   169	}
