   231	int robotctl_servo_open(struct robotctl_servo_ctx_s *ctx)
   232	{
   233	  struct pwm_info_s info;
   234	  int angle;
   235	  int ret;
   236	  int i;
   237	
   238	  ctx->cancel_check = NULL;
   239	  ctx->cancel_arg = NULL;
   240	  memcpy(ctx->angle, g_robotctl_home, sizeof(ctx->angle));
   241	  memcpy(ctx->angle_known, g_servo_runtime.angle_known,
   242	         sizeof(ctx->angle_known));
   243	  for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
   244	    {
   245	      if (ctx->angle_known[i])
   246	        {
   247	          ctx->angle[i] = g_servo_runtime.angle[i];
   248	        }
   249	    }
   250	  ctx->pwm_enabled = false;
   251	  ctx->command_count = 0;
   252	  ctx->skipped_count = 0;
   253	  ctx->total_angle_delta = 0;
   254	  ret = robotctl_servo_open_device(ctx);
   255	  if (ret < 0)
   256	    {
   257	      return ret;
   258	    }
   259	
   260	  memset(&info, 0, sizeof(info));
   261	  if (ioctl(ctx->fd, PWMIOC_GETCHARACTERISTICS,
   262	            (unsigned long)((uintptr_t)&info)) == 0 &&
   263	      info.frequency == ROBOTCTL_PWM_FREQUENCY)
   264	    {
   265	      for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
   266	        {
   267	          angle = robotctl_duty_to_angle(info.channels[i].duty);
   268	          if (angle >= 0)
   269	            {
   270	              ctx->angle[i] = robotctl_clamp_angle(angle - g_trim[i]);
   271	              ctx->angle_known[i] = true;
   272	              g_servo_runtime.angle[i] = ctx->angle[i];
   273	              g_servo_runtime.angle_known[i] = true;
   274	            }
   275	        }
   276	    }
   277	
   278	  return 0;
   279	}
