   281	void robotctl_servo_close(struct robotctl_servo_ctx_s *ctx)
   282	{
   283	  if (ctx->fd >= 0)
   284	    {
   285	      close(ctx->fd);
   286	      ctx->fd = -1;
   287	    }
   288	}
