   290	int robotctl_servo_stop(struct robotctl_servo_ctx_s *ctx, bool announce)
   291	{
   292	  int saved_errno;
   293	  int ret;
   294	
   295	  /* PWMIOC_STOP already removes the output waveform.  Do not send a
   296	   * zero-duty frame here: robotctl_apply_frame() starts PWM after every
   297	   * SETCHARACTERISTICS call, which creates an unnecessary START->STOP cycle
   298	   * during every per-servo move. */
   299	  printf("[ROBOT-SERVO] stop fd=%d pwm=%d\n", ctx->fd,
   300	         ctx->pwm_enabled ? 1 : 0);
   301	  ret = ioctl(ctx->fd, PWMIOC_STOP, 0);
   302	  if (ret < 0)
   303	    {
   304	      saved_errno = errno;
   305	      fprintf(stderr, "robotctl: PWMIOC_STOP failed errno=%d\n",
   306	              saved_errno);
   307	      return -saved_errno;
   308	    }
   309	
   310	  ctx->pwm_enabled = false;
   311	  if (announce)
   312	    {
   313	      printf("robotctl: servo PWM stopped\n");
   314	    }
   315	
   316	  return 0;
   317	}
