   319	int robotctl_servo_move_one(struct robotctl_servo_ctx_s *ctx,
   320	                            enum robotctl_servo_e servo, int target,
   321	                            int interval_ms, int settle_ms)
   322	{
   323	  int frame[ROBOTCTL_SERVO_COUNT];
   324	  int current;
   325	  int next;
   326	  int previous;
   327	  int total_steps;
   328	  int step_index = 0;
   329	  int delay_ms;
   330	  int ret;
   331	
   332	  target = robotctl_clamp_angle(target);
   333	  current = ctx->angle[servo];
   334	  if (ctx->angle_known[servo] && current == target)
   335	    {
   336	      ctx->skipped_count++;
   337	      return 0;
   338	    }
   339	
   340	  if (ctx->fd < 0)
   341	    {
   342	      ret = robotctl_servo_open_device(ctx);
   343	      if (ret < 0)
   344	        {
   345	          return ret;
   346	        }
   347	    }
   348	
   349	  memcpy(frame, ctx->angle, sizeof(frame));
   350	  total_steps = (abs(target - current) + ROBOTCTL_SAFE_STEP_DEG - 1) /
   351	                ROBOTCTL_SAFE_STEP_DEG;
   352	  if (total_steps < 1)
   353	    {
   354	      total_steps = 1;
   355	    }
   356	
   357	  do
   358	    {
   359	      if (robotctl_servo_cancelled(ctx))
   360	        {
   361	          robotctl_servo_stop_and_close(ctx);
   362	          return -ECANCELED;
   363	        }
   364	
   365	      if (current < target)
   366	        {
   367	          next = current + ROBOTCTL_SAFE_STEP_DEG;
   368	          if (next > target)
   369	            {
   370	              next = target;
   371	            }
   372	        }
   373	      else if (current > target)
   374	        {
   375	          next = current - ROBOTCTL_SAFE_STEP_DEG;
   376	          if (next < target)
   377	            {
   378	              next = target;
   379	            }
   380	        }
   381	      else
   382	        {
   383	          next = target;
   384	        }
   385	
   386	      previous = current;
   387	      frame[servo] = next;
   388	      if (step_index == 0)
   389	        {
   390	          printf("[ROBOT-SERVO] first-frame servo=%s fd=%d current=%d "
   391	                 "target=%d\n", robotctl_servo_name(servo), ctx->fd,
   392	                 current, target);
   393	        }
   394	      ret = robotctl_apply_frame(ctx, frame, 1u << servo);
   395	      if (ret < 0)
   396	        {
   397	          robotctl_servo_stop_and_close(ctx);
   398	          return ret;
   399	        }
   400	
   401	      if (step_index == 0)
   402	        {
   403	          printf("[ROBOT-SERVO] first-frame-applied servo=%s\n",
   404	                 robotctl_servo_name(servo));
   405	        }
   406	
   407	      current = next;
   408	      ctx->angle[servo] = next;
   409	      ctx->angle_known[servo] = true;
   410	      g_servo_runtime.angle[servo] = next;
   411	      g_servo_runtime.angle_known[servo] = true;
   412	      ctx->command_count++;
   413	      ctx->total_angle_delta += (unsigned int)abs(next - previous);
   414	      if (current != target)
   415	        {
   416	          step_index++;
   417	          delay_ms = interval_ms;
   418	          if (step_index * 100 < total_steps * ROBOTCTL_RAMP_START_PERCENT)
   419	            {
   420	              delay_ms += interval_ms / 2;
   421	            }
   422	          else if (step_index * 100 >=
   423	                   total_steps * ROBOTCTL_RAMP_END_PERCENT)
   424	            {
   425	              delay_ms += interval_ms / 4;
   426	            }
   427	          usleep(delay_ms * 1000);
   428	        }
   429	    }
   430	  while (current != target);

    90	  cancel_requested = g_motion.cancel_requested;
    91	  pthread_mutex_unlock(&g_motion.lock);
    92	  return cancel_requested;
    93	}
