   752	int robot_motion_submit_and_wait(enum robot_motion_source_e source,
   753	                                 enum robot_motion_direction_e direction,
   754	                                 unsigned int steps, unsigned int period_ms,
   755	                                 uint32_t timeout_ms, int *result)
   756	{
   757	  int request_id;
   758	  int motion_result;
   759	  int wait_result;
   760	
   761	  request_id = robot_motion_submit(source, direction, steps, period_ms);
   762	  if (request_id < 0)
   763	    {
   764	      return request_id;
   765	    }
   766	
   767	  printf("[ROBOT-MOTION] waiting id=%d timeout_ms=%lu\n", request_id,
   768	         (unsigned long)timeout_ms);
   769	  wait_result = robot_motion_wait_timeout((uint32_t)request_id, timeout_ms,
   770	                                          &motion_result);
   771	  if (wait_result == -ETIMEDOUT)
   772	    {
   773	      bool still_running;
   774	
   775	      pthread_mutex_lock(&g_motion.lock);
   776	      still_running = g_motion.completed_request_id < (uint32_t)request_id;
   777	      if (still_running)
   778	        {
   779	          g_motion.cancel_requested = true;
   780	        }
   781	      else
   782	        {
   783	          motion_result = g_motion.last_result;
   784	        }
   785	      pthread_mutex_unlock(&g_motion.lock);
   786	
   787	      if (still_running)
   788	        {
   789	          printf("[ROBOT-MOTION] timeout stop requested id=%d\n", request_id);
   790	          wait_result = robot_motion_wait((uint32_t)request_id,
   791	                                          &motion_result);
   792	          if (wait_result < 0)
   793	            {
   794	              return wait_result;
   795	            }
   796	
   797	          printf("[ROBOT-MOTION] timeout stopped id=%d worker_rc=%d\n",
   798	                 request_id, motion_result);
   799	          return -ETIMEDOUT;
   800	        }
   801	    }
   802	
   803	  if (wait_result < 0)
   804	    {
   805	      return wait_result;
   806	    }
   807	
   808	  if (result != NULL)
   809	    {
   810	      *result = motion_result;
   811	    }
   812	
   813	  return motion_result;
   814	}
