    62	static int robot_motion_tool_number(cJSON *item, unsigned int minimum,
    63	                                    unsigned int maximum,
    64	                                    unsigned int *value)
    65	{
    66	  double number;
    67	
    68	  if (item == NULL || !cJSON_IsNumber(item) || value == NULL)
    69	    {
    70	      return -EINVAL;
    71	    }
    72	
    73	  number = item->valuedouble;
    74	  if (number < minimum || number > maximum || number != (double)(int)number)
    75	    {
    76	      return -EINVAL;
    77	    }
    78	
    79	  *value = (unsigned int)number;
    80	  return 0;
    81	}
