 81	static int robotctl_clamp_angle(int angle)
 82	{
 83	  if (angle < 0)
 84	    {
 85	      return 0;
 86	    }
 87	
 88	  if (angle > 180)
 89	    {
 90	      return 180;
 91	    }
 92	
 93	  return angle;
 94	}
