 96	static ub16_t robotctl_angle_to_duty(int angle)
 97	{
 98	  uint32_t pulse_us;
 99	
100	  angle = robotctl_clamp_angle(angle);
101	  pulse_us = ROBOTCTL_SERVO_MIN_US +
102	             ((ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US) * angle) / 180;
103	
104	  return (ub16_t)(((uint64_t)pulse_us << 16) / ROBOTCTL_SERVO_PERIOD_US);
105	}
106	
107	static int robotctl_duty_to_angle(ub16_t duty)
108	{
109	  uint32_t pulse_us;
110	
111	  pulse_us = ((uint64_t)duty * ROBOTCTL_SERVO_PERIOD_US) >> 16;
112	  if (pulse_us < ROBOTCTL_SERVO_MIN_US ||
113	      pulse_us > ROBOTCTL_SERVO_MAX_US)
114	    {
115	      return -1;
116	    }
117	
118	  return (int)(((pulse_us - ROBOTCTL_SERVO_MIN_US) * 180) /
119	               (ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US));
120	}
