  printf("[ROBOT-MOTION] backend init begin\n");
  ret = robotctl_servo_open(&ctx);
  printf("[ROBOT-MOTION] backend init done rc=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  ctx.cancel_check = robot_motion_cancel_check;
