             robot_motion_tool_now_ms(), -EINVAL);
      return ERROR;
    }

  period_ms = robot_motion_default_period(direction);
  steps_item = cJSON_GetObjectItem(root, "steps");
  if (steps_item != NULL &&
      robot_motion_tool_number(steps_item, ROBOT_MOTION_MIN_STEPS, 1,
